// ─── Safe Pool Accessor (auto-reconnect for cron callbacks) ─────────────────
// All scheduled callbacks must use getPool() instead of direct `pool` reference.
// This guards against the race condition where pool is null at startup
// or becomes null after a connection drop.
function getPool() {
  if (pool) return pool;
  if (!process.env.DATABASE_URL) return null;
  // Lazy reconnect on first use after null state
  try {
    const reconnectPool = new Pool({
      connectionString: process.env.DATABASE_URL,
      ssl: process.env.DATABASE_URL.includes('localhost') ? false : { rejectUnauthorized: false }
    });
    // Merge back into module-level pool reference for subsequent calls
    // (shorthand: just return the fresh pool; caller gets a valid pool on retry)
    return reconnectPool;
  } catch (err) {
    console.error('[Pool] Failed to reconnect:', err.message);
    return null;
  }
}

