// ─── In-Memory Rate Limiter for /api/* ──────────────────
// 100 requests per minute per IP — sliding window
(function () {
  var WINDOW_MS = 60 * 1000;
  var MAX_REQUESTS = 100;
  var store = new Map();

  setInterval(function () {
    var now = Date.now();
    store.forEach(function (entry, ip) {
      if (now - entry.windowStart > WINDOW_MS * 2) store.delete(ip);
    });
  }, 5 * 60 * 1000);

  app.use('/api/', function rateLimiter(req, res, next) {
    // Bypass Stripe webhook (signature verified separately)
    if (req.path === '/stripe-webhook') return next();

    var ip =
      (req.headers['x-forwarded-for'] || '').split(',')[0].trim() ||
      (req.socket && req.socket.remoteAddress) ||
      'unknown';

    var now = Date.now();
    var entry = store.get(ip);

    if (!entry || now - entry.windowStart > WINDOW_MS) {
      store.set(ip, { windowStart: now, count: 1 });
      return next();
    }

    entry.count += 1;
    if (entry.count > MAX_REQUESTS) {
      res.setHeader('Retry-After', '60');
      return res.status(429).json({
        error: 'Too many requests. Please wait before retrying.',
        retryAfter: 60
      });
    }
    return next();
  });
}());

