// ─── Report Issue Injection Middleware ─────────────────────────────────────────
// Intercepts HTML GET requests before express.static, reads the file, injects
// the Report Issue script tag before </body>, then sends the modified HTML.
// Non-HTML assets fall through to express.static unchanged.
(function () {
  // /app and /app.html MUST be skipped — the /app route handler (requireAuth)
  // injects window.__SERVER_AUTHENTICATED and inline visibility styles.
  // If this middleware intercepts /app first, it serves raw app.html without
  // auth injection and the user sees the marketing page instead of the dashboard.
  const REPORT_SKIP_PATHS = new Set(['/admin.html', '/login.html', '/signup.html', '/forgot-password.html', '/reset-password.html', '/phase-zero.html', '/lockout.html', '/offline.html', '/coming-soon.html', '/report-issue.js', '/app', '/app.html']);
  const REPORT_INJECT = '\n<script src="/report-issue.js" defer></script>';
  const STATIC_DIR = path.join(__dirname, 'public');

  app.use(function reportIssueInjector(req, res, next) {
    if (req.method !== 'GET' && req.method !== 'HEAD') return next();
    const p = req.path;
    if (p.startsWith('/api/')) return next();
    // Only intercept .html paths (or extensionless that resolve to HTML)
    if (p.includes('.') && !p.endsWith('.html')) return next();
    if (REPORT_SKIP_PATHS.has(p) || REPORT_SKIP_PATHS.has(p + '.html')) return next();

    // Try to resolve the HTML file
    let filePath = path.join(STATIC_DIR, p);
    if (!filePath.endsWith('.html')) filePath = filePath.endsWith('/') ? filePath + 'index.html' : filePath + '.html';

    // Security: ensure file is within STATIC_DIR
    const resolved = path.resolve(filePath);
    if (!resolved.startsWith(STATIC_DIR + path.sep) && resolved !== STATIC_DIR) return next();

    if (!fs.existsSync(resolved)) return next();

    try {
      let html = fs.readFileSync(resolved, 'utf8');
      if (html.includes('</body>')) {
        html = html.replace(/<\/body>/i, REPORT_INJECT + '\n</body>');
      }
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.setHeader('Cache-Control', 'no-cache');
      res.send(html);
    } catch (e) {
      next(); // fall through to static serving on error
    }
  });
}());

