const PASSWORD_MIN_LENGTH = 10;
const BCRYPT_ROUNDS = 12;

function validatePassword(password) {
  const errors = [];
  if (!password || password.length < PASSWORD_MIN_LENGTH) {
    errors.push(`Password must be at least ${PASSWORD_MIN_LENGTH} characters`);
  }
  if (!/[a-zA-Z]/.test(password)) {
    errors.push('Password must contain at least 1 letter');
  }
  if (!/[0-9]/.test(password)) {
    errors.push('Password must contain at least 1 number');
  }
  return { valid: errors.length === 0, errors };
}

// Seed default allocations for a new user
async function seedUserAllocations(client, userId) {
  const categories = await client.query('SELECT id, default_percentage FROM categories ORDER BY sort_order');
  for (const cat of categories.rows) {
    await client.query(
      `INSERT INTO user_allocations (user_id, category_id, percentage) VALUES ($1, $2, $3)
       ON CONFLICT (user_id, category_id) DO NOTHING`,
      [userId, cat.id, cat.default_percentage]
    );
  }
}

