// ALL Pro access checks MUST use these functions.
// DO NOT inline Pro logic anywhere else in this file.
// Previous bugs: #86587, #87049, #109046, #141889, #154484

const CREATOR_EMAIL = (process.env.CREATOR_EMAIL || 'owner@example.com').toLowerCase();

// ─── TWO-TIER ALLOWLIST ──────────────────────────────────────────────────────
// Tier 1: Admin — chris.finrev@gmail.com only. Full admin panel, all controls.
// Tier 2: Owner — ecci2760@gmail.com, ecci2760f@gmail.com, dianes3cps@gmail.com.
//          Sovereign feature access for free. NO admin panel. NO affiliate eligibility.
//
// ADMIN_EMAILS env var: canonical source for admin-tier accounts.
// OWNER_EMAILS env var: canonical source for owner-tier accounts.

const ADMIN_EMAILS = (process.env.ADMIN_EMAILS || 'chris.finrev@gmail.com')
  .split(',').map(e => e.trim().toLowerCase()).filter(Boolean);

const OWNER_EMAILS = (process.env.OWNER_EMAILS || process.env.FUTURE_GEN_EMAILS || 'ecci2760@gmail.com,ecci2760f@gmail.com,dianes3cps@gmail.com')
  .split(',').map(e => e.trim().toLowerCase()).filter(Boolean);

// Legacy alias — callers that still reference FUTURE_GEN_EMAILS get OWNER_EMAILS
const FUTURE_GEN_EMAILS = OWNER_EMAILS;

function isAdminEmail(email) {
  return !!(email && ADMIN_EMAILS.includes(email.toLowerCase()));
}

function isOwnerEmail(email) {
  return !!(email && OWNER_EMAILS.includes(email.toLowerCase()));
}

// Legacy alias — same check, kept for backward compatibility
function isFutureGenEmail(email) {
  return isOwnerEmail(email);
}

// NDA/Beta agreement is required for ALL pre-launch accounts (except creator).
// Launch date for NDA purposes: June 30, 2026 (when public beta ends).
const NDA_LAUNCH_DATE = process.env.NDA_LAUNCH_DATE
  ? new Date(process.env.NDA_LAUNCH_DATE)
  : new Date('2026-06-30T23:59:00');
const NDA_VERSION = 'v1';

// Launch date used for promo-code grace period logic.
// After this date, promo users who've been signed up >= 30 days enter a 14-day
// grace period before their Pro access is revoked.
const PROMO_LAUNCH_DATE = process.env.LAUNCH_DATE
  ? new Date(process.env.LAUNCH_DATE)
  : new Date('2026-06-30T23:59:59Z');

// Generate a unique referral code for a user.
// Format: FACTS-XXXXXX (6 random alphanumeric chars, uppercase)
async function generateUniqueReferralCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no I, O, 0, 1 to avoid confusion
  for (let attempt = 0; attempt < 20; attempt++) {
    let code = 'FACTS-';
    for (let i = 0; i < 6; i++) {
      code += chars[Math.floor(Math.random() * chars.length)];
    }
    const existing = await pool.query('SELECT id FROM users WHERE referral_code = $1', [code]);
    if (existing.rows.length === 0) return code;
  }
  throw new Error('Failed to generate unique referral code after 20 attempts');
}

/**
 * Check if a user has Pro access.
 * Accepts either a userId (number) or a user object with {id, email, is_creator, promo_code_used, plan, paid_until}.
 * Checks: is_creator flag, email === CREATOR_EMAIL, promo code, active subscription.
 * Auto-heals: if email matches CREATOR_EMAIL but is_creator flag is false, fixes the flag.
 */
async function hasProAccess(userOrId) {
  let user;
  if (typeof userOrId === 'object' && userOrId !== null) {
    user = userOrId;
  } else {
    const result = await pool.query(
      'SELECT id, email, plan, paid_until, is_creator, promo_code_used, promo_grace_expired, trial_expires_at FROM users WHERE id = $1',
      [userOrId]
    );
    if (result.rows.length === 0) return false;
    user = result.rows[0];
  }

  // 1. Creator flag set in DB
  if (user.is_creator) return true;

  // 1b. Owner email — full sovereign access, no admin rights
  if (isOwnerEmail(user.email)) return true;

  // 2. Email matches CREATOR_EMAIL (belt-and-suspenders: survives flag loss)
  if (user.email && user.email.toLowerCase() === CREATOR_EMAIL) {
    // Auto-heal: fix the missing is_creator flag in background
    if (user.id) {
      pool.query('UPDATE users SET is_creator = true WHERE id = $1 AND is_creator = false', [user.id])
        .catch(err => console.error('Auto-heal is_creator flag failed:', err.message));
    }
    return true;
  }

  // 3. Redeemed a promo code — BUT only if the post-launch grace period hasn't expired.
  //    promo_grace_expired is set to TRUE by the daily promo-grace-manager job after
  //    the 14-day countdown runs out. Until then (or if it was never triggered) it is
  //    FALSE/null, meaning the promo still grants Pro.
  if (user.promo_code_used && !user.promo_grace_expired) return true;

  // 4. Active paid subscription
  if (user.plan === 'paid' && user.paid_until && new Date(user.paid_until) > new Date()) return true;

  // 5. Active 21-day free trial (Habitual Handshake)
  if (user.trial_expires_at && new Date(user.trial_expires_at) > new Date()) return true;

  // 6. family Pro — user is an active member of a NON-INCUBATOR family whose owner has Pro.
  //    Owner pays; all active members inherit their Pro access automatically.
  //    NOTE: Incubator sub-accounts are excluded here — they get educational (Levels 1-3) only.
  //    Use hasIncubatorSubAccess() to check educational-tier access for sub-accounts.
  if (user.id) {
    try {
      const householdRes = await pool.query(`
        SELECT 1
        FROM household_members hm
        JOIN households h ON h.id = hm.household_id
        JOIN users owner ON owner.id = h.owner_id
        WHERE hm.user_id = $1
          AND hm.status = 'active'
          AND hm.broke_away_at IS NULL
          AND h.is_incubator = false
          AND owner.id != $1
          AND owner.plan = 'paid'
          AND owner.paid_until > NOW()
        LIMIT 1
      `, [user.id]);
      if (householdRes.rows.length > 0) return true;
    } catch (e) {
      // Non-fatal: if family lookup fails, fall through to free
    }
  }

  return false;
}

/**
 * Check if a user is an active Family Incubator sub-account.
 * Sub-accounts get educational access (Levels 1–3) only — NOT full Pro.
 * Returns true if:
 *   - User is an active, non-broken-away sub-account of an incubator family
 *   - The head of family has an active Pro subscription
 *
 * Returns false once the sub-account breaks away (they then need their own Pro sub).
 */
async function hasIncubatorSubAccess(userId) {
  try {
    const res = await pool.query(`
      SELECT 1
      FROM household_members hm
      JOIN households h ON h.id = hm.household_id
      JOIN users head ON head.id = h.owner_id
      WHERE hm.user_id = $1
        AND hm.status = 'active'
        AND hm.is_sub_account = true
        AND hm.broke_away_at IS NULL
        AND h.is_incubator = true
        AND head.plan = 'paid'
        AND head.paid_until > NOW()
        AND head.id != $1
      LIMIT 1
    `, [userId]);
    return res.rows.length > 0;
  } catch (e) {
    return false;
  }
}

/**
 * ── PRODUCT TIER HELPERS ──────────────────────────────────────────────────────
 *
 * Maps the 5-tier product structure to the existing pricing_tier column.
 *
 * Tier hierarchy (ascending):
 *   free → pro → business → elite → sovereign
 */

/**
 * Return the simplified product tier for a user.
 * Returns: 'free' | 'pro' | 'business' | 'elite' | 'sovereign'
 */
async function getUserProductTier(userId) {
  try {
    const res = await pool.query(
      'SELECT pricing_tier, plan, paid_until, is_creator, email FROM users WHERE id = $1',
      [userId]
    );
    if (res.rows.length === 0) return 'free';
    const u = res.rows[0];
    if (u.is_creator) return 'sovereign'; // Creator gets full access
    if (isOwnerEmail(u.email)) return 'sovereign'; // Owner gets full access, no admin rights
    const pt = u.pricing_tier || 'none';
    if (pt === 'sovereign_executive') return 'sovereign';
    if (pt === 'tfr_elite') return 'elite';
    if (pt === 'business_core' || pt === 'business_bundle') return 'business';
    if (pt === 'tfr_pro' || pt === 'individual_pro') return 'pro';
    return 'free';
  } catch (e) {
    return 'free';
  }
}

/**
 * Check if user has Business tier or higher (Levels 7-9).
 * Returns true for: business_core, business_bundle, tfr_elite, sovereign_executive, is_creator
 */
async function hasBusinessAccess(userId) {
  try {
    const res = await pool.query(
      'SELECT pricing_tier, plan, paid_until, is_creator, email FROM users WHERE id = $1',
      [userId]
    );
    if (res.rows.length === 0) return false;
    const u = res.rows[0];
    if (u.is_creator) return true;
    if (isOwnerEmail(u.email)) return true;
    const pt = u.pricing_tier || 'none';
    if (!['business_core','business_bundle','tfr_elite','sovereign_executive'].includes(pt)) return false;
    // Must have active subscription
    if (u.plan === 'paid' && u.paid_until && new Date(u.paid_until) > new Date()) return true;
    return false;
  } catch (e) { return false; }
}

/**
 * Check if user has Elite Pro tier or higher (Levels 10-12).
 * Returns true for: tfr_elite, sovereign_executive, is_creator
 */
async function hasEliteAccess(userId) {
  try {
    const res = await pool.query(
      'SELECT pricing_tier, plan, paid_until, is_creator, email FROM users WHERE id = $1',
      [userId]
    );
    if (res.rows.length === 0) return false;
    const u = res.rows[0];
    if (u.is_creator) return true;
    if (isOwnerEmail(u.email)) return true;
    const pt = u.pricing_tier || 'none';
    if (!['tfr_elite','sovereign_executive'].includes(pt)) return false;
    if (u.plan === 'paid' && u.paid_until && new Date(u.paid_until) > new Date()) return true;
    return false;
  } catch (e) { return false; }
}

/**
 * Check if user has Sovereign Executive tier.
 * Returns true for: sovereign_executive, is_creator
 */
async function hasSovereignAccess(userId) {
  try {
    const res = await pool.query(
      'SELECT pricing_tier, plan, paid_until, is_creator, email FROM users WHERE id = $1',
      [userId]
    );
    if (res.rows.length === 0) return false;
    const u = res.rows[0];
    if (u.is_creator) return true;
    if (isOwnerEmail(u.email)) return true;
    const pt = u.pricing_tier || 'none';
    if (pt !== 'sovereign_executive') return false;
    // Sovereign is a lifetime purchase — no paid_until check needed (but keep plan check)
    // It may be set as plan='paid' with a far-future paid_until, or handled separately.
    // We trust pricing_tier = sovereign_executive as authoritative.
    return true;
  } catch (e) { return false; }
}

/**
 * Check if a user's credit gate has been satisfied for Pro upgrade.
 * Returns: { required: bool, satisfied: bool, status: string }
 */
async function checkCreditGate(userId) {
  try {
    const res = await pool.query(
      'SELECT credit_gate_status, email FROM users WHERE id = $1',
      [userId]
    );
    if (res.rows.length === 0) return { required: false, satisfied: false, status: 'unknown' };
    // Creator and owner emails are exempt from credit gate
    if (isOwnerEmail(res.rows[0].email) || (res.rows[0].email || '').toLowerCase() === CREATOR_EMAIL) {
      return { required: false, satisfied: true, status: 'not_required' };
    }
    const status = res.rows[0].credit_gate_status || 'pending';
    const satisfied = ['uploaded', 'waived'].includes(status);
    return { required: status !== 'not_required', satisfied, status };
  } catch (e) {
    return { required: false, satisfied: true, status: 'error' };
  }
}

