// Helper: check if user has met all requirements to unlock affiliate status
// Called automatically when user turns 18, completes curriculum, or completes milestones
async function checkAndGrantAffiliateAccess(userId) {
  try {
    const userResult = await pool.query(
      `SELECT id, email, name, date_of_birth,
              affiliate_curriculum_completed, affiliate_usage_milestones_completed,
              affiliate_unlock_notified_at
       FROM users WHERE id = $1`,
      [userId]
    );
    if (userResult.rows.length === 0) return;
    const user = userResult.rows[0];

    // Age check
    if (!user.date_of_birth) return;
    const dob = new Date(user.date_of_birth);
    const eighteenth = new Date(dob);
    eighteenth.setFullYear(eighteenth.getFullYear() + 18);
    if (new Date() < eighteenth) return; // Not yet 18

    // All requirements must be met
    if (!user.affiliate_curriculum_completed || !user.affiliate_usage_milestones_completed) return;

    // Already has an active affiliate record?
    const existingAffiliate = await pool.query(
      'SELECT id FROM affiliates WHERE user_id = $1 AND status = \'active\'',
      [userId]
    );
    if (existingAffiliate.rows.length > 0) return; // Already active

    // Grant affiliate access — generate referral code and create record
    const referralCode = await generateUniqueReferralCode();
    await pool.query(
      `INSERT INTO affiliates (user_id, email, referral_code, status, is_minor, age_verified_at)
       VALUES ($1, $2, $3, 'active', false, NOW())
       ON CONFLICT (user_id) DO UPDATE SET status = 'active', is_minor = false, age_verified_at = NOW()`,
      [userId, user.email, referralCode]
    );

    // Mark user as having been notified (avoid duplicate notifications)
    await pool.query(
      'UPDATE users SET affiliate_unlock_notified_at = NOW() WHERE id = $1',
      [userId]
    );

    console.log(`[AffiliateUnlock] User ${userId} unlocked affiliate access — code: ${referralCode}`);
  } catch (err) {
    console.error('[AffiliateUnlock] checkAndGrantAffiliateAccess error:', err.message);
  }
}

// GET /api/affiliate/family-frozen
// Family member views their own frozen commission balance
app.get('/api/affiliate/family-frozen', requireAuth, async (req, res) => {
  try {
    const result = await pool.query(
      `SELECT
         a.id AS affiliate_id,
         a.referral_code,
         a.family_household_id,
         h.name AS household_name,
         -- Total frozen (can't withdraw yet)
         COALESCE(frozen.total_frozen, 0) AS frozen_balance_cents,
         -- Total unfrozen (available to withdraw)
         COALESCE(unfrozen.total_unfrozen, 0) AS unfrozen_balance_cents,
         -- Recent frozen commissions detail
         recent.commissions AS recent_frozen
       FROM affiliates a
       LEFT JOIN households h ON h.id = a.family_household_id
       LEFT JOIN (
         SELECT affiliate_id, SUM(amount_cents) AS total_frozen
         FROM commissions
         WHERE family_split_type = 'member_frozen' AND frozen_until_pro = true AND unfrozen_at IS NULL
           AND status != 'forfeited'
         GROUP BY affiliate_id
       ) frozen ON frozen.affiliate_id = a.id
       LEFT JOIN (
         SELECT affiliate_id, SUM(amount_cents) AS total_unfrozen
         FROM commissions
         WHERE family_split_type = 'member_frozen' AND unfrozen_at IS NOT NULL
         GROUP BY affiliate_id
       ) unfrozen ON unfrozen.affiliate_id = a.id
       LEFT JOIN LATERAL (
         SELECT json_agg(json_build_object(
           'id', c.id,
           'amount_cents', c.amount_cents,
           'earned_at', c.earned_at,
           'unfrozen_at', c.unfrozen_at,
           'status', c.status
         ) ORDER BY c.earned_at DESC) AS commissions
         FROM commissions c
         WHERE c.affiliate_id = a.id AND c.family_split_type = 'member_frozen'
         LIMIT 10
       ) recent ON true
       WHERE a.user_id = $1
       LIMIT 1`,
      [req.userId]
    );

    if (result.rows.length === 0) {
      return res.json({
        success: true,
        is_family_member: false,
        frozen_balance_cents: 0,
        unfrozen_balance_cents: 0,
        recent_frozen: []
      });
    }

    const row = result.rows[0];
    res.json({
      success: true,
      is_family_member: !!row.family_household_id,
      household_name: row.household_name,
      affiliate_id: row.affiliate_id,
      referral_code: row.referral_code,
      frozen_balance_cents: parseInt(row.frozen_balance_cents) || 0,
      unfrozen_balance_cents: parseInt(row.unfrozen_balance_cents) || 0,
      recent_frozen: row.recent_frozen || []
    });
  } catch (err) {
    console.error('GET /api/affiliate/family-frozen error:', err.message);
    res.status(500).json({ error: 'Failed to fetch frozen balance' });
  }
});

