// Export personal data as CSV (available to all users — data fairness)
app.get('/api/user/personal-data-export', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    // Fetch all personal data
    const [
      transactionsResult,
      debtsResult,
      billsResult,
      creditCardsResult,
      bankAccountsResult,
      giftCardsResult
    ] = await Promise.all([
      pool.query(
        `SELECT t.transaction_date, t.description, t.amount, t.type,
                c.name as category, sc.name as subcategory,
                t.notes, t.txn_tag, t.created_at
         FROM transactions t
         LEFT JOIN categories c ON c.id = t.category_id
         LEFT JOIN subcategories sc ON sc.id = t.subcategory_id
         WHERE t.user_id = $1
         ORDER BY t.transaction_date DESC`,
        [userId]
      ),
      pool.query(
        `SELECT name, balance, interest_rate, minimum_payment, account_type,
                created_at
         FROM debts WHERE user_id = $1 ORDER BY created_at`,
        [userId]
      ),
      pool.query(
        `SELECT name, amount, due_day, frequency, is_active, created_at
         FROM recurring_bills WHERE user_id = $1 ORDER BY created_at`,
        [userId]
      ).catch(() => ({ rows: [] })),
      pool.query(
        `SELECT name, balance, credit_limit, apr, due_date, created_at
         FROM credit_cards WHERE user_id = $1 ORDER BY created_at`,
        [userId]
      ).catch(() => ({ rows: [] })),
      pool.query(
        `SELECT institution_name, account_name, account_type, balance, created_at
         FROM bank_accounts WHERE user_id = $1 ORDER BY created_at`,
        [userId]
      ).catch(() => ({ rows: [] })),
      pool.query(
        `SELECT store_name, card_name, balance, created_at
         FROM gift_cards WHERE user_id = $1 ORDER BY created_at`,
        [userId]
      ).catch(() => ({ rows: [] }))
    ]);

    // Build CSV content
    const sections = [];

    const toCsv = (rows, headers) => {
      if (!rows.length) return '';
      const escape = (v) => {
        if (v === null || v === undefined) return '';
        const s = String(v);
        if (s.includes(',') || s.includes('"') || s.includes('\n')) {
          return '"' + s.replace(/"/g, '""') + '"';
        }
        return s;
      };
      const header = headers.join(',');
      const lines = rows.map(r => headers.map(h => escape(r[h])).join(','));
      return [header, ...lines].join('\n');
    };

    sections.push('=== TRANSACTIONS ===');
    sections.push(toCsv(transactionsResult.rows, [
      'transaction_date', 'description', 'amount', 'type', 'category', 'subcategory', 'notes', 'txn_tag', 'created_at'
    ]));

    if (debtsResult.rows.length) {
      sections.push('\n=== DEBTS ===');
      sections.push(toCsv(debtsResult.rows, ['name', 'balance', 'interest_rate', 'minimum_payment', 'account_type', 'created_at']));
    }

    if (billsResult.rows.length) {
      sections.push('\n=== RECURRING BILLS ===');
      sections.push(toCsv(billsResult.rows, ['name', 'amount', 'due_day', 'frequency', 'is_active', 'created_at']));
    }

    if (creditCardsResult.rows.length) {
      sections.push('\n=== CREDIT CARDS ===');
      sections.push(toCsv(creditCardsResult.rows, ['name', 'balance', 'credit_limit', 'apr', 'due_date', 'created_at']));
    }

    if (bankAccountsResult.rows.length) {
      sections.push('\n=== BANK ACCOUNTS ===');
      sections.push(toCsv(bankAccountsResult.rows, ['institution_name', 'account_name', 'account_type', 'balance', 'created_at']));
    }

    if (giftCardsResult.rows.length) {
      sections.push('\n=== GIFT CARDS ===');
      sections.push(toCsv(giftCardsResult.rows, ['store_name', 'card_name', 'balance', 'created_at']));
    }

    // Mark export in offboarding record if applicable
    await pool.query(
      `UPDATE household_offboarding_records SET data_exported_at = NOW()
       WHERE user_id = $1 AND reintegrated_at IS NULL AND data_exported_at IS NULL`,
      [userId]
    );

    const filename = `facts-finance-export-${new Date().toISOString().split('T')[0]}.csv`;
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.send(sections.join('\n'));
  } catch (err) {
    console.error('GET /api/user/personal-data-export error:', err.message);
    res.status(500).json({ error: 'Failed to export data' });
  }
});

