// Grant or update permission
app.post('/api/permissions/grant', requireAuth, async (req, res) => {
  try {
    const {
      household_id,
      viewer_user_id,
      category_id,
      can_view = true,
      can_edit = false,
      share_summary_only = false
    } = req.body;

    if (!household_id || !viewer_user_id) {
      return res.status(400).json({ error: 'household_id and viewer_user_id are required' });
    }

    // Verify both users are members of the family
    const memberCheck = await pool.query(`
      SELECT COUNT(*) as count
      FROM household_members
      WHERE household_id = $1 AND user_id IN ($2, $3)
    `, [household_id, req.userId, viewer_user_id]);

    if (parseInt(memberCheck.rows[0].count) !== 2) {
      return res.status(403).json({ error: 'Both users must be members of the family' });
    }

    // Cannot grant permissions to yourself
    if (req.userId === parseInt(viewer_user_id)) {
      return res.status(400).json({ error: 'Cannot grant permissions to yourself' });
    }

    // Upsert permission
    const result = await pool.query(`
      INSERT INTO household_permissions
      (household_id, owner_user_id, viewer_user_id, category_id, can_view, can_edit, share_summary_only)
      VALUES ($1, $2, $3, $4, $5, $6, $7)
      ON CONFLICT (household_id, owner_user_id, viewer_user_id, category_id)
      DO UPDATE SET
        can_view = EXCLUDED.can_view,
        can_edit = EXCLUDED.can_edit,
        share_summary_only = EXCLUDED.share_summary_only,
        updated_at = NOW()
      RETURNING *
    `, [household_id, req.userId, viewer_user_id, category_id, can_view, can_edit, share_summary_only]);

    res.json({ success: true, permission: result.rows[0] });
  } catch (err) {
    console.error('POST /api/permissions/grant error:', err.message);
    res.status(500).json({ error: 'Failed to grant permission' });
  }
});

// Grant permissions to ALL family members for a category (convenience)
app.post('/api/permissions/grant-all', requireAuth, async (req, res) => {
  try {
    const {
      household_id,
      category_id,
      can_view = true,
      can_edit = false,
      share_summary_only = false
    } = req.body;

    if (!household_id) {
      return res.status(400).json({ error: 'household_id is required' });
    }

    // Verify user is a member of the family
    const memberCheck = await pool.query(
      'SELECT 1 FROM household_members WHERE household_id = $1 AND user_id = $2',
      [household_id, req.userId]
    );
    if (memberCheck.rows.length === 0) {
      return res.status(403).json({ error: 'Not a member of this family' });
    }

    // Get all other members of the family
    const members = await pool.query(
      'SELECT user_id FROM household_members WHERE household_id = $1 AND user_id != $2',
      [household_id, req.userId]
    );

    // Grant permissions to all members
    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      for (const member of members.rows) {
        await client.query(`
          INSERT INTO household_permissions
          (household_id, owner_user_id, viewer_user_id, category_id, can_view, can_edit, share_summary_only)
          VALUES ($1, $2, $3, $4, $5, $6, $7)
          ON CONFLICT (household_id, owner_user_id, viewer_user_id, category_id)
          DO UPDATE SET
            can_view = EXCLUDED.can_view,
            can_edit = EXCLUDED.can_edit,
            share_summary_only = EXCLUDED.share_summary_only,
            updated_at = NOW()
        `, [household_id, req.userId, member.user_id, category_id, can_view, can_edit, share_summary_only]);
      }

      await client.query('COMMIT');
      res.json({ success: true, count: members.rows.length });
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('POST /api/permissions/grant-all error:', err.message);
    res.status(500).json({ error: 'Failed to grant permissions to all' });
  }
});

// Revoke permission
app.delete('/api/permissions/revoke', requireAuth, async (req, res) => {
  try {
    const { household_id, viewer_user_id, category_id } = req.body;

    if (!household_id || !viewer_user_id) {
      return res.status(400).json({ error: 'household_id and viewer_user_id are required' });
    }

    const result = await pool.query(`
      DELETE FROM household_permissions
      WHERE household_id = $1
        AND owner_user_id = $2
        AND viewer_user_id = $3
        AND (category_id = $4 OR ($4::INTEGER IS NULL AND category_id IS NULL))
      RETURNING *
    `, [household_id, req.userId, viewer_user_id, category_id]);

    res.json({ success: true, revoked: result.rows.length });
  } catch (err) {
    console.error('DELETE /api/permissions/revoke error:', err.message);
    res.status(500).json({ error: 'Failed to revoke permission' });
  }
});

