// POST log an expense against a shared budget category (any member)
app.post('/api/households/:id/shared-budgets/:budgetId/expenses', requireAuth, async (req, res) => {
  try {
    const { id, budgetId } = req.params;
    const { amount, description, expense_date } = req.body;
    if (!amount || parseFloat(amount) <= 0) return res.status(400).json({ error: 'Amount must be greater than 0' });

    const memberRow = await pool.query(`SELECT id FROM household_members WHERE household_id = $1 AND user_id = $2`, [id, req.userId]);
    if (memberRow.rows.length === 0) return res.status(403).json({ error: 'Not a member of this family' });

    const budgetRow = await pool.query(`SELECT id FROM shared_budget_categories WHERE id = $1 AND household_id = $2`, [budgetId, id]);
    if (budgetRow.rows.length === 0) return res.status(404).json({ error: 'Budget category not found' });

    const dateStr = expense_date || new Date().toISOString().split('T')[0];
    const result = await pool.query(
      `INSERT INTO shared_budget_expenses (budget_category_id, household_id, logged_by, amount, description, expense_date)
       VALUES ($1, $2, $3, $4, $5, $6) RETURNING *`,
      [budgetId, id, req.userId, parseFloat(amount), description?.trim() || null, dateStr]
    );
    res.json({ success: true, expense: result.rows[0] });
  } catch (err) {
    console.error('POST /api/households/:id/shared-budgets/:budgetId/expenses error:', err.message);
    res.status(500).json({ error: 'Failed to log shared expense' });
  }
});

// GET expense history for a shared budget category (any member)
app.get('/api/households/:id/shared-budgets/:budgetId/expenses', requireAuth, async (req, res) => {
  try {
    const { id, budgetId } = req.params;
    const { month, year } = req.query;
    const memberRow = await pool.query(`SELECT id FROM household_members WHERE household_id = $1 AND user_id = $2`, [id, req.userId]);
    if (memberRow.rows.length === 0) return res.status(403).json({ error: 'Not a member' });

    const targetMonth = parseInt(month) || new Date().getMonth() + 1;
    const targetYear = parseInt(year) || new Date().getFullYear();

    const result = await pool.query(`
      SELECT sbe.id, sbe.amount, sbe.description, sbe.expense_date, sbe.created_at,
             sbe.logged_by, u.name as member_name
      FROM shared_budget_expenses sbe
      JOIN users u ON u.id = sbe.logged_by
      WHERE sbe.budget_category_id = $1 AND sbe.household_id = $2
        AND EXTRACT(MONTH FROM sbe.expense_date) = $3
        AND EXTRACT(YEAR FROM sbe.expense_date) = $4
      ORDER BY sbe.expense_date DESC, sbe.created_at DESC
      LIMIT 100
    `, [budgetId, id, targetMonth, targetYear]);

    res.json({ success: true, expenses: result.rows });
  } catch (err) {
    console.error('GET /api/households/:id/shared-budgets/:budgetId/expenses error:', err.message);
    res.status(500).json({ error: 'Failed to load expenses' });
  }
});

// DELETE a shared budget expense (logged_by or family owner)
app.delete('/api/shared-budget-expenses/:expenseId', requireAuth, async (req, res) => {
  try {
    const { expenseId } = req.params;
    const expRow = await pool.query(
      `SELECT sbe.*, h.owner_id FROM shared_budget_expenses sbe
       JOIN households h ON h.id = sbe.household_id
       WHERE sbe.id = $1`,
      [expenseId]
    );
    if (expRow.rows.length === 0) return res.status(404).json({ error: 'Expense not found' });
    const exp = expRow.rows[0];
    if (exp.logged_by !== req.userId && exp.owner_id !== req.userId) {
      return res.status(403).json({ error: 'Can only delete your own expenses (or be the family owner)' });
    }
    await pool.query(`DELETE FROM shared_budget_expenses WHERE id = $1`, [expenseId]);
    res.json({ success: true });
  } catch (err) {
    console.error('DELETE /api/shared-budget-expenses/:expenseId error:', err.message);
    res.status(500).json({ error: 'Failed to delete expense' });
  }
});

// PUT set per-member contribution targets for a budget category (owner/co-admin)
app.put('/api/households/:id/shared-budgets/:budgetId/member-targets', requireAuth, async (req, res) => {
  try {
    const { id, budgetId } = req.params;
    const { targets } = req.body; // Array of { user_id, expected_amount }
    if (!Array.isArray(targets)) return res.status(400).json({ error: 'targets must be an array' });

    const householdRow = await pool.query(`SELECT owner_id FROM households WHERE id = $1`, [id]);
    if (householdRow.rows.length === 0) return res.status(404).json({ error: 'family not found' });
    const memberRow = await pool.query(`SELECT role FROM household_members WHERE household_id = $1 AND user_id = $2`, [id, req.userId]);
    if (memberRow.rows.length === 0) return res.status(403).json({ error: 'Not a member' });
    const isOwner = householdRow.rows[0].owner_id === req.userId;
    const isCoAdmin = memberRow.rows[0].role === 'co_admin';
    if (!isOwner && !isCoAdmin) return res.status(403).json({ error: 'Only owner or co-admin can set member targets' });

    for (const t of targets) {
      if (parseFloat(t.expected_amount) > 0) {
        await pool.query(
          `INSERT INTO shared_budget_member_targets (budget_category_id, user_id, expected_amount)
           VALUES ($1, $2, $3)
           ON CONFLICT (budget_category_id, user_id) DO UPDATE SET expected_amount = $3, updated_at = NOW()`,
          [budgetId, t.user_id, parseFloat(t.expected_amount)]
        );
      } else {
        await pool.query(`DELETE FROM shared_budget_member_targets WHERE budget_category_id = $1 AND user_id = $2`, [budgetId, t.user_id]);
      }
    }
    res.json({ success: true });
  } catch (err) {
    console.error('PUT /api/households/:id/shared-budgets/:budgetId/member-targets error:', err.message);
    res.status(500).json({ error: 'Failed to set member targets' });
  }
});

// ═══════════════════════════════════════════════════════════
// ─── SUBSCRIPTIONS ──────────────────────────────────────
// ═══════════════════════════════════════════════════════════
// ─── STRIPE PAYMENT LINKS ─────────────────────────────────────────────────────
// Individual Pro — $14.99/mo or $149/yr (single user, all levels, no family features)
const STRIPE_INDIVIDUAL_MONTHLY_LINK = process.env.STRIPE_INDIVIDUAL_MONTHLY_LINK || null;
const STRIPE_INDIVIDUAL_ANNUAL_LINK  = process.env.STRIPE_INDIVIDUAL_ANNUAL_LINK  || null;

// 6-Tier Stripe Links (set via env vars after creating Stripe products)
const STRIPE_TFR_PRO_MONTHLY_LINK         = process.env.STRIPE_TFR_PRO_MONTHLY_LINK || null;
const STRIPE_TFR_PRO_ANNUAL_LINK          = process.env.STRIPE_TFR_PRO_ANNUAL_LINK || null;
const STRIPE_BUSINESS_CORE_MONTHLY_LINK   = process.env.STRIPE_BUSINESS_CORE_MONTHLY_LINK || null;
const STRIPE_BUSINESS_BUNDLE_MONTHLY_LINK = process.env.STRIPE_BUSINESS_BUNDLE_MONTHLY_LINK || null;
const STRIPE_BUSINESS_BUNDLE_ANNUAL_LINK  = process.env.STRIPE_BUSINESS_BUNDLE_ANNUAL_LINK || null;
const STRIPE_TFR_ELITE_MONTHLY_LINK       = process.env.STRIPE_TFR_ELITE_MONTHLY_LINK || null;
const STRIPE_TFR_ELITE_ANNUAL_LINK        = process.env.STRIPE_TFR_ELITE_ANNUAL_LINK || null;
const STRIPE_SOVEREIGN_LINK               = process.env.STRIPE_SOVEREIGN_LINK || null;

// ─── PRICING CONSTANTS ────────────────────────────────────────────────────────
// Individual Pro — $14.99/mo | $149.90/yr
const INDIVIDUAL_MONTHLY_CENTS = 1499;     // $14.99/month
const INDIVIDUAL_ANNUAL_CENTS  = 14990;    // $149.90/year (~$12.49/mo, 2 months free)

// 6-Tier Pricing — tier names map to pricing_tier field in users table
const TFR_PRO_MONTHLY_CENTS          = 2599;     // $25.99/month  — Family Pro    (Levels 3-6, Most Popular)
const TFR_PRO_ANNUAL_CENTS           = 25990;    // $259.90/year  — Family Pro Annual (~$21.66/mo, 2 months free)
const BUSINESS_CORE_MONTHLY_CENTS    = 9700;     // $97/month     — Business Core (legacy, kept for backward compat)
const BUSINESS_BUNDLE_MONTHLY_CENTS  = 29700;    // $297/month    — Business      (Levels 7-11, Best Value)
const BUSINESS_BUNDLE_ANNUAL_CENTS   = 297000;   // $2,970/year   — Business Annual ($247.50/mo, 2 months free)
const TFR_ELITE_MONTHLY_CENTS        = 19700;    // $197/month    — Elite         (Levels 7-11, HELOC Engine)
const TFR_ELITE_ANNUAL_CENTS         = 150000;   // $1,500/year   — Elite Annual  ($125/mo, 36% off)
const SOVEREIGN_EXEC_CENTS           = 1999700;  // $19,997 one-time — Sovereign Executive (Level 12, lifetime)

// Map plan identifier → pricing_tier string (single source of truth)
const PLAN_TO_PRICING_TIER = {
  'pro':                  'individual_pro',       // legacy 'pro' plan now maps to individual_pro
  'household_pro':        'tfr_pro',              // legacy 'household_pro' now maps to tfr_pro (Family Pro)
  'individual_pro':       'individual_pro',
  'tfr_pro':              'tfr_pro',
  'business_core':        'business_core',
  'business_bundle':      'business_bundle',
  'tfr_elite':            'tfr_elite',
  'sovereign_executive':  'sovereign_executive',
};

// Map plan identifier → amount_cents (monthly, for new tiers)
const NEW_TIER_AMOUNT_CENTS = {
  'individual_pro':      INDIVIDUAL_MONTHLY_CENTS,
  'tfr_pro':             TFR_PRO_MONTHLY_CENTS,
  'business_core':       BUSINESS_CORE_MONTHLY_CENTS,
  'business_bundle':     BUSINESS_BUNDLE_MONTHLY_CENTS,
  'tfr_elite':           TFR_ELITE_MONTHLY_CENTS,
  'sovereign_executive': SOVEREIGN_EXEC_CENTS,
};

// Map plan identifier → annual amount_cents
const ANNUAL_TIER_AMOUNT_CENTS = {
  'individual_pro':  INDIVIDUAL_ANNUAL_CENTS,
  'tfr_pro':         TFR_PRO_ANNUAL_CENTS,
  'business_bundle': BUSINESS_BUNDLE_ANNUAL_CENTS,
  'tfr_elite':       TFR_ELITE_ANNUAL_CENTS,
};

// Map plan identifier → Stripe payment link (annual variant)
const ANNUAL_TIER_STRIPE_LINKS = {
  'individual_pro':  () => STRIPE_INDIVIDUAL_ANNUAL_LINK,
  'tfr_pro':         () => STRIPE_TFR_PRO_ANNUAL_LINK,
  'business_bundle': () => STRIPE_BUSINESS_BUNDLE_ANNUAL_LINK,
  'tfr_elite':       () => STRIPE_TFR_ELITE_ANNUAL_LINK,
};

// Map plan identifier → Stripe payment link (monthly)
const NEW_TIER_STRIPE_LINKS = {
  'individual_pro':      () => STRIPE_INDIVIDUAL_MONTHLY_LINK,
  'tfr_pro':             () => STRIPE_TFR_PRO_MONTHLY_LINK,
  'business_core':       () => STRIPE_BUSINESS_CORE_MONTHLY_LINK,
  'business_bundle':     () => STRIPE_BUSINESS_BUNDLE_MONTHLY_LINK,
  'tfr_elite':           () => STRIPE_TFR_ELITE_MONTHLY_LINK,
  'sovereign_executive': () => STRIPE_SOVEREIGN_LINK,
};

// All valid plan identifiers
const VALID_PLANS = ['individual_pro', 'tfr_pro', 'business_core', 'business_bundle', 'tfr_elite', 'sovereign_executive'];

// Check available referral balance for an email
app.get('/api/balance/check', requireAuth, async (req, res) => {
  try {
    const { email, plan_type } = req.query;

    if (!email || !email.includes('@')) {
      return res.status(400).json({ error: 'Valid email required' });
    }

    // Determine pricing based on plan and plan_type
    const { plan: planParam } = req.query;
    const isAnnual = plan_type === 'annual';
    let planAmount;
    if (NEW_TIER_AMOUNT_CENTS.hasOwnProperty(planParam)) {
      const supportsAnnualCheck = isAnnual && ANNUAL_TIER_AMOUNT_CENTS.hasOwnProperty(planParam);
      planAmount = supportsAnnualCheck ? ANNUAL_TIER_AMOUNT_CENTS[planParam] : NEW_TIER_AMOUNT_CENTS[planParam];
    } else {
      // Default to Individual Pro pricing for unknown plans
      planAmount = isAnnual ? INDIVIDUAL_ANNUAL_CENTS : INDIVIDUAL_MONTHLY_CENTS;
    }

    // Check if user has an affiliate account
    const affiliateResult = await pool.query(
      'SELECT approved_balance_cents, pending_balance_cents FROM affiliates WHERE LOWER(email) = LOWER($1)',
      [email.toLowerCase()]
    );

    if (affiliateResult.rows.length === 0) {
      return res.json({
        has_balance: false,
        approved_balance_cents: 0,
        pending_balance_cents: 0,
        can_pay_full: false
      });
    }

    const affiliate = affiliateResult.rows[0];
    const approvedBalance = parseInt(affiliate.approved_balance_cents) || 0;
    const pendingBalance = parseInt(affiliate.pending_balance_cents) || 0;

    res.json({
      has_balance: approvedBalance > 0,
      approved_balance_cents: approvedBalance,
      pending_balance_cents: pendingBalance,
      can_pay_full: approvedBalance >= planAmount
    });
  } catch (err) {
    console.error('GET /api/balance/check error:', err.message);
    res.status(500).json({ error: 'Failed to check balance' });
  }
});

app.post('/api/subscriptions/create', async (req, res) => {
  try {
    const { email, plan, plan_type, referral_code, balance_to_apply } = req.body;

    if (!email || !email.includes('@')) {
      return res.status(400).json({ error: 'Valid email required' });
    }

    if (!VALID_PLANS.includes(plan)) {
      return res.status(400).json({ error: 'Invalid plan' });
    }

    // Determine pricing based on plan and plan_type
    const isAnnual = plan_type === 'annual';
    const isIndividualPro = plan === 'individual_pro';
    const isNewTier = NEW_TIER_AMOUNT_CENTS.hasOwnProperty(plan);

    // ── Credit Gate Check ─────────────────────────────────────────────────────
    // Personal paid tiers (individual_pro, tfr_pro, tfr_elite) require credit report.
    // Business tiers (business_core, business_bundle) are exempt.
    const CREDIT_GATE_REQUIRED_PLANS = ['individual_pro', 'tfr_pro', 'tfr_elite'];
    if (CREDIT_GATE_REQUIRED_PLANS.includes(plan) && req.session && req.session.userId) {
      const cgCheck = await checkCreditGate(req.session.userId);
      if (cgCheck.required && !cgCheck.satisfied) {
        return res.status(402).json({
          error: 'Credit report upload required. Please upload your credit report in the Document Vault before activating this plan.',
          code: 'CREDIT_GATE_REQUIRED',
          upload_url: '/document-vault.html'
        });
      }
    }

    // Business tiers are exempt from credit gate — set not_required if user is logged in
    const CREDIT_GATE_EXEMPT_PLANS = ['business_core', 'business_bundle'];
    if (CREDIT_GATE_EXEMPT_PLANS.includes(plan) && req.session && req.session.userId) {
      pool.query(
        "UPDATE users SET credit_gate_status = 'not_required' WHERE id = $1 AND (credit_gate_status IS NULL OR credit_gate_status = 'pending')",
        [req.session.userId]
      ).catch(err => console.error('[CreditGate] Exempt update failed:', err.message));
    }

    let planAmount;
    let stripeLink;

    // sovereign_executive is always one-time, no annual option
    const isSovereign = plan === 'sovereign_executive';
    // Annual billing supported for: individual_pro, tfr_pro, business_bundle, tfr_elite
    const supportsAnnual = !isSovereign && ANNUAL_TIER_AMOUNT_CENTS.hasOwnProperty(plan);
    const billingIsAnnual = isAnnual && supportsAnnual;

    if (isNewTier) {
      planAmount = billingIsAnnual ? ANNUAL_TIER_AMOUNT_CENTS[plan] : NEW_TIER_AMOUNT_CENTS[plan];
      stripeLink = billingIsAnnual
        ? (ANNUAL_TIER_STRIPE_LINKS[plan] ? ANNUAL_TIER_STRIPE_LINKS[plan]() : null)
        : NEW_TIER_STRIPE_LINKS[plan]();
      if (!stripeLink) {
        return res.status(503).json({ error: `Payment link for ${plan} (${billingIsAnnual ? 'annual' : 'monthly'}) is not yet configured. Please contact support.` });
      }
    } else {
      return res.status(400).json({ error: 'Invalid plan' });
    }

    const balanceToApply = parseInt(balance_to_apply) || 0;
    const stripeAmount = Math.max(0, planAmount - balanceToApply);
    const paymentMethod = balanceToApply === 0 ? 'stripe' :
                         (stripeAmount === 0 ? 'balance' : 'mixed');

    // If using balance, verify it's available
    let affiliateId = null;
    if (balanceToApply > 0) {
      const affiliateResult = await pool.query(
        'SELECT id, approved_balance_cents FROM affiliates WHERE LOWER(email) = LOWER($1)',
        [email.toLowerCase()]
      );

      if (affiliateResult.rows.length === 0 || affiliateResult.rows[0].approved_balance_cents < balanceToApply) {
        return res.status(400).json({ error: 'Insufficient balance' });
      }

      affiliateId = affiliateResult.rows[0].id;
    }

    // sovereign_executive is one_time; new tiers are monthly; legacy supports annual
    const normalizedPlanType = plan === 'sovereign_executive' ? 'one_time'
                             : plan_type === 'annual' ? 'annual' : 'monthly';

    // Create subscription record
    const result = await pool.query(
      `INSERT INTO subscriptions (email, plan, plan_type, amount_cents, status, stripe_payment_link,
                                   balance_applied_cents, stripe_amount_cents, payment_method)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       RETURNING id`,
      [
        email.toLowerCase(),
        plan,
        normalizedPlanType,
        planAmount,
        paymentMethod === 'balance' ? 'completed' : 'pending', // If full balance, mark completed immediately
        stripeLink,
        balanceToApply,
        stripeAmount,
        paymentMethod
      ]
    );

    const subscriptionId = result.rows[0].id;

    // Track referral if provided
    if (referral_code) {
      await trackReferral(email, referral_code, subscriptionId);
    }

    // If full balance payment, deduct balance and activate subscription immediately
    if (paymentMethod === 'balance') {
      const client = await pool.connect();
      try {
        await client.query('BEGIN');

        // Get current balance
        const balanceResult = await client.query(
          'SELECT approved_balance_cents FROM affiliates WHERE id = $1',
          [affiliateId]
        );
        const currentBalance = balanceResult.rows[0].approved_balance_cents;
        const newBalance = currentBalance - balanceToApply;

        // Deduct balance from affiliate
        await client.query(
          'UPDATE affiliates SET approved_balance_cents = $1, updated_at = NOW() WHERE id = $2',
          [newBalance, affiliateId]
        );

        // Record balance transaction
        await client.query(
          `INSERT INTO balance_transactions (affiliate_id, subscription_id, type, amount_cents,
                                             description, balance_before_cents, balance_after_cents)
           VALUES ($1, $2, 'payment', $3, $4, $5, $6)`,
          [
            affiliateId,
            subscriptionId,
            balanceToApply,
            `Pro subscription payment (full balance)`,
            currentBalance,
            newBalance
          ]
        );

        // Activate subscription
        const expiresAt = new Date();
        if (isAnnual) {
          expiresAt.setFullYear(expiresAt.getFullYear() + 1); // Annual: +1 year
        } else {
          expiresAt.setMonth(expiresAt.getMonth() + 1); // Monthly: +1 month
        }

        await client.query(
          `UPDATE subscriptions
           SET status = 'completed', started_at = NOW(), expires_at = $1, updated_at = NOW()
           WHERE id = $2`,
          [expiresAt, subscriptionId]
        );

        await client.query(
          `INSERT INTO users (email, plan, paid_until, created_at)
           VALUES ($1, 'paid', $2, NOW())
           ON CONFLICT (LOWER(email))
           DO UPDATE SET plan = 'paid', paid_until = $2, updated_at = NOW()`,
          [email.toLowerCase(), expiresAt]
        );

        // Update subscription plan type and pricing_tier on user record
        const activatePricingTier = PLAN_TO_PRICING_TIER[plan] || 'individual_pro';
        await client.query(
          `UPDATE users SET subscription_plan_type = $1, pricing_tier = $2 WHERE LOWER(email) = LOWER($3)`,
          [normalizedPlanType, activatePricingTier, email]
        );

        // ── family Pro: mark owner tier + link family ──────────────────
        if (isHouseholdPro) {
          await client.query(
            `UPDATE users SET subscription_tier = 'family' WHERE LOWER(email) = LOWER($1)`,
            [email]
          );
          // Link subscription to family (if one exists)
          const balOwnerUser = await client.query(
            'SELECT id FROM users WHERE LOWER(email) = LOWER($1)', [email]
          );
          if (balOwnerUser.rows.length > 0) {
            const balOwnerId = balOwnerUser.rows[0].id;
            const balHousehold = await client.query(
              'SELECT id FROM households WHERE owner_id = $1 ORDER BY created_at DESC LIMIT 1',
              [balOwnerId]
            );
            if (balHousehold.rows.length > 0) {
              await client.query(
                'UPDATE subscriptions SET household_id = $1 WHERE id = $2',
                [balHousehold.rows[0].id, subscriptionId]
              );
            }
          }
        }

        await client.query('COMMIT');

        // Process commissions asynchronously
        processCommission(subscriptionId, false).catch(err => {
          console.error('Commission processing error:', err.message);
        });

        // ── Orphan/Ghost lifecycle hooks (balance payment path) ───────────
        pool.query('SELECT id FROM users WHERE LOWER(email) = LOWER($1)', [email])
          .then(r => {
            const uid = r.rows.length > 0 ? r.rows[0].id : null;
            if (uid) {
              convertGhostToGold(uid).catch(() => {});
              processOrphanUpgrade(uid).catch(() => {});
            }
          }).catch(() => {});

        return res.json({
          subscription_id: subscriptionId,
          payment_complete: true,
          balance_used: balanceToApply,
          stripe_amount: 0,
          message: 'Subscription activated! Paid with referral balance.'
        });
      } catch (err) {
        await client.query('ROLLBACK');
        throw err;
      } finally {
        client.release();
      }
    }

    // If partial or no balance, return Stripe payment URL
    const paymentUrl = new URL(stripeLink);
    paymentUrl.searchParams.set('prefilled_email', email);
    paymentUrl.searchParams.set('client_reference_id', `sub_${subscriptionId}`);

    res.json({
      subscription_id: subscriptionId,
      payment_url: paymentUrl.toString(),
      balance_used: balanceToApply,
      stripe_amount: stripeAmount,
      message: balanceToApply > 0
        ? `Balance applied: $${(balanceToApply / 100).toFixed(2)}. Remaining: $${(stripeAmount / 100).toFixed(2)} via Stripe.`
        : 'Proceed to Stripe checkout.'
    });
  } catch (err) {
    console.error('POST /api/subscriptions/create error:', err.message);
    res.status(500).json({ error: 'Failed to create subscription' });
  }
});

app.post('/api/subscriptions/verify', async (req, res) => {
  try {
    const { subscription_id } = req.body;

    if (!subscription_id) {
      return res.status(400).json({ error: 'subscription_id required' });
    }

    const subResult = await pool.query(
      'SELECT * FROM subscriptions WHERE id = $1',
      [parseInt(subscription_id)]
    );

    if (subResult.rows.length === 0) {
      return res.status(404).json({ error: 'Subscription not found' });
    }

    const subscription = subResult.rows[0];

    if (subscription.status === 'completed') {
      return res.json({ verified: true, status: 'completed' });
    }

    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      // Determine billing period
      const isSovereignVerify = subscription.plan === 'sovereign_executive' || subscription.plan_type === 'one_time';
      const isAnnual = !isSovereignVerify && (
        subscription.plan_type === 'annual' ||
        subscription.amount_cents === INDIVIDUAL_ANNUAL_CENTS
      );

      const expiresAt = new Date();
      if (isSovereignVerify) {
        expiresAt.setFullYear(expiresAt.getFullYear() + 100); // Lifetime
      } else if (isAnnual) {
        expiresAt.setFullYear(expiresAt.getFullYear() + 1); // Annual: +1 year
      } else {
        expiresAt.setMonth(expiresAt.getMonth() + 1); // Monthly: +1 month
      }

      // If this subscription used balance (mixed payment), deduct it now
      if (subscription.payment_method === 'mixed' && subscription.balance_applied_cents > 0) {
        const affiliateResult = await client.query(
          'SELECT id, approved_balance_cents FROM affiliates WHERE LOWER(email) = LOWER($1)',
          [subscription.email.toLowerCase()]
        );

        if (affiliateResult.rows.length > 0) {
          const affiliate = affiliateResult.rows[0];
          const currentBalance = affiliate.approved_balance_cents;
          const balanceToApply = subscription.balance_applied_cents;
          const newBalance = Math.max(0, currentBalance - balanceToApply);

          // Deduct balance
          await client.query(
            'UPDATE affiliates SET approved_balance_cents = $1, updated_at = NOW() WHERE id = $2',
            [newBalance, affiliate.id]
          );

          // Record transaction
          await client.query(
            `INSERT INTO balance_transactions (affiliate_id, subscription_id, type, amount_cents,
                                               description, balance_before_cents, balance_after_cents)
             VALUES ($1, $2, 'payment', $3, $4, $5, $6)`,
            [
              affiliate.id,
              subscription_id,
              balanceToApply,
              `Pro subscription payment (balance portion of mixed payment)`,
              currentBalance,
              newBalance
            ]
          );
        }
      }

      await client.query(
        `UPDATE subscriptions
         SET status = 'completed', started_at = NOW(), expires_at = $1, updated_at = NOW()
         WHERE id = $2`,
        [expiresAt, subscription_id]
      );

      await client.query(
        `INSERT INTO users (email, plan, paid_until, created_at)
         VALUES ($1, 'paid', $2, NOW())
         ON CONFLICT (LOWER(email))
         DO UPDATE SET plan = 'paid', paid_until = $2, updated_at = NOW()`,
        [subscription.email.toLowerCase(), expiresAt]
      );

      // Update subscription plan type and pricing_tier on user record
      const verifyPlanType = subscription.plan_type || (isAnnual ? 'annual' : 'monthly');
      const verifyPricingTier = PLAN_TO_PRICING_TIER[subscription.plan] || 'individual_pro';
      await client.query(
        `UPDATE users SET subscription_plan_type = $1, pricing_tier = $2 WHERE LOWER(email) = LOWER($3)`,
        [verifyPlanType, verifyPricingTier, subscription.email]
      );

      // ── family Pro: mark owner tier + grant Pro to all active members ──
      if (subscription.plan === 'household_pro') {
        // Mark owner as family tier
        await client.query(
          `UPDATE users SET subscription_tier = 'family' WHERE LOWER(email) = LOWER($1)`,
          [subscription.email]
        );

        // Find the family owned by this user and grant Pro to all active members
        const ownerUser = await client.query(
          'SELECT id FROM users WHERE LOWER(email) = LOWER($1)', [subscription.email]
        );
        if (ownerUser.rows.length > 0) {
          const ownerId = ownerUser.rows[0].id;
          // Update subscription record with household_id (link the two)
          const ownerHousehold = await client.query(
            'SELECT id FROM households WHERE owner_id = $1 ORDER BY created_at DESC LIMIT 1',
            [ownerId]
          );
          if (ownerHousehold.rows.length > 0) {
            const householdId = ownerHousehold.rows[0].id;
            await client.query(
              'UPDATE subscriptions SET household_id = $1 WHERE id = $2',
              [householdId, subscription_id]
            );
          }
        }
      }

      await client.query('COMMIT');

      // Resolve the user ID from subscription email for orphan/ghost hooks
      const subUserResult = await pool.query(
        'SELECT id FROM users WHERE LOWER(email) = LOWER($1)', [subscription.email]
      );
      const subUserId = subUserResult.rows.length > 0 ? subUserResult.rows[0].id : null;

      processCommission(parseInt(subscription_id), false).catch(err => {
        console.error('Commission processing error:', err.message);
      });

      // ── Orphan/Ghost lifecycle hooks ──────────────────────────────────────
      // Run async, non-blocking, non-fatal
      if (subUserId) {
        // Ghost → Gold: if this user was a ghost slot, activate them
        convertGhostToGold(subUserId).catch(() => {});
        // Orphan placement: if this user was in the holding tank, run placement
        processOrphanUpgrade(subUserId).catch(() => {});
      }

      res.json({ verified: true, status: 'completed' });
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('POST /api/subscriptions/verify error:', err.message);
    res.status(500).json({ error: 'Failed to verify subscription' });
  }
});

// ═══════════════════════════════════════════════════════════
// ─── STRIPE WEBHOOK ─────────────────────────────────────
// ═══════════════════════════════════════════════════════════
// Handles automatic subscription renewals, cancellations, and payment failures.
// Requires STRIPE_SECRET_KEY and STRIPE_WEBHOOK_SECRET env vars.
// Register this URL in the Stripe Dashboard: https://financial-revolution.polsia.app/api/stripe-webhook
// Events to enable: checkout.session.completed, invoice.payment_succeeded,
//                   customer.subscription.deleted, invoice.payment_failed

// Accounts that must never be affected by webhook events (all owner emails)
const STRIPE_EXEMPT_EMAILS = ['dianes3cps@gmail.com', 'ecci2760@gmail.com', 'ecci2760f@gmail.com'];

app.post('/api/stripe-webhook', async (req, res) => {
  const sig = req.headers['stripe-signature'];
  const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

  if (!webhookSecret) {
    console.warn('[Stripe Webhook] STRIPE_WEBHOOK_SECRET not set — rejecting event');
    return res.status(400).json({ error: 'Webhook not configured' });
  }

  if (!process.env.STRIPE_SECRET_KEY) {
    console.warn('[Stripe Webhook] STRIPE_SECRET_KEY not set — cannot initialize Stripe');
    return res.status(400).json({ error: 'Stripe not configured' });
  }

  let event;
  try {
    const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
    event = stripe.webhooks.constructEvent(req.body, sig, webhookSecret);
  } catch (err) {
    console.error('[Stripe Webhook] Signature verification failed:', err.message);
    return res.status(400).json({ error: `Webhook signature verification failed: ${err.message}` });
  }

  console.log('[Stripe Webhook] Received event:', event.type, event.id);

  try {
    switch (event.type) {

      // ── checkout.session.completed ──────────────────────────────────────────
      // Fires when a customer pays via a Stripe payment link.
      // We use client_reference_id=sub_{subscriptionId} to link back to our DB.
      // Auto-verifies the subscription (replaces manual /api/subscriptions/verify call).
      case 'checkout.session.completed': {
        const session = event.data.object;
        const clientRef = session.client_reference_id; // "sub_123"
        const stripeCustomerId = session.customer;
        const stripeSubscriptionId = session.subscription;

        if (!clientRef || !clientRef.startsWith('sub_')) {
          console.log('[Stripe Webhook] checkout.session.completed: no valid client_reference_id, skipping');
          break;
        }

        const subscriptionId = parseInt(clientRef.replace('sub_', ''), 10);
        if (isNaN(subscriptionId)) {
          console.warn('[Stripe Webhook] checkout.session.completed: unparseable client_reference_id:', clientRef);
          break;
        }

        const subResult = await pool.query('SELECT * FROM subscriptions WHERE id = $1', [subscriptionId]);
        if (subResult.rows.length === 0) {
          console.warn('[Stripe Webhook] checkout.session.completed: subscription not found:', subscriptionId);
          break;
        }
        const sub = subResult.rows[0];

        if (STRIPE_EXEMPT_EMAILS.includes(sub.email.toLowerCase())) {
          console.log('[Stripe Webhook] Skipping exempt account:', sub.email);
          break;
        }

        // If already completed, just store Stripe IDs (idempotent)
        if (sub.status === 'completed') {
          console.log('[Stripe Webhook] checkout.session.completed: subscription already completed, updating Stripe IDs:', subscriptionId);
          if (stripeSubscriptionId) {
            await pool.query(
              `UPDATE users SET stripe_subscription_id = $1, subscription_status = 'active', updated_at = NOW()
               WHERE LOWER(email) = LOWER($2)`,
              [stripeSubscriptionId, sub.email]
            );
          }
          if (stripeCustomerId || stripeSubscriptionId) {
            await pool.query(
              `UPDATE subscriptions
               SET stripe_customer_id = COALESCE($1, stripe_customer_id),
                   stripe_subscription_id = COALESCE($2, stripe_subscription_id),
                   updated_at = NOW()
               WHERE id = $3`,
              [stripeCustomerId, stripeSubscriptionId, subscriptionId]
            );
          }
          break;
        }

        // Determine billing period
        // sovereign_executive is a one-time payment — access for 100 years
        const isSovereign = sub.plan === 'sovereign_executive';
        const isAnnual = !isSovereign && (
          sub.plan_type === 'annual' ||
          sub.amount_cents === INDIVIDUAL_ANNUAL_CENTS
        );
        const expiresAt = new Date();
        if (isSovereign) {
          expiresAt.setFullYear(expiresAt.getFullYear() + 100); // Lifetime access
        } else if (isAnnual) {
          expiresAt.setFullYear(expiresAt.getFullYear() + 1);
        } else {
          expiresAt.setMonth(expiresAt.getMonth() + 1);
        }

        const whClient = await pool.connect();
        try {
          await whClient.query('BEGIN');

          // If mixed payment, deduct balance portion
          if (sub.payment_method === 'mixed' && sub.balance_applied_cents > 0) {
            const affResult = await whClient.query(
              'SELECT id, approved_balance_cents FROM affiliates WHERE LOWER(email) = LOWER($1)',
              [sub.email.toLowerCase()]
            );
            if (affResult.rows.length > 0) {
              const aff = affResult.rows[0];
              const newBal = Math.max(0, aff.approved_balance_cents - sub.balance_applied_cents);
              await whClient.query(
                'UPDATE affiliates SET approved_balance_cents = $1, updated_at = NOW() WHERE id = $2',
                [newBal, aff.id]
              );
              await whClient.query(
                `INSERT INTO balance_transactions
                 (affiliate_id, subscription_id, type, amount_cents, description, balance_before_cents, balance_after_cents)
                 VALUES ($1, $2, 'payment', $3, $4, $5, $6)`,
                [aff.id, subscriptionId, sub.balance_applied_cents,
                 'Pro subscription payment (webhook auto-verify, balance portion)',
                 aff.approved_balance_cents, newBal]
              );
            }
          }

          // Mark subscription completed, store Stripe IDs
          await whClient.query(
            `UPDATE subscriptions
             SET status = 'completed', started_at = NOW(), expires_at = $1,
                 stripe_customer_id = COALESCE($2, stripe_customer_id),
                 stripe_subscription_id = COALESCE($3, stripe_subscription_id),
                 updated_at = NOW()
             WHERE id = $4`,
            [expiresAt, stripeCustomerId, stripeSubscriptionId, subscriptionId]
          );

          // Activate Pro on user record
          await whClient.query(
            `INSERT INTO users (email, plan, paid_until, stripe_subscription_id, subscription_status, created_at)
             VALUES ($1, 'paid', $2, $3, 'active', NOW())
             ON CONFLICT (LOWER(email))
             DO UPDATE SET plan = 'paid', paid_until = $2,
                           stripe_subscription_id = COALESCE($3, users.stripe_subscription_id),
                           subscription_status = 'active', updated_at = NOW()`,
            [sub.email.toLowerCase(), expiresAt, stripeSubscriptionId]
          );

          // Update subscription plan type and pricing_tier on user record
          const whPlanType = sub.plan_type || (isAnnual ? 'annual' : 'monthly');
          const whPricingTier = PLAN_TO_PRICING_TIER[sub.plan] || 'individual_pro';
          await whClient.query(
            `UPDATE users SET subscription_plan_type = $1, pricing_tier = $2 WHERE LOWER(email) = LOWER($3)`,
            [whPlanType, whPricingTier, sub.email]
          );

          // family Pro: mark tier + link family
          if (sub.plan === 'household_pro') {
            await whClient.query(
              `UPDATE users SET subscription_tier = 'family' WHERE LOWER(email) = LOWER($1)`,
              [sub.email]
            );
            const whOwner = await whClient.query(
              'SELECT id FROM users WHERE LOWER(email) = LOWER($1)', [sub.email]
            );
            if (whOwner.rows.length > 0) {
              const whHousehold = await whClient.query(
                'SELECT id FROM households WHERE owner_id = $1 ORDER BY created_at DESC LIMIT 1',
                [whOwner.rows[0].id]
              );
              if (whHousehold.rows.length > 0) {
                await whClient.query(
                  'UPDATE subscriptions SET household_id = $1 WHERE id = $2',
                  [whHousehold.rows[0].id, subscriptionId]
                );
              }
            }
          }

          await whClient.query('COMMIT');
        } catch (err) {
          await whClient.query('ROLLBACK');
          throw err;
        } finally {
          whClient.release();
        }

        // Async lifecycle hooks
        const whUserRes = await pool.query(
          'SELECT id FROM users WHERE LOWER(email) = LOWER($1)', [sub.email]
        );
        const whUserId = whUserRes.rows.length > 0 ? whUserRes.rows[0].id : null;
        processCommission(subscriptionId, false).catch(err =>
          console.error('[Stripe Webhook] Commission error:', err.message));
        if (whUserId) {
          convertGhostToGold(whUserId).catch(() => {});
          processOrphanUpgrade(whUserId).catch(() => {});
          // If this user was a family plan member, unfreeze their frozen commissions on Pro upgrade
          if (sub.plan !== 'household_pro') {
            unfreezeCommissionsAfterProUpgrade(whUserId).catch(() => {});
          }
          // Check Junior affiliate unlock (18th birthday + curriculum + milestones)
          checkAndGrantAffiliateAccess(whUserId).catch(() => {});
        }

        console.log(`[Stripe Webhook] checkout.session.completed: activated sub #${subscriptionId} for ${sub.email}, expires ${expiresAt.toISOString()}`);
        break;
      }

      // ── invoice.payment_succeeded ────────────────────────────────────────────
      // Fires on every successful renewal payment.
      // Extends paid_until by 1 month or 1 year based on the subscription plan.
      case 'invoice.payment_succeeded': {
        const invoice = event.data.object;

        // First payment is handled by checkout.session.completed — skip here
        if (invoice.billing_reason === 'subscription_create') {
          console.log('[Stripe Webhook] invoice.payment_succeeded: billing_reason=subscription_create, handled by checkout.session.completed, skipping');
          break;
        }

        const stripeSubId = invoice.subscription;
        if (!stripeSubId) {
          console.log('[Stripe Webhook] invoice.payment_succeeded: no subscription ID, skipping');
          break;
        }

        // Look up user by stripe_subscription_id
        const renewUserRes = await pool.query(
          `SELECT id, email, plan, paid_until, subscription_plan_type
           FROM users WHERE stripe_subscription_id = $1`,
          [stripeSubId]
        );

        if (renewUserRes.rows.length === 0) {
          console.warn('[Stripe Webhook] invoice.payment_succeeded: no user found for stripe_subscription_id:', stripeSubId);
          break;
        }
        const renewUser = renewUserRes.rows[0];

        if (STRIPE_EXEMPT_EMAILS.includes(renewUser.email.toLowerCase())) {
          console.log('[Stripe Webhook] Skipping exempt account:', renewUser.email);
          break;
        }

        // Get plan_type from most recent completed subscription record
        const planTypeRes = await pool.query(
          `SELECT plan_type, plan FROM subscriptions
           WHERE LOWER(email) = LOWER($1) AND status = 'completed'
           ORDER BY created_at DESC LIMIT 1`,
          [renewUser.email]
        );
        const planType = planTypeRes.rows.length > 0
          ? planTypeRes.rows[0].plan_type
          : (renewUser.subscription_plan_type || 'monthly');
        const subPlan = planTypeRes.rows.length > 0 ? planTypeRes.rows[0].plan : 'pro';
        const isAnnualRenewal = planType === 'annual';

        // Extend from current paid_until (or now if already expired)
        const currentPaidUntil = renewUser.paid_until ? new Date(renewUser.paid_until) : new Date();
        const baseDate = currentPaidUntil > new Date() ? currentPaidUntil : new Date();
        const newPaidUntil = new Date(baseDate);
        if (isAnnualRenewal) {
          newPaidUntil.setFullYear(newPaidUntil.getFullYear() + 1);
        } else {
          newPaidUntil.setMonth(newPaidUntil.getMonth() + 1);
        }

        await pool.query(
          `UPDATE users
           SET plan = 'paid', paid_until = $1, subscription_status = 'active', updated_at = NOW()
           WHERE id = $2`,
          [newPaidUntil, renewUser.id]
        );

        // Update the subscription record's expires_at (most recent completed subscription for this user)
        await pool.query(
          `UPDATE subscriptions
           SET expires_at = $1, updated_at = NOW()
           WHERE id = (
             SELECT id FROM subscriptions
             WHERE LOWER(email) = LOWER($2) AND status = 'completed'
               AND (stripe_subscription_id = $3 OR stripe_subscription_id IS NULL)
             ORDER BY created_at DESC
             LIMIT 1
           )`,
          [newPaidUntil, renewUser.email, stripeSubId]
        );

        // family Pro note: member access inherits from owner's paid_until via hasProAccess()
        // No additional action needed — the owner's paid_until extension covers all members.

        console.log(`[Stripe Webhook] invoice.payment_succeeded: extended Pro for ${renewUser.email} until ${newPaidUntil.toISOString()} (${planType})`);
        break;
      }

      // ── customer.subscription.deleted ────────────────────────────────────────
      // Fires when a subscription is cancelled (immediately or at period end).
      // We mark the subscription cancelled but leave paid_until intact —
      // access expires naturally when paid_until is reached.
      case 'customer.subscription.deleted': {
        const deletedSub = event.data.object;
        const delStripeSubId = deletedSub.id;

        const delUserRes = await pool.query(
          'SELECT id, email, paid_until FROM users WHERE stripe_subscription_id = $1',
          [delStripeSubId]
        );

        if (delUserRes.rows.length === 0) {
          console.warn('[Stripe Webhook] customer.subscription.deleted: no user found for:', delStripeSubId);
          break;
        }
        const delUser = delUserRes.rows[0];

        if (STRIPE_EXEMPT_EMAILS.includes(delUser.email.toLowerCase())) break;

        // Mark subscription cancelled; access expires when paid_until is reached
        await pool.query(
          `UPDATE users SET subscription_status = 'cancelled', updated_at = NOW() WHERE id = $1`,
          [delUser.id]
        );
        await pool.query(
          `UPDATE subscriptions SET status = 'cancelled', updated_at = NOW()
           WHERE stripe_subscription_id = $1`,
          [delStripeSubId]
        );

        console.log(`[Stripe Webhook] customer.subscription.deleted: marked cancelled for ${delUser.email}, access expires ${delUser.paid_until || 'immediately'}`);
        break;
      }

      // ── invoice.payment_failed ───────────────────────────────────────────────
      // Fires when a renewal payment fails.
      // We flag the account as past_due. Stripe will retry automatically.
      // Access continues until paid_until expires naturally.
      case 'invoice.payment_failed': {
        const failedInvoice = event.data.object;
        const failStripeSubId = failedInvoice.subscription;
        if (!failStripeSubId) break;

        const failUserRes = await pool.query(
          'SELECT id, email, paid_until FROM users WHERE stripe_subscription_id = $1',
          [failStripeSubId]
        );

        if (failUserRes.rows.length === 0) {
          console.warn('[Stripe Webhook] invoice.payment_failed: no user found for:', failStripeSubId);
          break;
        }
        const failUser = failUserRes.rows[0];

        if (STRIPE_EXEMPT_EMAILS.includes(failUser.email.toLowerCase())) break;

        // Flag as past_due — access still continues until paid_until expires
        await pool.query(
          `UPDATE users SET subscription_status = 'past_due', updated_at = NOW() WHERE id = $1`,
          [failUser.id]
        );

        console.log(`[Stripe Webhook] invoice.payment_failed: flagged past_due for ${failUser.email} (access until ${failUser.paid_until || 'expired'})`);
        break;
      }

      default:
        console.log('[Stripe Webhook] Unhandled event type:', event.type);
    }
  } catch (err) {
    console.error('[Stripe Webhook] Error processing event', event.type, ':', err.message, err.stack);
    return res.status(500).json({ error: 'Internal webhook processing error' });
  }

  res.json({ received: true });
});

app.get('/api/subscriptions/status', async (req, res) => {
  try {
    const { email } = req.query;

    if (!email) {
      return res.status(400).json({ error: 'email query parameter required' });
    }

    const userResult = await pool.query(
      `SELECT id, email, plan, paid_until, is_creator, promo_code_used, promo_grace_expired,
              subscription_plan_type
       FROM users WHERE LOWER(email) = LOWER($1)`,
      [email]
    );

    if (userResult.rows.length === 0) {
      return res.json({ plan: 'free', paid: false });
    }

    const user = userResult.rows[0];
    // Use centralized Pro access check (single source of truth)
    const hasPro = await hasProAccess(user);

    res.json({
      plan: hasPro ? 'paid' : 'free',
      paid: hasPro,
      paid_until: user.paid_until,
      is_creator: user.is_creator || (user.email && user.email.toLowerCase() === CREATOR_EMAIL) || false,
      has_promo: !!user.promo_code_used,
      subscription_plan_type: user.subscription_plan_type || 'monthly'
    });
  } catch (err) {
    console.error('GET /api/subscriptions/status error:', err.message);
    res.status(500).json({ error: 'Failed to get subscription status' });
  }
});

