// ═══════════════════════════════════════════════════════════
// ─── AFFILIATE SYSTEM ────────────────────────────────────
// ═══════════════════════════════════════════════════════════
// Old 50%/10% model removed — all commission rates are in FG_INITIAL_RATES / FG_RECURRING_RATES below
const PAYOUT_MINIMUM_CENTS = 5000;

// Future Generations 5-Level Commission Rates (percentage of payment)
// Flat rate: same for initial AND all renewals. 31% total max payout, 69% margin.
// relationship_tag (FAMILY / CLOSE_CONTACT) is disclosure-only — never alter these standard rates.
// Use lib/relationshipTags.resolveCommissionRates() for payout parity helpers.
const FG_INITIAL_RATES = [16, 8, 4, 2, 1]; // Levels 1-5 (= STANDARD_COMMISSION_RATES)
const FG_RECURRING_RATES = [16, 8, 4, 2, 1]; // Levels 1-5 (same as initial)

// Legacy Placement Startup Rates — Month 1 ONLY (20-5-3-2-1 = 31% total)
// Enroller (who recruited) = 20%, Placement Parent = 5%,
// Tree L3 = 3%, Tree L4 = 2%, Tree L5 = 1%
const FG_LEGACY_ENROLLER_RATE = 20;       // Enroller gets this on Month 1
const FG_LEGACY_PLACEMENT_RATES = [5, 3, 2, 1]; // Placement Parent + 3 tree levels above them

function generateReferralCode(email) {
  const username = email.split('@')[0].replace(/[^a-zA-Z0-9]/g, '');
  const random = Math.random().toString(36).substring(2, 6).toUpperCase();
  return `${username.substring(0, 8).toUpperCase()}${random}`;
}

// ─── MLM TREE PLACEMENT HELPERS ─────────────────────────────────────────────

// Count all Level-1 (first-line, directly under company) affiliates.
// During seed phase: first 100 codeless joiners get Level 1.
async function getFirstLineAffiliateCount() {
  const result = await pool.query(
    "SELECT COUNT(*) FROM affiliates WHERE affiliate_level = 1"
  );
  return parseInt(result.rows[0].count, 10);
}

// Breadth-first placement: find the best parent node for a codeless post-seed signup.
// Algorithm: find the affiliate at the shallowest level with the fewest direct children.
// Tie-break: shallowest level first, then oldest (created_at ASC).
// This naturally fills Level 2 across all Level-1 nodes before going to Level 3, etc.
async function bfsAffiliatePlacement() {
  const result = await pool.query(`
    SELECT a1.id, a1.affiliate_level, a1.user_id,
           COUNT(a2.id) AS child_count
    FROM affiliates a1
    LEFT JOIN affiliates a2 ON a2.parent_affiliate_id = a1.id
    WHERE a1.affiliate_level < 5
      AND a1.status = 'active'
    GROUP BY a1.id, a1.affiliate_level, a1.user_id, a1.created_at
    ORDER BY COUNT(a2.id) ASC, a1.affiliate_level ASC, a1.created_at ASC
    LIMIT 1
  `);

  if (result.rows.length === 0) {
    // Fallback: place at Level 1 (shouldn't happen post-seed)
    return { parentAffiliateId: null, affiliateLevel: 1, placementMethod: 'bfs', parentUserId: null };
  }

  const parent = result.rows[0];
  return {
    parentAffiliateId: parent.id,
    affiliateLevel: parent.affiliate_level + 1,
    placementMethod: 'bfs',
    parentUserId: parent.user_id
  };
}

// Get the front-line child count for an affiliate (direct recruits, non-revoked, non-ghost)
async function getAffiliateFrontLineWidth(affiliateId) {
  const result = await pool.query(
    `SELECT COUNT(*) AS count FROM affiliates
     WHERE parent_affiliate_id = $1 AND status != 'revoked'`,
    [affiliateId]
  );
  return parseInt(result.rows[0].count);
}

// Get the next leg position for an affiliate's front line (1-indexed)
async function getNextLegPosition(affiliateId) {
  const result = await pool.query(
    `SELECT COALESCE(MAX(leg_position), 0) + 1 AS next_pos
     FROM affiliates
     WHERE parent_affiliate_id = $1 AND status != 'revoked'`,
    [affiliateId]
  );
  return parseInt(result.rows[0].next_pos);
}

// Find the weakest leg (fewest total descendants) for Legacy Placement overflow.
// "Weakest" = the direct child with the smallest subtree size (closest to needing
// a Level-5 anchor). Ties broken by oldest creation date.
async function findWeakestLeg(affiliateId) {
  const result = await pool.query(`
    WITH direct_children AS (
      SELECT id, user_id, affiliate_level, created_at
      FROM affiliates
      WHERE parent_affiliate_id = $1
        AND status != 'revoked'
        AND is_ghost_slot = false
    ),
    subtree_counts AS (
      SELECT dc.id, dc.user_id, dc.affiliate_level, dc.created_at,
             (
               SELECT COUNT(*)
               FROM affiliates desc_a
               WHERE desc_a.parent_affiliate_id = dc.id
                 AND desc_a.status != 'revoked'
             ) AS direct_child_count
      FROM direct_children dc
    )
    SELECT id, user_id, affiliate_level, direct_child_count
    FROM subtree_counts
    ORDER BY direct_child_count ASC, created_at ASC
    LIMIT 1
  `, [affiliateId]);

  return result.rows.length > 0 ? result.rows[0] : null;
}

// Determine where a joining user should be placed in the affiliate tree.
// 4x5 Gated Progression rules:
//   1. Referral code (referred_by_user_id set):
//      a. Referrer has capacity in current phase (< current_phase * 4 legs) → place directly
//      b. Referrer at phase capacity → Legacy Placement: drop to weakest leg
//   2. Seed phase (< 100 Level-1 affiliates) → Level 1 (corporate/seed)
//   3. Post-seed → BFS auto-placement under corporate node
async function determineAffiliatePlacement(userId) {
  const userResult = await pool.query(
    'SELECT id, referred_by_user_id FROM users WHERE id = $1', [userId]
  );
  if (userResult.rows.length === 0) {
    return { parentAffiliateId: null, affiliateLevel: 1, placementMethod: 'seed', parentUserId: null, isLegacyPlacement: false, enrollerId: null };
  }

  const referredByUserId = userResult.rows[0].referred_by_user_id;

  // ── Case 1: User was referred via a referral code ─────────────────────────
  if (referredByUserId) {
    const parentAff = await pool.query(
      `SELECT id, affiliate_level, current_phase FROM affiliates
       WHERE user_id = $1 AND status != 'revoked'`,
      [referredByUserId]
    );

    if (parentAff.rows.length > 0) {
      const p = parentAff.rows[0];
      const currentPhase = p.current_phase || 1;
      const maxWidth = currentPhase * 4; // 4x5: 4 legs per phase, max 20 total

      const currentWidth = await getAffiliateFrontLineWidth(p.id);

      if (currentWidth < maxWidth) {
        // ── Direct placement: referrer has capacity in current phase ──────
        const nextPos = await getNextLegPosition(p.id);
        return {
          parentAffiliateId: p.id,
          affiliateLevel: (p.affiliate_level || 1) + 1,
          placementMethod: 'code',
          parentUserId: referredByUserId,
          isLegacyPlacement: false,
          enrollerId: null,
          legPosition: nextPos
        };
      } else {
        // ── Legacy Placement: referrer at phase capacity ──────────────────
        // Drop recruit into the referrer's weakest leg (fewest descendants).
        // Enroller earns 20% Month 1 (vs standard 16%).
        console.log(`[Placement] ${referredByUserId} at phase capacity (${currentWidth}/${maxWidth}) → Legacy Placement for user ${userId}`);
        const weakestLeg = await findWeakestLeg(p.id);

        if (weakestLeg) {
          const nextPos = await getNextLegPosition(weakestLeg.id);
          return {
            parentAffiliateId: weakestLeg.id,
            affiliateLevel: (weakestLeg.affiliate_level || 1) + 1,
            placementMethod: 'legacy_drop',
            parentUserId: weakestLeg.user_id,
            isLegacyPlacement: true,
            enrollerId: p.id, // original recruiter (earns 20% Month 1)
            legPosition: nextPos
          };
        }

        // Fallback: place directly despite capacity (edge case, no legs exist yet)
        const nextPosFallback = await getNextLegPosition(p.id);
        return {
          parentAffiliateId: p.id,
          affiliateLevel: (p.affiliate_level || 1) + 1,
          placementMethod: 'code',
          parentUserId: referredByUserId,
          isLegacyPlacement: false,
          enrollerId: null,
          legPosition: nextPosFallback
        };
      }
    }

    // Referrer exists but isn't an affiliate yet — place under them at level 2
    return {
      parentAffiliateId: null,
      affiliateLevel: 2,
      placementMethod: 'code',
      parentUserId: referredByUserId,
      isLegacyPlacement: false,
      enrollerId: null,
      legPosition: 1
    };
  }

  // ── Case 2: No referral code — check seed phase ───────────────────────────
  // Corporate/seed placements have unlimited width (Master Node has no phase cap).
  const firstLineCount = await getFirstLineAffiliateCount();
  if (firstLineCount < 100) {
    return { parentAffiliateId: null, affiliateLevel: 1, placementMethod: 'seed', parentUserId: null, isLegacyPlacement: false, enrollerId: null };
  }

  // ── Case 3: Post-seed — BFS placement ────────────────────────────────────
  // BFS under the corporate node has no width cap (infinite Master Node width).
  const bfsResult = await bfsAffiliatePlacement();
  return { ...bfsResult, isLegacyPlacement: false, enrollerId: null };
}

// ═══════════════════════════════════════════════════════════
// ─── ORPHAN PLACEMENT SYSTEM ─────────────────────────────
// ═══════════════════════════════════════════════════════════

// ── MERIT GATE — Company Gift Slot Mapping ────────────────────────────────────
//
// Under the 3:1 Merit Gate system, each affiliate receives a maximum of 3 company
// gifts, placed at slots 1, 5, and 9.  Slots 2-4, 6-8 are user-recruited.
//
// NO AUTO-FILL: Company gift slots are awarded only through merit-based queue
// placement via the Master Valve sliding-scale algorithm.  There is no timed
// auto-fill safety net.  The 14-day silent Slot 1 auto-fill (runSilentAutoFill)
// has been permanently disabled.  Orphans without an eligible merit-queue
// recipient remain in the pool until a qualifying affiliate earns placement.
//
//   Slot 1 : 1st company gift  (merit queue — no auto-fill)
//   Slot 5 : 2nd company gift  (gate: active_personals >= 3 required)
//   Slot 9 : 3rd company gift  (final — no gate beyond personals from Slot 5)
//   > Slot 9 : no more company gifts (returns null)
//
// Width limit: 20 total slots per affiliate (preserved from 4x5 system).
function getOrphanSlotForPhase(phase) {
  // Maps phase → first available company gift slot for that phase.
  // Only phases 1-3 have company gifts under the 3:1 Merit Gate.
  if (phase === 1) return 1;
  if (phase === 2) return 5;
  if (phase === 3) return 9;
  // Phases 4-5 no longer yield company gifts
  return null;
}

// Returns the next company gift slot after the current one.
// After 3 gifts (slot 9) → null (eligibility ends).
function getNextCompanyGiftSlot(currentSlot) {
  if (currentSlot === 1) return 5;
  if (currentSlot === 5) return 9;
  return null; // slot 9 was the 3rd and final gift
}

// ── MASTER VALVE — Sliding-Scale Orphan Distribution ─────────────────────────
//
// The cycle length is cached in orphan_placement_config.current_cycle_length and
// updated weekly by the recalculateMasterValve() job in affiliate-jobs.js.
//
// Tiers (based on active legs from Company Master Node):
//   Startup  (1-20  legs): cycle=5  → 4 field + 1 corp per cycle
//   Growth   (21-50 legs): cycle=3  → 2 field + 1 corp per cycle
//   Sovereign (51+  legs): cycle=50 → 49 field + 1 corp per cycle
//
// Returns the cycle length for the current valve tier.
// Reads from DB cache; falls back to 5 (startup) if table/row not yet seeded.
async function getMasterValveCycleLength(client) {
  const result = await client.query(
    'SELECT current_cycle_length FROM orphan_placement_config WHERE id = 1'
  );
  if (result.rows.length === 0) return 5; // Startup fallback
  return result.rows[0].current_cycle_length || 5;
}

// Count active direct legs from the Company Master Node.
// "Legs" = direct active children of the master node in the affiliate tree.
async function getActiveLegCountFromMaster(client) {
  const result = await client.query(`
    SELECT COUNT(*) AS leg_count
    FROM affiliates a
    JOIN affiliates master ON master.is_master_node = true
    WHERE a.parent_affiliate_id = master.id
      AND a.status = 'active'
      AND a.is_ghost_slot = false
  `);
  return parseInt(result.rows[0]?.leg_count || 0);
}

// Determine if the next orphan goes to Field or Corp.
// Uses orphan_sequence_number to track position in the ratio cycle.
// Increments the counter. Must be called inside a transaction with FOR UPDATE.
async function determineOrphanDestination(client) {
  const configResult = await client.query(
    'SELECT orphan_sequence_number, current_cycle_length, current_valve_tier FROM orphan_placement_config WHERE id = 1 FOR UPDATE'
  );
  if (configResult.rows.length === 0) return { destination: 'field', valveTier: 'startup', activelegs: 0 };
  const config = configResult.rows[0];
  const seqNum = config.orphan_sequence_number;

  // Use cached cycle length from Master Valve (updated weekly)
  const cycleLength = config.current_cycle_length || 5;
  const valveTier = config.current_valve_tier || 'startup';
  const positionInCycle = seqNum % cycleLength;
  // Last slot in the cycle = Corp
  const destination = (positionInCycle === cycleLength - 1) ? 'corp' : 'field';

  // Advance counter
  await client.query(
    'UPDATE orphan_placement_config SET orphan_sequence_number = orphan_sequence_number + 1, updated_at = NOW() WHERE id = 1'
  );
  return { destination, valveTier };
}

// Find the longest-waiting eligible affiliate for orphan placement.
// Merit Gate eligibility rules:
//   ✅ Active, non-ghost, orphan_placement_eligible, FACTS certified
//   ✅ Has an open orphan slot queued (next_orphan_slot IS NOT NULL)
//   ✅ Has received fewer than 3 company gifts (company_gifts_received < 3)
//   ✅ Slot 5 gate: if requesting Slot 5, must have personal_recruit_count >= 3
async function findNextEligibleAffiliateForOrphan(client) {
  const result = await client.query(`
    SELECT a.id, a.user_id, a.next_orphan_slot, a.orphan_waiting_since,
           a.affiliate_level, a.company_gifts_received, a.personal_recruit_count
    FROM affiliates a
    JOIN users u ON u.id = a.user_id
    WHERE a.status = 'active'
      AND a.is_ghost_slot = false
      AND a.orphan_placement_eligible = true
      AND (u.is_facts_certified = true OR a.is_facts_certified = true)
      AND a.next_orphan_slot IS NOT NULL
      AND a.orphan_waiting_since IS NOT NULL
      AND a.company_gifts_received < 3
      AND (
        a.next_orphan_slot != 5
        OR a.personal_recruit_count >= 3
        -- Slot 5 Merit Gate: must have ≥3 active personals before receiving 2nd gift
      )
    ORDER BY a.orphan_waiting_since ASC
    LIMIT 1
  `);
  return result.rows.length > 0 ? result.rows[0] : null;
}

// Full orphan placement flow — called when a holding-tank user upgrades to Pro.
// Determines Field vs Corp via Master Valve sliding scale, then applies Merit Gate.
async function processOrphanUpgrade(userId) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Only process if user is in the pool in waiting_upgrade state
    const orphanResult = await client.query(
      `SELECT * FROM orphan_pool WHERE user_id = $1 AND status = 'waiting_upgrade'`,
      [userId]
    );
    if (orphanResult.rows.length === 0) {
      await client.query('ROLLBACK');
      return;
    }

    // Mark as upgraded (ready to place)
    await client.query(
      `UPDATE orphan_pool SET status = 'ready_to_place', upgraded_at = NOW() WHERE user_id = $1`,
      [userId]
    );

    // Determine destination via Master Valve sliding scale
    const { destination, valveTier } = await determineOrphanDestination(client);

    // Count current active legs for audit trail
    const activeLegCount = await getActiveLegCountFromMaster(client);

    if (destination === 'field') {
      const eligibleAffiliate = await findNextEligibleAffiliateForOrphan(client);

      if (eligibleAffiliate) {
        const slotNum = eligibleAffiliate.next_orphan_slot;

        // Get the orphan user's email
        const orphanUser = await client.query(
          'SELECT email, referred_by_user_id FROM users WHERE id = $1', [userId]
        );
        if (orphanUser.rows.length === 0) { await client.query('ROLLBACK'); return; }
        const orphanEmail = orphanUser.rows[0].email;

        // Check if orphan is already in affiliates (ghost slot from a previous referral — edge case)
        const existingAff = await client.query(
          'SELECT id FROM affiliates WHERE user_id = $1', [userId]
        );
        if (existingAff.rows.length === 0) {
          // Place orphan in the affiliate's tree (no level cap — 4x5 supports deep chains)
          const orphanLevel = (eligibleAffiliate.affiliate_level || 1) + 1;
          const orphanNextPos = await getNextLegPosition(eligibleAffiliate.id);
          await client.query(
            `INSERT INTO affiliates
               (user_id, email, referral_code, status, parent_affiliate_id, affiliate_level,
                placement_method, is_ghost_slot, leg_position, good_standing_started_at, created_at)
             VALUES ($1, $2, NULL, 'active', $3, $4, 'orphan', false, $5, NOW(), NOW())`,
            [userId, orphanEmail, eligibleAffiliate.id, orphanLevel, orphanNextPos]
          );
          // Link user's referred_by_user_id to the receiving affiliate's user
          await client.query(
            `UPDATE users SET referred_by_user_id = $1 WHERE id = $2 AND referred_by_user_id IS NULL`,
            [eligibleAffiliate.user_id, userId]
          );
        }

        // Mark orphan as placed
        await client.query(
          `UPDATE orphan_pool
           SET status = 'placed', placement_affiliate_id = $1, placement_slot = $2, placed_at = NOW()
           WHERE user_id = $3`,
          [eligibleAffiliate.id, slotNum, userId]
        );

        // ── Merit Gate: Advance orphan slot to next company gift position ──────
        // Company gift slots: 1 → 5 → 9 → null (max 3 gifts)
        const nextSlot = getNextCompanyGiftSlot(slotNum);

        await client.query(
          `UPDATE affiliates
           SET orphans_received        = orphans_received + 1,
               company_gifts_received  = company_gifts_received + 1,
               orphan_waiting_since    = CASE WHEN $1 IS NOT NULL THEN NOW() ELSE NULL END,
               next_orphan_slot        = $1,
               updated_at              = NOW()
           WHERE id = $2`,
          [nextSlot, eligibleAffiliate.id]
        );

        // ── Audit Log ─────────────────────────────────────────────────────────
        await client.query(
          `INSERT INTO assignment_log
             (orphan_user_id, assigned_affiliate_id, slot_number, destination,
              valve_tier, active_legs_at_time, is_auto_fill, merit_gate_passed)
           VALUES ($1, $2, $3, 'field', $4, $5, false, true)`,
          [userId, eligibleAffiliate.id, slotNum, valveTier, activeLegCount]
        );

        console.log(`[Orphan] Field placement: user ${userId} → affiliate ${eligibleAffiliate.id} slot ${slotNum} [${valveTier}]`);
      } else {
        // No eligible affiliates → fallback to Corp (all field slots blocked by Merit Gate)
        await client.query(
          `UPDATE orphan_pool SET status = 'corp_placed', placed_at = NOW() WHERE user_id = $1`, [userId]
        );
        await client.query(
          `UPDATE orphan_placement_config SET corp_front_line_width = corp_front_line_width + 1, updated_at = NOW() WHERE id = 1`
        );
        await client.query(
          `INSERT INTO assignment_log
             (orphan_user_id, assigned_affiliate_id, slot_number, destination,
              valve_tier, active_legs_at_time, is_auto_fill, merit_gate_passed)
           VALUES ($1, NULL, NULL, 'corp_fallback', $2, $3, false, false)`,
          [userId, valveTier, activeLegCount]
        );
        console.log(`[Orphan] No eligible affiliates (Merit Gate) — corp fallback for user ${userId} [${valveTier}]`);
      }
    } else {
      // Corp placement by Master Valve scaling split
      await client.query(
        `UPDATE orphan_pool SET status = 'corp_placed', placed_at = NOW() WHERE user_id = $1`, [userId]
      );
      await client.query(
        `UPDATE orphan_placement_config SET corp_front_line_width = corp_front_line_width + 1, updated_at = NOW() WHERE id = 1`
      );
      await client.query(
        `INSERT INTO assignment_log
           (orphan_user_id, assigned_affiliate_id, slot_number, destination,
            valve_tier, active_legs_at_time, is_auto_fill, merit_gate_passed)
         VALUES ($1, NULL, NULL, 'corp', $2, $3, false, true)`,
        [userId, valveTier, activeLegCount]
      );
      console.log(`[Orphan] Corp placement (Master Valve ${valveTier}): user ${userId}`);
    }

    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('[Orphan] processOrphanUpgrade error:', err.message);
  } finally {
    client.release();
  }
}

// ─── GHOST SLOT CREATION ─────────────────────────────────────────────────────
// Called at signup when a free user signs up via a referral link.
// Creates a ghost affiliate record — they hold a tree position but earn $0 commission.
async function createGhostSlotForReferral(userId, referrerId) {
  try {
    // Don't double-create
    const existing = await pool.query('SELECT id FROM affiliates WHERE user_id = $1', [userId]);
    if (existing.rows.length > 0) return;
    const inPool = await pool.query('SELECT id FROM orphan_pool WHERE user_id = $1', [userId]);
    if (inPool.rows.length > 0) return;

    // Find referrer's affiliate record
    const referrerAff = await pool.query(
      `SELECT id, affiliate_level FROM affiliates WHERE user_id = $1 AND status != 'revoked'`,
      [referrerId]
    );
    if (referrerAff.rows.length === 0) {
      // Referrer isn't an affiliate — add to orphan pool instead
      await pool.query(
        `INSERT INTO orphan_pool (user_id, status, created_at) VALUES ($1, 'waiting_upgrade', NOW()) ON CONFLICT (user_id) DO NOTHING`,
        [userId]
      );
      return;
    }

    const referrerAffiliate = referrerAff.rows[0];
    const ghostLevel = (referrerAffiliate.affiliate_level || 1) + 1;

    // Check if referrer is at 4x5 phase capacity — ghost slots count toward width
    const referrerPhase = referrerAffiliate.current_phase || 1;
    const referrerMaxWidth = referrerPhase * 4;
    const referrerCurrentWidth = await getAffiliateFrontLineWidth(referrerAffiliate.id);

    if (referrerCurrentWidth >= referrerMaxWidth) {
      // Referrer at capacity — ghost goes to orphan pool instead
      await pool.query(
        `INSERT INTO orphan_pool (user_id, status, created_at) VALUES ($1, 'waiting_upgrade', NOW()) ON CONFLICT (user_id) DO NOTHING`,
        [userId]
      );
      console.log(`[Ghost] Referrer ${referrerAffiliate.id} at capacity (${referrerCurrentWidth}/${referrerMaxWidth}) → orphan pool`);
      return;
    }

    const userResult = await pool.query('SELECT email FROM users WHERE id = $1', [userId]);
    if (userResult.rows.length === 0) return;

    const nextLegPos = await getNextLegPosition(referrerAffiliate.id);

    // Insert ghost slot record
    await pool.query(
      `INSERT INTO affiliates
         (user_id, email, referral_code, status, parent_affiliate_id, affiliate_level,
          placement_method, is_ghost_slot, leg_position, created_at)
       VALUES ($1, $2, NULL, 'active', $3, $4, 'ghost', true, $5, NOW())
       ON CONFLICT DO NOTHING`,
      [userId, userResult.rows[0].email, referrerAffiliate.id, ghostLevel, nextLegPos]
    );

    // Increment referrer's personal_recruit_count (they personally referred this person)
    // Ghost slots DO count as personal recruits — they just don't earn commission until upgraded.
    await pool.query(
      `UPDATE affiliates SET personal_recruit_count = personal_recruit_count + 1 WHERE id = $1`,
      [referrerAffiliate.id]
    );

    console.log(`[Ghost] Created ghost slot for user ${userId} under affiliate ${referrerAffiliate.id}`);
  } catch (err) {
    console.error('[Ghost] createGhostSlotForReferral error:', err.message);
    // Non-fatal
  }
}

// ─── GHOST → GOLD CONVERSION ─────────────────────────────────────────────────
// Called when a ghost slot user upgrades to Pro.
// Removes ghost status, activates the slot, triggers commission chain.
async function convertGhostToGold(userId) {
  try {
    const ghostResult = await pool.query(
      `SELECT id FROM affiliates WHERE user_id = $1 AND is_ghost_slot = true`,
      [userId]
    );
    if (ghostResult.rows.length === 0) return false;

    await pool.query(
      `UPDATE affiliates
       SET is_ghost_slot = false,
           ghost_upgraded_at = NOW(),
           good_standing_started_at = NOW(),
           status = 'active',
           updated_at = NOW()
       WHERE id = $1`,
      [ghostResult.rows[0].id]
    );
    console.log(`[Ghost→Gold] User ${userId} converted — commission chain now active`);
    return true;
  } catch (err) {
    console.error('[Ghost→Gold] convertGhostToGold error:', err.message);
    return false;
  }
}

// ── 4x5 DEPTH GATE CHECKER ────────────────────────────────────────────────────
//
// For a given affiliate ID and one of their direct children (legs), check if
// that leg's subtree has an active non-ghost member at exactly N hops depth.
// Uses a recursive CTE to walk the parent_affiliate_id chain.
//
// Returns { isDeepEnough: bool, maxDepth: number }
async function checkLegDepth(affiliateId, legId, targetDepth = 5) {
  const result = await pool.query(`
    WITH RECURSIVE leg_tree AS (
      SELECT id, parent_affiliate_id, status, is_ghost_slot, 1 AS depth
      FROM affiliates
      WHERE id = $1

      UNION ALL

      SELECT a.id, a.parent_affiliate_id, a.status, a.is_ghost_slot, lt.depth + 1
      FROM affiliates a
      JOIN leg_tree lt ON a.parent_affiliate_id = lt.id
      WHERE lt.depth < $2
        AND a.status != 'revoked'
    )
    SELECT
      MAX(depth) AS max_depth,
      BOOL_OR(depth = $2 AND status != 'revoked' AND is_ghost_slot = false) AS reached_target
    FROM leg_tree
  `, [legId, targetDepth]);

  if (!result.rows.length) return { isDeepEnough: false, maxDepth: 0 };
  const row = result.rows[0];
  return {
    isDeepEnough: row.reached_target === true,
    maxDepth: parseInt(row.max_depth) || 0
  };
}

// ── CHECK AND UPDATE DEPTH GATES ─────────────────────────────────────────────
//
// Runs daily (via affiliate-jobs.js). For every active affiliate:
//   1. Get the 4 legs in their CURRENT phase
//   2. Check if all 4 legs have an active member at 5 hops below the affiliate
//   3. Update phase_N_depth_gate_met accordingly
//   4. Re-lock if a previously-met gate no longer qualifies (member left/deactivated)
//   5. Advance current_phase if gate is met AND personal_recruit_count >= phase * 3
//
async function checkAndUpdateDepthGates(pool) {
  console.log('Running: Check and update 4x5 phase depth gates...');

  try {
    // Fetch all active, non-ghost affiliates who are building a phase tree
    const affiliatesResult = await pool.query(`
      SELECT a.id, a.email, a.current_phase, a.personal_recruit_count,
             a.phase_1_depth_gate_met, a.phase_2_depth_gate_met,
             a.phase_3_depth_gate_met, a.phase_4_depth_gate_met, a.phase_5_depth_gate_met
      FROM affiliates a
      WHERE a.status = 'active'
        AND a.is_ghost_slot = false
      ORDER BY a.id ASC
    `);

    let phaseAdvances = 0;
    let gatesUpdated = 0;
    let relocks = 0;

    for (const aff of affiliatesResult.rows) {
      const phase = aff.current_phase || 1;

      // Get this affiliate's direct children (legs), ordered by creation / leg_position
      const legsResult = await pool.query(`
        SELECT id, leg_position
        FROM affiliates
        WHERE parent_affiliate_id = $1
          AND status != 'revoked'
        ORDER BY COALESCE(leg_position, id) ASC
        LIMIT 20
      `, [aff.id]);

      const allLegs = legsResult.rows;

      // The 4 legs that belong to the current phase
      // Phase 1 = legs at positions 1-4, Phase 2 = 5-8, Phase 3 = 9-12, etc.
      const phaseStartIdx = (phase - 1) * 4;
      const phaseEndIdx = phase * 4;
      const phaseLegs = allLegs.slice(phaseStartIdx, phaseEndIdx);

      const fieldName = `phase_${phase}_depth_gate_met`;
      const currentGateMet = aff[fieldName] === true;

      // Gate cannot be met if the phase doesn't have all 4 legs yet
      if (phaseLegs.length < 4) {
        if (currentGateMet) {
          // Was met — re-lock
          await pool.query(
            `UPDATE affiliates SET ${fieldName} = false, updated_at = NOW() WHERE id = $1`,
            [aff.id]
          );
          relocks++;
          console.log(`[DepthGate] Phase ${phase} RE-LOCKED for ${aff.email} (only ${phaseLegs.length}/4 legs)`);
        }
        continue;
      }

      // Check if all 4 legs in this phase have an active member at depth 5
      let allLegsDeep = true;
      for (const leg of phaseLegs) {
        const { isDeepEnough } = await checkLegDepth(aff.id, leg.id, 5);
        if (!isDeepEnough) {
          allLegsDeep = false;
          break;
        }
      }

      // Update gate status if it changed
      if (allLegsDeep !== currentGateMet) {
        await pool.query(
          `UPDATE affiliates SET ${fieldName} = $1, updated_at = NOW() WHERE id = $2`,
          [allLegsDeep, aff.id]
        );
        gatesUpdated++;

        if (!allLegsDeep && currentGateMet) {
          relocks++;
          console.log(`[DepthGate] Phase ${phase} RE-LOCKED for ${aff.email} (leg dropped below 5 deep)`);
        } else if (allLegsDeep && !currentGateMet) {
          console.log(`[DepthGate] Phase ${phase} GATE MET for ${aff.email} ✅`);
        }
      }

      // ── Phase advancement check ───────────────────────────────────────────
      // Criteria: gate met + personal_recruit_count >= phase * 3
      // Only advance if currently ON this phase (not already past it)
      const personalsRequired = phase * 3;
      const personalsActual = aff.personal_recruit_count || 0;

      if (allLegsDeep && personalsActual >= personalsRequired && phase < 5) {
        const advanceResult = await pool.query(
          `UPDATE affiliates
           SET current_phase = current_phase + 1, updated_at = NOW()
           WHERE id = $1 AND current_phase = $2
           RETURNING current_phase`,
          [aff.id, phase]
        );

        if (advanceResult.rowCount > 0) {
          phaseAdvances++;
          console.log(`[DepthGate] 🎉 ${aff.email} ADVANCED to Phase ${phase + 1}! (${personalsActual} personals, gate met)`);
        }
      } else if (allLegsDeep && personalsActual < personalsRequired && phase < 5) {
        console.log(`[DepthGate] ${aff.email}: gate met but needs ${personalsRequired - personalsActual} more personals for Phase ${phase + 1}`);
      }
    }

    console.log(
      `[DepthGate] Complete. Affiliates checked: ${affiliatesResult.rows.length}, ` +
      `Gates updated: ${gatesUpdated}, Phase advances: ${phaseAdvances}, Re-locks: ${relocks}`
    );
  } catch (err) {
    console.error('checkAndUpdateDepthGates error:', err.message);
  }
}

// ─── ADD TO ORPHAN POOL ───────────────────────────────────────────────────────
// Called at signup for users with no referral code — they go to the Holding Tank.
async function addToOrphanPool(userId) {
  try {
    await pool.query(
      `INSERT INTO orphan_pool (user_id, status, created_at)
       VALUES ($1, 'waiting_upgrade', NOW())
       ON CONFLICT (user_id) DO NOTHING`,
      [userId]
    );
    console.log(`[OrphanPool] User ${userId} added to Holding Tank`);
  } catch (err) {
    console.error('[OrphanPool] addToOrphanPool error:', err.message);
    // Non-fatal
  }
}

app.post('/api/affiliate/join', async (req, res) => {
  try {
    const { email, accept_terms } = req.body;
    if (!email || !email.includes('@')) {
      return res.status(400).json({ error: 'Valid email required' });
    }
    if (!accept_terms) {
      return res.status(400).json({ error: 'You must accept the affiliate terms and FTC disclosure to join' });
    }

    const normalizedEmail = email.toLowerCase();
    const userResult = await pool.query(
      'SELECT id, plan, paid_until, is_creator, is_admin, income_programs_blocked, promo_code_used, email FROM users WHERE LOWER(email) = $1',
      [normalizedEmail]
    );

    if (userResult.rows.length === 0) {
      return res.status(400).json({ error: 'User not found' });
    }

    const user = userResult.rows[0];
    const hasPro = await hasProAccess(user.id);

    if (!hasPro) {
      return res.status(403).json({ error: 'Only active paid subscribers can join Future Generations.' });
    }

    // Admin and Future Generations accounts are permanently blocked from affiliate enrollment.
    // Future Generations (OWNER_EMAILS) get free sovereign access but earn no commissions or referral payouts.
    if (isAdminIncomeBlockedUser(user)) {
      return res.status(403).json({ error: INCOME_BLOCK_ERROR, code: 'ADMIN_INCOME_BLOCKED' });
    }

    const existingAffiliate = await pool.query(
      'SELECT * FROM affiliates WHERE email = $1',
      [normalizedEmail]
    );

    if (existingAffiliate.rows.length > 0) {
      return res.json({ message: 'Already an affiliate', affiliate: existingAffiliate.rows[0] });
    }

    let referralCode;
    let attempts = 0;
    while (attempts < 10) {
      referralCode = generateReferralCode(email);
      const codeCheck = await pool.query('SELECT id FROM affiliates WHERE referral_code = $1', [referralCode]);
      if (codeCheck.rows.length === 0) break;
      attempts++;
    }

    // If user already has an active Pro subscription, start the good standing clock immediately.
    const proCheck = await hasProAccess(user);

    // Determine placement: seed / BFS / code / legacy_drop (4x5 rules)
    const placement = await determineAffiliatePlacement(user.id);

    const enrollmentType = placement.isLegacyPlacement ? 'legacy' : 'standard';
    const enrollerId = placement.enrollerId || null;

    const result = await pool.query(
      `INSERT INTO affiliates (user_id, email, referral_code, status, good_standing_started_at,
                               parent_affiliate_id, affiliate_level, placement_method,
                               enrollment_type, enroller_id, is_legacy_placement, leg_position, enrolled_at)
       VALUES ($1, $2, $3, 'active', $4, $5, $6, $7, $8, $9, $10, $11, NOW()) RETURNING *`,
      [user.id, normalizedEmail, referralCode, proCheck ? new Date() : null,
       placement.parentAffiliateId, placement.affiliateLevel, placement.placementMethod,
       enrollmentType, enrollerId, placement.isLegacyPlacement || false, placement.legPosition || null]
    );

    const newAffiliate = result.rows[0];

    // ── Beta Phase Invite Taper: set beta_invites_remaining based on tier ────
    // Tier = affiliate_level (Tier 0 = master node = unlimited, Tier 1-5+ = 5-1)
    // This is set immediately so the affiliate has their invite quota from day 1.
    const inviteLevel = placement.affiliateLevel || 1;
    const betaInvitesRemaining = (inviteLevel <= 0)
      ? null  // Tier 0 / master node = unlimited
      : Math.max(1, 6 - inviteLevel);  // Level 1→5, Level 2→4, …, Level 5+→1
    await pool.query(
      `UPDATE affiliates
       SET beta_invites_remaining = $1, updated_at = NOW()
       WHERE id = $2 AND beta_invites_remaining IS NULL`,
      [betaInvitesRemaining, newAffiliate.id]
    );
    newAffiliate.beta_invites_remaining = betaInvitesRemaining;

    // Sync users.referred_by_user_id (ensures commission chain works for renewals)
    if (placement.parentUserId) {
      await pool.query(
        `UPDATE users SET referred_by_user_id = $1 WHERE id = $2 AND referred_by_user_id IS NULL`,
        [placement.parentUserId, user.id]
      );
    }

    // Increment personal_recruit_count on the ENROLLER (not the placement parent for legacy):
    // - Standard: increment parent's personal_recruit_count
    // - Legacy: increment the enroller's personal_recruit_count (they personally recruited this person)
    // Orphans do NOT count toward personal recruit totals.
    if (placement.parentAffiliateId && !placement.isLegacyPlacement) {
      await pool.query(
        `UPDATE affiliates SET personal_recruit_count = personal_recruit_count + 1, updated_at = NOW()
         WHERE id = $1`,
        [placement.parentAffiliateId]
      );
    } else if (placement.isLegacyPlacement && enrollerId) {
      await pool.query(
        `UPDATE affiliates SET personal_recruit_count = personal_recruit_count + 1, updated_at = NOW()
         WHERE id = $1`,
        [enrollerId]
      );
    }

    res.json({ message: 'Welcome to the affiliate program!', affiliate: newAffiliate, placement_type: enrollmentType });
  } catch (err) {
    console.error('POST /api/affiliate/join error:', err.message);
    res.status(500).json({ error: 'Failed to join Future Generations' });
  }
});

app.get('/api/affiliate/dashboard', async (req, res) => {
  try {
    const { email } = req.query;
    if (!email) {
      return res.status(400).json({ error: 'email query parameter required' });
    }

    const normalizedEmail = email.toLowerCase();
    const affiliateResult = await pool.query('SELECT * FROM affiliates WHERE email = $1', [normalizedEmail]);

    if (affiliateResult.rows.length === 0) {
      return res.status(404).json({ error: 'Not an affiliate' });
    }

    const affiliate = affiliateResult.rows[0];

    const referralStats = await pool.query(
      `SELECT COUNT(*) as total_referrals,
              COUNT(*) FILTER (WHERE status = 'converted') as converted_referrals
       FROM referrals WHERE affiliate_id = $1`,
      [affiliate.id]
    );

    const referrals = await pool.query(
      `SELECT r.id, r.referred_email, r.converted_at, r.status,
              COALESCE(SUM(c.amount_cents), 0) as total_commission_cents
       FROM referrals r LEFT JOIN commissions c ON c.referral_id = r.id
       WHERE r.affiliate_id = $1
       GROUP BY r.id, r.referred_email, r.converted_at, r.status
       ORDER BY r.created_at DESC LIMIT 20`,
      [affiliate.id]
    );

    const pendingCommissions = await pool.query(
      `SELECT c.id, c.type, c.amount_cents, c.earned_at, r.referred_email
       FROM commissions c JOIN referrals r ON r.id = c.referral_id
       WHERE c.affiliate_id = $1 AND c.status = 'pending'
       ORDER BY c.earned_at DESC`,
      [affiliate.id]
    );

    const approvedCommissions = await pool.query(
      `SELECT c.id, c.type, c.amount_cents, c.earned_at, c.approved_at, r.referred_email
       FROM commissions c JOIN referrals r ON r.id = c.referral_id
       WHERE c.affiliate_id = $1 AND c.status = 'approved'
       ORDER BY c.approved_at DESC`,
      [affiliate.id]
    );

    const payouts = await pool.query(
      `SELECT id, amount_cents, status, processed_at, created_at
       FROM payouts WHERE affiliate_id = $1 ORDER BY created_at DESC LIMIT 10`,
      [affiliate.id]
    );

    // Orphan & Phase data
    const tankCountResult = await pool.query(
      `SELECT COUNT(*) AS count FROM orphan_pool WHERE status = 'waiting_upgrade'`
    );
    const ghostCountResult = await pool.query(
      `SELECT COUNT(*) AS count FROM affiliates WHERE parent_affiliate_id = $1 AND is_ghost_slot = true`,
      [affiliate.id]
    );

    // ── 30-Day Vesting Wallet data ──────────────────────────────────────────
    // Oldest pending commission date (drives the countdown timer)
    // Vesting window: 30 days after referral signup (updated from 90d)
    let vestingData = {
      oldest_pending_earned_at: null,
      days_elapsed: 0,
      days_until_release: 30,
      vesting_progress_pct: 0,
      next_payout_date: null,
      heartbeats_completed_count: 0,
      show_day91_celebration: false,
      first_release_amount_cents: affiliate.first_release_amount_cents || 0
    };
    try {
      const vestingNow = new Date();
      const oldestPendingRes = await pool.query(
        `SELECT MIN(earned_at) AS oldest_pending FROM commissions
         WHERE affiliate_id = $1 AND status = 'pending'`,
        [affiliate.id]
      );
      if (oldestPendingRes.rows[0]?.oldest_pending) {
        const oldestEarnedAt = new Date(oldestPendingRes.rows[0].oldest_pending);
        const daysElapsed = Math.floor((vestingNow - oldestEarnedAt) / 86400000);
        const daysLeft = Math.max(0, 30 - daysElapsed);
        vestingData.oldest_pending_earned_at = oldestPendingRes.rows[0].oldest_pending;
        vestingData.days_elapsed = daysElapsed;
        vestingData.days_until_release = daysLeft;
        vestingData.vesting_progress_pct = Math.min(100, Math.round((daysElapsed / 30) * 100));
      }

      // Count heartbeats completed in the last 3 months
      const last3Months = [1, 2, 3].map(i => {
        const d = new Date(vestingNow.getFullYear(), vestingNow.getMonth() - i, 1);
        return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
      });
      const hbCountRes = await pool.query(
        `SELECT COUNT(DISTINCT month_year) AS cnt
         FROM affiliate_heartbeats
         WHERE user_id = $1
           AND month_year = ANY($2)
           AND signature_confirmed = true`,
        [affiliate.user_id, last3Months]
      );
      vestingData.heartbeats_completed_count = parseInt(hbCountRes.rows[0]?.cnt || 0);

      // Next payout date: 1st of next month + 30 days (Net-30 on approved)
      const nextPayoutDate = new Date(vestingNow.getFullYear(), vestingNow.getMonth() + 1, 1);
      nextPayoutDate.setDate(nextPayoutDate.getDate() + 30);
      vestingData.next_payout_date = nextPayoutDate.toISOString().split('T')[0];

      // Show Day 91 celebration if the affiliate just had their first release
      // (first_release_sent_at was set within the last 24h)
      if (affiliate.first_release_sent_at) {
        const hoursSinceRelease = (new Date() - new Date(affiliate.first_release_sent_at)) / 3600000;
        vestingData.show_day91_celebration = hoursSinceRelease <= 24;
      }
    } catch (vestingErr) {
      console.error('Vesting data fetch error (non-fatal):', vestingErr.message);
    }

    res.json({
      affiliate: {
        id: affiliate.id, email: affiliate.email,
        referral_code: affiliate.referral_code,
        referral_link: `https://financial-revolution.polsia.app/pricing.html?ref=${affiliate.referral_code}`,
        status: affiliate.status,
        pending_balance_cents: affiliate.pending_balance_cents,
        approved_balance_cents: affiliate.approved_balance_cents,
        lifetime_earnings_cents: affiliate.lifetime_earnings_cents,
        grace_period_ends_at: affiliate.grace_period_ends_at,
        stripe_connect_onboarding_completed: affiliate.stripe_connect_onboarding_completed,
        // Tree placement
        affiliate_level: affiliate.affiliate_level || 1,
        placement_method: affiliate.placement_method || 'seed',
        // Phase & Orphan data
        current_phase: affiliate.current_phase || 1,
        personal_recruit_count: affiliate.personal_recruit_count || 0,
        orphan_placement_eligible: affiliate.orphan_placement_eligible || false,
        orphan_waiting_since: affiliate.orphan_waiting_since || null,
        orphans_received: affiliate.orphans_received || 0,
        next_orphan_slot: affiliate.next_orphan_slot || null,
        ghost_slots_count: parseInt(ghostCountResult.rows[0].count)
      },
      stats: referralStats.rows[0],
      referrals: referrals.rows,
      pending_commissions: pendingCommissions.rows,
      approved_commissions: approvedCommissions.rows,
      payouts: payouts.rows,
      payout_info: {
        can_request_payout: affiliate.approved_balance_cents >= PAYOUT_MINIMUM_CENTS,
        minimum_cents: PAYOUT_MINIMUM_CENTS,
        minimum_display: '$50.00'
      },
      // 30-Day Vesting Wallet data
      vesting: vestingData,
      // Holding Tank counter (shown to all affiliates)
      holding_tank: {
        waiting_count: parseInt(tankCountResult.rows[0].count),
        label: `${parseInt(tankCountResult.rows[0].count)} Free Users in the Waiting Tank`
      }
    });
  } catch (err) {
    console.error('GET /api/affiliate/dashboard error:', err.message);
    res.status(500).json({ error: 'Failed to fetch affiliate dashboard' });
  }
});

app.post('/api/affiliate/request-payout', async (req, res) => {
  try {
    const { email } = req.body;
    if (!email) return res.status(400).json({ error: 'email required' });

    const normalizedEmail = email.toLowerCase();
    const affiliateResult = await pool.query('SELECT * FROM affiliates WHERE email = $1', [normalizedEmail]);

    if (affiliateResult.rows.length === 0) {
      return res.status(404).json({ error: 'Not an affiliate' });
    }

    const affiliate = affiliateResult.rows[0];
    if (affiliate.user_id && (await userBlockedFromIncomePrograms(pool, affiliate.user_id))) {
      return res.status(403).json({ error: INCOME_BLOCK_ERROR, code: 'ADMIN_INCOME_BLOCKED' });
    }
    if (affiliate.status !== 'active') {
      return res.status(403).json({ error: 'Affiliate account is not active' });
    }
    if (affiliate.approved_balance_cents < PAYOUT_MINIMUM_CENTS) {
      return res.status(400).json({
        error: `Minimum payout is $50. Your approved balance: $${(affiliate.approved_balance_cents / 100).toFixed(2)}`
      });
    }

    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const payoutResult = await client.query(
        `INSERT INTO payouts (affiliate_id, amount_cents, status) VALUES ($1, $2, 'requested') RETURNING *`,
        [affiliate.id, affiliate.approved_balance_cents]
      );
      await client.query(`UPDATE affiliates SET approved_balance_cents = 0, updated_at = NOW() WHERE id = $1`, [affiliate.id]);
      await client.query(`UPDATE commissions SET status = 'paid', updated_at = NOW() WHERE affiliate_id = $1 AND status = 'approved'`, [affiliate.id]);
      await client.query('COMMIT');
      res.json({ message: 'Payout requested successfully', payout: payoutResult.rows[0] });
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('POST /api/affiliate/request-payout error:', err.message);
    res.status(500).json({ error: 'Failed to request payout' });
  }
});

// Affiliate tier tree — returns the affiliate's 5-level downline for dashboard visualization
app.get('/api/affiliate/tier-tree', async (req, res) => {
  try {
    const { email } = req.query;
    if (!email) return res.status(400).json({ error: 'email required' });

    const normalizedEmail = email.toLowerCase();
    const affResult = await pool.query(
      'SELECT a.id, a.user_id FROM affiliates a WHERE LOWER(a.email) = $1',
      [normalizedEmail]
    );
    if (affResult.rows.length === 0) return res.status(404).json({ error: 'Not an affiliate' });

    const { user_id: rootUserId } = affResult.rows[0];

    // Recursive BFS — walk up to 5 levels deep
    async function getChildren(userId, depth) {
      if (depth > 5) return [];
      const kids = await pool.query(
        `SELECT u.id, u.name, u.email, u.plan, u.paid_until,
                a.status AS affiliate_status, a.referral_code,
                a.pending_balance_cents, a.approved_balance_cents,
                a.affiliate_level, a.placement_method,
                a.is_ghost_slot, a.ghost_upgraded_at
         FROM users u
         LEFT JOIN affiliates a ON a.user_id = u.id
         WHERE u.referred_by_user_id = $1
         ORDER BY u.created_at ASC`,
        [userId]
      );
      const nodes = [];
      for (const k of kids.rows) {
        const isPro = k.plan === 'paid' && k.paid_until && new Date(k.paid_until) > new Date();
        const isGhost = k.is_ghost_slot === true;
        nodes.push({
          id: k.id,
          name: k.name || k.email.split('@')[0],
          email: k.email,
          is_pro: isPro,
          affiliate_status: k.affiliate_status || null,
          referral_code: k.referral_code || null,
          pending_balance_cents: k.pending_balance_cents || 0,
          approved_balance_cents: k.approved_balance_cents || 0,
          affiliate_level: k.affiliate_level || depth,
          placement_method: k.placement_method || null,
          // Ghost Slot fields
          is_ghost_slot: isGhost,
          ghost_upgraded_at: k.ghost_upgraded_at || null,
          slot_status: isGhost ? 'ghost' : 'gold', // UI label
          depth,
          children: await getChildren(k.id, depth + 1)
        });
      }
      return nodes;
    }

    const tree = await getChildren(rootUserId, 1);

    // Count total members across all levels
    function countAll(nodes) { return nodes.reduce((acc, n) => acc + 1 + countAll(n.children), 0); }
    const totalMembers = countAll(tree);

    res.json({ tree, totalMembers });
  } catch (err) {
    console.error('GET /api/affiliate/tier-tree error:', err.message);
    res.status(500).json({ error: 'Failed to load tier tree' });
  }
});

