// Returns phase progression status for an affiliate (4x5 gated system)
// Includes per-leg depth thermometer data for the dashboard UI.
app.get('/api/affiliate/phase-status', async (req, res) => {
  try {
    const { email } = req.query;
    if (!email) return res.status(400).json({ error: 'email required' });

    const affResult = await pool.query(
      `SELECT a.*, u.is_facts_certified
       FROM affiliates a
       JOIN users u ON u.id = a.user_id
       WHERE LOWER(a.email) = LOWER($1)`,
      [email]
    );
    if (affResult.rows.length === 0) return res.status(404).json({ error: 'Not an affiliate' });

    const aff = affResult.rows[0];
    const currentPhase = aff.current_phase || 1;

    // Get all direct children (legs), ordered by leg_position
    const legsResult = await pool.query(`
      SELECT id, email, is_ghost_slot, status, leg_position,
             COALESCE(leg_position, ROW_NUMBER() OVER (ORDER BY created_at ASC, id ASC)) AS effective_pos
      FROM affiliates
      WHERE parent_affiliate_id = $1
        AND status != 'revoked'
      ORDER BY COALESCE(leg_position, id) ASC
      LIMIT 20
    `, [aff.id]);

    const allLegs = legsResult.rows;
    const frontLineWidth = allLegs.length;

    // For the current phase, compute per-leg depth (thermometer 0-5)
    // Only compute for current phase legs (expensive recursive query)
    const phaseStartIdx = (currentPhase - 1) * 4;
    const phaseEndIdx = currentPhase * 4;
    const currentPhaseLegs = allLegs.slice(phaseStartIdx, phaseEndIdx);

    const legDepths = [];
    for (const leg of currentPhaseLegs) {
      const { maxDepth } = await checkLegDepth(aff.id, leg.id, 5);
      legDepths.push({
        leg_id: leg.id,
        leg_position: leg.effective_pos,
        is_ghost: leg.is_ghost_slot,
        max_depth: maxDepth,
        reached_5: maxDepth >= 5
      });
    }

    // Phase rules: 3 personals per phase + all 4 legs 5-deep to unlock next phase
    const phases = [1,2,3,4,5].map(phase => {
      const slotsStart = (phase - 1) * 4 + 1;
      const slotsEnd = phase * 4;
      const isCurrentPhase = currentPhase === phase;
      const isUnlocked = currentPhase > phase;
      const isLocked = currentPhase < phase;

      // Gate status from DB (set by daily checkAndUpdateDepthGates job)
      const depthGateMet = aff[`phase_${phase}_depth_gate_met`] === true;
      const orphanSlot = getOrphanSlotForPhase(phase);

      // Legs in this phase
      const phaseLegsForPhase = allLegs.slice((phase - 1) * 4, phase * 4);
      const legsFilledCount = phaseLegsForPhase.length;

      return {
        phase,
        leg_range: `${slotsStart}-${slotsEnd}`,
        status: isUnlocked ? 'unlocked' : (isCurrentPhase ? 'active' : 'locked'),
        depth_gate_met: depthGateMet,
        orphan_slot: orphanSlot,
        personals_required: phase * 3,
        legs_filled: legsFilledCount,
        legs_needed: Math.max(0, 4 - legsFilledCount),
        // Current phase gets live depth data; others get snapshot from DB
        leg_depths: isCurrentPhase ? legDepths : []
      };
    });

    // Tank count for the "X waiting" indicator
    const tankCount = await pool.query(
      `SELECT COUNT(*) AS count FROM orphan_pool WHERE status = 'waiting_upgrade'`
    );

    // Personals needed for next phase unlock
    const personalsForNextPhase = currentPhase < 5 ? (currentPhase * 3) : null;
    const personalsStillNeeded = personalsForNextPhase
      ? Math.max(0, personalsForNextPhase - (aff.personal_recruit_count || 0))
      : 0;

    res.json({
      affiliate_id: aff.id,
      current_phase: currentPhase,
      front_line_width: frontLineWidth,
      max_width: currentPhase * 4,
      personal_recruit_count: aff.personal_recruit_count || 0,
      personals_needed_for_next_phase: personalsStillNeeded,
      is_facts_certified: aff.is_facts_certified || false,
      orphan_placement_eligible: aff.orphan_placement_eligible || false,
      orphan_waiting_since: aff.orphan_waiting_since,
      orphans_received: aff.orphans_received,
      next_orphan_slot: aff.next_orphan_slot,
      phases,
      holding_tank_count: parseInt(tankCount.rows[0].count),
      // Live leg depths for current phase thermometer
      current_phase_leg_depths: legDepths
    });
  } catch (err) {
    console.error('GET /api/affiliate/phase-status error:', err.message);
    res.status(500).json({ error: 'Failed to fetch phase status' });
  }
});

// Enter orphan queue — affiliate opts in to receive orphan placements
// Called when they complete Phase 1 certification and want to be eligible
app.post('/api/affiliate/enter-orphan-queue', async (req, res) => {
  try {
    const { email } = req.body;
    if (!email) return res.status(400).json({ error: 'email required' });

    const affResult = await pool.query(
      `SELECT a.id, a.status, a.orphan_placement_eligible, a.next_orphan_slot, a.current_phase, u.is_facts_certified
       FROM affiliates a JOIN users u ON u.id = a.user_id
       WHERE LOWER(a.email) = LOWER($1)`,
      [email]
    );
    if (affResult.rows.length === 0) return res.status(404).json({ error: 'Not an affiliate' });

    const aff = affResult.rows[0];
    if (aff.status !== 'active') return res.status(403).json({ error: 'Affiliate must be active' });
    if (!aff.orphan_placement_eligible) {
      return res.status(403).json({
        error: 'Orphan placement eligibility requires: active status, FACTS certification, and current heartbeat compliance'
      });
    }
    if (aff.next_orphan_slot) {
      return res.json({ message: 'Already in orphan queue', next_orphan_slot: aff.next_orphan_slot });
    }

    // Set them up for the next orphan slot based on current phase (max 3 gifts: 1, 5, 9)
    const nextSlot = getOrphanSlotForPhase(aff.current_phase);
    if (!nextSlot) {
      return res.status(400).json({
        error: 'You have received the maximum 3 company gifts. No further orphan slots available.'
      });
    }

    // Set slot1_gift_waiting_since when entering for the first time (Slot 1).
    // This drives the silent 14-day auto-fill safety net (backend only).
    const isFirstSlot = (nextSlot === 1);
    await pool.query(
      `UPDATE affiliates
       SET next_orphan_slot        = $1,
           orphan_waiting_since    = NOW(),
           slot1_gift_waiting_since = CASE WHEN $2 THEN NOW() ELSE slot1_gift_waiting_since END,
           updated_at              = NOW()
       WHERE id = $3`,
      [nextSlot, isFirstSlot, aff.id]
    );

    res.json({ message: 'Entered orphan queue', next_orphan_slot: nextSlot, waiting_since: new Date() });
  } catch (err) {
    console.error('POST /api/affiliate/enter-orphan-queue error:', err.message);
    res.status(500).json({ error: 'Failed to enter orphan queue' });
  }
});

