async function trackReferral(email, referralCode, subscriptionId) {
  try {
    if (!referralCode) return;
    const affiliateResult = await pool.query(
      'SELECT id, user_id, affiliate_level FROM affiliates WHERE referral_code = $1 AND status = $2',
      [referralCode, 'active']
    );
    if (affiliateResult.rows.length === 0) return;

    const affiliate = affiliateResult.rows[0];

    // Set referred_by_user_id on the referred user (builds the commission tree)
    await pool.query(
      `UPDATE users SET referred_by_user_id = $1, updated_at = NOW()
       WHERE LOWER(email) = LOWER($2) AND referred_by_user_id IS NULL`,
      [affiliate.user_id, email]
    );

    await pool.query(
      `INSERT INTO referrals (affiliate_id, referred_email, subscription_id, referral_code, status)
       VALUES ($1, $2, $3, $4, 'pending')`,
      [affiliate.id, email.toLowerCase(), subscriptionId, referralCode]
    );

    // If the referred user is already an affiliate, sync their parent_affiliate_id
    // (handles case where they joined the program before subscribing via a referral link)
    const referredUser = await pool.query(
      'SELECT id FROM users WHERE LOWER(email) = LOWER($1)', [email]
    );
    if (referredUser.rows.length > 0) {
      const referredUserId = referredUser.rows[0].id;
      const newLevel = Math.min((affiliate.affiliate_level || 1) + 1, 5);
      await pool.query(
        `UPDATE affiliates
         SET parent_affiliate_id = $1,
             affiliate_level     = $2,
             placement_method    = 'code',
             updated_at          = NOW()
         WHERE user_id = $3
           AND (parent_affiliate_id IS NULL OR placement_method != 'code')`,
        [affiliate.id, newLevel, referredUserId]
      );
    }
  } catch (err) {
    console.error('trackReferral error:', err.message);
  }
}

// ─── Commission Helper: insert one commission record ────────────────────────
// Deduplication-safe: silently skips if an identical record exists.
// Returns true if inserted, false if duplicate.
// ── Unfreeze family-frozen commissions when a member upgrades to individual Pro ──
async function unfreezeCommissionsAfterProUpgrade(userId) {
  try {
    // Find affiliate for this user
    const affResult = await pool.query(
      'SELECT id, family_household_id FROM affiliates WHERE user_id = $1 LIMIT 1',
      [userId]
    );
    if (affResult.rows.length === 0) return;
    const aff = affResult.rows[0];
    if (!aff.family_household_id) return; // Not a family member, nothing to unfreeze

    // Unfreeze all frozen commissions
    const unfreezeResult = await pool.query(
      `UPDATE commissions
       SET frozen_until_pro = false, unfrozen_at = NOW(), updated_at = NOW()
       WHERE affiliate_id = $1 AND family_split_type = 'member_frozen'
         AND frozen_until_pro = true AND unfrozen_at IS NULL
         AND status != 'forfeited'
       RETURNING amount_cents`,
      [aff.id]
    );

    const totalUnfrozenCents = unfreezeResult.rows.reduce((sum, r) => sum + r.amount_cents, 0);

    if (totalUnfrozenCents > 0) {
      // Add to pending balance
      await pool.query(
        `UPDATE affiliates SET pending_balance_cents = pending_balance_cents + $1,
         family_household_id = NULL, updated_at = NOW() WHERE id = $2`,
        [totalUnfrozenCents, aff.id]
      );
      console.log(`[FamilyPlan] Unfroze ${totalUnfrozenCents}¢ for affiliate ${aff.id} (user ${userId}) on Pro upgrade`);
    }
  } catch (err) {
    console.error('[FamilyPlan] unfreezeCommissionsAfterProUpgrade error:', err.message);
  }
}

async function insertCommissionRecord(client, {
  affiliateId, referralId, subscriptionId, commissionType, amountCents, percentage, level, sourceUserId
}) {
  if (amountCents <= 0) return false;

  const existing = await client.query(
    'SELECT id FROM commissions WHERE subscription_id = $1 AND affiliate_id = $2 AND type = $3 AND level = $4 AND (family_split_type IS NULL OR family_split_type = \'full\')',
    [subscriptionId, affiliateId, commissionType, level]
  );
  if (existing.rows.length > 0) return false;

  // ── Family Plan 50/50 Split ───────────────────────────────────────────────
  // If the affiliate is currently a member of a family family,
  // split the commission: 50% to billing owner, 50% frozen for the member
  const affResult = await client.query(
    'SELECT family_household_id FROM affiliates WHERE id = $1',
    [affiliateId]
  );
  const familyHouseholdId = affResult.rows[0]?.family_household_id || null;

  if (familyHouseholdId) {
    // Find the family owner's affiliate
    const ownerResult = await client.query(
      `SELECT a.id AS owner_affiliate_id
       FROM affiliates a
       JOIN households h ON h.owner_id = a.user_id
       WHERE h.id = $1 AND a.status IN ('active','at_risk')
       LIMIT 1`,
      [familyHouseholdId]
    );
    const ownerAffiliateId = ownerResult.rows[0]?.owner_affiliate_id || null;

    const ownerHalf = Math.floor(amountCents / 2);
    const memberHalf = amountCents - ownerHalf; // Handle odd cents

    // 1. Owner's 50% — goes to owner's affiliate balance (normal pending)
    if (ownerAffiliateId && ownerHalf > 0) {
      const ownerExisting = await client.query(
        `SELECT id FROM commissions WHERE subscription_id = $1 AND affiliate_id = $2 AND type = $3 AND level = $4 AND family_split_type = 'owner_share'`,
        [subscriptionId, ownerAffiliateId, commissionType, level]
      );
      if (ownerExisting.rows.length === 0) {
        await client.query(
          `INSERT INTO commissions
             (affiliate_id, referral_id, subscription_id, type, amount_cents, percentage, level, source_user_id,
              status, earned_at, family_split_type, family_household_id)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'pending', NOW(), 'owner_share', $9)`,
          [ownerAffiliateId, referralId, subscriptionId, commissionType,
           ownerHalf, percentage / 2, level, sourceUserId, familyHouseholdId]
        );
        await client.query(
          `UPDATE affiliates SET pending_balance_cents = pending_balance_cents + $1, updated_at = NOW() WHERE id = $2`,
          [ownerHalf, ownerAffiliateId]
        );
      }
    }

    // 2. Member's 50% — frozen until they upgrade to individual Pro
    if (memberHalf > 0) {
      const memberExisting = await client.query(
        `SELECT id FROM commissions WHERE subscription_id = $1 AND affiliate_id = $2 AND type = $3 AND level = $4 AND family_split_type = 'member_frozen'`,
        [subscriptionId, affiliateId, commissionType, level]
      );
      if (memberExisting.rows.length === 0) {
        await client.query(
          `INSERT INTO commissions
             (affiliate_id, referral_id, subscription_id, type, amount_cents, percentage, level, source_user_id,
              status, earned_at, family_split_type, family_household_id, frozen_until_pro)
           VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'pending', NOW(), 'member_frozen', $9, true)`,
          [affiliateId, referralId, subscriptionId, commissionType,
           memberHalf, percentage / 2, level, sourceUserId, familyHouseholdId]
        );
        // Note: frozen commissions do NOT add to pending_balance_cents until unfrozen
        // They appear in dashboard but can't be withdrawn
      }
    }

    console.log(`[Commission] Family split for affiliate ${affiliateId} (family ${familyHouseholdId}): owner gets ${ownerHalf}¢, member frozen ${memberHalf}¢`);
    return true;
  }
  // ── End Family Plan 50/50 Split ───────────────────────────────────────────

  // Standard (non-family) commission
  await client.query(
    `INSERT INTO commissions
       (affiliate_id, referral_id, subscription_id, type, amount_cents, percentage, level, source_user_id, status, earned_at, family_split_type)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'pending', NOW(), 'full')`,
    [affiliateId, referralId, subscriptionId, commissionType, amountCents, percentage, level, sourceUserId]
  );
  await client.query(
    `UPDATE affiliates SET pending_balance_cents = pending_balance_cents + $1, updated_at = NOW() WHERE id = $2`,
    [amountCents, affiliateId]
  );
  return true;
}

// ─── Legacy Startup Commission (Month 1 only) ───────────────────────────────
// Structure: Enroller=20%, Placement Parent=5%, L3=3%, L4=2%, L5=1%
// Unclaimed levels: Sovereign Vacuum — retained by company (Master Node).
async function processLegacyStartupCommission(client, recruitAffiliate, subscriptionId, referralId, sourceUser, subscription) {
  const commissionType = 'initial';

  // Step 1: Pay Enroller 20%
  if (recruitAffiliate.enroller_id) {
    const enrollerResult = await client.query(
      `SELECT id, is_ghost_slot FROM affiliates WHERE id = $1 AND status = 'active'`,
      [recruitAffiliate.enroller_id]
    );
    if (enrollerResult.rows.length > 0 && !enrollerResult.rows[0].is_ghost_slot) {
      const amount = Math.floor((subscription.amount_cents * FG_LEGACY_ENROLLER_RATE) / 100);
      const inserted = await insertCommissionRecord(client, {
        affiliateId: enrollerResult.rows[0].id,
        referralId,
        subscriptionId,
        commissionType,
        amountCents: amount,
        percentage: FG_LEGACY_ENROLLER_RATE,
        level: 1,
        sourceUserId: sourceUser.id
      });
      if (inserted) {
        console.log(`[LegacyCommission] Enroller (id:${enrollerResult.rows[0].id}) receives 20% ($${(amount / 100).toFixed(2)})`);
      }
    } else {
      // Enroller is ghost/inactive — Sovereign Vacuum: company retains 20%
      console.log(`[LegacyCommission] Enroller slot empty/ghost — Sovereign Vacuum absorbs 20%`);
    }
  }

  // Step 2: Pay Placement Parent 5%, then walk up placement tree for 3%, 2%, 1%
  // Placement parent = parent_affiliate_id on the recruit's affiliate record
  let currentAffiliateId = recruitAffiliate.parent_affiliate_id;
  const placementRates = FG_LEGACY_PLACEMENT_RATES; // [5, 3, 2, 1]
  let levelOffset = 2; // Starts at position 2 (enroller was 1)

  for (let i = 0; i < placementRates.length && currentAffiliateId; i++) {
    const nodeResult = await client.query(
      `SELECT id, parent_affiliate_id, is_ghost_slot, status FROM affiliates WHERE id = $1`,
      [currentAffiliateId]
    );
    if (nodeResult.rows.length === 0) break;
    const node = nodeResult.rows[0];

    if (node.is_ghost_slot || node.status !== 'active') {
      // Ghost or inactive: Sovereign Vacuum — skip (but still walk up for next level)
      console.log(`[LegacyCommission] Level ${levelOffset} slot (id:${node.id}) ghost/inactive — Sovereign Vacuum absorbs ${placementRates[i]}%`);
    } else {
      const amount = Math.floor((subscription.amount_cents * placementRates[i]) / 100);
      const inserted = await insertCommissionRecord(client, {
        affiliateId: node.id,
        referralId,
        subscriptionId,
        commissionType,
        amountCents: amount,
        percentage: placementRates[i],
        level: levelOffset,
        sourceUserId: sourceUser.id
      });
      if (inserted) {
        const label = i === 0 ? 'Placement Parent' : `Tree L${levelOffset}`;
        console.log(`[LegacyCommission] ${label} (id:${node.id}) receives ${placementRates[i]}% ($${(amount / 100).toFixed(2)})`);
      }
    }

    currentAffiliateId = node.parent_affiliate_id;
    levelOffset++;
  }
}

// ─── Legacy Renewal Commission (Month 2+) ───────────────────────────────────
// Uses TREE POSITION (parent_affiliate_id chain) with standard 16-8-4-2-1 rates.
// Ghost slot compression still applies.
async function processLegacyRenewalCommission(client, recruitAffiliate, subscriptionId, referralId, sourceUser, subscription) {
  const commissionType = 'renewal';
  const rates = FG_RECURRING_RATES; // [16, 8, 4, 2, 1]

  // Walk up the placement tree (parent_affiliate_id chain)
  let currentAffiliateId = recruitAffiliate.parent_affiliate_id;
  let level = 1;
  let hops = 0;

  while (level <= 5 && currentAffiliateId && hops < 20) {
    hops++;
    const nodeResult = await client.query(
      `SELECT id, parent_affiliate_id, is_ghost_slot, status FROM affiliates WHERE id = $1`,
      [currentAffiliateId]
    );
    if (nodeResult.rows.length === 0) break;
    const node = nodeResult.rows[0];

    if (node.is_ghost_slot) {
      // Ghost Slot: compress past — don't consume a level
      console.log(`[LegacyRenewal] Compressing past ghost slot affiliate ${node.id}`);
      currentAffiliateId = node.parent_affiliate_id;
      continue; // Don't increment level
    }

    if (node.status === 'active') {
      const rate = rates[level - 1];
      const amount = Math.floor((subscription.amount_cents * rate) / 100);
      await insertCommissionRecord(client, {
        affiliateId: node.id,
        referralId,
        subscriptionId,
        commissionType,
        amountCents: amount,
        percentage: rate,
        level,
        sourceUserId: sourceUser.id
      });
    }

    level++;
    currentAffiliateId = node.parent_affiliate_id;
  }
}

async function processCommission(subscriptionId, isRenewal = false) {
  const WATERFALL_RATES = [16, 8, 4, 2, 1]; // Level 1-5 percentages (total = 31%)

  try {
    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      // ── Load subscription ─────────────────────────────────────────────────
      const subResult = await client.query(
        'SELECT * FROM subscriptions WHERE id = $1', [subscriptionId]
      );
      if (subResult.rows.length === 0) { await client.query('ROLLBACK'); return; }
      const subscription = subResult.rows[0];

      // ── Find the payer user ───────────────────────────────────────────────
      const userResult = await client.query(
        'SELECT id, referred_by_user_id FROM users WHERE LOWER(email) = LOWER($1)',
        [subscription.email]
      );
      if (userResult.rows.length === 0) { await client.query('ROLLBACK'); return; }
      const sourceUser = userResult.rows[0];

      // ── Find the referral record linked to this subscription ──────────────
      const referralResult = await client.query(
        'SELECT id, affiliate_id FROM referrals WHERE subscription_id = $1 LIMIT 1',
        [subscriptionId]
      );
      const referralId = referralResult.rows.length > 0 ? referralResult.rows[0].id : null;

      // ── Check if recruit has a Legacy Placement ─────────────────────────────
      const recruitAffResult = await client.query(
        `SELECT id, enrollment_type, enroller_id, parent_affiliate_id, enrolled_at
         FROM affiliates WHERE user_id = $1`,
        [sourceUser.id]
      );
      const recruitAffiliate = recruitAffResult.rows.length > 0 ? recruitAffResult.rows[0] : null;

      const isLegacy = recruitAffiliate && recruitAffiliate.enrollment_type === 'legacy';

      if (isLegacy && !isRenewal) {
        // ── Legacy Month 1: 20-5-3-2-1 startup bonus ─────────────────────────
        console.log(`[Commission] Legacy startup commission for user ${sourceUser.id} (sub ${subscriptionId})`);
        await processLegacyStartupCommission(client, recruitAffiliate, subscriptionId, referralId, sourceUser, subscription);
      } else if (isLegacy && isRenewal) {
        // ── Legacy Month 2+: standard rates via placement tree ────────────────
        console.log(`[Commission] Legacy renewal commission for user ${sourceUser.id} (sub ${subscriptionId})`);
        await processLegacyRenewalCommission(client, recruitAffiliate, subscriptionId, referralId, sourceUser, subscription);
      } else {
        // ── Standard commission: walk up referred_by_user_id chain ────────────
        const rates = isRenewal ? FG_RECURRING_RATES : FG_INITIAL_RATES;
        const commissionType = isRenewal ? 'renewal' : 'initial';

        // Walk up the referral tree, up to 5 levels.
        // Ghost Slot Compression: if an ancestor is a ghost slot (free user who hasn't
        // upgraded to Pro yet), we skip them WITHOUT consuming a commission level.
        // The commission compresses past the ghost to the next active paid upline.
        let currentUserId = sourceUser.referred_by_user_id;
        let level = 1;
        let hops = 0; // safety cap to prevent infinite loops

        while (level <= 5 && currentUserId && hops < 20) {
          hops++;
          // Find the ancestor user
          const ancestorResult = await client.query(
            'SELECT id, email, is_admin, is_creator, income_programs_blocked, referred_by_user_id FROM users WHERE id = $1',
            [currentUserId]
          );
          if (ancestorResult.rows.length === 0) break;
          const ancestor = ancestorResult.rows[0];

          // Block admin (CREATOR_EMAIL) and Future Generations accounts from receiving commissions.
          // Future Generations get free sovereign access but are not eligible for affiliate payouts.
          if (isAdminIncomeBlockedUser(ancestor)) {
            console.log(`[Commission] Skipping ineligible email — blocked from payout (user ${ancestor.id})`);
            level++;
            currentUserId = ancestor.referred_by_user_id;
            continue;
          }

          // Check if ancestor has an active affiliate account (also fetch is_ghost_slot)
          const affiliateResult = await client.query(
            'SELECT id, is_ghost_slot FROM affiliates WHERE user_id = $1 AND status = $2',
            [ancestor.id, 'active']
          );

          const affiliateRecord = affiliateResult.rows.length > 0 ? affiliateResult.rows[0] : null;
          const isGhostSlot = affiliateRecord && affiliateRecord.is_ghost_slot;

          if (isGhostSlot) {
            // Ghost Slot: compress past — don't award commission, don't consume a level
            console.log(`[Commission] Compressing past ghost slot user ${ancestor.id} at depth ${hops}`);
            currentUserId = ancestor.referred_by_user_id;
            continue; // Skip level++ — ghost doesn't consume a level
          }

          if (affiliateRecord && referralId) {
            const rate = rates[level - 1];
            await insertCommissionRecord(client, {
              affiliateId: affiliateRecord.id,
              referralId,
              subscriptionId,
              commissionType,
              amountCents: Math.floor((subscription.amount_cents * rate) / 100),
              percentage: rate,
              level,
              sourceUserId: sourceUser.id
            });
          }

          // Move up the tree — consume one commission level
          level++;
          currentUserId = ancestor.referred_by_user_id;
        }
      }

      // Levels beyond the chain length (missing uplines) also feed the accumulator
      for (let i = uplineChain.length; i < WATERFALL_RATES.length; i++) {
        accumulatedPct += WATERFALL_RATES[i];
      }

      // ── Step 3: Deposit vacuum remainder to Master Node ───────────────────
      if (accumulatedPct > 0) {
        const masterCents = Math.floor((subscription.amount_cents * accumulatedPct) / 100);
        if (masterCents > 0) {
          await depositVacuumToMasterNode(
            client, masterCents, accumulatedPct, subscriptionId, commissionType, sourceUser.id
          );
        }
      }

      // ── Step 4: Mark referral as converted (initial subscriptions only) ───
      if (!isRenewal && referralId) {
        await client.query(
          `UPDATE referrals
           SET status = 'converted', converted_at = NOW(), updated_at = NOW()
           WHERE id = $1`,
          [referralId]
        );
      }

      await client.query('COMMIT');

      const totalPct = WATERFALL_RATES.reduce((a, b) => a + b, 0); // = 31
      console.log(
        `[Commission] Subscription #${subscriptionId} (${commissionType}) processed — ` +
        `${totalPct}% pool fully distributed across ${uplineChain.length} level(s) + Master Node`
      );

    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('processCommission error:', err.message);
  }
}

