// ─── FUTURE GENERATIONS ─────────────────────────────────
// ═══════════════════════════════════════════════════════════

// Join Future Generations — any authenticated user can join
app.post('/api/future-generations/join', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    // Check if already a member
    const existing = await pool.query('SELECT * FROM affiliates WHERE user_id = $1', [userId]);
    if (existing.rows.length > 0) {
      return res.json({
        message: 'Already a member of Future Generations',
        affiliate: existing.rows[0]
      });
    }

    // Get user email
    const userResult = await pool.query('SELECT email FROM users WHERE id = $1', [userId]);
    if (userResult.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    const email = userResult.rows[0].email;

    // Generate unique referral code
    let referralCode;
    let attempts = 0;
    while (attempts < 10) {
      referralCode = generateReferralCode(email);
      const codeCheck = await pool.query('SELECT id FROM affiliates WHERE referral_code = $1', [referralCode]);
      if (codeCheck.rows.length === 0) break;
      attempts++;
    }

    // If user is already Pro, start the 30-day good standing clock immediately
    const proCheck = await hasProAccess(userId);

    // Determine placement: seed / BFS / code
    const placement = await determineAffiliatePlacement(userId);

    const result = await pool.query(
      `INSERT INTO affiliates (user_id, email, referral_code, status, good_standing_started_at,
                               parent_affiliate_id, affiliate_level, placement_method)
       VALUES ($1, $2, $3, 'active', $4, $5, $6, $7) RETURNING *`,
      [userId, email.toLowerCase(), referralCode, proCheck ? new Date() : null,
       placement.parentAffiliateId, placement.affiliateLevel, placement.placementMethod]
    );

    // Sync users.referred_by_user_id for BFS placements (ensures commission chain works for renewals)
    if (placement.parentUserId) {
      await pool.query(
        `UPDATE users SET referred_by_user_id = $1 WHERE id = $2 AND referred_by_user_id IS NULL`,
        [placement.parentUserId, userId]
      );
    }

    res.json({
      message: 'Welcome to Future Generations!',
      affiliate: result.rows[0]
    });
  } catch (err) {
    console.error('POST /api/future-generations/join error:', err.message);
    if (err.code === '23505') {
      // Unique constraint — already exists
      const existing = await pool.query('SELECT * FROM affiliates WHERE user_id = $1', [req.userId]);
      if (existing.rows.length > 0) {
        return res.json({ message: 'Already a member', affiliate: existing.rows[0] });
      }
    }
    res.status(500).json({ error: 'Failed to join Future Generations' });
  }
});

// Future Generations Dashboard
app.get('/api/future-generations/dashboard', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    // Check if user is a member
    const affiliateResult = await pool.query('SELECT * FROM affiliates WHERE user_id = $1', [userId]);

    if (affiliateResult.rows.length === 0) {
      const orgRes = await pool.query('SELECT COUNT(*) FROM affiliates');
      return res.json({ member: false, total_org_size: parseInt(orgRes.rows[0].count, 10) });
    }

    const affiliate = affiliateResult.rows[0];

    // Count referrals
    const referralCount = await pool.query(
      `SELECT COUNT(*) as total_referrals,
              COUNT(*) FILTER (WHERE status = 'converted') as active_referrals
       FROM referrals WHERE affiliate_id = $1`,
      [affiliate.id]
    );

    // Count descendants in the tree (all levels)
    const treeCount = await pool.query(`
      WITH RECURSIVE referral_tree AS (
        SELECT id, 1 as level FROM users WHERE referred_by_user_id = $1
        UNION ALL
        SELECT u.id, rt.level + 1
        FROM users u
        JOIN referral_tree rt ON u.referred_by_user_id = rt.id
        WHERE rt.level < 5
      )
      SELECT level, COUNT(*) as count FROM referral_tree GROUP BY level ORDER BY level
    `, [userId]);

    // Commission breakdown by level
    const commissionsByLevel = await pool.query(`
      SELECT level, type,
             SUM(amount_cents) as total_cents,
             COUNT(*) as count
      FROM commissions
      WHERE affiliate_id = $1 AND status != 'forfeited'
      GROUP BY level, type
      ORDER BY level, type
    `, [affiliate.id]);

    // Recent commissions
    const recentCommissions = await pool.query(`
      SELECT c.level, c.type, c.amount_cents, c.status, c.earned_at
      FROM commissions c
      WHERE c.affiliate_id = $1
      ORDER BY c.earned_at DESC
      LIMIT 10
    `, [affiliate.id]);

    const totalBalance = affiliate.pending_balance_cents + affiliate.approved_balance_cents;

    // Downline count by affiliate_level (using parent_affiliate_id chain)
    const downlineByLevel = await pool.query(`
      WITH RECURSIVE downline AS (
        SELECT a.id, a.affiliate_level, 1 AS depth
        FROM affiliates a
        WHERE a.parent_affiliate_id = $1

        UNION ALL

        SELECT a.id, a.affiliate_level, dl.depth + 1
        FROM affiliates a
        JOIN downline dl ON a.parent_affiliate_id = dl.id
        WHERE dl.depth < 5
      )
      SELECT affiliate_level, COUNT(*) AS count
      FROM downline
      GROUP BY affiliate_level
      ORDER BY affiliate_level
    `, [affiliate.id]);

    const totalDownline = downlineByLevel.rows.reduce((s, r) => s + parseInt(r.count, 10), 0);

    // Total org size
    const orgSizeResult = await pool.query('SELECT COUNT(*) FROM affiliates');
    const totalOrgSize = parseInt(orgSizeResult.rows[0].count, 10);

    // Seed phase status
    const firstLineCount = await getFirstLineAffiliateCount();

    // Commission rates for display
    const COMMISSION_RATES = FG_INITIAL_RATES.map((rate, i) => ({
      level: i + 1,
      percentage: rate,
      label: `Level ${i + 1}`
    }));

    // Good standing info
    const hasPro = await hasProAccess(userId);
    const goodStandingStarted = affiliate.good_standing_started_at ? new Date(affiliate.good_standing_started_at) : null;
    const goodStandingAchieved = affiliate.good_standing_achieved_at ? new Date(affiliate.good_standing_achieved_at) : null;
    const now = new Date();
    let goodStandingDaysCompleted = 0;
    if (goodStandingStarted) {
      goodStandingDaysCompleted = Math.min(
        Math.floor((now - goodStandingStarted) / (1000 * 60 * 60 * 24)),
        30
      );
    }

    // NOTE: usage_points (Aura Restored) intentionally excluded from this endpoint.
    // Aura Restored shopping points are separate from affiliate commissions.
    // Points data is served by /api/future-generations/points instead.

    res.json({
      member: true,
      referral_code: affiliate.referral_code,
      referral_link: `https://financial-revolution.polsia.app/pricing.html?ref=${affiliate.referral_code}`,
      active_referrals: parseInt(referralCount.rows[0]?.active_referrals || 0),
      total_referrals: parseInt(referralCount.rows[0]?.total_referrals || 0),
      balance_cents: totalBalance,
      pending_balance_cents: affiliate.pending_balance_cents,
      approved_balance_cents: affiliate.approved_balance_cents,
      lifetime_earnings_cents: affiliate.lifetime_earnings_cents,
      // Tree placement info
      affiliate_level: affiliate.affiliate_level || 1,
      placement_method: affiliate.placement_method || 'seed',
      // Downline stats
      downline_by_level: downlineByLevel.rows.map(r => ({
        level: r.affiliate_level,
        count: parseInt(r.count, 10)
      })),
      total_downline: totalDownline,
      total_org_size: totalOrgSize,
      // Seed phase info
      seed_phase: {
        active: firstLineCount < 100,
        first_line_count: firstLineCount,
        first_line_capacity: 100,
        first_line_remaining: Math.max(0, 100 - firstLineCount)
      },
      // Commission rates for display
      commission_rates: COMMISSION_RATES,
      tree: treeCount.rows,
      commissions_by_level: commissionsByLevel.rows,
      recent_commissions: recentCommissions.rows,
      payout_info: {
        can_request_payout: affiliate.approved_balance_cents >= PAYOUT_MINIMUM_CENTS,
        minimum_cents: PAYOUT_MINIMUM_CENTS,
        minimum_display: '$50.00'
      },
      good_standing: {
        achieved: !!goodStandingAchieved,
        achieved_at: goodStandingAchieved ? goodStandingAchieved.toISOString() : null,
        days_completed: goodStandingDaysCompleted,
        days_remaining: goodStandingAchieved ? 0 : Math.max(0, 30 - goodStandingDaysCompleted),
        started_at: goodStandingStarted ? goodStandingStarted.toISOString() : null,
        can_collect_bonuses: !!goodStandingAchieved,
        is_pro: hasPro
      },
    });
  } catch (err) {
    console.error('GET /api/future-generations/dashboard error:', err.message);
    res.status(500).json({ error: 'Failed to fetch Future Generations dashboard' });
  }
});

