// GET /api/heloc-velocity/debt-data
// Returns user debt data from FACTS ledger for pre-populating the HELOC calculators.
// Includes: all debts, monthly income/expense summary, and any HELOC accounts from bank_accounts.
// Gated to Elite Pro + Sovereign Executive.
app.get('/api/heloc-velocity/debt-data', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    // Check Elite access
    const eliteCheck = await pool.query(
      'SELECT pricing_tier, plan, paid_until, is_creator FROM users WHERE id = $1',
      [userId]
    );
    if (!eliteCheck.rows.length) return res.status(404).json({ error: 'User not found' });
    const u = eliteCheck.rows[0];
    const isCreator = u.is_creator || (u.email && u.email.toLowerCase() === CREATOR_EMAIL);
    const isEliteTier = ['tfr_elite', 'sovereign_executive'].includes(u.pricing_tier);
    const isActiveSub = u.plan === 'paid' && u.paid_until && new Date(u.paid_until) > new Date();
    if (!isCreator && !(isEliteTier && isActiveSub)) {
      return res.status(403).json({ error: 'Elite Pro access required' });
    }

    // Fetch all debts
    const debtsRes = await pool.query(
      'SELECT id, name, balance, interest_rate, minimum_payment, current_payment, notes FROM debts WHERE user_id = $1 ORDER BY interest_rate DESC, balance DESC',
      [userId]
    );

    // Fetch last 3 months income/expense totals from transactions
    const incomeRes = await pool.query(
      `SELECT COALESCE(SUM(amount), 0) AS total
       FROM transactions
       WHERE user_id = $1 AND type = 'income'
         AND transaction_date >= (CURRENT_DATE - INTERVAL '3 months')`,
      [userId]
    );
    const expenseRes = await pool.query(
      `SELECT COALESCE(SUM(amount), 0) AS total
       FROM transactions
       WHERE user_id = $1 AND type = 'expense'
         AND transaction_date >= (CURRENT_DATE - INTERVAL '3 months')`,
      [userId]
    );

    // Fetch bank accounts that are HELOC type
    const helocRes = await pool.query(
      `SELECT id, name, current_balance, institution_name
       FROM bank_accounts
       WHERE user_id = $1 AND LOWER(account_type) LIKE '%heloc%'
       ORDER BY created_at DESC`,
      [userId]
    );

    const avgMonthlyIncome = parseFloat(incomeRes.rows[0].total) / 3;
    const avgMonthlyExpenses = parseFloat(expenseRes.rows[0].total) / 3;

    // Compute total monthly interest across all debts (for Interest Leak display)
    const debts = debtsRes.rows.map(d => ({
      id: d.id,
      name: d.name,
      balance: parseFloat(d.balance),
      interest_rate: parseFloat(d.interest_rate),
      minimum_payment: parseFloat(d.minimum_payment),
      current_payment: d.current_payment ? parseFloat(d.current_payment) : parseFloat(d.minimum_payment),
      notes: d.notes || null,
      // Monthly interest charge at current balance
      monthly_interest: parseFloat(d.balance) * (parseFloat(d.interest_rate) / 100 / 12),
    }));

    const totalMonthlyInterest = debts.reduce((sum, d) => sum + d.monthly_interest, 0);
    const totalAnnualInterest = totalMonthlyInterest * 12;
    const totalDebtBalance = debts.reduce((sum, d) => sum + d.balance, 0);

    res.json({
      debts,
      avg_monthly_income: avgMonthlyIncome,
      avg_monthly_expenses: avgMonthlyExpenses,
      avg_monthly_surplus: avgMonthlyIncome - avgMonthlyExpenses,
      total_monthly_interest_leak: totalMonthlyInterest,
      total_annual_interest_leak: totalAnnualInterest,
      total_debt_balance: totalDebtBalance,
      heloc_accounts: helocRes.rows.map(a => ({
        id: a.id,
        name: a.name,
        balance: parseFloat(a.current_balance || 0),
        institution: a.institution_name || null,
      })),
      has_data: debts.length > 0 || avgMonthlyIncome > 0,
    });
  } catch (err) {
    console.error('GET /api/heloc-velocity/debt-data error:', err.message);
    res.status(500).json({ error: 'Failed to load debt data' });
  }
});

