// Initialize inactivity manager scheduler (runs daily at 2 AM UTC)
// This checks for inactive accounts and sends warning emails
function initializeInactivityScheduler() {
  const schedule = '0 2 * * *'; // 2 AM UTC daily

  if (!cron.validate(schedule)) {
    console.error('[Scheduler] Invalid cron schedule:', schedule);
    return null;
  }

  const task = cron.schedule(schedule, () => {
    const p = getPool();
    if (!p) {
      console.error('[Scheduler] Inactivity job skipped: pool unavailable');
      return;
    }
    console.log('[Scheduler] Triggering inactivity check job');
    runInactivityJob(p).catch(err => {
      console.error('[Scheduler] Inactivity job error:', err.message);
    });
  }, {
    scheduled: true,
    timezone: 'UTC'
  });

  console.log('[Scheduler] Inactivity job initialized (daily at 2 AM UTC)');

  return {
    task,
    runNow: () => {
      const p = getPool();
      return p ? runInactivityJob(p) : Promise.reject(new Error('pool unavailable'));
    }
  };
}

// Initialize scheduler on startup — skip if in-process crons are disabled
