// Initialize heartbeat compliance schedulers (Monthly Heartbeat v2)
// - 1st of month 08:00 UTC: Day 1 reminders (heartbeat window open)
// - 5th of month 09:00 UTC: squad health reports + family tag alerts ("2 days left")
// - 8th of month 00:30 UTC: flip non-completers to 'pending', move commissions to escrow
// - Daily 10:00 UTC: Day 60/90 cliff warning checks
const {
  runHeartbeatComplianceCheck,
  runDay1Reminders,
  runDay5Jobs,
  runDay60and90Warnings,
  releaseEscrow: releaseHeartbeatEscrow
} = require('./jobs/heartbeat-compliance');

function initializeHeartbeatComplianceScheduler() {
  // 1st of every month at 08:00 UTC — Day 1 heartbeat window open reminders
  const schedule1st = '0 8 1 * *';
  if (!cron.validate(schedule1st)) {
    console.error('[HeartbeatV2] Invalid cron schedule (Day 1):', schedule1st);
    return null;
  }
  const task1st = cron.schedule(schedule1st, () => {
    const p = getPool();
    if (!p) { console.error('[HeartbeatV2] Day 1 reminders skipped: pool unavailable'); return; }
    console.log('[HeartbeatV2] Running Day 1 heartbeat reminders (1st of month)');
    runDay1Reminders(p).catch(err => {
      console.error('[HeartbeatV2] Day 1 reminders error:', err.message);
    });
  }, { scheduled: true, timezone: 'UTC' });

  // 5th of every month at 09:00 UTC — squad health report + family alerts
  const schedule5th = '0 9 5 * *';
  const task5th = cron.schedule(schedule5th, () => {
    const p = getPool();
    if (!p) { console.error('[HeartbeatV2] Day 5 jobs skipped: pool unavailable'); return; }
    console.log('[HeartbeatV2] Running Day 5 squad health + family alerts');
    runDay5Jobs(p).catch(err => {
      console.error('[HeartbeatV2] Day 5 job error:', err.message);
    });
  }, { scheduled: true, timezone: 'UTC' });

  // 8th of every month at 00:30 UTC — main compliance check: pending + escrow
  const schedule8th = '30 0 8 * *';
  const task8th = cron.schedule(schedule8th, () => {
    const p = getPool();
    if (!p) { console.error('[HeartbeatV2] Compliance check skipped: pool unavailable'); return; }
    console.log('[HeartbeatV2] Running monthly compliance check (8th) — escrow + cliff');
    runHeartbeatComplianceCheck(p).catch(err => {
      console.error('[HeartbeatV2] 8th compliance check error:', err.message);
    });
  }, { scheduled: true, timezone: 'UTC' });

  // Daily at 10:00 UTC — Day 60/90 cliff warning checks
  const scheduleDailyCliff = '0 10 * * *';
  const taskDailyCliff = cron.schedule(scheduleDailyCliff, () => {
    const p = getPool();
    if (!p) { console.error('[HeartbeatV2] Cliff warnings skipped: pool unavailable'); return; }
    runDay60and90Warnings(p).catch(err => {
      console.error('[HeartbeatV2] Day 60/90 cliff check error:', err.message);
    });
  }, { scheduled: true, timezone: 'UTC' });

  console.log('[HeartbeatV2] Schedulers initialized: Day1 08:00 | Day5 09:00 | Day8 00:30 | Daily cliff 10:00 (all UTC)');

  return {
    task1st,
    task5th,
    task8th,
    taskDailyCliff,
    runDay1: () => { const p = getPool(); return p ? runDay1Reminders(p) : Promise.reject(new Error('pool unavailable')); },
    runComplianceCheck: () => { const p = getPool(); return p ? runHeartbeatComplianceCheck(p) : Promise.reject(new Error('pool unavailable')); },
    runDay5: () => { const p = getPool(); return p ? runDay5Jobs(p) : Promise.reject(new Error('pool unavailable')); },
    runCliffWarnings: () => { const p = getPool(); return p ? runDay60and90Warnings(p) : Promise.reject(new Error('pool unavailable')); }
  };
}

