// PATCH /api/user/verification-method — Update 2FA delivery method (email or sms)
app.patch('/api/user/verification-method', requireAuth, async (req, res) => {
  try {
    const { method, phone } = req.body;

    if (!method || !['email', 'sms'].includes(method)) {
      return res.status(400).json({ error: 'Method must be "email" or "sms"' });
    }

    if (method === 'sms') {
      if (!phone) return res.status(400).json({ error: 'Phone number required for SMS verification' });

      // Validate E.164: + followed by 7-15 digits
      const e164Regex = /^\+[1-9]\d{6,14}$/;
      const cleanPhone = phone.trim();
      if (!e164Regex.test(cleanPhone)) {
        return res.status(400).json({
          error: 'Phone number must be in E.164 format, e.g. +12025551234'
        });
      }

      // Send a test verification to confirm the number is reachable
      const smsResult = await sendVerification(cleanPhone);
      if (!smsResult.success && !smsResult.stub) {
        return res.status(400).json({ error: smsResult.error || 'Failed to send verification code to that number.' });
      }

      await pool.query(
        `UPDATE users SET verification_method = 'sms', verified_phone = $1, updated_at = NOW() WHERE id = $2`,
        [cleanPhone, req.userId]
      );

      return res.json({
        success: true,
        message: smsResult.stub
          ? 'Phone saved (SMS in test mode — any 6-digit code will be accepted on your next login).'
          : 'Saved. SMS verification is now active for your account.',
        method: 'sms',
        phone: cleanPhone
      });
    }

    // Switching to email — keep phone stored but change method
    await pool.query(
      `UPDATE users SET verification_method = 'email', updated_at = NOW() WHERE id = $1`,
      [req.userId]
    );
    res.json({ success: true, message: 'Verification codes will be sent to your email.', method: 'email' });
  } catch (err) {
    console.error('PATCH /api/user/verification-method error:', err.message);
    res.status(500).json({ error: 'Failed to update verification method' });
  }
});

