// ═══════════════════════════════════════════════════════════════════════════
// ─── FINANCIAL NEWS HUB ───────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════

const NEWS_CACHE = { data: null, timestamp: 0 };
const NEWS_CACHE_TTL = 30 * 60 * 1000; // 30 minutes

const NEWS_FEEDS = [
  { url: 'https://www.cnbc.com/id/100003114/device/rss/rss.html', source: 'CNBC Markets' },
  { url: 'https://www.cnbc.com/id/10000664/device/rss/rss.html', source: 'CNBC Finance' },
  { url: 'https://www.cnbc.com/id/15839135/device/rss/rss.html', source: 'CNBC Economy' },
  { url: 'https://feeds.content.dowjones.io/public/rss/mw_realtimeheadlines', source: 'MarketWatch' },
  { url: 'https://feeds.reuters.com/reuters/businessNews', source: 'Reuters' },
  { url: 'https://feeds.reuters.com/reuters/topNews', source: 'Reuters Top' },
];

function parseRSSXML(xml) {
  const items = [];
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xml)) !== null) {
    const item = match[1];
    const getField = (tag) => {
      const m = item.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${tag}>`, 'i'));
      if (!m) return '';
      return m[1]
        .replace(/<[^>]+>/g, '')
        .replace(/&apos;/g, "'")
        .replace(/&quot;/g, '"')
        .replace(/&lt;/g, '<')
        .replace(/&gt;/g, '>')
        .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code, 10)))
        .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
        .replace(/&amp;/g, '&')
        .replace(/&nbsp;/g, ' ')
        .trim();
    };
    const linkMatch = item.match(/<link[^>]*>\s*(https?:\/\/[^\s<]+)/i)
      || item.match(/<guid[^>]*>(https?:\/\/[^\s<]+)<\/guid>/i);
    const link = linkMatch ? linkMatch[1].trim() : '';
    const title = getField('title');
    const description = getField('description').substring(0, 280);
    const pubDate = getField('pubDate');
    if (title && link) {
      items.push({
        title,
        link,
        description,
        pubDate,
        timestamp: pubDate ? new Date(pubDate).getTime() : 0
      });
    }
  }
  return items;
}

function categorizeNews(title, description) {
  const text = (title + ' ' + description).toLowerCase();
  if (/\binterest rate|federal reserve|\bthe fed\b|inflation\b|cpi\b|monetary policy|rate cut|rate hike|treasury yield|fomc/.test(text)) return 'Rates';
  if (/\btax\b|irs\b|tax deduction|tax refund|tax filing|w-2\b|1099\b|capital gains tax|tax season/.test(text)) return 'Taxes';
  if (/housing market|mortgage rate|real estate|home price|home sale|foreclosure|rental price|property tax|housing cost/.test(text)) return 'Housing';
  if (/social security|medicare|medicaid|retirement fund|401k|403b|\bira\b|pension fund|roth ira|annuity|retire/.test(text)) return 'Retirement';
  if (/student loan|tuition cost|college cost|financial aid|fafsa|student debt/.test(text)) return 'Student Loans';
  if (/credit card|credit score|fico|personal loan rate|auto loan|consumer debt|credit limit/.test(text)) return 'Credit';
  if (/job market|unemployment|layoff|hiring|wage growth|payroll|job loss|employment rate|jobless/.test(text)) return 'Jobs';
  if (/stock market|\bs&p\b|nasdaq|dow jones|wall street|equity market|shares|stock index|bull market|bear market|\betf\b/.test(text)) return 'Markets';
  return 'Economy';
}

// GET /api/news — Aggregated financial news from RSS feeds
app.get('/api/news', async (req, res) => {
  try {
    const now = Date.now();
    if (NEWS_CACHE.data && (now - NEWS_CACHE.timestamp) < NEWS_CACHE_TTL) {
      return res.json({
        success: true,
        articles: NEWS_CACHE.data,
        cached: true,
        count: NEWS_CACHE.data.length,
        lastUpdated: new Date(NEWS_CACHE.timestamp).toISOString()
      });
    }

    const fetchFeed = async (feed) => {
      try {
        const response = await fetch(feed.url, {
          headers: {
            'User-Agent': 'Mozilla/5.0 (compatible; FinancialRevolution/1.0; +https://financial-revolution.polsia.app/news)',
            'Accept': 'application/rss+xml, application/xml, text/xml, */*'
          },
          signal: AbortSignal.timeout(8000)
        });
        if (!response.ok) {
          console.warn(`[News] Feed ${feed.source} returned ${response.status}`);
          return [];
        }
        const xml = await response.text();
        const items = parseRSSXML(xml);
        return items.map(item => ({
          ...item,
          source: feed.source,
          category: categorizeNews(item.title, item.description)
        }));
      } catch (err) {
        console.warn(`[News] Feed failed: ${feed.source} — ${err.message}`);
        return [];
      }
    };

    const results = await Promise.allSettled(NEWS_FEEDS.map(fetchFeed));
    let articles = [];
    for (const r of results) {
      if (r.status === 'fulfilled') articles.push(...r.value);
    }

    // Deduplicate by first 60 chars of title
    const seen = new Set();
    articles = articles.filter(a => {
      const key = a.title.toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 60);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });

    // Sort newest first
    articles.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
    articles = articles.slice(0, 100);

    NEWS_CACHE.data = articles;
    NEWS_CACHE.timestamp = now;

    console.log(`[News] Fetched ${articles.length} articles from ${NEWS_FEEDS.length} feeds`);
    res.json({
      success: true,
      articles,
      cached: false,
      count: articles.length,
      lastUpdated: new Date().toISOString()
    });
  } catch (err) {
    console.error('[News] API error:', err.message);
    // If cache has stale data, return it
    if (NEWS_CACHE.data) {
      return res.json({
        success: true,
        articles: NEWS_CACHE.data,
        cached: true,
        stale: true,
        count: NEWS_CACHE.data.length,
        lastUpdated: new Date(NEWS_CACHE.timestamp).toISOString()
      });
    }
    res.status(500).json({ success: false, error: 'Failed to fetch news' });
  }
});

