// GET /api/net-worth — Get all entries for the logged-in user (enhanced with category)
app.get('/api/net-worth', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Net Worth Dashboard is a paid feature. Upgrade to unlock.', code: 'PRO_REQUIRED' });
    const result = await pool.query(
      `SELECT id, type, name, value, category, interest_rate, created_at, updated_at
       FROM net_worth_entries
       WHERE user_id = $1
       ORDER BY type, category, created_at ASC`,
      [req.userId]
    );
    const assets = result.rows.filter(r => r.type === 'asset');
    const debts  = result.rows.filter(r => r.type === 'debt');
    const totalAssets = assets.reduce((s, r) => s + parseFloat(r.value), 0);
    const totalDebts  = debts.reduce((s, r) => s + parseFloat(r.value), 0);

    // Build category breakdowns
    const assetsByCategory = {};
    assets.forEach(r => {
      const cat = r.category || 'other';
      assetsByCategory[cat] = (assetsByCategory[cat] || 0) + parseFloat(r.value);
    });
    const debtsByCategory = {};
    debts.forEach(r => {
      const cat = r.category || 'other';
      debtsByCategory[cat] = (debtsByCategory[cat] || 0) + parseFloat(r.value);
    });

    res.json({
      success: true,
      entries: result.rows,
      summary: {
        total_assets: totalAssets,
        total_debts: totalDebts,
        net_worth: totalAssets - totalDebts,
        assets_by_category: assetsByCategory,
        debts_by_category: debtsByCategory
      }
    });
  } catch (err) {
    console.error('[NetWorth] GET error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to fetch net worth data' });
  }
});

// POST /api/net-worth — Create a new asset or debt entry
app.post('/api/net-worth', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Net Worth Dashboard is a paid feature. Upgrade to unlock.', code: 'PRO_REQUIRED' });
    const { type, name, value, category, interest_rate } = req.body;
    if (!type || !['asset', 'debt'].includes(type)) {
      return res.status(400).json({ success: false, error: 'type must be "asset" or "debt"' });
    }
    if (!name || typeof name !== 'string' || !name.trim()) {
      return res.status(400).json({ success: false, error: 'name is required' });
    }
    const numValue = parseFloat(value);
    if (isNaN(numValue) || numValue < 0) {
      return res.status(400).json({ success: false, error: 'value must be a non-negative number' });
    }
    const cat = (typeof category === 'string' && category.trim()) ? category.trim() : 'other';
    const rate = (interest_rate !== undefined && interest_rate !== null && interest_rate !== '') ? parseFloat(interest_rate) : null;
    if (rate !== null && (isNaN(rate) || rate < 0 || rate > 100)) {
      return res.status(400).json({ success: false, error: 'interest_rate must be between 0 and 100' });
    }
    const result = await pool.query(
      `INSERT INTO net_worth_entries (user_id, type, name, value, category, interest_rate)
       VALUES ($1, $2, $3, $4, $5, $6)
       RETURNING id, type, name, value, category, interest_rate, created_at, updated_at`,
      [req.userId, type, name.trim(), numValue, cat, rate]
    );
    res.status(201).json({ success: true, entry: result.rows[0] });
  } catch (err) {
    console.error('[NetWorth] POST error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to create entry' });
  }
});

// PUT /api/net-worth/:id — Update an existing entry
app.put('/api/net-worth/:id', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Net Worth Dashboard is a paid feature. Upgrade to unlock.', code: 'PRO_REQUIRED' });
    const id = parseInt(req.params.id);
    if (isNaN(id)) return res.status(400).json({ success: false, error: 'Invalid entry ID' });
    const { name, value, category, interest_rate } = req.body;
    if (!name || typeof name !== 'string' || !name.trim()) {
      return res.status(400).json({ success: false, error: 'name is required' });
    }
    const numValue = parseFloat(value);
    if (isNaN(numValue) || numValue < 0) {
      return res.status(400).json({ success: false, error: 'value must be a non-negative number' });
    }
    const cat = (typeof category === 'string' && category.trim()) ? category.trim() : 'other';
    const rate = (interest_rate !== undefined && interest_rate !== null && interest_rate !== '') ? parseFloat(interest_rate) : null;
    if (rate !== null && (isNaN(rate) || rate < 0 || rate > 100)) {
      return res.status(400).json({ success: false, error: 'interest_rate must be between 0 and 100' });
    }
    const result = await pool.query(
      `UPDATE net_worth_entries
       SET name = $1, value = $2, category = $3, interest_rate = $4, updated_at = NOW()
       WHERE id = $5 AND user_id = $6
       RETURNING id, type, name, value, category, interest_rate, created_at, updated_at`,
      [name.trim(), numValue, cat, rate, id, req.userId]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'Entry not found' });
    }
    res.json({ success: true, entry: result.rows[0] });
  } catch (err) {
    console.error('[NetWorth] PUT error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to update entry' });
  }
});

