// POST /api/net-worth/snapshot — Save today's net worth snapshot
app.post('/api/net-worth/snapshot', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Net Worth Dashboard is a paid feature. Upgrade to unlock.', code: 'PRO_REQUIRED' });
    const result = await pool.query(
      `SELECT id, type, value FROM net_worth_entries WHERE user_id = $1`,
      [req.userId]
    );
    const assets = result.rows.filter(r => r.type === 'asset');
    const debts  = result.rows.filter(r => r.type === 'debt');
    const totalAssets = assets.reduce((s, r) => s + parseFloat(r.value), 0);
    const totalDebts  = debts.reduce((s, r) => s + parseFloat(r.value), 0);
    const netWorth = totalAssets - totalDebts;

    const snapshotDate = new Date().toISOString().split('T')[0];
    // Upsert: one snapshot per user per day
    const snap = await pool.query(
      `INSERT INTO net_worth_snapshots (user_id, total_assets, total_debts, net_worth, snapshot_date)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (user_id, snapshot_date) DO UPDATE
         SET total_assets = EXCLUDED.total_assets,
             total_debts  = EXCLUDED.total_debts,
             net_worth    = EXCLUDED.net_worth,
             created_at   = NOW()
       RETURNING *`,
      [req.userId, totalAssets, totalDebts, netWorth, snapshotDate]
    );
    res.json({ success: true, snapshot: snap.rows[0] });
  } catch (err) {
    console.error('[NetWorth] Snapshot error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to save snapshot' });
  }
});

