// DUPLICATE DETECTION
// ─────────────────────────────────────────────────────────────────────────────

// GET /api/duplicates/scan?type=all|transactions|debts|net_worth|bills|bank_accounts|gift_cards
app.get('/api/duplicates/scan', requireAuth, async (req, res) => {
  try {
    const { type = 'all' } = req.query;
    const userId = req.userId;
    const results = {};
    const shouldScan = (t) => type === 'all' || type === t;

    // --- Transactions ---
    if (shouldScan('transactions')) {
      const r = await pool.query(`
        SELECT
          transaction_date::text AS key_date,
          ROUND(amount::numeric, 2)::text AS key_amount,
          LOWER(TRIM(description)) AS key_desc,
          json_agg(
            json_build_object(
              'id', id,
              'description', description,
              'amount', amount,
              'transaction_date', transaction_date::text,
              'type', type,
              'category_id', category_id,
              'created_at', created_at::text
            ) ORDER BY created_at ASC
          ) AS entries
        FROM transactions
        WHERE user_id = $1
        GROUP BY key_date, key_amount, key_desc
        HAVING COUNT(*) > 1
        ORDER BY COUNT(*) DESC
      `, [userId]);
      if (r.rows.length > 0) results.transactions = r.rows.map(row => row.entries);
    }

    // --- Debts ---
    if (shouldScan('debts')) {
      const r = await pool.query(`
        SELECT
          LOWER(TRIM(name)) AS key_name,
          ROUND(balance::numeric, 2) AS key_balance,
          ROUND(interest_rate::numeric, 2) AS key_rate,
          json_agg(
            json_build_object(
              'id', id,
              'name', name,
              'balance', balance,
              'interest_rate', interest_rate,
              'minimum_payment', minimum_payment,
              'created_at', created_at::text
            ) ORDER BY created_at ASC
          ) AS entries
        FROM debts
        WHERE user_id = $1
        GROUP BY key_name, key_balance, key_rate
        HAVING COUNT(*) > 1
        ORDER BY COUNT(*) DESC
      `, [userId]);
      if (r.rows.length > 0) results.debts = r.rows.map(row => row.entries);
    }

    // --- Net Worth ---
    if (shouldScan('net_worth')) {
      const r = await pool.query(`
        SELECT
          LOWER(TRIM(name)) AS key_name,
          type AS key_type,
          ROUND(value::numeric, 2) AS key_value,
          json_agg(
            json_build_object(
              'id', id,
              'name', name,
              'type', type,
              'value', value,
              'category', category,
              'created_at', created_at::text
            ) ORDER BY created_at ASC
          ) AS entries
        FROM net_worth_entries
        WHERE user_id = $1
        GROUP BY key_name, key_type, key_value
        HAVING COUNT(*) > 1
        ORDER BY COUNT(*) DESC
      `, [userId]);
      if (r.rows.length > 0) results.net_worth = r.rows.map(row => row.entries);
    }

    // --- Bills ---
    if (shouldScan('bills')) {
      const r = await pool.query(`
        SELECT
          LOWER(TRIM(name)) AS key_name,
          ROUND(amount::numeric, 2) AS key_amount,
          due_day AS key_due,
          json_agg(
            json_build_object(
              'id', id,
              'name', name,
              'amount', amount,
              'due_day', due_day,
              'frequency', frequency,
              'created_at', created_at::text
            ) ORDER BY created_at ASC
          ) AS entries
        FROM recurring_bills
        WHERE user_id = $1
        GROUP BY key_name, key_amount, key_due
        HAVING COUNT(*) > 1
        ORDER BY COUNT(*) DESC
      `, [userId]);
      if (r.rows.length > 0) results.bills = r.rows.map(row => row.entries);
    }

    // --- Bank Accounts ---
    if (shouldScan('bank_accounts')) {
      const r = await pool.query(`
        SELECT
          LOWER(TRIM(name)) AS key_name,
          json_agg(
            json_build_object(
              'id', id,
              'name', name,
              'current_balance', current_balance,
              'starting_balance', starting_balance,
              'created_at', created_at::text
            ) ORDER BY created_at ASC
          ) AS entries
        FROM bank_accounts
        WHERE user_id = $1 AND is_archived = FALSE
        GROUP BY key_name
        HAVING COUNT(*) > 1
        ORDER BY COUNT(*) DESC
      `, [userId]);
      if (r.rows.length > 0) results.bank_accounts = r.rows.map(row => row.entries);
    }

    // --- Gift Cards ---
    if (shouldScan('gift_cards')) {
      const r = await pool.query(`
        SELECT
          LOWER(TRIM(name)) AS key_name,
          ROUND(initial_balance::numeric, 2) AS key_balance,
          json_agg(
            json_build_object(
              'id', id,
              'name', name,
              'initial_balance', initial_balance,
              'current_balance', current_balance,
              'created_at', created_at::text
            ) ORDER BY created_at ASC
          ) AS entries
        FROM gift_cards
        WHERE user_id = $1 AND is_archived = FALSE
        GROUP BY key_name, key_balance
        HAVING COUNT(*) > 1
        ORDER BY COUNT(*) DESC
      `, [userId]);
      if (r.rows.length > 0) results.gift_cards = r.rows.map(row => row.entries);
    }

    const totalGroups = Object.values(results).reduce((sum, groups) => sum + groups.length, 0);
    const totalDuplicates = Object.values(results).reduce(
      (sum, groups) => sum + groups.reduce((s, g) => s + g.length - 1, 0), 0
    );

    res.json({ success: true, results, totalGroups, totalDuplicates });
  } catch (err) {
    console.error('[Duplicates] scan error:', err.message);
    res.status(500).json({ success: false, error: 'Duplicate scan failed' });
  }
});

// DELETE /api/duplicates/bulk — delete selected duplicate entries
app.delete('/api/duplicates/bulk', requireAuth, async (req, res) => {
  try {
    const { deletions } = req.body; // Array of { type, ids: [...] }
    if (!Array.isArray(deletions) || deletions.length === 0) {
      return res.status(400).json({ success: false, error: 'No deletions specified' });
    }

    const userId = req.userId;
    let totalDeleted = 0;
    const client = await pool.connect();

    try {
      await client.query('BEGIN');

      for (const { type, ids } of deletions) {
        if (!ids || !Array.isArray(ids) || ids.length === 0) continue;

        if (type === 'transactions') {
          // Handle each transaction individually (bank balance reversal)
          for (const id of ids) {
            const txnRes = await client.query(
              'DELETE FROM transactions WHERE id = $1 AND user_id = $2 RETURNING *',
              [parseInt(id), userId]
            );
            if (txnRes.rows.length === 0) continue;
            const deleted = txnRes.rows[0];
            // Reverse bank account balance if tagged (allocations cascade-delete automatically)
            if (deleted.bank_account_id) {
              const reversal = deleted.type === 'income' ? -parseFloat(deleted.amount) : parseFloat(deleted.amount);
              await client.query(
                'UPDATE bank_accounts SET current_balance = current_balance + $1, updated_at = NOW() WHERE id = $2',
                [reversal, deleted.bank_account_id]
              );
            }
            totalDeleted++;
          }
        } else {
          const tableMap = {
            debts: 'debts',
            net_worth: 'net_worth_entries',
            bills: 'recurring_bills',
            bank_accounts: 'bank_accounts',
            gift_cards: 'gift_cards'
          };
          const table = tableMap[type];
          if (!table) continue;
          const result = await client.query(
            `DELETE FROM ${table} WHERE id = ANY($1::int[]) AND user_id = $2`,
            [ids.map(Number), userId]
          );
          totalDeleted += result.rowCount;
        }
      }

      await client.query('COMMIT');
      res.json({ success: true, deleted: totalDeleted });
    } catch (txErr) {
      await client.query('ROLLBACK');
      throw txErr;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('[Duplicates] bulk delete error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to delete duplicates' });
  }
});

