// PUT /api/portfolio/prices — batch upsert current prices (and create price snapshot)
app.put('/api/portfolio/prices', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Paid subscription required' });

    const { prices } = req.body; // Array of { ticker, price }
    if (!Array.isArray(prices) || prices.length === 0) {
      return res.status(400).json({ success: false, error: 'prices array required' });
    }

    const today = new Date().toISOString().split('T')[0];
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      for (const { ticker, price } of prices) {
        if (!ticker || price == null) continue;
        const t = ticker.toUpperCase();
        const p = parseFloat(price);
        // Upsert current price
        await client.query(
          `INSERT INTO portfolio_prices (user_id, ticker, current_price, updated_at)
           VALUES ($1, $2, $3, NOW())
           ON CONFLICT (user_id, ticker) DO UPDATE SET current_price = EXCLUDED.current_price, updated_at = NOW()`,
          [req.userId, t, p]
        );
        // Upsert today's snapshot (only one snapshot per ticker per day)
        await client.query(
          `INSERT INTO portfolio_price_snapshots (user_id, ticker, price, snapshot_date)
           VALUES ($1, $2, $3, $4)
           ON CONFLICT (user_id, ticker, snapshot_date) DO UPDATE SET price = EXCLUDED.price`,
          [req.userId, t, p, today]
        );
      }
      await client.query('COMMIT');
      res.json({ success: true });
    } catch (innerErr) {
      await client.query('ROLLBACK');
      throw innerErr;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error('[Portfolio] update prices error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to update prices' });
  }
});

// GET /api/portfolio/holdings — computed holdings per account (or combined)
// ?account_type=ira|roth_ira|brokerage|combined  (default: combined)
// ?ticker=SOC  (optional — filter to a specific ticker)
app.get('/api/portfolio/holdings', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Paid subscription required' });

    await ensurePortfolioAccounts(req.userId);

    const { account_type = 'combined', ticker: filterTicker } = req.query;

    // Fetch accounts
    const acctResult = await pool.query(
      `SELECT id, account_type, display_name, starting_value, starting_date
       FROM portfolio_accounts WHERE user_id = $1`,
      [req.userId]
    );
    const accounts = acctResult.rows;
    const accountMap = {};
    accounts.forEach(a => { accountMap[a.id] = a; });

    // Build account_id filter
    let acctIds = accounts.map(a => a.id);
    if (account_type !== 'combined') {
      const filtered = accounts.filter(a => a.account_type === account_type);
      if (!filtered.length) return res.json({ success: true, holdings: [], summary: {}, accounts });
      acctIds = filtered.map(a => a.id);
    }

    // Fetch all transactions for these accounts
    let txSql = `
      SELECT t.id, t.account_id, t.ticker, t.transaction_type,
             t.shares, t.price_per_share, t.amount, t.transaction_date,
             a.account_type, a.display_name
      FROM portfolio_transactions t
      JOIN portfolio_accounts a ON a.id = t.account_id
      WHERE t.account_id = ANY($1::int[])
    `;
    const txParams = [acctIds];
    if (filterTicker) { txParams.push(filterTicker.toUpperCase()); txSql += ` AND UPPER(t.ticker) = $${txParams.length}`; }
    txSql += ' ORDER BY t.transaction_date ASC';

    const txResult = await pool.query(txSql, txParams);
    const transactions = txResult.rows;

    // Fetch current prices
    const priceResult = await pool.query(
      `SELECT ticker, current_price FROM portfolio_prices WHERE user_id = $1`,
      [req.userId]
    );
    const priceMap = {};
    priceResult.rows.forEach(p => { priceMap[p.ticker.toUpperCase()] = parseFloat(p.current_price); });

    // Compute holdings grouped by (account_id, ticker)
    // holdingsMap[`${account_id}:${ticker}`] = { shares, costBasis, accountId, accountType, displayName, ticker }
    const holdingsMap = {};
    const cashMap = {}; // cashMap[account_id] = cash balance

    for (const tx of transactions) {
      const key = `${tx.account_id}:${tx.ticker.toUpperCase()}`;
      const acctKey = String(tx.account_id);

      if (!holdingsMap[key]) {
        holdingsMap[key] = {
          ticker: tx.ticker.toUpperCase(),
          account_id: tx.account_id,
          account_type: tx.account_type,
          display_name: tx.display_name,
          shares: 0,
          cost_basis: 0
        };
      }
      if (!cashMap[acctKey]) cashMap[acctKey] = 0;

      const shares = parseFloat(tx.shares || 0);
      const price  = parseFloat(tx.price_per_share || 0);
      const amount = parseFloat(tx.amount || 0);

      const divAmt   = parseFloat(tx.dividend_amount || 0);
      const lendAmt  = parseFloat(tx.lending_income  || 0);
      const intAmt   = parseFloat(tx.interest_amount || 0);
      const borrowAmt= parseFloat(tx.borrowing_cost  || 0);
      const feeAmt   = parseFloat(tx.fee             || 0);

      switch (tx.transaction_type) {
        case 'buy':
          holdingsMap[key].shares     += shares;
          holdingsMap[key].cost_basis += amount + feeAmt;
          cashMap[acctKey]            -= (amount + feeAmt);
          break;
        case 'sell':
          // Proportionally reduce cost basis
          if (holdingsMap[key].shares > 0) {
            const avgCost = holdingsMap[key].cost_basis / holdingsMap[key].shares;
            holdingsMap[key].cost_basis -= avgCost * shares;
          }
          holdingsMap[key].shares -= shares;
          cashMap[acctKey]        += (amount - feeAmt);
          break;
        case 'sto':
          // Sell To Open (covered call / put): premium received, does NOT add shares
          cashMap[acctKey] += (amount - feeAmt);
          break;
        case 'btc':
          // Buy To Close: premium paid, does NOT remove shares
          cashMap[acctKey] -= (amount + feeAmt);
          break;
        case 'expired':
          // Option expires worthless — no cash change (premium already captured via STO)
          break;
        case 'transfer':
          // Transfer shares in/out — share count changes, treated like buy cost-basis-wise
          if (shares > 0) {
            holdingsMap[key].shares     += shares;
            holdingsMap[key].cost_basis += amount;
          } else {
            const sh = Math.abs(shares);
            if (holdingsMap[key].shares > 0) {
              const avgCost = holdingsMap[key].cost_basis / holdingsMap[key].shares;
              holdingsMap[key].cost_basis -= avgCost * sh;
            }
            holdingsMap[key].shares += shares; // shares is negative here
          }
          break;
        case 'dividend':
          cashMap[acctKey] += (divAmt > 0 ? divAmt : amount);
          break;
        case 'interest':
          // Positive = earned; negative = paid (margin interest)
          cashMap[acctKey] += (intAmt !== 0 ? intAmt : amount);
          break;
        case 'lending':
          cashMap[acctKey] += (lendAmt > 0 ? lendAmt : amount);
          break;
        case 'deposit':
          cashMap[acctKey] += amount;
          break;
        case 'withdrawal':
          cashMap[acctKey] -= amount;
          break;
      }
    }

    // Build holdings array
    const holdings = [];
    for (const h of Object.values(holdingsMap)) {
      if (h.shares <= 0.0001) continue; // skip fully sold positions
      const currentPrice  = priceMap[h.ticker] ?? 0;
      const currentValue  = h.shares * currentPrice;
      const gainLoss      = currentValue - h.cost_basis;
      const gainLossPct   = h.cost_basis > 0 ? (gainLoss / h.cost_basis) * 100 : 0;
      const avgCost       = h.shares > 0 ? h.cost_basis / h.shares : 0;

      holdings.push({
        ticker:         h.ticker,
        account_id:     h.account_id,
        account_type:   h.account_type,
        display_name:   h.display_name,
        shares:         parseFloat(h.shares.toFixed(6)),
        avg_cost:       parseFloat(avgCost.toFixed(4)),
        actual_cost:    parseFloat(h.cost_basis.toFixed(2)),
        current_price:  currentPrice,
        current_value:  parseFloat(currentValue.toFixed(2)),
        gain_loss:      parseFloat(gainLoss.toFixed(2)),
        gain_loss_pct:  parseFloat(gainLossPct.toFixed(2))
      });
    }

    // Cash balances per account
    const cashRows = [];
    for (const [acctId, balance] of Object.entries(cashMap)) {
      const acct = accountMap[parseInt(acctId)];
      if (!acct) continue;
      cashRows.push({
        ticker:         'CASH',
        account_id:     parseInt(acctId),
        account_type:   acct.account_type,
        display_name:   acct.display_name,
        shares:         null,
        avg_cost:       1,
        actual_cost:    parseFloat(balance.toFixed(2)),
        current_price:  1,
        current_value:  parseFloat(balance.toFixed(2)),
        gain_loss:      0,
        gain_loss_pct:  0,
        is_cash:        true,
        cash_balance:   parseFloat(balance.toFixed(2))
      });
    }

    // Summary
    const allHoldings   = [...holdings, ...cashRows];
    const totalValue    = allHoldings.reduce((s, h) => s + (h.current_value || 0), 0);
    const sharesTotal   = holdings.reduce((s, h) => s + (h.current_value || 0), 0);
    const cashTotal     = cashRows.reduce((s, h) => s + (h.current_value || 0), 0);

    // Starting value (sum of starting_value for selected accounts)
    const selectedAccounts = account_type === 'combined' ? accounts : accounts.filter(a => a.account_type === account_type);
    const startingValue = selectedAccounts.reduce((s, a) => s + parseFloat(a.starting_value || 0), 0);
    const totalGainLoss = totalValue - startingValue;
    const totalGainLossPct = startingValue > 0 ? (totalGainLoss / startingValue) * 100 : 0;

    res.json({
      success: true,
      holdings: allHoldings,
      cash_rows: cashRows,
      equity_holdings: holdings,
      accounts,
      summary: {
        starting_value:    parseFloat(startingValue.toFixed(2)),
        current_value:     parseFloat(totalValue.toFixed(2)),
        total_gain_loss:   parseFloat(totalGainLoss.toFixed(2)),
        gain_loss_pct:     parseFloat(totalGainLossPct.toFixed(2)),
        shares_total:      parseFloat(sharesTotal.toFixed(2)),
        cash_total:        parseFloat(cashTotal.toFixed(2)),
        grand_total:       parseFloat(totalValue.toFixed(2))
      }
    });
  } catch (err) {
    console.error('[Portfolio] holdings error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to compute holdings' });
  }
});


// GET /api/portfolio/closed-positions — FIFO-computed closed positions for the current calendar year
// ?account_type=ira|roth_ira|brokerage|combined  (default: combined)
app.get('/api/portfolio/closed-positions', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Paid subscription required' });

    await ensurePortfolioAccounts(req.userId);

    const { account_type = 'combined' } = req.query;

    // Fetch accounts
    const acctResult = await pool.query(
      `SELECT id, account_type, display_name FROM portfolio_accounts WHERE user_id = $1`,
      [req.userId]
    );
    const accounts = acctResult.rows;

    // Build account_id filter
    let acctIds = accounts.map(a => a.id);
    if (account_type !== 'combined') {
      const filtered = accounts.filter(a => a.account_type === account_type);
      if (!filtered.length) return res.json({
        success: true, closed_positions: [],
        summary: { total_gain_loss: 0, total_gain_loss_pct: 0, total_proceeds: 0, total_cost: 0, wins: 0, losses: 0, total_positions: 0 },
        tax_implications: { by_account: {}, brokerage_only: { short_term_gains: 0, short_term_losses: 0, long_term_gains: 0, long_term_losses: 0, net_short_term: 0, net_long_term: 0 } }
      });
      acctIds = filtered.map(a => a.id);
    }

    // Fetch all buy/sell/transfer transactions sorted chronologically for FIFO lot tracking
    const txResult = await pool.query(
      `SELECT t.id, t.account_id, t.ticker, t.transaction_type,
              t.shares, t.price_per_share, t.amount, t.transaction_date,
              a.account_type, a.display_name
       FROM portfolio_transactions t
       JOIN portfolio_accounts a ON a.id = t.account_id
       WHERE t.account_id = ANY($1::int[])
         AND t.transaction_type IN ('buy', 'sell', 'transfer')
       ORDER BY t.transaction_date ASC, t.id ASC`,
      [acctIds]
    );
    const transactions = txResult.rows;

    // FIFO lot tracking
    const lotsMap = {};
    const closedEvents = [];

    for (const tx of transactions) {
      const key      = tx.account_id + ':' + tx.ticker.toUpperCase();
      const ticker   = tx.ticker.toUpperCase();
      if (!lotsMap[key]) lotsMap[key] = [];

      const txShares = parseFloat(tx.shares || 0);
      const txPrice  = parseFloat(tx.price_per_share || 0);
      const txAmount = parseFloat(tx.amount || 0);
      const txDate   = new Date(tx.transaction_date);

      if (tx.transaction_type === 'buy' || tx.transaction_type === 'transfer') {
        // Transfer shares in: add lot at cost basis (use price_per_share if available, else 0)
        if (txShares > 0) {
          lotsMap[key].push({ purchaseDate: txDate, shares: txShares, pricePerShare: txPrice });
        }
      } else if (tx.transaction_type === 'sell') {
        const lots = lotsMap[key];
        if (!lots || lots.length === 0) continue;

        let remainingShares = txShares;
        let totalCostBasis  = 0;
        const consumedLots  = [];

        while (remainingShares > 0.00001 && lots.length > 0) {
          const lot             = lots[0];
          const sharesToConsume = Math.min(remainingShares, lot.shares);
          const costOfConsumed  = sharesToConsume * lot.pricePerShare;
          consumedLots.push({ purchaseDate: lot.purchaseDate, shares: sharesToConsume, pricePerShare: lot.pricePerShare, cost: costOfConsumed });
          totalCostBasis  += costOfConsumed;
          remainingShares -= sharesToConsume;
          lot.shares      -= sharesToConsume;
          if (lot.shares < 0.00001) lots.shift();
        }

        // Record closed position only when ALL lots consumed
        if (lots.length === 0 && remainingShares < 0.00001) {
          const totalShares = consumedLots.reduce((s, cl) => s + cl.shares, 0);
          const proceeds    = txAmount || (txShares * txPrice);
          const gainLoss    = proceeds - totalCostBasis;
          const gainLossPct = totalCostBasis > 0 ? (gainLoss / totalCostBasis) * 100 : 0;

          // Weighted average holding period
          let weightedDays = 0;
          for (const cl of consumedLots) {
            const days = Math.round((txDate - cl.purchaseDate) / (1000 * 60 * 60 * 24));
            weightedDays += days * (cl.shares / totalShares);
          }
          const holdingDays = Math.round(weightedDays);

          // Per-lot short/long-term breakdown
          let stCost = 0, stProceeds = 0, ltCost = 0;
          for (const cl of consumedLots) {
            const days    = Math.round((txDate - cl.purchaseDate) / (1000 * 60 * 60 * 24));
            const lotProc = (cl.shares / totalShares) * proceeds;
            if (days < 365) { stCost += cl.cost; stProceeds += lotProc; }
            else             { ltCost += cl.cost; }
          }
          const ltProceeds = proceeds - stProceeds;

          let taxClassification;
          if      (stCost > 0 && ltCost > 0) taxClassification = 'Mixed';
          else if (ltCost > 0)               taxClassification = 'Long-term';
          else                               taxClassification = 'Short-term';

          const dateOpened = consumedLots.reduce(
            (earliest, cl) => cl.purchaseDate < earliest ? cl.purchaseDate : earliest,
            consumedLots[0].purchaseDate
          );

          closedEvents.push({
            ticker,
            account_id:         tx.account_id,
            account_type:       tx.account_type,
            display_name:       tx.display_name,
            date_opened:        dateOpened.toISOString().split('T')[0],
            date_closed:        txDate.toISOString().split('T')[0],
            shares:             parseFloat(totalShares.toFixed(6)),
            avg_cost:           parseFloat((totalCostBasis / totalShares).toFixed(4)),
            actual_cost:        parseFloat(totalCostBasis.toFixed(2)),
            proceeds:           parseFloat(proceeds.toFixed(2)),
            gain_loss:          parseFloat(gainLoss.toFixed(2)),
            gain_loss_pct:      parseFloat(gainLossPct.toFixed(2)),
            holding_days:       holdingDays,
            tax_classification: taxClassification,
            st_cost:            parseFloat(stCost.toFixed(2)),
            st_proceeds:        parseFloat(stProceeds.toFixed(2)),
            lt_cost:            parseFloat(ltCost.toFixed(2)),
            lt_proceeds:        parseFloat(ltProceeds.toFixed(2))
          });
        }
      }
    }

    // Filter to current calendar year
    const currentYear = new Date().getFullYear();
    const ytd = closedEvents.filter(p => parseInt(p.date_closed.split('-')[0]) === currentYear);

    const totalGL   = ytd.reduce((s, p) => s + p.gain_loss, 0);
    const totalCost = ytd.reduce((s, p) => s + p.actual_cost, 0);
    const totalProc = ytd.reduce((s, p) => s + p.proceeds, 0);
    const wins      = ytd.filter(p => p.gain_loss >= 0).length;
    const losses    = ytd.filter(p => p.gain_loss < 0).length;

    const buildTax = (positions) => {
      const stG = positions.reduce((s, p) => s + Math.max(0, p.st_proceeds - p.st_cost), 0);
      const stL = positions.reduce((s, p) => s + Math.min(0, p.st_proceeds - p.st_cost), 0);
      const ltG = positions.reduce((s, p) => s + Math.max(0, p.lt_proceeds - p.lt_cost), 0);
      const ltL = positions.reduce((s, p) => s + Math.min(0, p.lt_proceeds - p.lt_cost), 0);
      return {
        short_term_gains:  parseFloat(stG.toFixed(2)),
        short_term_losses: parseFloat(Math.abs(stL).toFixed(2)),
        long_term_gains:   parseFloat(ltG.toFixed(2)),
        long_term_losses:  parseFloat(Math.abs(ltL).toFixed(2)),
        net_short_term:    parseFloat((stG + stL).toFixed(2)),
        net_long_term:     parseFloat((ltG + ltL).toFixed(2))
      };
    };

    const byAccount = {};
    for (const at of ['ira', 'roth_ira', 'brokerage']) {
      byAccount[at] = buildTax(ytd.filter(p => p.account_type === at));
    }

    res.json({
      success: true,
      closed_positions: ytd,
      summary: {
        total_gain_loss:     parseFloat(totalGL.toFixed(2)),
        total_gain_loss_pct: totalCost > 0 ? parseFloat(((totalProc - totalCost) / totalCost * 100).toFixed(2)) : 0,
        total_proceeds:      parseFloat(totalProc.toFixed(2)),
        total_cost:          parseFloat(totalCost.toFixed(2)),
        wins,
        losses,
        total_positions: ytd.length
      },
      tax_implications: {
        by_account:     byAccount,
        brokerage_only: buildTax(ytd.filter(p => p.account_type === 'brokerage'))
      }
    });
  } catch (err) {
    console.error('[Portfolio] closed-positions error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to compute closed positions' });
  }
});

// GET /api/portfolio/performance — historical performance data for chart
// Returns: { tickers: [...], series: { TICKER: [{date, price_pct}] } }
// price_pct = % change from first price point (or avg_cost as baseline)
app.get('/api/portfolio/performance', requireAuth, async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ success: false, error: 'Paid subscription required' });

    const { account_type = 'combined', start_date, end_date } = req.query;

    // Determine account filter
    const acctResult = await pool.query(
      `SELECT id, account_type FROM portfolio_accounts WHERE user_id = $1`,
      [req.userId]
    );
    let acctIds = acctResult.rows.map(a => a.id);
    if (account_type !== 'combined') {
      const filtered = acctResult.rows.filter(a => a.account_type === account_type);
      acctIds = filtered.map(a => a.id);
    }
    if (!acctIds.length) return res.json({ success: true, tickers: [], series: {} });

    // Get distinct tickers in these accounts (equity only)
    const tickerResult = await pool.query(
      `SELECT DISTINCT ticker FROM portfolio_transactions
       WHERE account_id = ANY($1::int[]) AND transaction_type IN ('buy','sell')`,
      [acctIds]
    );
    const tickers = tickerResult.rows.map(r => r.ticker.toUpperCase());
    if (!tickers.length) return res.json({ success: true, tickers: [], series: {} });

    // YTD default: Jan 1 of current year
    const today = new Date().toISOString().split('T')[0];
    const ytdStart = `${new Date().getFullYear()}-01-01`;
    const effectiveStart = start_date || ytdStart;
    const effectiveEnd   = end_date   || today;

    // Get price snapshots for these tickers in the date range
    const snapResult = await pool.query(
      `SELECT ticker, price, snapshot_date
       FROM portfolio_price_snapshots
       WHERE user_id = $1
         AND UPPER(ticker) = ANY($2::text[])
         AND snapshot_date >= $3
         AND snapshot_date <= $4
       ORDER BY ticker, snapshot_date ASC`,
      [req.userId, tickers, effectiveStart, effectiveEnd]
    );

    // Also add avg_cost as a baseline data point per ticker using transaction history
    const avgCostResult = await pool.query(
      `SELECT ticker, transaction_date, price_per_share
       FROM portfolio_transactions
       WHERE account_id = ANY($1::int[])
         AND transaction_type = 'buy'
       ORDER BY ticker, transaction_date ASC`,
      [acctIds]
    );

    // Build series per ticker
    const series = {};
    for (const ticker of tickers) {
      const tickerSnaps = snapResult.rows
        .filter(r => r.ticker.toUpperCase() === ticker)
        .map(r => ({ date: r.snapshot_date.toISOString().split('T')[0], price: parseFloat(r.price) }));

      // Also add first buy price as anchor if no snapshots before effective start
      const firstBuy = avgCostResult.rows.find(r => r.ticker.toUpperCase() === ticker);
      if (firstBuy && parseFloat(firstBuy.price_per_share) > 0) {
        const firstBuyDate = firstBuy.transaction_date.toISOString().split('T')[0];
        if (!tickerSnaps.find(s => s.date === firstBuyDate)) {
          tickerSnaps.unshift({ date: firstBuyDate, price: parseFloat(firstBuy.price_per_share) });
          tickerSnaps.sort((a, b) => a.date.localeCompare(b.date));
        }
      }

      if (tickerSnaps.length === 0) continue;

      // Compute % change from first snapshot
      const basePrice = tickerSnaps[0].price;
      series[ticker] = tickerSnaps.map(s => ({
        date: s.date,
        price: s.price,
        pct: basePrice > 0 ? parseFloat(((s.price - basePrice) / basePrice * 100).toFixed(2)) : 0
      }));
    }

    res.json({
      success: true,
      tickers: Object.keys(series),
      series,
      date_range: { start: effectiveStart, end: effectiveEnd }
    });
  } catch (err) {
    console.error('[Portfolio] performance error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to compute performance' });
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Annual Performance Goals
// ─────────────────────────────────────────────────────────────────────────────

// GET /api/portfolio/annual-goal — get user's target return %
app.get('/api/portfolio/annual-goal', requireAuth, async (req, res) => {
  try {
    if (!await hasProAccess(req.userId)) return res.status(403).json({ success: false, error: 'Paid plan required' });
    const r = await pool.query('SELECT goal_pct FROM portfolio_annual_goals WHERE user_id = $1', [req.userId]);
    res.json({ success: true, goal_pct: r.rows.length ? parseFloat(r.rows[0].goal_pct) : 20.0 });
  } catch (err) {
    console.error('[Portfolio] annual-goal GET error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to fetch goal' });
  }
});

// PUT /api/portfolio/annual-goal — upsert user's target return %
app.put('/api/portfolio/annual-goal', requireAuth, async (req, res) => {
  try {
    if (!await hasProAccess(req.userId)) return res.status(403).json({ success: false, error: 'Paid plan required' });
    const { goal_pct } = req.body;
    if (goal_pct == null || isNaN(goal_pct)) return res.status(400).json({ success: false, error: 'goal_pct required' });
    const val = Math.max(0, Math.min(999, parseFloat(goal_pct)));
    await pool.query(`
      INSERT INTO portfolio_annual_goals (user_id, goal_pct, updated_at)
      VALUES ($1, $2, NOW())
      ON CONFLICT (user_id) DO UPDATE SET goal_pct = EXCLUDED.goal_pct, updated_at = NOW()
    `, [req.userId, val]);
    res.json({ success: true, goal_pct: val });
  } catch (err) {
    console.error('[Portfolio] annual-goal PUT error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to save goal' });
  }
});

// GET /api/portfolio/annual-performance — full year-by-year table
// ?account_type=combined|ira|roth_ira|brokerage  (default: combined)
app.get('/api/portfolio/annual-performance', requireAuth, async (req, res) => {
  try {
    if (!await hasProAccess(req.userId)) return res.status(403).json({ success: false, error: 'Paid plan required' });

    const accountType = req.query.account_type || 'combined';
    const currentYear = new Date().getFullYear();

    // 1. Goal %
    const goalRow = await pool.query('SELECT goal_pct FROM portfolio_annual_goals WHERE user_id = $1', [req.userId]);
    const goalPct = goalRow.rows.length ? parseFloat(goalRow.rows[0].goal_pct) : 20.0;

    // 2. Account starting dates to determine earliest year
    const acctRows = await pool.query(
      'SELECT account_type, starting_value, starting_date FROM portfolio_accounts WHERE user_id = $1',
      [req.userId]
    );
    const acctMap = {};
    let earliestYear = currentYear;
    for (const a of acctRows.rows) {
      acctMap[a.account_type] = { starting_value: parseFloat(a.starting_value), starting_date: a.starting_date };
      const yr = new Date(a.starting_date).getFullYear();
      if (yr < earliestYear) earliestYear = yr;
    }

    // 3. Locked historical records
    const types = accountType === 'combined' ? ['ira', 'roth_ira', 'brokerage'] : [accountType];
    const recRows = await pool.query(
      `SELECT * FROM portfolio_annual_records WHERE user_id = $1 AND account_type = ANY($2) ORDER BY year, account_type`,
      [req.userId, types]
    );
    // Index by year → account_type
    const recMap = {}; // recMap[year][account_type] = record
    for (const r of recRows.rows) {
      if (!recMap[r.year]) recMap[r.year] = {};
      recMap[r.year][r.account_type] = r;
    }

    // 4. Current-year live data from holdings + transactions
    const yearStart = `${currentYear}-01-01`;
    const yearEnd   = `${currentYear}-12-31`;

    // Current holdings value per account
    const holdingsRows = await pool.query(
      `SELECT a.account_type,
              SUM(CASE WHEN t.transaction_type IN ('deposit','dividend','sto','interest','lending') THEN t.amount
                       WHEN t.transaction_type IN ('withdrawal','btc') THEN -t.amount
                       WHEN t.transaction_type = 'buy'  THEN -t.amount
                       WHEN t.transaction_type = 'sell' THEN t.amount
                       ELSE 0 END) AS cash_flow
       FROM portfolio_transactions t
       JOIN portfolio_accounts a ON a.id = t.account_id
       WHERE t.user_id = $1
       GROUP BY a.account_type`,
      [req.userId]
    );
    // Get total current value from holdings endpoint logic — simplified: use account starting + cash flow + equity value
    // We'll compute via the same approach as the holdings endpoint but summarised
    const holdingsSummary = await pool.query(
      `WITH tx AS (
         SELECT a.account_type,
                t.transaction_type,
                t.shares,
                t.amount,
                t.ticker
         FROM portfolio_transactions t
         JOIN portfolio_accounts a ON a.id = t.account_id
         WHERE t.user_id = $1
       ),
       equity AS (
         SELECT tx.account_type,
                SUM(CASE WHEN tx.transaction_type IN ('buy','transfer')  THEN tx.shares
                         WHEN tx.transaction_type = 'sell'               THEN -tx.shares
                         ELSE 0 END) AS total_shares,
                tx.ticker
         FROM tx GROUP BY tx.account_type, tx.ticker
       ),
       priced AS (
         SELECT e.account_type,
                e.total_shares * COALESCE(p.current_price, 0) AS equity_value
         FROM equity e
         LEFT JOIN portfolio_prices p ON p.user_id = $1 AND p.ticker = e.ticker
         WHERE e.total_shares > 0
       ),
       cash AS (
         SELECT tx.account_type,
                SUM(CASE WHEN tx.transaction_type IN ('deposit','dividend','sto','interest','lending') THEN tx.amount
                         WHEN tx.transaction_type IN ('withdrawal','btc','buy')                       THEN -tx.amount
                         WHEN tx.transaction_type = 'sell'                                            THEN tx.amount
                         ELSE 0 END) AS cash_balance
         FROM tx GROUP BY tx.account_type
       )
       SELECT
         COALESCE(priced.account_type, cash.account_type) AS account_type,
         COALESCE(SUM(priced.equity_value), 0) AS equity_value,
         COALESCE(MAX(cash.cash_balance), 0)   AS cash_balance
       FROM priced
       FULL OUTER JOIN cash ON cash.account_type = priced.account_type
       GROUP BY COALESCE(priced.account_type, cash.account_type)`,
      [req.userId]
    );

    // Live value map: account_type → {equity, cash, total}
    const liveValueMap = {};
    for (const a of acctRows.rows) {
      const sv = parseFloat(a.starting_value) || 0;
      const hs = holdingsSummary.rows.find(h => h.account_type === a.account_type);
      const equity = hs ? parseFloat(hs.equity_value) : 0;
      const cash   = hs ? parseFloat(hs.cash_balance)  : 0;
      liveValueMap[a.account_type] = { total: sv + cash + equity };
    }

    // Year-to-date deposits + withdrawals per account (current year only)
    const ytdTxRows = await pool.query(
      `SELECT a.account_type,
              SUM(CASE WHEN t.transaction_type = 'deposit'    THEN t.amount ELSE 0 END) AS deposits,
              SUM(CASE WHEN t.transaction_type = 'withdrawal' THEN t.amount ELSE 0 END) AS withdrawals
       FROM portfolio_transactions t
       JOIN portfolio_accounts a ON a.id = t.account_id
       WHERE t.user_id = $1
         AND t.transaction_date >= $2 AND t.transaction_date <= $3
       GROUP BY a.account_type`,
      [req.userId, yearStart, yearEnd]
    );
    const ytdMap = {};
    for (const t of ytdTxRows.rows) {
      ytdMap[t.account_type] = {
        deposits:    parseFloat(t.deposits)    || 0,
        withdrawals: parseFloat(t.withdrawals) || 0
      };
    }

    // 5. Build year rows
    const futureYears = 10;
    const endYear = currentYear + futureYears;
    const years = [];
    for (let y = earliestYear; y <= endYear; y++) years.push(y);

    // Helper: get last year's ending value for an account (for starting value chain)
    function getStartingValue(acctType, year) {
      // Check stored record from previous year
      if (recMap[year - 1] && recMap[year - 1][acctType]) {
        return parseFloat(recMap[year - 1][acctType].ending_value);
      }
      // Fall back to account starting_value if this is the first year
      if (acctMap[acctType]) {
        const acctStartYear = new Date(acctMap[acctType].starting_date).getFullYear();
        if (year === acctStartYear || year <= acctStartYear) {
          return parseFloat(acctMap[acctType].starting_value);
        }
      }
      return 0;
    }

    // For current year, starting value = last year's end OR account starting_value
    function getCurrentYearStart(acctType) {
      if (recMap[currentYear - 1] && recMap[currentYear - 1][acctType]) {
        return parseFloat(recMap[currentYear - 1][acctType].ending_value);
      }
      return parseFloat((acctMap[acctType] || {}).starting_value) || 0;
    }

    // Build combined or single-account rows
    const result = [];

    for (const year of years) {
      if (accountType === 'combined') {
        // Sum all 3 accounts
        let startTotal = 0, depositTotal = 0, withdrawalTotal = 0, endTotal = 0;
        let isPast = year < currentYear, isCurrent = year === currentYear, isFuture = year > currentYear;

        if (isPast) {
          for (const at of ['ira', 'roth_ira', 'brokerage']) {
            const rec = recMap[year] && recMap[year][at];
            if (rec) {
              startTotal      += parseFloat(rec.starting_value);
              depositTotal    += parseFloat(rec.deposits);
              withdrawalTotal += parseFloat(rec.withdrawals);
              endTotal        += parseFloat(rec.ending_value);
            }
          }
          if (startTotal === 0 && endTotal === 0) continue; // skip empty past years
        } else if (isCurrent) {
          for (const at of ['ira', 'roth_ira', 'brokerage']) {
            startTotal      += getCurrentYearStart(at);
            depositTotal    += (ytdMap[at] || {}).deposits    || 0;
            withdrawalTotal += (ytdMap[at] || {}).withdrawals || 0;
            endTotal        += (liveValueMap[at] || {}).total || 0;
          }
        } else {
          // Future: project from previous year ending
          let prevEndTotal = 0;
          for (const at of ['ira', 'roth_ira', 'brokerage']) {
            prevEndTotal += getProjectedEnd(at, year - 1, currentYear, goalPct, recMap, liveValueMap, ytdMap, acctMap);
          }
          startTotal = prevEndTotal;
          depositTotal = 0; withdrawalTotal = 0;
          endTotal = startTotal * (1 + goalPct / 100);
        }

        const gain       = endTotal - startTotal + withdrawalTotal - depositTotal;
        const gainPct    = startTotal > 0 ? (gain / startTotal) * 100 : 0;
        const goalEnd    = startTotal * (1 + goalPct / 100) + depositTotal - withdrawalTotal;
        const onTrack    = isFuture ? true : gainPct >= goalPct;

        result.push({
          year,
          account_type: 'combined',
          starting_value:  startTotal,
          deposits:        depositTotal,
          withdrawals:     withdrawalTotal,
          ending_value:    endTotal,
          gain_loss:       gain,
          gain_loss_pct:   gainPct,
          goal_end_value:  goalEnd,
          on_track:        onTrack,
          is_current:      isCurrent,
          is_future:       isFuture,
          is_locked:       isPast,
          records:         recMap[year] || null
        });
      } else {
        // Single account
        const at = accountType;
        let startVal, deposits, withdrawals, endVal;
        let isPast = year < currentYear, isCurrent = year === currentYear, isFuture = year > currentYear;

        if (isPast) {
          const rec = recMap[year] && recMap[year][at];
          if (!rec) continue; // skip years without data
          startVal    = parseFloat(rec.starting_value);
          deposits    = parseFloat(rec.deposits);
          withdrawals = parseFloat(rec.withdrawals);
          endVal      = parseFloat(rec.ending_value);
        } else if (isCurrent) {
          startVal    = getCurrentYearStart(at);
          deposits    = (ytdMap[at] || {}).deposits    || 0;
          withdrawals = (ytdMap[at] || {}).withdrawals || 0;
          endVal      = (liveValueMap[at] || {}).total || 0;
        } else {
          // Projected
          const prevEnd = getProjectedEnd(at, year - 1, currentYear, goalPct, recMap, liveValueMap, ytdMap, acctMap);
          startVal    = prevEnd;
          deposits    = 0; withdrawals = 0;
          endVal      = startVal * (1 + goalPct / 100);
        }

        const gain    = endVal - startVal + withdrawals - deposits;
        const gainPct = startVal > 0 ? (gain / startVal) * 100 : 0;
        const goalEnd = startVal * (1 + goalPct / 100) + deposits - withdrawals;
        const onTrack = isFuture ? true : gainPct >= goalPct;

        result.push({
          year,
          account_type:    at,
          starting_value:  startVal,
          deposits,
          withdrawals,
          ending_value:    endVal,
          gain_loss:       gain,
          gain_loss_pct:   gainPct,
          goal_end_value:  goalEnd,
          on_track:        onTrack,
          is_current:      isCurrent,
          is_future:       isFuture,
          is_locked:       isPast,
          record_id:       recMap[year] && recMap[year][at] ? recMap[year][at].id : null
        });
      }
    }

    res.json({ success: true, rows: result, goal_pct: goalPct });
  } catch (err) {
    console.error('[Portfolio] annual-performance error:', err.message, err.stack);
    res.status(500).json({ success: false, error: 'Failed to compute annual performance' });
  }
});

// Helper: get projected end value for an account in a given year
function getProjectedEnd(acctType, year, currentYear, goalPct, recMap, liveValueMap, ytdMap, acctMap) {
  if (year < currentYear) {
    const rec = recMap[year] && recMap[year][acctType];
    if (rec) return parseFloat(rec.ending_value);
    return 0;
  }
  if (year === currentYear) {
    return (liveValueMap[acctType] || {}).total || 0;
  }
  // Recurse for future
  const prevEnd = getProjectedEnd(acctType, year - 1, currentYear, goalPct, recMap, liveValueMap, ytdMap, acctMap);
  return prevEnd * (1 + goalPct / 100);
}

// POST /api/portfolio/annual-records — save/upsert a historical year record
app.post('/api/portfolio/annual-records', requireAuth, async (req, res) => {
  try {
    if (!await hasProAccess(req.userId)) return res.status(403).json({ success: false, error: 'Paid plan required' });
    const { account_type, year, starting_value, deposits, withdrawals, ending_value, notes } = req.body;
    if (!account_type || !year) return res.status(400).json({ success: false, error: 'account_type and year required' });
    const validTypes = ['ira', 'roth_ira', 'brokerage'];
    if (!validTypes.includes(account_type)) return res.status(400).json({ success: false, error: 'Invalid account_type' });

    const r = await pool.query(`
      INSERT INTO portfolio_annual_records
        (user_id, account_type, year, starting_value, deposits, withdrawals, ending_value, notes, updated_at)
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8,NOW())
      ON CONFLICT (user_id, account_type, year) DO UPDATE SET
        starting_value = EXCLUDED.starting_value,
        deposits       = EXCLUDED.deposits,
        withdrawals    = EXCLUDED.withdrawals,
        ending_value   = EXCLUDED.ending_value,
        notes          = EXCLUDED.notes,
        updated_at     = NOW()
      RETURNING *
    `, [req.userId, account_type, parseInt(year),
        parseFloat(starting_value) || 0, parseFloat(deposits) || 0,
        parseFloat(withdrawals) || 0, parseFloat(ending_value) || 0,
        notes || null]);

    res.json({ success: true, record: r.rows[0] });
  } catch (err) {
    console.error('[Portfolio] annual-records POST error:', err.message);
    res.status(500).json({ success: false, error: 'Failed to save record' });
  }
});

