//  JUNIOR REVOLUTIONARIES — Kid Command Console, Missions & Family Panel
// ═══════════════════════════════════════════════════════════════════════════

// Level thresholds (XP required to *reach* each level)
const JR_LEVEL_THRESHOLDS = [0, 0, 100, 300, 600, 1000, 1500];
const JR_LEVEL_NAMES      = ['', 'Recruit', 'Cadet', 'Specialist', 'Sergeant', 'Commander', 'General'];
const JR_LEVEL_EMOJIS     = ['', '🏕️', '⛺', '🗼', '🏯', '🏰', '🏰'];
const JR_FORTRESS_NAMES   = ['', 'Base Camp', 'Forward Outpost', 'Watchtower', 'Border Fort', 'Fortress', 'Grand Citadel'];

function calcJrLevel(xp) {
  let lv = 1;
  for (let i = 2; i <= 6; i++) { if (xp >= JR_LEVEL_THRESHOLDS[i]) lv = i; }
  return lv;
}
function xpToNextLevel(xp, lv) {
  if (lv >= 6) return { needed: 0, progress: 0, pct: 100 };
  const next = JR_LEVEL_THRESHOLDS[lv + 1];
  const prev = JR_LEVEL_THRESHOLDS[lv];
  return { needed: next - prev, progress: xp - prev, pct: Math.min(100, Math.floor(((xp - prev) / (next - prev)) * 100)) };
}
function genAccessCode() {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  return Array.from({ length: 12 }, () => chars[Math.floor(Math.random() * chars.length)]).join('');
}

// Badge definitions
const BADGE_DEFS = [
  { key: 'first_mission',     name: 'First Mission',    emoji: '🎯', desc: 'Complete your very first mission' },
  { key: 'on_fire',           name: 'On Fire',          emoji: '🔥', desc: 'Complete 3 missions in a row' },
  { key: 'speed_demon',       name: 'Speed Demon',      emoji: '⚡', desc: 'Complete a mission quickly' },
  { key: 'champion',          name: 'Champion',         emoji: '🏆', desc: 'Reach Specialist rank (Level 3)' },
  { key: 'money_mind',        name: 'Money Mind',       emoji: '💰', desc: 'Complete 5 money-related missions' },
  { key: 'fortress_builder',  name: 'Fortress Builder', emoji: '🏰', desc: 'Reach the highest rank: General' },
  { key: 'star_cadet',        name: 'Star Cadet',       emoji: '⭐', desc: 'Complete 10 missions total' },
  { key: 'legend',            name: 'Legend',           emoji: '🌟', desc: 'Complete 25 missions total' },
  { key: 'quick_learner',     name: 'Quick Learner',    emoji: '📚', desc: 'Unlock 3 Knowledge Vault entries' },
  { key: 'dedicated',         name: 'Dedicated',        emoji: '💪', desc: 'Maintain a 5-mission streak' },
];

async function checkAndAwardBadges(kid_id) {
  try {
    const kid    = (await pool.query('SELECT * FROM junior_profiles WHERE id = $1', [kid_id])).rows[0];
    if (!kid) return [];
    const done   = parseInt((await pool.query("SELECT COUNT(*) as n FROM apprentice_missions WHERE kid_id = $1 AND status = 'completed'", [kid_id])).rows[0].n);
    const earned = new Set((await pool.query('SELECT badge_key FROM junior_badges WHERE kid_id = $1', [kid_id])).rows.map(r => r.badge_key));
    const toAward = [];
    const tryBadge = (key) => { if (!earned.has(key)) toAward.push(key); };
    const lv = calcJrLevel(kid.xp);
    if (done >= 1)  tryBadge('first_mission');
    if (done >= 10) tryBadge('star_cadet');
    if (done >= 25) tryBadge('legend');
    if (lv >= 3) tryBadge('champion');
    if (lv >= 6) tryBadge('fortress_builder');
    if (kid.current_streak >= 5) tryBadge('dedicated');
    const moneyCount = parseInt((await pool.query(
      "SELECT COUNT(*) as n FROM apprentice_missions WHERE kid_id = $1 AND status = 'completed' AND (title ILIKE '%money%' OR title ILIKE '%save%' OR title ILIKE '%budget%' OR title ILIKE '%spend%')",
      [kid_id]
    )).rows[0].n);
    if (moneyCount >= 5) tryBadge('money_mind');
    const vaultCount = parseInt((await pool.query(
      'SELECT COUNT(*) as n FROM knowledge_vault_entries WHERE parent_user_id = $1 AND level_required <= $2',
      [kid.parent_user_id, lv]
    )).rows[0].n);
    if (vaultCount >= 3) tryBadge('quick_learner');
    for (const key of toAward) {
      const def = BADGE_DEFS.find(b => b.key === key);
      if (!def) continue;
      await pool.query(
        'INSERT INTO junior_badges (kid_id, badge_key, badge_name, badge_emoji) VALUES ($1,$2,$3,$4) ON CONFLICT DO NOTHING',
        [kid_id, key, def.name, def.emoji]
      );
    }
    return toAward;
  } catch (err) {
    console.error('[Junior] checkAndAwardBadges error:', err.message);
    return [];
  }
}

