// GET /api/junior/family-progress — full family dashboard for parent
app.get('/api/junior/family-progress', requireAuth, async (req, res) => {
  try {
    const kids = (await pool.query('SELECT * FROM junior_profiles WHERE parent_user_id = $1 ORDER BY created_at ASC', [req.userId])).rows;
    const appUrl = process.env.APP_URL || 'https://financial-revolution.polsia.app';
    const result = [];
    for (const k of kids) {
      const missions  = (await pool.query("SELECT * FROM apprentice_missions WHERE kid_id = $1 ORDER BY created_at DESC LIMIT 20", [k.id])).rows;
      const badges    = (await pool.query('SELECT * FROM junior_badges WHERE kid_id = $1', [k.id])).rows;
      const total     = missions.length;
      const completed = missions.filter(m => m.status === 'completed').length;
      const pending   = missions.filter(m => m.status === 'pending_confirm').length;
      const active    = missions.filter(m => m.status === 'active').length;
      const lv        = calcJrLevel(k.xp);
      result.push({
        ...k,
        level: lv,
        level_name: JR_LEVEL_NAMES[lv],
        level_emoji: JR_LEVEL_EMOJIS[lv],
        fortress_name: JR_FORTRESS_NAMES[lv],
        next_xp: xpToNextLevel(k.xp, lv),
        missions_summary: { total, completed, pending, active },
        completion_rate: total ? Math.round((completed / total) * 100) : 0,
        badges,
        recent_missions: missions.slice(0, 5),
        share_url: `${appUrl}/junior-command?kid=${k.id}&code=${k.access_code}`
      });
    }
    res.json({ kids: result });
  } catch (err) {
    console.error('[Junior] GET family-progress:', err.message);
    res.status(500).json({ error: 'Failed to load family progress' });
  }
});

