// PUT /api/junior/missions/:id/confirm — parent confirms or rejects
app.put('/api/junior/missions/:id/confirm', requireAuth, async (req, res) => {
  try {
    const { action = 'approve', notes } = req.body;
    const mission = (await pool.query(
      'SELECT * FROM apprentice_missions WHERE id = $1 AND parent_user_id = $2',
      [req.params.id, req.userId]
    )).rows[0];
    if (!mission) return res.status(404).json({ error: 'Mission not found' });
    if (action === 'approve') {
      await pool.query(
        "UPDATE apprentice_missions SET status = 'completed', completed_at = NOW(), notes = $1 WHERE id = $2",
        [notes || null, req.params.id]
      );
      const updKid = (await pool.query(
        'UPDATE junior_profiles SET xp = xp + $1, last_activity = CURRENT_DATE, current_streak = current_streak + 1, updated_at = NOW() WHERE id = $2 RETURNING *',
        [mission.xp_reward, mission.kid_id]
      )).rows[0];
      const newLevel = calcJrLevel(updKid.xp);
      if (newLevel !== updKid.level) {
        await pool.query('UPDATE junior_profiles SET level = $1 WHERE id = $2', [newLevel, updKid.id]);
      }
      const newBadges = await checkAndAwardBadges(mission.kid_id);
      res.json({ success: true, xp_awarded: mission.xp_reward, new_level: newLevel, new_badges: newBadges });
    } else {
      await pool.query("UPDATE apprentice_missions SET status = 'active', notes = $1 WHERE id = $2", [notes || null, req.params.id]);
      res.json({ success: true, action: 'returned_to_active' });
    }
  } catch (err) {
    console.error('[Junior] PUT missions confirm:', err.message);
    res.status(500).json({ error: 'Failed to confirm mission' });
  }
});

