// ══════════════════════════════════════════════════════════════════════════════
//  TFR ENGAGEMENT SYSTEM — Command Console, Rank/XP, Leak Detector, Micro-Wins
// ══════════════════════════════════════════════════════════════════════════════

const TFR_RANKS = [
  { level: 1,  name: 'THE INITIATE',   phase: 1, xp_required: 0     },
  { level: 2,  name: 'THE SCOUT',      phase: 1, xp_required: 100   },
  { level: 3,  name: 'THE TACTICIAN',  phase: 1, xp_required: 300   },
  { level: 4,  name: 'THE DISRUPTOR',  phase: 2, xp_required: 600   },
  { level: 5,  name: 'THE INSURGENT',  phase: 2, xp_required: 1000  },
  { level: 6,  name: 'THE COMMANDER',  phase: 2, xp_required: 1600  },
  { level: 7,  name: 'THE STRATEGIST', phase: 3, xp_required: 2400  },
  { level: 8,  name: 'THE ARCHITECT',  phase: 3, xp_required: 3400  },
  { level: 9,  name: 'THE MARSHAL',    phase: 3, xp_required: 4600  },
  { level: 10, name: 'THE LIBERATOR',  phase: 4, xp_required: 6000  },
  { level: 11, name: 'THE VANGUARD',   phase: 4, xp_required: 8000  },
  { level: 12, name: 'THE SOVEREIGN',  phase: 4, xp_required: 10500 },
];

const TFR_PHASE_NAMES = { 1: 'RESISTANCE', 2: 'UPRISING', 3: 'EXPANSION', 4: 'LIBERATION' };

const TFR_PHASE_THEMES = {
  1: { accent: '#cd7f32', accent2: '#e8a857', label: 'bronze',   bg: 'rgba(205,127,50,0.12)' },
  2: { accent: '#a8b8c8', accent2: '#d4e1ec', label: 'silver',   bg: 'rgba(168,184,200,0.12)' },
  3: { accent: '#c9a227', accent2: '#e8c96a', label: 'gold',     bg: 'rgba(201,162,39,0.12)' },
  4: { accent: '#e5e4e2', accent2: '#f0f0f0', label: 'platinum', bg: 'rgba(229,228,226,0.12)' },
};

function tfrCalcLevel(xp) {
  let lvl = 1;
  for (let i = TFR_RANKS.length - 1; i >= 0; i--) {
    if (xp >= TFR_RANKS[i].xp_required) { lvl = TFR_RANKS[i].level; break; }
  }
  return lvl;
}

function tfrXpToNext(xp, level) {
  const next = TFR_RANKS.find(r => r.level === level + 1);
  if (!next) return 0;
  return next.xp_required - xp;
}

// ── Timezone-aware date helpers for daily check-in ────────────────────────
function getUserLocalDate(timezone) {
  // Returns the user's local date as "YYYY-MM-DD" using their IANA timezone.
  // Falls back to UTC if timezone is missing or invalid.
  try {
    if (!timezone) throw new Error('no tz');
    const formatter = new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone,
      year: 'numeric', month: '2-digit', day: '2-digit',
    });
    return formatter.format(new Date()); // "2026-04-12"
  } catch {
    return new Date().toISOString().split('T')[0];
  }
}

function getUserLocalYesterday(timezone) {
  try {
    if (!timezone) throw new Error('no tz');
    const now = new Date();
    const yesterday = new Date(now.getTime() - 86400000);
    const formatter = new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone,
      year: 'numeric', month: '2-digit', day: '2-digit',
    });
    return formatter.format(yesterday);
  } catch {
    return new Date(Date.now() - 86400000).toISOString().split('T')[0];
  }
}

function isValidTimezone(tz) {
  try {
    Intl.DateTimeFormat(undefined, { timeZone: tz });
    return true;
  } catch { return false; }
}

async function tfrEnsureStats(userId, client) {
  const existing = (await client.query(
    'SELECT * FROM tfr_user_stats WHERE user_id = $1', [userId]
  )).rows[0];
  if (existing) return existing;
  const deadline = new Date(Date.now() + 48 * 60 * 60 * 1000);
  const row = (await client.query(`
    INSERT INTO tfr_user_stats (user_id, first_blood_deadline)
    VALUES ($1, $2)
    ON CONFLICT (user_id) DO UPDATE SET updated_at = NOW()
    RETURNING *
  `, [userId, deadline])).rows[0];
  return row;
}

async function tfrAwardXp(userId, source, description, baseXp, client) {
  const stats = (await client.query('SELECT * FROM tfr_user_stats WHERE user_id = $1', [userId])).rows[0];
  if (!stats) return { xp: baseXp, level: 1, leveled_up: false };
  const streak = stats.streak_days || 0;
  const multiplier = streak >= 3 ? 1.5 : 1.0;
  const earned = Math.round(baseXp * multiplier);
  const prevLevel = tfrCalcLevel(stats.xp);
  const newXp = stats.xp + earned;
  const newLevel = tfrCalcLevel(newXp);
  const leveledUp = newLevel > prevLevel;
  const prevPhase = TFR_RANKS.find(r => r.level === prevLevel)?.phase || 1;
  const newPhase = TFR_RANKS.find(r => r.level === newLevel)?.phase || 1;
  const phaseUp = newPhase > prevPhase;
  const prestige = newLevel >= 12;
  await client.query(`
    UPDATE tfr_user_stats
    SET xp = $1, level = $2, phase = $3, prestige = $4, updated_at = NOW()
    WHERE user_id = $5
  `, [newXp, newLevel, newPhase, prestige, userId]);
  await client.query(`
    INSERT INTO tfr_xp_events (user_id, xp_earned, multiplier, source, description)
    VALUES ($1, $2, $3, $4, $5)
  `, [userId, earned, multiplier, source, description]);
  return { xp: newXp, level: newLevel, xp_earned: earned, multiplier, leveled_up: leveledUp, phase_up: phaseUp, new_rank: TFR_RANKS.find(r => r.level === newLevel) };
}

