// GET /api/nda/status — check if current user needs to accept NDA and whether they have
app.get('/api/nda/status', requireAuth, async (req, res) => {
  try {
    const now = new Date();
    const isBeforeLaunch = now < NDA_LAUNCH_DATE;

    // After launch date, no NDA required
    if (!isBeforeLaunch) {
      return res.json({ success: true, required: false, accepted: true });
    }

    // Creator is exempt
    const creatorCheck = await isCreator(req.userId);
    if (creatorCheck) {
      return res.json({ success: true, required: false, accepted: true });
    }

    const ndaResult = await pool.query(
      'SELECT id, accepted_at, nda_version FROM nda_acceptances WHERE user_id = $1 AND nda_version = $2',
      [req.userId, NDA_VERSION]
    );

    res.json({
      success: true,
      required: true,
      accepted: ndaResult.rows.length > 0,
      accepted_at: ndaResult.rows[0]?.accepted_at || null,
      nda_version: NDA_VERSION
    });
  } catch (err) {
    console.error('GET /api/nda/status error:', err.message);
    res.status(500).json({ error: 'Failed to check NDA status' });
  }
});

// POST /api/nda/accept — record user's NDA acceptance
app.post('/api/nda/accept', requireAuth, async (req, res) => {
  try {
    const ipAddress = (req.headers['x-forwarded-for'] || req.socket.remoteAddress || '').toString().split(',')[0].trim();

    await pool.query(
      `INSERT INTO nda_acceptances (user_id, accepted_at, nda_version, ip_address)
       VALUES ($1, NOW(), $2, $3)
       ON CONFLICT (user_id, nda_version) DO UPDATE SET accepted_at = NOW()`,
      [req.userId, NDA_VERSION, ipAddress]
    );

    res.json({ success: true, message: 'Beta NDA accepted. Welcome to FACTS!' });
  } catch (err) {
    console.error('POST /api/nda/accept error:', err.message);
    res.status(500).json({ error: 'Failed to record NDA acceptance' });
  }
});

