// GET /api/user/referral-code — get (or generate) current user's referral code
app.get('/api/user/referral-code', requireAuth, async (req, res) => {
  try {
    const userResult = await pool.query(
      'SELECT referral_code FROM users WHERE id = $1',
      [req.userId]
    );

    if (userResult.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    let referralCode = userResult.rows[0].referral_code;

    // Generate code if missing (for existing users who pre-date this feature)
    if (!referralCode) {
      referralCode = await generateUniqueReferralCode();
      await pool.query(
        'UPDATE users SET referral_code = $1 WHERE id = $2',
        [referralCode, req.userId]
      );
    }

    const appUrl = process.env.APP_URL || 'https://financial-revolution.polsia.app';
    const referralLink = `${appUrl}/signup.html?ref=${referralCode}`;

    // Count referrals made by this user
    const referralCount = await pool.query(
      'SELECT COUNT(*) as count FROM users WHERE referred_by_user_id = $1',
      [req.userId]
    );

    res.json({
      success: true,
      referral_code: referralCode,
      referral_link: referralLink,
      referral_count: parseInt(referralCount.rows[0].count)
    });
  } catch (err) {
    console.error('GET /api/user/referral-code error:', err.message);
    res.status(500).json({ error: 'Failed to get referral code' });
  }
});

