// ─── PWA: Push Notification Endpoints ────────────────────────────────────────

// Returns the VAPID public key for the client to use when subscribing
app.get('/api/push/vapid-public-key', (req, res) => {
  if (!vapidKeys || !vapidKeys.publicKey) {
    return res.status(503).json({ error: 'Push notifications not configured' });
  }
  res.json({ publicKey: vapidKeys.publicKey });
});

// Save a push subscription
app.post('/api/push/subscribe', async (req, res) => {
  if (!vapidKeys) return res.status(503).json({ error: 'Push not configured' });
  try {
    const { subscription } = req.body;
    if (!subscription || !subscription.endpoint) {
      return res.status(400).json({ error: 'Invalid subscription' });
    }
    const userId = req.session?.userId || null;
    const userAgent = req.headers['user-agent'] || null;
    const p256dh = subscription.keys?.p256dh || null;
    const auth = subscription.keys?.auth || null;

    await pool.query(`
      INSERT INTO push_subscriptions (user_id, endpoint, p256dh, auth, user_agent, updated_at)
      VALUES ($1, $2, $3, $4, $5, NOW())
      ON CONFLICT (endpoint)
        DO UPDATE SET user_id = EXCLUDED.user_id,
                      p256dh = EXCLUDED.p256dh,
                      auth = EXCLUDED.auth,
                      user_agent = EXCLUDED.user_agent,
                      updated_at = NOW()
    `, [userId, subscription.endpoint, p256dh, auth, userAgent]);

    res.json({ success: true });
  } catch (err) {
    console.error('POST /api/push/subscribe error:', err.message);
    res.status(500).json({ error: 'Failed to save subscription' });
  }
});

// Remove a push subscription
app.post('/api/push/unsubscribe', async (req, res) => {
  try {
    const { endpoint } = req.body;
    if (!endpoint) return res.status(400).json({ error: 'endpoint required' });
    await pool.query('DELETE FROM push_subscriptions WHERE endpoint = $1', [endpoint]);
    res.json({ success: true });
  } catch (err) {
    console.error('POST /api/push/unsubscribe error:', err.message);
    res.status(500).json({ error: 'Failed to remove subscription' });
  }
});

// Send a push notification to a specific user (internal/admin)
app.post('/api/push/send', async (req, res) => {
  if (!webPush || !vapidKeys) return res.status(503).json({ error: 'Push not configured' });
  const { userId, title, body, url } = req.body;
  if (!userId || !title) return res.status(400).json({ error: 'userId and title required' });

  try {
    const result = await pool.query(
      'SELECT endpoint, p256dh, auth FROM push_subscriptions WHERE user_id = $1',
      [userId]
    );
    if (!result.rows.length) return res.json({ success: true, sent: 0 });

    const payload = JSON.stringify({ title, body: body || '', url: url || '/app' });
    let sent = 0;
    for (const sub of result.rows) {
      try {
        await webPush.sendNotification({
          endpoint: sub.endpoint,
          keys: { p256dh: sub.p256dh, auth: sub.auth }
        }, payload);
        sent++;
      } catch (pushErr) {
        if (pushErr.statusCode === 410 || pushErr.statusCode === 404) {
          // Subscription expired — clean it up
          await pool.query('DELETE FROM push_subscriptions WHERE endpoint = $1', [sub.endpoint]);
        } else {
          console.warn('[PWA] Push send error:', pushErr.message);
        }
      }
    }
    res.json({ success: true, sent });
  } catch (err) {
    console.error('POST /api/push/send error:', err.message);
    res.status(500).json({ error: 'Failed to send push' });
  }
});

// ═══════════════════════════════════════════════════════════
// ─── YEAR-END ARCHIVE ROUTES ──────────────────────────────
// ═══════════════════════════════════════════════════════════

/**
 * GET /api/year-archive/years
 * Returns list of years with archive metadata for the current user.
 * Includes: is_locked, is_visible (2 most recent), is_collapsed (years 3-5),
 * scheduled_deletion_at, has_snapshot, grace_period_ends.
 */
app.get('/api/year-archive/years', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const currentYear = new Date().getFullYear();

    // Get all snapshots for user
    const snapshotRes = await pool.query(
      `SELECT year, is_locked, grace_period_ends, locked_at, created_at
       FROM year_end_snapshots
       WHERE user_id = $1
       ORDER BY year DESC`,
      [userId]
    );
    const snapshotMap = {};
    snapshotRes.rows.forEach(s => { snapshotMap[s.year] = s; });

    // Get the earliest year the user has data for (transactions or snapshots)
    const earliestRes = await pool.query(
      `SELECT MIN(EXTRACT(YEAR FROM transaction_date)::INTEGER) as min_year
       FROM transactions
       WHERE user_id = $1`,
      [userId]
    );
    const snapshotYears = snapshotRes.rows.map(s => s.year);
    const minTransactionYear = earliestRes.rows[0]?.min_year || currentYear;
    const earliestYear = Math.min(minTransactionYear, ...snapshotYears, currentYear);

    // Build year list: current year + up to 4 prior years visible, plus any snapshots
    const allYears = new Set();
    allYears.add(currentYear);
    for (let y = currentYear - 1; y >= Math.max(currentYear - 4, earliestYear); y--) {
      allYears.add(y);
    }
    snapshotYears.forEach(y => allYears.add(y));

    const years = Array.from(allYears).sort((a, b) => b - a).map(year => {
      const snap = snapshotMap[year] || null;
      const isCurrentYear = year === currentYear;
      const yearsSinceNow = currentYear - year;

      // Visibility: current year + 1 prior = fully visible; years 2-4 prior = collapsed; 5+ = to be deleted
      const isVisible = yearsSinceNow <= 1; // current year and last year
      const isCollapsed = yearsSinceNow >= 2 && yearsSinceNow <= 4; // years 3-5
      const isEligibleForDeletion = yearsSinceNow >= 5;

      // Deletion date: Jan 1 of (year + 6)
      const scheduledDeletionAt = `${year + 6}-01-01`;

      // Grace period: Jan 1 - Jan 31 of year+1 (can edit prior year)
      const gracePeriodEnds = snap?.grace_period_ends || `${year + 1}-01-31`;
      const isInGracePeriod = !snap?.is_locked && new Date() <= new Date(gracePeriodEnds);
      const isLocked = snap?.is_locked || (!isCurrentYear && !isInGracePeriod);

      return {
        year,
        has_snapshot: !!snap,
        is_current: isCurrentYear,
        is_visible: isVisible,
        is_collapsed: isCollapsed,
        is_eligible_for_deletion: isEligibleForDeletion,
        is_locked: isLocked,
        is_in_grace_period: isInGracePeriod,
        grace_period_ends: gracePeriodEnds,
        scheduled_deletion_at: scheduledDeletionAt,
        snapshot_created_at: snap?.created_at || null
      };
    });

    res.json({ success: true, years, current_year: currentYear });
  } catch (err) {
    console.error('GET /api/year-archive/years error:', err.message);
    res.status(500).json({ error: 'Failed to fetch archive years' });
  }
});

/**
 * GET /api/year-archive/snapshot/:year
 * Returns the full year-end snapshot (balance data) for a given year.
 * If no snapshot exists, builds a live one (for current year or unlocked years).
 */
app.get('/api/year-archive/snapshot/:year', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const year = parseInt(req.params.year);

    if (isNaN(year) || year < 2000 || year > 2100) {
      return res.status(400).json({ error: 'Invalid year' });
    }

    // Check if snapshot exists
    const snapshotRes = await pool.query(
      `SELECT * FROM year_end_snapshots WHERE user_id = $1 AND year = $2`,
      [userId, year]
    );

    if (snapshotRes.rows.length > 0) {
      return res.json({ success: true, snapshot: snapshotRes.rows[0] });
    }

    // Build live summary for years without a snapshot
    const yearStart = `${year}-01-01`;
    const yearEnd = `${year}-12-31`;

    const txRes = await pool.query(
      `SELECT type, SUM(amount) as total
       FROM transactions
       WHERE user_id = $1
         AND transaction_date >= $2
         AND transaction_date <= $3
       GROUP BY type`,
      [userId, yearStart, yearEnd]
    );

    const summary = { income: 0, expense: 0, net: 0 };
    txRes.rows.forEach(r => {
      if (r.type === 'income') summary.income = parseFloat(r.total || 0);
      if (r.type === 'expense') summary.expense = parseFloat(r.total || 0);
    });
    summary.net = summary.income - summary.expense;

    // Transaction count
    const txCountRes = await pool.query(
      `SELECT COUNT(*) as count
       FROM transactions
       WHERE user_id = $1
         AND transaction_date >= $2
         AND transaction_date <= $3`,
      [userId, yearStart, yearEnd]
    );

    const liveSummary = {
      year,
      is_live: true,
      transactions_summary: summary,
      transaction_count: parseInt(txCountRes.rows[0]?.count || 0)
    };

    res.json({ success: true, snapshot: liveSummary, is_live: true });
  } catch (err) {
    console.error(`GET /api/year-archive/snapshot/${req.params.year} error:`, err.message);
    res.status(500).json({ error: 'Failed to fetch year snapshot' });
  }
});

/**
 * GET /api/year-archive/transactions/:year
 * Returns paginated transactions filtered to a specific year.
 * Supports all existing filters (type, category_id) plus year.
 */
app.get('/api/year-archive/transactions/:year', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const year = parseInt(req.params.year);

    if (isNaN(year) || year < 2000 || year > 2100) {
      return res.status(400).json({ error: 'Invalid year' });
    }

    const { type, category_id, limit = 100, offset = 0 } = req.query;
    const yearStart = `${year}-01-01`;
    const yearEnd = `${year}-12-31`;

    let query = `
      SELECT t.*, c.name as category_name, c.slug as category_slug,
             c.color as category_color, c.icon as category_icon,
             COALESCE(ba.name, bra.name) as bank_account_name
      FROM transactions t
      LEFT JOIN categories c ON c.id = t.category_id
      LEFT JOIN bank_accounts ba ON ba.id = t.bank_account_id
      LEFT JOIN brokerage_accounts bra ON bra.id = t.brokerage_account_id
      WHERE t.user_id = $1
        AND t.transaction_date >= $2
        AND t.transaction_date <= $3
    `;
    const params = [userId, yearStart, yearEnd];
    let paramIdx = 4;

    if (type) {
      query += ` AND t.type = $${paramIdx++}`;
      params.push(type);
    }
    if (category_id) {
      query += ` AND t.category_id = $${paramIdx++}`;
      params.push(parseInt(category_id));
    }

    // Count query
    const countQuery = query.replace(
      /SELECT t\.\*, c\.name.*FROM transactions t/,
      'SELECT COUNT(*) as total FROM transactions t'
    );
    const countParams = params.slice(0, paramIdx - 1);

    query += ` ORDER BY t.transaction_date DESC, t.created_at DESC`;
    query += ` LIMIT $${paramIdx++} OFFSET $${paramIdx++}`;
    params.push(parseInt(limit), parseInt(offset));

    const [result, countResult] = await Promise.all([
      pool.query(query, params),
      pool.query(`SELECT COUNT(*) as total FROM transactions WHERE user_id = $1 AND transaction_date >= $2 AND transaction_date <= $3`, [userId, yearStart, yearEnd])
    ]);

    const rows = result.rows.map(t => ({
      ...t,
      transaction_date: t.transaction_date
        ? (t.transaction_date instanceof Date
            ? t.transaction_date.toISOString().split('T')[0]
            : String(t.transaction_date).split('T')[0])
        : null
    }));

    res.json({
      success: true,
      transactions: rows,
      total: parseInt(countResult.rows[0]?.total || 0),
      year
    });
  } catch (err) {
    console.error(`GET /api/year-archive/transactions/${req.params.year} error:`, err.message);
    res.status(500).json({ error: 'Failed to fetch year transactions' });
  }
});

/**
 * POST /api/year-archive/close/:year
 * Manually trigger year-end close for a specific year (creates/updates snapshot).
 * Admin-only in production, available for testing.
 */
app.post('/api/year-archive/close/:year', requireAuth, async (req, res) => {
  const client = await pool.connect();
  try {
    const userId = req.userId;
    const year = parseInt(req.params.year);

    if (isNaN(year) || year < 2000 || year > 2100) {
      return res.status(400).json({ error: 'Invalid year' });
    }

    // Check if already locked
    const existing = await client.query(
      `SELECT id, is_locked FROM year_end_snapshots WHERE user_id = $1 AND year = $2`,
      [userId, year]
    );
    if (existing.rows.length > 0 && existing.rows[0].is_locked) {
      return res.status(409).json({ error: `Year ${year} is already locked and cannot be re-closed` });
    }

    const yearStart = `${year}-01-01`;
    const yearEnd = `${year}-12-31`;
    const gracePeriodEnds = `${year + 1}-01-31`;

    // Gather balance data
    const [bankRes, debtRes, txRes] = await Promise.all([
      client.query(
        `SELECT id, name, current_balance FROM bank_accounts WHERE user_id = $1 AND (is_archived = FALSE OR is_archived IS NULL)`,
        [userId]
      ),
      client.query(`SELECT id, name, balance, interest_rate FROM debts WHERE user_id = $1`, [userId]),
      client.query(
        `SELECT type, SUM(amount) as total FROM transactions WHERE user_id = $1 AND transaction_date >= $2 AND transaction_date <= $3 GROUP BY type`,
        [userId, yearStart, yearEnd]
      )
    ]);

    const txSummary = { income: 0, expense: 0, net: 0 };
    txRes.rows.forEach(r => {
      if (r.type === 'income') txSummary.income = parseFloat(r.total || 0);
      if (r.type === 'expense') txSummary.expense = parseFloat(r.total || 0);
    });
    txSummary.net = txSummary.income - txSummary.expense;

    const balanceData = {
      year,
      snapshot_date: yearEnd,
      bank_accounts: bankRes.rows.map(r => ({ id: r.id, name: r.name, balance: parseFloat(r.current_balance || 0) })),
      debts: debtRes.rows.map(r => ({ id: r.id, name: r.name, balance: parseFloat(r.balance || 0), interest_rate: parseFloat(r.interest_rate || 0) })),
      transactions_summary: txSummary
    };

    const result = await client.query(
      `INSERT INTO year_end_snapshots (user_id, year, snapshot_date, balance_data, is_locked, grace_period_ends)
       VALUES ($1, $2, $3, $4, FALSE, $5)
       ON CONFLICT (user_id, year) DO UPDATE SET
         balance_data = EXCLUDED.balance_data,
         grace_period_ends = EXCLUDED.grace_period_ends,
         updated_at = NOW()
       RETURNING *`,
      [userId, year, yearEnd, balanceData, gracePeriodEnds]
    );

    res.json({ success: true, snapshot: result.rows[0] });
  } catch (err) {
    console.error(`POST /api/year-archive/close/${req.params.year} error:`, err.message);
    res.status(500).json({ error: 'Failed to create year-end snapshot' });
  } finally {
    client.release();
  }
});

/**
 * GET /api/year-archive/warnings/pending
 * Returns unacknowledged archive warnings for the current user.
 * Used by the frontend to show login-gate modal.
 */
app.get('/api/year-archive/warnings/pending', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    const result = await pool.query(
      `SELECT id, year_to_delete, deletion_date, warning_level, sent_at
       FROM archive_warnings
       WHERE user_id = $1 AND acknowledged_at IS NULL
       ORDER BY warning_level ASC`,
      [userId]
    );

    // Also check if a warning should exist based on current date (in case job hasn't run)
    const currentYear = new Date().getFullYear();
    const yearToDelete = currentYear - 5;
    const deletionDate = new Date(`${currentYear + 1}-01-01`);
    const daysLeft = Math.ceil((deletionDate - new Date()) / (1000 * 60 * 60 * 24));

    // Synthesize a warning if within warning window and no stored warning
    let pendingWarnings = result.rows;
    if (daysLeft <= 90 && result.rows.length === 0) {
      const warningLevel = [90, 60, 30, 7, 1].find(l => daysLeft <= l) || 90;
      // Check if user has data for that year
      const hasData = await pool.query(
        `SELECT 1 FROM transactions WHERE user_id = $1 AND EXTRACT(YEAR FROM transaction_date)::INTEGER = $2 LIMIT 1`,
        [userId, yearToDelete]
      );
      if (hasData.rows.length > 0) {
        // Auto-create the warning record
        try {
          await pool.query(
            `INSERT INTO archive_warnings (user_id, year_to_delete, deletion_date, warning_level, sent_at)
             VALUES ($1, $2, $3, $4, NOW())
             ON CONFLICT (user_id, year_to_delete, warning_level) DO NOTHING`,
            [userId, yearToDelete, deletionDate.toISOString().split('T')[0], warningLevel]
          );
          // Fetch the newly created warning
          const newResult = await pool.query(
            `SELECT id, year_to_delete, deletion_date, warning_level, sent_at
             FROM archive_warnings
             WHERE user_id = $1 AND acknowledged_at IS NULL
             ORDER BY warning_level ASC`,
            [userId]
          );
          pendingWarnings = newResult.rows;
        } catch (e) {
          // Ignore - table may not exist yet in migration window
        }
      }
    }

    res.json({
      success: true,
      warnings: pendingWarnings,
      has_pending: pendingWarnings.length > 0
    });
  } catch (err) {
    console.error('GET /api/year-archive/warnings/pending error:', err.message);
    res.status(500).json({ error: 'Failed to fetch pending warnings' });
  }
});

/**
 * POST /api/year-archive/warnings/:id/acknowledge
 * Marks a specific archive warning as acknowledged.
 */
app.post('/api/year-archive/warnings/:id/acknowledge', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const warningId = parseInt(req.params.id);

    const result = await pool.query(
      `UPDATE archive_warnings
       SET acknowledged_at = NOW()
       WHERE id = $1 AND user_id = $2
       RETURNING *`,
      [warningId, userId]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Warning not found' });
    }

    res.json({ success: true, warning: result.rows[0] });
  } catch (err) {
    console.error(`POST /api/year-archive/warnings/${req.params.id}/acknowledge error:`, err.message);
    res.status(500).json({ error: 'Failed to acknowledge warning' });
  }
});

