/**
 * GET /api/year-archive/export/:year
 * Export all transactions for a given year as CSV.
 * Pro feature — free users see a prompt to upgrade.
 */
app.get('/api/year-archive/export/:year', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const year = parseInt(req.params.year);

    if (isNaN(year) || year < 2000 || year > 2100) {
      return res.status(400).json({ error: 'Invalid year' });
    }

    // Check Pro access
    const hasPro = await hasProAccess(userId);
    if (!hasPro) {
      return res.status(403).json({
        error: `CSV export for archived years is a paid feature. Please upgrade to download your ${year} data.`,
        code: 'PRO_REQUIRED'
      });
    }

    const yearStart = `${year}-01-01`;
    const yearEnd = `${year}-12-31`;

    const result = await pool.query(
      `SELECT
         t.transaction_date,
         t.type,
         c.name as category,
         t.subcategory,
         t.amount,
         t.description,
         COALESCE(ba.name, bra.name) as bank_account
       FROM transactions t
       LEFT JOIN categories c ON t.category_id = c.id
       LEFT JOIN bank_accounts ba ON t.bank_account_id = ba.id
       LEFT JOIN brokerage_accounts bra ON bra.id = t.brokerage_account_id
       WHERE t.user_id = $1
         AND t.transaction_date >= $2
         AND t.transaction_date <= $3
       ORDER BY t.transaction_date DESC`,
      [userId, yearStart, yearEnd]
    );

    const csvRows = ['Date,Type,Category,Subcategory,Amount,Description,Bank Account'];
    for (const row of result.rows) {
      const date = row.transaction_date ? new Date(row.transaction_date).toISOString().split('T')[0] : '';
      const type = row.type || '';
      const category = (row.category || '').replace(/"/g, '""');
      const subcategory = (row.subcategory || '').replace(/"/g, '""');
      const amount = row.amount || '0.00';
      const description = (row.description || '').replace(/"/g, '""');
      const bankAccount = (row.bank_account || '').replace(/"/g, '""');
      csvRows.push(`${date},${type},"${category}","${subcategory}",${amount},"${description}","${bankAccount}"`);
    }

    const csvContent = csvRows.join('\n');
    const filename = `facts_transactions_${year}.csv`;
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.send(csvContent);
  } catch (err) {
    console.error(`GET /api/year-archive/export/${req.params.year} error:`, err.message);
    res.status(500).json({ error: 'Failed to export year data' });
  }
});

/**
 * GET /api/year-archive/summary/:year
 * Returns income/expense summary + category breakdown for a year.
 */
app.get('/api/year-archive/summary/:year', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const year = parseInt(req.params.year);

    if (isNaN(year) || year < 2000 || year > 2100) {
      return res.status(400).json({ error: 'Invalid year' });
    }

    const yearStart = `${year}-01-01`;
    const yearEnd = `${year}-12-31`;

    const [txSummary, categoryBreakdown, monthlyBreakdown] = await Promise.all([
      // Overall summary
      pool.query(
        `SELECT type, SUM(amount) as total, COUNT(*) as count
         FROM transactions
         WHERE user_id = $1 AND transaction_date >= $2 AND transaction_date <= $3
         GROUP BY type`,
        [userId, yearStart, yearEnd]
      ),
      // Category breakdown
      pool.query(
        `SELECT c.name as category_name, c.color as category_color, c.slug as category_slug,
                t.type, SUM(t.amount) as total, COUNT(*) as count
         FROM transactions t
         LEFT JOIN categories c ON c.id = t.category_id
         WHERE t.user_id = $1
           AND t.transaction_date >= $2
           AND t.transaction_date <= $3
           AND t.type = 'expense'
         GROUP BY c.name, c.color, c.slug, t.type
         ORDER BY total DESC`,
        [userId, yearStart, yearEnd]
      ),
      // Monthly breakdown
      pool.query(
        `SELECT
           EXTRACT(MONTH FROM transaction_date)::INTEGER as month,
           type,
           SUM(amount) as total
         FROM transactions
         WHERE user_id = $1
           AND transaction_date >= $2
           AND transaction_date <= $3
         GROUP BY month, type
         ORDER BY month`,
        [userId, yearStart, yearEnd]
      )
    ]);

    const summary = { income: 0, expense: 0, net: 0, income_count: 0, expense_count: 0 };
    txSummary.rows.forEach(r => {
      if (r.type === 'income') {
        summary.income = parseFloat(r.total || 0);
        summary.income_count = parseInt(r.count || 0);
      }
      if (r.type === 'expense') {
        summary.expense = parseFloat(r.total || 0);
        summary.expense_count = parseInt(r.count || 0);
      }
    });
    summary.net = summary.income - summary.expense;

    // Build monthly data (12 months)
    const monthly = Array.from({ length: 12 }, (_, i) => ({
      month: i + 1,
      month_name: new Date(year, i, 1).toLocaleString('en-US', { month: 'short' }),
      income: 0,
      expense: 0
    }));
    monthlyBreakdown.rows.forEach(r => {
      const m = monthly[r.month - 1];
      if (r.type === 'income') m.income = parseFloat(r.total || 0);
      if (r.type === 'expense') m.expense = parseFloat(r.total || 0);
    });

    res.json({
      success: true,
      year,
      summary,
      categories: categoryBreakdown.rows.map(r => ({
        name: r.category_name || 'Uncategorized',
        color: r.category_color || '#6b7280',
        slug: r.category_slug,
        total: parseFloat(r.total || 0),
        count: parseInt(r.count || 0)
      })),
      monthly
    });
  } catch (err) {
    console.error(`GET /api/year-archive/summary/${req.params.year} error:`, err.message);
    res.status(500).json({ error: 'Failed to fetch year summary' });
  }
});

// ─────────────────────────────────────────────────────────────────────────────

// ── Startup hook: ensure PWA icons exist with CORRECT DIMENSIONS ─────────────
// Icons are committed to git, so they should always exist. This is a safety net
// that also validates actual PNG dimensions match manifest declarations.
// Chrome rejects icons where declared sizes don't match actual dimensions,
// preventing beforeinstallprompt from firing.
function ensurePWAIconsSync() {
  const iconDir = path.join(__dirname, 'public', 'icons');
  const iconSpecs = [
    { file: 'icon-192.png', minW: 192, minH: 192, maskable: false },
    { file: 'icon-512.png', minW: 512, minH: 512, maskable: false },
    { file: 'icon-maskable.png', minW: 512, minH: 512, maskable: true },
  ];

  if (!fs.existsSync(iconDir)) {
    fs.mkdirSync(iconDir, { recursive: true });
    console.log('[PWA] Created icons directory');
  }

  // Check each icon: exists, valid PNG, and correct dimensions
  let allValid = true;
  for (const spec of iconSpecs) {
    const iconPath = path.join(iconDir, spec.file);
    if (fs.existsSync(iconPath)) {
      const buf = fs.readFileSync(iconPath);
      if (buf.length >= 24 && buf[0] === 137 && buf[1] === 80 && buf[2] === 78 && buf[3] === 71) {
        const w = buf.readUInt32BE(16);
        const h = buf.readUInt32BE(20);
        const aspect = Math.min(w, h) / Math.max(w, h);
        if (w >= spec.minW && h >= spec.minH && aspect >= 0.9) {
          continue; // This icon is valid (correct size AND square)
        }
        if (aspect < 0.9) {
          console.warn('[PWA] ' + spec.file + ': NOT SQUARE ' + w + 'x' + h + ' (aspect ' + aspect.toFixed(2) + '). PWA icons must be square.');
        } else {
          console.warn('[PWA] ' + spec.file + ': dimensions ' + w + 'x' + h + ' < required ' + spec.minW + 'x' + spec.minH);
        }
      } else {
        console.warn('[PWA] ' + spec.file + ': invalid PNG signature');
      }
    } else {
      console.warn('[PWA] ' + spec.file + ': missing');
    }
    allValid = false;
  }

  if (allValid) {
    console.log('[PWA] All icons valid with correct dimensions');
    return;
  }

  // Generate icons at EXACT declared sizes (emergency fallback)
  console.warn('[PWA] Generating emergency fallback icons at correct sizes...');
  try {
    const zlibMod = require('zlib');
    const CRC_T = new Uint32Array(256);
    for (let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);CRC_T[n]=c;}
    function crc(b){let c=0xffffffff;for(let i=0;i<b.length;i++)c=CRC_T[(c^b[i])&0xff]^(c>>>8);return(c^0xffffffff)>>>0;}
    function chunk(t,d){const tb=Buffer.from(t,'ascii');const l=Buffer.alloc(4);l.writeUInt32BE(d.length,0);const cr=Buffer.alloc(4);cr.writeUInt32BE(crc(Buffer.concat([tb,d])),0);return Buffer.concat([l,tb,d,cr]);}

    function genIcon(W, H, isMaskable) {
      const BG = [0x0a,0x0f,0x1a,0xff];
      const FG = [0x10,0xb9,0x81,0xff];
      const pad = isMaskable ? Math.floor(W*0.2) : 0;
      const aW = W-pad*2, aH = H-pad*2;
      const lL=pad+Math.floor(aW*0.28), lR=pad+Math.floor(aW*0.72);
      const lT=pad+Math.floor(aH*0.15), lB=pad+Math.floor(aH*0.85);
      const sW=Math.floor(aW*0.14), bH=Math.floor(aH*0.11);
      const mR=pad+Math.floor(aW*0.64), mT=lT+Math.floor((lB-lT)*0.38);
      const rowLen=1+W*4;
      const raw=Buffer.alloc(rowLen*H);
      for(let y=0;y<H;y++){
        const off=y*rowLen; raw[off]=0;
        for(let x=0;x<W;x++){
          const px=off+1+x*4; let c=BG;
          if(y>=lT&&y<lB&&x>=lL&&x<lL+sW) c=FG;
          if(y>=lT&&y<lT+bH&&x>=lL&&x<lR) c=FG;
          if(y>=mT&&y<mT+bH&&x>=lL&&x<mR) c=FG;
          raw[px]=c[0];raw[px+1]=c[1];raw[px+2]=c[2];raw[px+3]=c[3];
        }
      }
      const comp=zlibMod.deflateSync(raw,{level:9});
      const sig=Buffer.from([137,80,78,71,13,10,26,10]);
      const ihdr=Buffer.alloc(13);
      ihdr.writeUInt32BE(W,0);ihdr.writeUInt32BE(H,4);
      ihdr[8]=8;ihdr[9]=6;ihdr[10]=0;ihdr[11]=0;ihdr[12]=0;
      return Buffer.concat([sig,chunk('IHDR',ihdr),chunk('IDAT',comp),chunk('IEND',Buffer.alloc(0))]);
    }

    for (const spec of iconSpecs) {
      const iconPath = path.join(iconDir, spec.file);
      // Only overwrite if missing or wrong dimensions
      let needsWrite = true;
      if (fs.existsSync(iconPath)) {
        const buf = fs.readFileSync(iconPath);
        if (buf.length >= 24 && buf[0]===137 && buf[1]===80) {
          const w=buf.readUInt32BE(16), h=buf.readUInt32BE(20);
          if (w >= spec.minW && h >= spec.minH) needsWrite = false;
        }
      }
      if (needsWrite) {
        const png = genIcon(spec.minW, spec.minH, spec.maskable);
        fs.writeFileSync(iconPath, png);
        console.log('[PWA] Fallback icon saved: ' + spec.file + ' (' + spec.minW + 'x' + spec.minH + ')');
      }
    }
  } catch (err) {
    console.error('[PWA] Fallback icon generation failed:', err.message);
  }
}

// ── PWA Diagnostic Endpoint ─────────────────────────────────────────────────
// Helps debug install issues: verifies all PWA install criteria are met
app.get('/api/pwa/diagnostic', (req, res) => {
  const iconDir = path.join(__dirname, 'public', 'icons');
  const manifestPath = path.join(__dirname, 'public', 'manifest.json');
  const swPath = path.join(__dirname, 'public', 'sw.js');
  const pwaPath = path.join(__dirname, 'public', 'pwa.js');

  const checks = {
    timestamp: new Date().toISOString(),
    manifest: {
      exists: fs.existsSync(manifestPath),
      size: fs.existsSync(manifestPath) ? fs.statSync(manifestPath).size : 0,
    },
    serviceWorker: {
      exists: fs.existsSync(swPath),
      size: fs.existsSync(swPath) ? fs.statSync(swPath).size : 0,
    },
    pwaScript: {
      exists: fs.existsSync(pwaPath),
      size: fs.existsSync(pwaPath) ? fs.statSync(pwaPath).size : 0,
    },
    icons: {},
    https: req.protocol === 'https' || req.get('x-forwarded-proto') === 'https',
  };

  // Chrome requires icon-192 to be >= 192x192 and icon-512 to be >= 512x512.
  // If actual PNG dimensions don't match manifest, beforeinstallprompt won't fire.
  const iconSpecs = [
    { file: 'icon-192.png', declaredW: 192, declaredH: 192 },
    { file: 'icon-512.png', declaredW: 512, declaredH: 512 },
    { file: 'icon-maskable.png', declaredW: 512, declaredH: 512 },
  ];
  let allIconsValid = true;
  for (const spec of iconSpecs) {
    const iconPath = path.join(iconDir, spec.file);
    const exists = fs.existsSync(iconPath);
    const size = exists ? fs.statSync(iconPath).size : 0;
    let validPng = false;
    let actualWidth = 0, actualHeight = 0;
    let dimensionsMatch = false;
    if (exists && size >= 24) {
      try {
        const fd = fs.openSync(iconPath, 'r');
        const hdr = Buffer.alloc(24);
        fs.readSync(fd, hdr, 0, 24, 0);
        fs.closeSync(fd);
        validPng = hdr[0]===137 && hdr[1]===80 && hdr[2]===78 && hdr[3]===71;
        if (validPng) {
          actualWidth = hdr.readUInt32BE(16);
          actualHeight = hdr.readUInt32BE(20);
          var aspect = Math.min(actualWidth, actualHeight) / Math.max(actualWidth, actualHeight);
          // Icon must be >= declared size AND roughly square (aspect >= 0.9)
          dimensionsMatch = actualWidth >= spec.declaredW && actualHeight >= spec.declaredH && aspect >= 0.9;
        }
      } catch { validPng = false; }
    }
    checks.icons[spec.file] = {
      exists, size, validPng,
      actualDimensions: actualWidth + 'x' + actualHeight,
      declaredDimensions: spec.declaredW + 'x' + spec.declaredH,
      dimensionsMatch
    };
    if (!exists || !validPng || !dimensionsMatch) allIconsValid = false;
  }

  checks.installable = checks.manifest.exists && checks.serviceWorker.exists &&
                        checks.pwaScript.exists && allIconsValid && checks.https;
  checks.swCacheVersion = 'v4';

  res.json(checks);
});

