// GET /api/settings/all — Get all settings data in one request
app.get('/api/settings/all', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const result = await pool.query(
      `SELECT id, email, name, display_name, avatar_url, avatar_color,
              notification_prefs, plan, paid_until, is_creator, promo_code_used, promo_grace_expired,
              two_factor_enabled, referral_code, created_at,
              pricing_tier, subscription_tier, subscription_plan_type
       FROM users WHERE id = $1`,
      [userId]
    );
    if (!result.rows.length) return res.status(404).json({ error: 'User not found' });

    const user = result.rows[0];
    const hasPro = await hasProAccess(user);

    // Get Plaid accounts (Pro only)
    let plaidAccounts = [];
    if (hasPro) {
      const plaidResult = await pool.query(
        `SELECT id, institution_name, account_name, account_type, account_subtype,
                account_mask, available_balance, current_balance, currency_code, last_synced_at
         FROM plaid_accounts WHERE user_id = $1 ORDER BY created_at ASC`,
        [userId]
      );
      plaidAccounts = plaidResult.rows;
    }

    // Get subscription info
    const subResult = await pool.query(
      `SELECT plan, amount_cents, status, started_at, expires_at, stripe_payment_link
       FROM subscriptions WHERE user_id = $1 AND status IN ('completed', 'pending')
       ORDER BY created_at DESC LIMIT 1`,
      [userId]
    );
    const subscription = subResult.rows[0] || null;

    // Get family/family plan membership info
    let householdInfo = null;
    try {
      const hhResult = await pool.query(`
        SELECT h.id, h.name, hm.role, hm.status,
               h.owner_id, owner.email as owner_email, owner.name as owner_name,
               owner.paid_until as owner_paid_until,
               h.cancelled_at, h.cancellation_grace_ends_at
        FROM household_members hm
        JOIN households h ON h.id = hm.household_id
        JOIN users owner ON owner.id = h.owner_id
        WHERE hm.user_id = $1 AND hm.status = 'active'
        ORDER BY hm.joined_at DESC LIMIT 1
      `, [userId]);
      if (hhResult.rows.length > 0) {
        const hh = hhResult.rows[0];
        householdInfo = {
          id: hh.id,
          name: hh.name,
          role: hh.role,
          is_owner: hh.owner_id === userId,
          owner_name: hh.owner_name,
          owner_email: hh.owner_email,
          owner_paid_until: hh.owner_paid_until,
          cancelled_at: hh.cancelled_at,
          grace_ends_at: hh.cancellation_grace_ends_at
        };
      }
    } catch (hhErr) {
      console.error('Settings: family lookup failed (non-fatal):', hhErr.message);
    }

    // Default notification prefs
    const defaultNotifPrefs = {
      bill_due_reminders: true,
      budget_overspend: true,
      subscription_renewal: true,
      fg_commission: true,
      product_updates: false
    };
    const notifPrefs = Object.assign({}, defaultNotifPrefs, user.notification_prefs || {});

    res.json({
      success: true,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        display_name: user.display_name,
        avatar_url: user.avatar_url,
        avatar_color: user.avatar_color || '#10b981',
        two_factor_enabled: user.two_factor_enabled || false,
        plan: hasPro ? 'paid' : 'free',
        paid_until: user.paid_until,
        is_creator: user.is_creator,
        promo_code_used: user.promo_code_used,
        created_at: user.created_at,
        pricing_tier: user.pricing_tier || 'none',
        subscription_tier: user.subscription_tier || 'individual',
        subscription_plan_type: user.subscription_plan_type || 'monthly'
      },
      notification_prefs: notifPrefs,
      subscription,
      plaid_accounts: plaidAccounts,
      has_pro: hasPro,
      stripe_monthly_link: STRIPE_INDIVIDUAL_MONTHLY_LINK,
      stripe_annual_link: STRIPE_INDIVIDUAL_ANNUAL_LINK,
      pricing: {
        monthly_cents: INDIVIDUAL_MONTHLY_CENTS,
        annual_cents: INDIVIDUAL_ANNUAL_CENTS
      },
      family: householdInfo,
      family_plan: {
        monthly_cents: TFR_PRO_MONTHLY_CENTS,
        stripe_monthly_link: STRIPE_TFR_PRO_MONTHLY_LINK
      },
      new_tiers: {
        tfr_pro: {
          monthly_cents: TFR_PRO_MONTHLY_CENTS,
          stripe_link: STRIPE_TFR_PRO_MONTHLY_LINK
        },
        business_core: {
          monthly_cents: BUSINESS_CORE_MONTHLY_CENTS,
          stripe_link: STRIPE_BUSINESS_CORE_MONTHLY_LINK
        },
        business_bundle: {
          monthly_cents: BUSINESS_BUNDLE_MONTHLY_CENTS,
          stripe_link: STRIPE_BUSINESS_BUNDLE_MONTHLY_LINK
        },
        tfr_elite: {
          monthly_cents: TFR_ELITE_MONTHLY_CENTS,
          stripe_link: STRIPE_TFR_ELITE_MONTHLY_LINK
        },
        sovereign_executive: {
          one_time_cents: SOVEREIGN_EXEC_CENTS,
          stripe_link: STRIPE_SOVEREIGN_LINK
        }
      }
    });
  } catch (err) {
    console.error('GET /api/settings/all error:', err.message);
    res.status(500).json({ error: 'Failed to load settings' });
  }
});

// PUT /api/settings/profile — Update display name and avatar
app.put('/api/settings/profile', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { display_name, avatar_color } = req.body;

    // Validate display name
    if (display_name !== undefined && display_name !== null) {
      const trimmed = display_name.trim();
      if (trimmed.length > 100) {
        return res.status(400).json({ error: 'Display name must be 100 characters or less' });
      }
    }

    // Validate avatar color
    const validColors = ['#10b981', '#3b82f6', '#8b5cf6', '#f59e0b', '#f43f5e', '#06b6d4', '#84cc16', '#ec4899'];
    const color = avatar_color && validColors.includes(avatar_color) ? avatar_color : null;

    const updates = [];
    const params = [];
    let paramIdx = 1;

    if (display_name !== undefined) {
      updates.push(`display_name = $${paramIdx++}`);
      params.push(display_name ? display_name.trim() || null : null);
    }
    if (color) {
      updates.push(`avatar_color = $${paramIdx++}`);
      params.push(color);
    }

    if (updates.length === 0) {
      return res.status(400).json({ error: 'No fields to update' });
    }

    updates.push(`updated_at = NOW()`);
    params.push(userId);

    const result = await pool.query(
      `UPDATE users SET ${updates.join(', ')} WHERE id = $${paramIdx} RETURNING display_name, avatar_color, name, email`,
      params
    );

    const updated = result.rows[0];
    res.json({
      success: true,
      display_name: updated.display_name,
      avatar_color: updated.avatar_color,
      display_label: updated.display_name || updated.name || updated.email
    });
  } catch (err) {
    console.error('PUT /api/settings/profile error:', err.message);
    res.status(500).json({ error: 'Failed to update profile' });
  }
});

// POST /api/settings/change-password — Change password
app.post('/api/settings/change-password', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { current_password, new_password, confirm_password } = req.body;

    if (!current_password || !new_password || !confirm_password) {
      return res.status(400).json({ error: 'All password fields are required' });
    }

    if (new_password !== confirm_password) {
      return res.status(400).json({ error: 'New passwords do not match' });
    }

    const { valid, errors } = validatePassword(new_password);
    if (!valid) {
      return res.status(400).json({ error: errors[0], errors });
    }

    // Get current password hash
    const result = await pool.query('SELECT password_hash FROM users WHERE id = $1', [userId]);
    if (!result.rows.length) return res.status(404).json({ error: 'User not found' });

    const user = result.rows[0];
    if (!user.password_hash) {
      return res.status(400).json({ error: 'No password set on this account' });
    }

    // Verify current password
    const match = await bcrypt.compare(current_password, user.password_hash);
    if (!match) {
      return res.status(400).json({ error: 'Current password is incorrect' });
    }

    // Hash and save new password
    const newHash = await bcrypt.hash(new_password, BCRYPT_ROUNDS);
    await pool.query(
      'UPDATE users SET password_hash = $1, updated_at = NOW() WHERE id = $2',
      [newHash, userId]
    );

    res.json({ success: true, message: 'Password changed successfully' });
  } catch (err) {
    console.error('POST /api/settings/change-password error:', err.message);
    res.status(500).json({ error: 'Failed to change password' });
  }
});

// POST /api/settings/change-email/request — Request email change
app.post('/api/settings/change-email/request', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { new_email, password } = req.body;

    if (!new_email || !new_email.includes('@')) {
      return res.status(400).json({ error: 'Valid email address required' });
    }
    if (!password) {
      return res.status(400).json({ error: 'Password required to change email' });
    }

    const normalizedEmail = new_email.toLowerCase().trim();

    // Get user
    const userResult = await pool.query(
      'SELECT email, password_hash FROM users WHERE id = $1',
      [userId]
    );
    if (!userResult.rows.length) return res.status(404).json({ error: 'User not found' });

    const user = userResult.rows[0];

    // Verify password
    const match = await bcrypt.compare(password, user.password_hash);
    if (!match) {
      return res.status(400).json({ error: 'Password is incorrect' });
    }

    // Check new email isn't already in use
    const emailCheck = await pool.query(
      'SELECT id FROM users WHERE LOWER(email) = $1 AND id != $2',
      [normalizedEmail, userId]
    );
    if (emailCheck.rows.length > 0) {
      return res.status(409).json({ error: 'This email address is already in use' });
    }

    // Rate limit: max 3 requests per hour
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
    const recentReqs = await pool.query(
      'SELECT COUNT(*) as count FROM email_change_tokens WHERE user_id = $1 AND created_at > $2',
      [userId, oneHourAgo]
    );
    if (parseInt(recentReqs.rows[0].count) >= 3) {
      return res.status(429).json({ error: 'Too many email change requests. Please try again later.' });
    }

    // Generate token
    const token = crypto.randomBytes(48).toString('hex');
    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

    // Invalidate old tokens for this user
    await pool.query(
      'UPDATE email_change_tokens SET used = true WHERE user_id = $1 AND used = false',
      [userId]
    );

    // Store new token
    await pool.query(
      'INSERT INTO email_change_tokens (user_id, new_email, token, expires_at) VALUES ($1, $2, $3, $4)',
      [userId, normalizedEmail, token, expiresAt]
    );

    const appUrl = process.env.APP_URL || 'https://financial-revolution.polsia.app';
    const confirmUrl = `${appUrl}/settings?action=confirm-email&token=${token}`;

    // Send confirmation email
    try {
      await fetch('https://polsia.com/api/proxy/email/send', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${process.env.POLSIA_API_KEY}`
        },
        body: JSON.stringify({
          to: normalizedEmail,
          subject: 'Confirm your new FACTS email address',
          html: `
            <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:600px;margin:0 auto;padding:20px;">
              <h2 style="color:#10b981;margin-bottom:16px;">Confirm Your New Email</h2>
              <p style="color:#333;line-height:1.6;margin-bottom:20px;">
                You requested to change your FACTS account email to this address. Click the button below to confirm the change.
              </p>
              <p style="margin-bottom:24px;">
                <a href="${confirmUrl}" style="display:inline-block;background:#10b981;color:#000;padding:12px 32px;text-decoration:none;border-radius:8px;font-weight:600;">
                  Confirm Email Change
                </a>
              </p>
              <p style="color:#666;font-size:0.875rem;">This link expires in 24 hours. If you didn't request this change, you can safely ignore this email.</p>
            </div>
          `,
          body: `Confirm your FACTS email change: ${confirmUrl}\n\nThis link expires in 24 hours.`,
          transactional: true
        })
      });
    } catch (emailErr) {
      console.error('[Settings] Email change confirmation email failed:', emailErr.message);
    }

    // Also notify old email
    try {
      await fetch('https://polsia.com/api/proxy/email/send', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${process.env.POLSIA_API_KEY}`
        },
        body: JSON.stringify({
          to: user.email,
          subject: 'FACTS: Email change requested',
          html: `
            <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:600px;margin:0 auto;padding:20px;">
              <h2 style="color:#f59e0b;margin-bottom:16px;">Email Change Requested</h2>
              <p style="color:#333;line-height:1.6;">
                A request was made to change your FACTS account email to <strong>${normalizedEmail}</strong>.
                If this wasn't you, please change your password immediately.
              </p>
            </div>
          `,
          body: `A request was made to change your FACTS account email to ${normalizedEmail}. If this wasn't you, please change your password.`,
          transactional: true
        })
      });
    } catch (notifyErr) {
      console.error('[Settings] Old email notification failed:', notifyErr.message);
    }

    res.json({
      success: true,
      message: `Confirmation link sent to ${normalizedEmail}. Check your inbox and click the link to confirm.`
    });
  } catch (err) {
    console.error('POST /api/settings/change-email/request error:', err.message);
    res.status(500).json({ error: 'Failed to send email change request' });
  }
});

// GET /api/settings/change-email/confirm — Confirm email change via token
app.get('/api/settings/change-email/confirm', async (req, res) => {
  try {
    const { token } = req.query;
    if (!token) return res.status(400).json({ error: 'Token required' });

    const tokenResult = await pool.query(
      `SELECT ect.*, u.email as current_email
       FROM email_change_tokens ect
       JOIN users u ON u.id = ect.user_id
       WHERE ect.token = $1`,
      [token]
    );

    if (!tokenResult.rows.length) {
      return res.status(400).json({ error: 'Invalid or expired confirmation link' });
    }

    const tokenRow = tokenResult.rows[0];

    if (tokenRow.used) {
      return res.status(400).json({ error: 'This confirmation link has already been used' });
    }
    if (new Date(tokenRow.expires_at) < new Date()) {
      return res.status(400).json({ error: 'This confirmation link has expired. Please request a new one.' });
    }

    // Check new email isn't taken (double-check)
    const emailCheck = await pool.query(
      'SELECT id FROM users WHERE LOWER(email) = $1 AND id != $2',
      [tokenRow.new_email, tokenRow.user_id]
    );
    if (emailCheck.rows.length > 0) {
      return res.status(409).json({ error: 'This email address is already in use by another account' });
    }

    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      await client.query(
        'UPDATE users SET email = $1, updated_at = NOW() WHERE id = $2',
        [tokenRow.new_email, tokenRow.user_id]
      );
      await client.query(
        'UPDATE email_change_tokens SET used = true WHERE id = $1',
        [tokenRow.id]
      );
      await client.query('COMMIT');
    } catch (txErr) {
      await client.query('ROLLBACK');
      throw txErr;
    } finally {
      client.release();
    }

    res.json({ success: true, message: 'Email address updated successfully', new_email: tokenRow.new_email });
  } catch (err) {
    console.error('GET /api/settings/change-email/confirm error:', err.message);
    res.status(500).json({ error: 'Failed to confirm email change' });
  }
});

// PUT /api/settings/notifications — Update notification preferences
app.put('/api/settings/notifications', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { bill_due_reminders, budget_overspend, subscription_renewal, fg_commission, product_updates } = req.body;

    const prefs = {};
    if (typeof bill_due_reminders === 'boolean') prefs.bill_due_reminders = bill_due_reminders;
    if (typeof budget_overspend === 'boolean') prefs.budget_overspend = budget_overspend;
    if (typeof subscription_renewal === 'boolean') prefs.subscription_renewal = subscription_renewal;
    if (typeof fg_commission === 'boolean') prefs.fg_commission = fg_commission;
    if (typeof product_updates === 'boolean') prefs.product_updates = product_updates;

    // Merge with existing prefs
    const existing = await pool.query('SELECT notification_prefs FROM users WHERE id = $1', [userId]);
    const currentPrefs = existing.rows[0]?.notification_prefs || {};
    const merged = Object.assign({}, currentPrefs, prefs);

    await pool.query(
      'UPDATE users SET notification_prefs = $1, updated_at = NOW() WHERE id = $2',
      [JSON.stringify(merged), userId]
    );

    res.json({ success: true, notification_prefs: merged });
  } catch (err) {
    console.error('PUT /api/settings/notifications error:', err.message);
    res.status(500).json({ error: 'Failed to save notification preferences' });
  }
});

// DELETE /api/settings/plaid-accounts/:id — Disconnect a Plaid account
app.delete('/api/settings/plaid-accounts/:id', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const accountId = parseInt(req.params.id);

    if (!accountId || isNaN(accountId)) {
      return res.status(400).json({ error: 'Invalid account ID' });
    }

    // Verify ownership
    const acctResult = await pool.query(
      'SELECT id, institution_name, account_name FROM plaid_accounts WHERE id = $1 AND user_id = $2',
      [accountId, userId]
    );
    if (!acctResult.rows.length) {
      return res.status(404).json({ error: 'Account not found' });
    }

    const acct = acctResult.rows[0];

    // Delete the account (cascades to related transactions if FK set, otherwise just remove)
    await pool.query('DELETE FROM plaid_accounts WHERE id = $1 AND user_id = $2', [accountId, userId]);

    res.json({
      success: true,
      message: `${acct.institution_name} - ${acct.account_name} disconnected successfully`
    });
  } catch (err) {
    console.error('DELETE /api/settings/plaid-accounts/:id error:', err.message);
    res.status(500).json({ error: 'Failed to disconnect account' });
  }
});

// POST /api/settings/delete-account — Delete account with safeguards
app.post('/api/settings/delete-account', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { password, confirmation } = req.body;

    if (!password) {
      return res.status(400).json({ error: 'Password required to delete account' });
    }
    if (confirmation !== 'DELETE') {
      return res.status(400).json({ error: 'Please type DELETE to confirm account deletion' });
    }

    // Get user
    const userResult = await pool.query(
      'SELECT email, password_hash, is_creator FROM users WHERE id = $1',
      [userId]
    );
    if (!userResult.rows.length) return res.status(404).json({ error: 'User not found' });

    const user = userResult.rows[0];

    // Prevent creator account deletion
    if (user.is_creator) {
      return res.status(403).json({ error: 'Creator account cannot be deleted through this flow' });
    }

    if (!user.password_hash) {
      return res.status(400).json({ error: 'No password set on this account' });
    }

    // Verify password
    const match = await bcrypt.compare(password, user.password_hash);
    if (!match) {
      return res.status(400).json({ error: 'Incorrect password' });
    }

    // Send farewell email before deletion
    try {
      await fetch('https://polsia.com/api/proxy/email/send', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${process.env.POLSIA_API_KEY}`
        },
        body: JSON.stringify({
          to: user.email,
          subject: 'Your FACTS account has been deleted',
          html: `
            <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:600px;margin:0 auto;padding:20px;">
              <h2 style="color:#f43f5e;margin-bottom:16px;">Account Deleted</h2>
              <p style="color:#333;line-height:1.6;">
                Your FACTS account and all associated data have been permanently deleted as requested.
              </p>
              <p style="color:#333;line-height:1.6;">
                If you ever want to start fresh, you're always welcome back at
                <a href="https://financial-revolution.polsia.app" style="color:#10b981;">financial-revolution.polsia.app</a>.
              </p>
              <p style="color:#666;font-size:0.875rem;margin-top:24px;">If you did not request this deletion, please contact us immediately.</p>
            </div>
          `,
          body: `Your FACTS account has been deleted. All data has been permanently erased.`,
          transactional: true
        })
      });
    } catch (emailErr) {
      console.error('[Settings] Account deletion email failed:', emailErr.message);
    }

    // Destroy session first
    req.session.destroy(() => {});

    // Delete user (cascades to related data via FK constraints)
    await pool.query('DELETE FROM users WHERE id = $1', [userId]);

    res.json({ success: true, message: 'Your account has been permanently deleted' });
  } catch (err) {
    console.error('POST /api/settings/delete-account error:', err.message);
    res.status(500).json({ error: 'Failed to delete account. Please try again.' });
  }
});

// POST /api/settings/avatar/upload — Upload profile photo (stored as data URL or R2)
// For now: accept a base64 image and store as avatar_url (small-scale approach)
// Note: For production scale, move to R2 upload
app.post('/api/settings/avatar', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { avatar_url } = req.body;

    // Accept either null (remove avatar) or a URL
    if (avatar_url !== null && avatar_url !== undefined) {
      // Basic validation: must be a URL or data URL
      const isDataUrl = typeof avatar_url === 'string' && avatar_url.startsWith('data:image/');
      const isHttpUrl = typeof avatar_url === 'string' && (avatar_url.startsWith('http://') || avatar_url.startsWith('https://'));

      if (!isDataUrl && !isHttpUrl && avatar_url !== '') {
        return res.status(400).json({ error: 'Invalid avatar URL' });
      }

      // Limit data URL size to 500KB
      if (isDataUrl && avatar_url.length > 700000) {
        return res.status(400).json({ error: 'Image too large. Please use an image under 500KB.' });
      }
    }

    await pool.query(
      'UPDATE users SET avatar_url = $1, updated_at = NOW() WHERE id = $2',
      [avatar_url || null, userId]
    );

    res.json({ success: true, avatar_url: avatar_url || null });
  } catch (err) {
    console.error('POST /api/settings/avatar error:', err.message);
    res.status(500).json({ error: 'Failed to update avatar' });
  }
});

