// POST /api/discovery-scan/complete
// Saves all 7 screens of data and marks the scan as completed.
// Accepts all fields at once (final submit) or partial saves.
// Once discovery_scan_completed = true, the affiliate gate unlocks.
app.post('/api/discovery-scan/complete', requireAuth, async (req, res) => {
  try {
    const {
      survival_runway_months,
      estimated_total_debt,   // dollars (decimal)
      monthly_burn,           // dollars (decimal)
      legacy_anchor,          // "just_me" | "children" | "family" | "charity"
      master_goal_monthly,    // dollars (decimal)
      completed               // boolean: true = mark as done
    } = req.body;

    // Convert dollar amounts → cents (integer)
    const debtCents  = estimated_total_debt  != null ? Math.round(parseFloat(estimated_total_debt)  * 100) : null;
    const burnCents  = monthly_burn          != null ? Math.round(parseFloat(monthly_burn)          * 100) : null;
    const goalCents  = master_goal_monthly   != null ? Math.round(parseFloat(master_goal_monthly)   * 100) : null;

    const familyAnchors = ['children', 'family', 'charity'];
    const familyIntent  = legacy_anchor ? familyAnchors.includes(legacy_anchor) : null;

    // Validate runway
    if (survival_runway_months != null) {
      const r = parseInt(survival_runway_months);
      if (isNaN(r) || r < 0 || r > 25) {
        return res.status(400).json({ error: 'survival_runway_months must be 0–25' });
      }
    }

    // Build dynamic SET clause — only update fields that were sent
    const updates = [];
    const values  = [];
    let   idx     = 1;

    if (survival_runway_months != null) { updates.push(`survival_runway_months = $${idx++}`);      values.push(parseInt(survival_runway_months)); }
    if (debtCents  != null)             { updates.push(`estimated_total_debt_cents = $${idx++}`);  values.push(debtCents);  }
    if (burnCents  != null)             { updates.push(`monthly_burn_cents = $${idx++}`);          values.push(burnCents);  }
    if (legacy_anchor != null)          { updates.push(`legacy_anchor = $${idx++}`);               values.push(legacy_anchor); }
    if (familyIntent != null)           { updates.push(`family_intent = $${idx++}`);               values.push(familyIntent); }
    if (goalCents  != null)             { updates.push(`master_goal_monthly_cents = $${idx++}`);   values.push(goalCents);  }

    if (completed === true) {
      updates.push(`discovery_scan_completed = $${idx++}`);  values.push(true);
      updates.push(`discovery_scan_date = $${idx++}`);       values.push(new Date().toISOString().split('T')[0]);
    }

    if (updates.length === 0) {
      return res.status(400).json({ error: 'No fields to update' });
    }

    updates.push(`updated_at = NOW()`);
    values.push(req.userId);

    await pool.query(
      `UPDATE users SET ${updates.join(', ')} WHERE id = $${idx}`,
      values
    );

    console.log(`[DiscoveryScan] user ${req.userId} saved scan data${completed ? ' (COMPLETED)' : ''}`);

    res.json({
      success: true,
      completed: completed === true
    });
  } catch (err) {
    console.error('POST /api/discovery-scan/complete error:', err.message);
    res.status(500).json({ error: 'Failed to save scan data' });
  }
});

