// ─── Helper: generate secure random token ──────────────────────────────────
function generateSuccessionToken() {
  return crypto.randomBytes(32).toString('hex');
}

// ─── GET /api/affiliate/succession ─────────────────────────────────────────
// Returns the current user's succession plan (designation) + any active transfer
app.get('/api/affiliate/succession', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    // Get affiliate record with succession plan fields
    const affResult = await pool.query(
      `SELECT a.id, a.user_id, a.status, a.referral_code,
              a.successor_name, a.successor_email, a.successor_relationship,
              a.succession_authorized_date, a.succession_signature_data, a.successor_id,
              u2.email AS successor_user_email, u2.name AS successor_user_name
         FROM affiliates a
         LEFT JOIN users u2 ON u2.id = a.successor_id
        WHERE a.user_id = $1`,
      [userId]
    );

    if (!affResult.rows.length) {
      return res.status(404).json({ error: 'Not an affiliate' });
    }

    const aff = affResult.rows[0];

    // Get any pending/active transfer
    const transferResult = await pool.query(
      `SELECT st.*, u_succ.email AS successor_user_email, u_admin.email AS admin_email
         FROM succession_transfers st
         LEFT JOIN users u_succ ON u_succ.id = st.successor_id
         LEFT JOIN users u_admin ON u_admin.id = st.admin_id
        WHERE st.affiliate_id = $1
          AND st.status NOT IN ('rejected','cancelled')
        ORDER BY st.created_at DESC
        LIMIT 1`,
      [aff.id]
    );

    res.json({
      success: true,
      succession_plan: {
        successor_name: aff.successor_name,
        successor_email: aff.successor_email,
        successor_relationship: aff.successor_relationship,
        succession_authorized_date: aff.succession_authorized_date,
        successor_id: aff.successor_id,
        successor_user_email: aff.successor_user_email,
        successor_user_name: aff.successor_user_name,
        is_designated: !!(aff.successor_email)
      },
      active_transfer: transferResult.rows[0] || null
    });
  } catch (err) {
    console.error('[Succession] GET /api/affiliate/succession error:', err.message);
    res.status(500).json({ error: 'Failed to load succession plan' });
  }
});

// ─── POST /api/affiliate/succession ────────────────────────────────────────
// Save / update the succession designation (the account holder signs here)
app.post('/api/affiliate/succession', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { successor_name, successor_email, successor_relationship, signature } = req.body;

    if (!successor_email || !successor_name || !successor_relationship || !signature) {
      return res.status(400).json({ error: 'successor_name, successor_email, successor_relationship, and signature are required' });
    }

    const validRelationships = ['child','grandchild','spouse','sibling','trust','other'];
    if (!validRelationships.includes(successor_relationship)) {
      return res.status(400).json({ error: 'Invalid relationship. Must be one of: ' + validRelationships.join(', ') });
    }

    // Verify caller is an affiliate
    const affResult = await pool.query(
      `SELECT id FROM affiliates WHERE user_id = $1`,
      [userId]
    );
    if (!affResult.rows.length) {
      return res.status(404).json({ error: 'You must be an affiliate to designate a successor' });
    }

    // Try to find the successor by email (they may not have an account yet)
    const successorUserResult = await pool.query(
      `SELECT id FROM users WHERE LOWER(email) = LOWER($1)`,
      [successor_email]
    );
    const successorUserId = successorUserResult.rows[0]?.id || null;

    // Save the designation
    await pool.query(
      `UPDATE affiliates SET
        successor_name = $1,
        successor_email = $2,
        successor_relationship = $3,
        succession_authorized_date = NOW(),
        succession_signature_data = $4,
        successor_id = $5,
        updated_at = NOW()
       WHERE user_id = $6`,
      [successor_name, successor_email, successor_relationship, signature, successorUserId, userId]
    );

    res.json({
      success: true,
      message: 'Succession plan saved. Your designated successor has been recorded.',
      successor_found_in_system: !!successorUserId
    });
  } catch (err) {
    console.error('[Succession] POST /api/affiliate/succession error:', err.message);
    res.status(500).json({ error: 'Failed to save succession plan' });
  }
});

// ─── POST /api/affiliate/succession/initiate-transfer ──────────────────────
// Account holder initiates a voluntary transfer (creates a succession_transfer record)
app.post('/api/affiliate/succession/initiate-transfer', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { signature } = req.body;

    if (!signature) return res.status(400).json({ error: 'Digital signature is required to initiate transfer' });

    // Verify caller is active affiliate with a succession plan
    const affResult = await pool.query(
      `SELECT id, successor_email, successor_name, successor_relationship, successor_id, status
         FROM affiliates
        WHERE user_id = $1`,
      [userId]
    );
    if (!affResult.rows.length) return res.status(404).json({ error: 'Not an affiliate' });

    const aff = affResult.rows[0];
    if (!aff.successor_email) {
      return res.status(400).json({ error: 'No successor designated. Please save your succession plan first.' });
    }

    // Check no active transfer already pending
    const existingResult = await pool.query(
      `SELECT id, status FROM succession_transfers
        WHERE affiliate_id = $1 AND status IN ('pending_successor_signature','pending_admin_approval')
        LIMIT 1`,
      [aff.id]
    );
    if (existingResult.rows.length) {
      return res.status(409).json({ error: 'A transfer request is already in progress.', status: existingResult.rows[0].status });
    }

    // Generate successor sign token
    const signToken = generateSuccessionToken();
    const tokenExpiry = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

    // Create the transfer record
    const insertResult = await pool.query(
      `INSERT INTO succession_transfers (
        affiliate_id, transfer_type, status,
        successor_id, successor_email, successor_name, successor_relationship,
        transferor_signed_at, transferor_signature,
        successor_sign_token, successor_sign_token_expires,
        created_at, updated_at
       ) VALUES ($1, 'voluntary', 'pending_successor_signature',
                 $2, $3, $4, $5,
                 NOW(), $6,
                 $7, $8,
                 NOW(), NOW())
       RETURNING id`,
      [
        aff.id,
        aff.successor_id, aff.successor_email, aff.successor_name, aff.successor_relationship,
        signature,
        signToken, tokenExpiry
      ]
    );

    const transferId = insertResult.rows[0].id;

    // Generate the sign URL for the successor
    const baseUrl = process.env.APP_URL || 'https://financial-revolution.polsia.app';
    const signUrl = `${baseUrl}/succession-sign?token=${signToken}`;

    console.log(`[Succession] Transfer #${transferId} initiated by user ${userId}. Successor sign URL: ${signUrl}`);

    res.json({
      success: true,
      message: 'Voluntary transfer initiated. Your successor must sign to proceed.',
      transfer_id: transferId,
      successor_sign_url: signUrl,
      token_expires: tokenExpiry.toISOString()
    });
  } catch (err) {
    console.error('[Succession] POST /api/affiliate/succession/initiate-transfer error:', err.message);
    res.status(500).json({ error: 'Failed to initiate transfer' });
  }
});

