// ─── GET /api/succession/sign/:token ───────────────────────────────────────
// Get transfer details for the sign page (public, no auth)
app.get('/api/succession/sign/:token', async (req, res) => {
  try {
    const { token } = req.params;

    const result = await pool.query(
      `SELECT st.id, st.status, st.successor_email, st.successor_name, st.successor_relationship,
              st.transfer_type, st.transferor_signed_at, st.successor_sign_token_expires,
              a.referral_code, u_orig.name AS original_holder_name, u_orig.email AS original_holder_email
         FROM succession_transfers st
         JOIN affiliates a ON a.id = st.affiliate_id
         JOIN users u_orig ON u_orig.id = a.user_id
        WHERE st.successor_sign_token = $1`,
      [token]
    );

    if (!result.rows.length) return res.status(404).json({ error: 'Invalid or expired sign link' });

    const transfer = result.rows[0];

    if (transfer.status !== 'pending_successor_signature') {
      return res.json({ success: true, transfer, already_signed: true });
    }

    if (new Date(transfer.successor_sign_token_expires) < new Date()) {
      return res.status(410).json({ error: 'This sign link has expired. Ask the transfer initiator to resend.' });
    }

    res.json({ success: true, transfer, already_signed: false });
  } catch (err) {
    console.error('[Succession] GET /api/succession/sign/:token error:', err.message);
    res.status(500).json({ error: 'Failed to load transfer' });
  }
});

// ─── POST /api/succession/sign/:token ──────────────────────────────────────
// Successor signs the transfer (public, no auth — verified by token)
app.post('/api/succession/sign/:token', async (req, res) => {
  try {
    const { token } = req.params;
    const { signature } = req.body;

    if (!signature) return res.status(400).json({ error: 'Signature is required' });

    // Find the transfer
    const result = await pool.query(
      `SELECT id, status, successor_sign_token_expires, affiliate_id
         FROM succession_transfers
        WHERE successor_sign_token = $1`,
      [token]
    );

    if (!result.rows.length) return res.status(404).json({ error: 'Invalid or expired sign link' });

    const transfer = result.rows[0];

    if (transfer.status !== 'pending_successor_signature') {
      return res.status(409).json({ error: 'This transfer has already been signed or processed' });
    }

    if (new Date(transfer.successor_sign_token_expires) < new Date()) {
      return res.status(410).json({ error: 'This sign link has expired' });
    }

    // Try to find successor's user account
    const affiliateResult = await pool.query(
      `SELECT successor_email, successor_id FROM affiliates
        WHERE id = $1`, [transfer.affiliate_id]
    );
    const succEmail = affiliateResult.rows[0]?.successor_email;
    const succUserResult = succEmail
      ? await pool.query(`SELECT id FROM users WHERE LOWER(email) = LOWER($1)`, [succEmail])
      : { rows: [] };
    const successorUserId = succUserResult.rows[0]?.id || null;

    // Record successor signature → move to pending_admin_approval
    await pool.query(
      `UPDATE succession_transfers SET
        successor_signed_at = NOW(),
        successor_signature = $1,
        successor_id = COALESCE(successor_id, $2),
        status = 'pending_admin_approval',
        updated_at = NOW()
       WHERE id = $3`,
      [signature, successorUserId, transfer.id]
    );

    res.json({
      success: true,
      message: 'Thank you for signing. This transfer is now pending corporate approval.'
    });
  } catch (err) {
    console.error('[Succession] POST /api/succession/sign/:token error:', err.message);
    res.status(500).json({ error: 'Failed to record signature' });
  }
});

