// GET /api/affiliate/graduation-check
// Returns whether the graduation modal should be shown for the current user.
// Conditions: Pro subscriber + FACTS certified + not already affiliate + not already chose retail
app.get('/api/affiliate/graduation-check', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    const userRes = await pool.query(
      `SELECT plan, paid_until, is_creator,
              is_facts_certified, sovereign_oath_signed,
              retail_choice_logged, retail_choice_logged_at,
              graduation_modal_shown
         FROM users WHERE id = $1`,
      [userId]
    );

    if (!userRes.rows.length) {
      return res.status(404).json({ error: 'User not found' });
    }

    const user = userRes.rows[0];

    // Admin / creator cannot participate in income-generating programs
    if (isAdminIncomeBlockedUser(user)) {
      return res.json({ should_show: false, reason: 'admin_income_blocked' });
    }

    // Must be a paid Pro subscriber
    const isPro = await hasProAccess(userId);
    if (!isPro) {
      return res.json({ should_show: false, reason: 'not_pro' });
    }

    // Must have completed FACTS Certification
    if (!user.is_facts_certified) {
      return res.json({ should_show: false, reason: 'not_certified',
                        is_certified: false });
    }

    // Check if already an affiliate
    const affiliateRes = await pool.query(
      'SELECT id, status, referral_code FROM affiliates WHERE user_id = $1',
      [userId]
    );
    const isAffiliate = affiliateRes.rows.length > 0;
    if (isAffiliate) {
      return res.json({
        should_show: false,
        reason: 'already_affiliate',
        is_certified: true,
        is_affiliate: true,
        referral_code: affiliateRes.rows[0].referral_code
      });
    }

    // Already explicitly chose retail — don't show again (they can unlock via settings)
    if (user.retail_choice_logged) {
      return res.json({
        should_show: false,
        reason: 'chose_retail',
        is_certified: true,
        is_affiliate: false,
        chose_retail: true,
        retail_choice_logged_at: user.retail_choice_logged_at
      });
    }

    // Show the graduation screen
    res.json({
      should_show: true,
      is_certified: true,
      is_affiliate: false,
      chose_retail: false,
      sovereign_oath_signed: user.sovereign_oath_signed || false,
      graduation_modal_shown: user.graduation_modal_shown || false
    });
  } catch (err) {
    console.error('[Graduation] GET /api/affiliate/graduation-check error:', err.message);
    res.status(500).json({ error: 'Failed to check graduation status' });
  }
});

