// POST /api/affiliate/sign-oath
// Signs the Sovereign Oath — a prerequisite for activating affiliate status.
// Records signature with timestamp and IP for audit trail.
app.post('/api/affiliate/sign-oath', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { signature_name } = req.body;

    if (!signature_name || signature_name.trim().length < 2) {
      return res.status(400).json({ error: 'A valid signature name is required to sign the Sovereign Oath.' });
    }

    // Check user exists and isn't creator
    const userRes = await pool.query(
      'SELECT id, is_creator, sovereign_oath_signed FROM users WHERE id = $1',
      [userId]
    );
    if (!userRes.rows.length) return res.status(404).json({ error: 'User not found' });
    if (userRes.rows[0].is_creator) return res.status(403).json({ error: 'Account not eligible.' });

    // Idempotent — already signed is fine
    if (userRes.rows[0].sovereign_oath_signed) {
      return res.json({ success: true, already_signed: true });
    }

    await pool.query(
      `UPDATE users
          SET sovereign_oath_signed = TRUE,
              sovereign_oath_signed_at = NOW()
        WHERE id = $1`,
      [userId]
    );

    const ip = req.headers['x-forwarded-for']?.split(',')[0]?.trim() || req.socket?.remoteAddress;
    console.log(`[Sovereign Oath] User ${userId} signed oath as "${signature_name.trim()}" from ${ip} at ${new Date().toISOString()}`);

    res.json({ success: true, signed_at: new Date().toISOString() });
  } catch (err) {
    console.error('[Graduation] POST /api/affiliate/sign-oath error:', err.message);
    res.status(500).json({ error: 'Failed to sign oath' });
  }
});

// POST /api/affiliate/graduate
// Full graduation flow: sign oath (if not already) + create affiliate record.
// Returns the referral link immediately after completion.
app.post('/api/affiliate/graduate', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { signature_name } = req.body;

    if (!signature_name || signature_name.trim().length < 2) {
      return res.status(400).json({ error: 'A valid signature name is required to sign the Sovereign Oath.' });
    }

    // Load user details
    const userRes = await pool.query(
      `SELECT id, email, name, plan, paid_until, is_creator,
              is_facts_certified, sovereign_oath_signed
         FROM users WHERE id = $1`,
      [userId]
    );
    if (!userRes.rows.length) return res.status(404).json({ error: 'User not found' });

    const user = userRes.rows[0];

    if (user.is_creator) {
      return res.status(403).json({ error: 'This account is not eligible to join Future Generations.' });
    }

    // Must be Pro
    const isPro = await hasProAccess(userId);
    if (!isPro) {
      return res.status(403).json({ error: 'Only active paid subscribers can unlock Future Generations affiliate status.' });
    }

    // Must be FACTS certified
    if (!user.is_facts_certified) {
      return res.status(403).json({ error: 'FACTS Certification must be complete before unlocking affiliate status.' });
    }

    // Check if already an affiliate
    const existingAffiliate = await pool.query(
      'SELECT * FROM affiliates WHERE user_id = $1',
      [userId]
    );
    if (existingAffiliate.rows.length > 0) {
      const aff = existingAffiliate.rows[0];
      const appUrl = process.env.APP_URL || 'https://financial-revolution.polsia.app';
      return res.json({
        success: true,
        already_affiliate: true,
        referral_code: aff.referral_code,
        referral_link: `${appUrl}/signup?ref=${aff.referral_code}`,
        affiliate_status: aff.status
      });
    }

    // Step 1: Sign the Sovereign Oath (idempotent)
    if (!user.sovereign_oath_signed) {
      await pool.query(
        `UPDATE users
            SET sovereign_oath_signed = TRUE,
                sovereign_oath_signed_at = NOW()
          WHERE id = $1`,
        [userId]
      );
      const ip = req.headers['x-forwarded-for']?.split(',')[0]?.trim() || req.socket?.remoteAddress;
      console.log(`[Sovereign Oath] User ${userId} signed oath as "${signature_name.trim()}" from ${ip} at ${new Date().toISOString()}`);
    }

    // Step 2: Clear any prior retail_choice flag (they changed their mind)
    await pool.query(
      `UPDATE users SET retail_choice_logged = FALSE, retail_choice_logged_at = NULL WHERE id = $1`,
      [userId]
    );

    // Step 3: Generate unique referral code
    let referralCode;
    let attempts = 0;
    while (attempts < 10) {
      referralCode = generateReferralCode(user.email);
      const codeCheck = await pool.query('SELECT id FROM affiliates WHERE referral_code = $1', [referralCode]);
      if (codeCheck.rows.length === 0) break;
      attempts++;
    }

    // Step 4: Determine tree placement
    const placement = await determineAffiliatePlacement(userId);

    // Step 5: Create affiliate record with status = active
    const result = await pool.query(
      `INSERT INTO affiliates (user_id, email, referral_code, status, good_standing_started_at,
                               parent_affiliate_id, affiliate_level, placement_method)
       VALUES ($1, $2, $3, 'active', NOW(), $4, $5, $6) RETURNING *`,
      [userId, user.email.toLowerCase(), referralCode,
       placement.parentAffiliateId, placement.affiliateLevel, placement.placementMethod]
    );

    // Step 6: Sync referred_by_user_id for commission chain
    if (placement.parentUserId) {
      await pool.query(
        `UPDATE users SET referred_by_user_id = $1 WHERE id = $2 AND referred_by_user_id IS NULL`,
        [placement.parentUserId, userId]
      );
    }

    const aff = result.rows[0];
    const appUrl = process.env.APP_URL || 'https://financial-revolution.polsia.app';
    const referralLink = `${appUrl}/signup?ref=${referralCode}`;

    console.log(`[Graduation] User ${userId} graduated to affiliate. Code: ${referralCode}, Level: ${placement.affiliateLevel}`);

    res.json({
      success: true,
      message: 'Welcome to Future Generations! Your affiliate link is active.',
      referral_code: referralCode,
      referral_link: referralLink,
      affiliate_status: 'active',
      affiliate_activation_date: new Date().toISOString(),
      affiliate_level: placement.affiliateLevel,
      orphan_eligible: true // First orphan is available on join
    });
  } catch (err) {
    console.error('[Graduation] POST /api/affiliate/graduate error:', err.message);
    res.status(500).json({ error: 'Failed to complete graduation' });
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// ─── CERTIFICATION GATE ──────────────────────────────────────────────────────
// Controls access to the Future Generations referral link.
// All 5 conditions must be met before the referral link is revealed.
//
//   1. Active Pro subscription         (hasProAccess)
//   2. Discovery Scan completed        (users.discovery_scan_completed)
//   3. Bank account linked via Plaid   (plaid_accounts count > 0, cached in users.bank_linked)
//   4. Credit profile uploaded         (users.credit_report_uploaded)
//   5. Sovereign Oath signed           (users.sovereign_oath_signed)
//
// AI Sweep: once bank is linked, scan plaid_transactions for outgoing payments
// to financial institutions not covered by a linked plaid_account.
// ─────────────────────────────────────────────────────────────────────────────

// Known financial institution keywords for AI Sweep transaction matching
const FINANCIAL_INSTITUTION_KEYWORDS = [
  'chase', 'wells fargo', 'bank of america', 'citibank', 'citi ', 'us bank',
  'pnc bank', 'capital one', 'td bank', 'truist', 'regions bank', 'suntrust',
  'fifth third', 'citizens bank', 'huntington', 'keybank', 'ally bank',
  'discover bank', 'synchrony', 'american express', 'amex', 'barclays',
  'vanguard', 'fidelity', 'schwab', 'merrill', 'edward jones', 'td ameritrade',
  'e*trade', 'etrade', 'robinhood', 'betterment', 'wealthfront', 'sofi',
  'navient', 'sallie mae', 'nelnet', 'mohela', 'aidvantage', 'fedloan',
  'great lakes', 'cornerstone', 'granite state', 'aspire', 'uheaa',
  'usaa', 'navy federal', 'pentagon federal', 'penfed', 'alliant',
  'affirm', 'afterpay', 'klarna', 'sezzle', 'uplift', 'bread financial',
  'paypal credit', 'marcus', 'goldman sachs', 'credit acceptance',
  'carmax auto', 'carvana', 'loan payment', 'mortgage payment', 'home loan',
  'car payment', 'auto loan', 'student loan', 'credit card payment'
];

/**
 * Run the AI Sweep for a user.
 * Looks at outgoing Plaid transactions and flags institutions found in transaction
 * names/merchant_names that are NOT already linked as plaid_accounts.
 * Returns array of { institution, transaction_id, amount, date, name }
 */
async function runCertificationAISweep(userId) {
  try {
    // Get linked Plaid institution names for this user (already declared)
    const linkedRes = await pool.query(
      `SELECT DISTINCT LOWER(institution_name) AS inst
         FROM plaid_accounts
        WHERE user_id = $1 AND institution_name IS NOT NULL`,
      [userId]
    );
    const linkedInstitutions = new Set(linkedRes.rows.map(r => r.inst));

    // Get recent outgoing transactions (last 90 days, negative amount = outgoing in Plaid)
    const txnRes = await pool.query(
      `SELECT plaid_transaction_id, name, merchant_name, amount, date
         FROM plaid_transactions
        WHERE user_id = $1
          AND amount > 0
          AND date >= NOW() - INTERVAL '90 days'
        ORDER BY date DESC
        LIMIT 500`,
      [userId]
    );

    const flagged = [];
    const seenInstitutions = new Set();

    for (const txn of txnRes.rows) {
      const txnName = (txn.name || '').toLowerCase();
      const merchantName = (txn.merchant_name || '').toLowerCase();
      const combined = txnName + ' ' + merchantName;

      for (const keyword of FINANCIAL_INSTITUTION_KEYWORDS) {
        if (combined.includes(keyword)) {
          // Check if this institution is already linked
          let isLinked = false;
          for (const linkedInst of linkedInstitutions) {
            if (linkedInst.includes(keyword) || keyword.includes(linkedInst)) {
              isLinked = true;
              break;
            }
          }

          if (!isLinked && !seenInstitutions.has(keyword)) {
            seenInstitutions.add(keyword);
            // Canonicalize institution name from the transaction
            const displayName = txn.merchant_name || txn.name;
            flagged.push({
              institution: displayName,
              keyword: keyword,
              amount: txn.amount,
              date: txn.date,
              transaction_name: txn.name
            });
          }
          break; // Don't double-flag same transaction
        }
      }
    }

    return flagged;
  } catch (err) {
    console.error('[Certification] AI Sweep error:', err.message);
    return []; // Non-fatal — sweep failure doesn't block certification
  }
}

// GET /api/certification/status
// Returns the full certification gate state for the authenticated user.
app.get('/api/certification/status', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;

    const userRes = await pool.query(
      `SELECT id, plan, paid_until, is_creator,
              discovery_scan_completed,
              bank_linked, credit_report_uploaded,
              sovereign_oath_signed,
              certification_status, certification_date,
              is_facts_certified, flagged_institutions
         FROM users WHERE id = $1`,
      [userId]
    );

    if (!userRes.rows.length) {
      return res.status(404).json({ error: 'User not found' });
    }

    const user = userRes.rows[0];

    // ── Gate 1: Pro subscription ──
    const isPro = await hasProAccess(userId);

    // ── Gate 2: Discovery Scan ──
    const discoveryDone = user.discovery_scan_completed === true;

    // ── Gate 3: Bank Linked (Plaid) ──
    const plaidRes = await pool.query(
      'SELECT COUNT(*) AS cnt FROM plaid_accounts WHERE user_id = $1',
      [userId]
    );
    const bankLinked = parseInt(plaidRes.rows[0].cnt) > 0;

    // Sync bank_linked field if it changed
    if (bankLinked !== user.bank_linked) {
      await pool.query('UPDATE users SET bank_linked = $1 WHERE id = $2', [bankLinked, userId]);
    }

    // ── Gate 4: Credit Report Uploaded ──
    const creditReportUploaded = user.credit_report_uploaded === true;

    // ── Gate 5: Sovereign Oath Signed ──
    const oathSigned = user.sovereign_oath_signed === true;

    // ── AI Sweep (only if bank is linked) ──
    let sweepAlerts = [];
    let currentFlagged = user.flagged_institutions || [];

    if (bankLinked) {
      sweepAlerts = await runCertificationAISweep(userId);
      // Only keep alerts that haven't been acknowledged yet
      const acknowledgedNames = new Set(
        currentFlagged.filter(f => f.acknowledged).map(f => f.institution?.toLowerCase())
      );
      sweepAlerts = sweepAlerts.filter(
        a => !acknowledgedNames.has((a.institution || '').toLowerCase())
      );
    }

    // ── Compute certification gate ──
    const allGatesMet = isPro && discoveryDone && bankLinked && creditReportUploaded && oathSigned && sweepAlerts.length === 0;

    let certStatus = user.certification_status || 'incomplete';

    if (allGatesMet && certStatus !== 'certified') {
      // Promote to certified!
      certStatus = 'certified';
      await pool.query(
        `UPDATE users
            SET certification_status = 'certified',
                certification_date    = NOW(),
                is_facts_certified    = TRUE
          WHERE id = $1`,
        [userId]
      );
      console.log(`[Certification] User ${userId} earned Sovereign Certification`);
    } else if (!allGatesMet && certStatus === 'certified') {
      // Lost certification (e.g., subscription lapsed) — downgrade gracefully
      certStatus = 'incomplete';
      await pool.query(
        `UPDATE users
            SET certification_status = 'incomplete',
                is_facts_certified    = FALSE
          WHERE id = $1`,
        [userId]
      );
      console.log(`[Certification] User ${userId} lost Sovereign Certification — gate condition no longer met`);
    }

    res.json({
      success: true,
      certification: {
        status: certStatus,
        certificationDate: user.certification_date,
        isCertified: certStatus === 'certified',
        gates: {
          isPro,
          discoveryDone,
          bankLinked,
          creditReportUploaded,
          oathSigned
        },
        sweepAlerts,       // New undeclared institutions found
        pendingSweepCount: sweepAlerts.length,
        allGatesMet
      }
    });
  } catch (err) {
    console.error('[Certification] GET /api/certification/status error:', err.message);
    res.status(500).json({ error: 'Failed to load certification status' });
  }
});

// POST /api/certification/upload-credit-report
// Marks the credit profile as uploaded/acknowledged by the user.
// Accepts either a PDF upload marker or a manual debt acknowledgment.
app.post('/api/certification/upload-credit-report', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { method } = req.body; // 'pdf_upload' | 'manual_entry'

    await pool.query(
      `UPDATE users SET credit_report_uploaded = TRUE WHERE id = $1`,
      [userId]
    );

    console.log(`[Certification] User ${userId} completed credit profile (method: ${method || 'not specified'})`);

    res.json({
      success: true,
      message: 'Credit profile recorded. This gate is now complete.',
      credit_report_uploaded: true
    });
  } catch (err) {
    console.error('[Certification] POST /api/certification/upload-credit-report error:', err.message);
    res.status(500).json({ error: 'Failed to update credit report status' });
  }
});

// POST /api/certification/acknowledge-sweep
// User acknowledges flagged institutions from the AI Sweep.
// They confirm the institution is closed/inactive or link it via Plaid.
app.post('/api/certification/acknowledge-sweep', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { institutionName, action } = req.body; // action: 'acknowledge' | 'will_link'

    if (!institutionName) {
      return res.status(400).json({ error: 'institutionName is required' });
    }

    // Load existing flagged list
    const userRes = await pool.query(
      'SELECT flagged_institutions FROM users WHERE id = $1',
      [userId]
    );
    const currentFlagged = userRes.rows[0]?.flagged_institutions || [];

    // Find or create entry for this institution
    const existing = currentFlagged.find(
      f => (f.institution || '').toLowerCase() === institutionName.toLowerCase()
    );

    if (existing) {
      existing.acknowledged = true;
      existing.acknowledgedAt = new Date().toISOString();
      existing.action = action || 'acknowledge';
    } else {
      currentFlagged.push({
        institution: institutionName,
        acknowledged: true,
        acknowledgedAt: new Date().toISOString(),
        action: action || 'acknowledge'
      });
    }

    await pool.query(
      'UPDATE users SET flagged_institutions = $1 WHERE id = $2',
      [JSON.stringify(currentFlagged), userId]
    );

    console.log(`[Certification] User ${userId} acknowledged institution: ${institutionName} (action: ${action})`);

    res.json({
      success: true,
      message: `"${institutionName}" has been acknowledged.`,
      acknowledged: true
    });
  } catch (err) {
    console.error('[Certification] POST /api/certification/acknowledge-sweep error:', err.message);
    res.status(500).json({ error: 'Failed to acknowledge institution' });
  }
});

