// ─────────────────────────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
// ─── FINANCIAL RESPONSIBILITY SCORECARD ───────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════

/**
 * Calculate the Financial Responsibility Scorecard for a given user.
 * Returns metrics (percentages only by default, dollar amounts optional).
 */
async function calculateScorecard(userId, showDollarAmounts = false) {
  const now = new Date();
  const ninetyDaysAgo = new Date(now - 90 * 24 * 60 * 60 * 1000);
  const twelveMonthsAgo = new Date(now - 365 * 24 * 60 * 60 * 1000);

  // ── 1. Allocation Adherence ────────────────────────────────────────────────
  // Compare actual spending distribution vs target allocations (last 90 days)
  let allocationScore = 50;
  let allocationData = { target: {}, actual: {}, deviation: 0 };
  try {
    const [allocRows, catRows, txRows] = await Promise.all([
      pool.query('SELECT ua.percentage, c.slug, c.name FROM user_allocations ua JOIN categories c ON c.id = ua.category_id WHERE ua.user_id = $1', [userId]),
      pool.query('SELECT id, slug, name FROM categories ORDER BY sort_order'),
      pool.query(`SELECT category_id, SUM(amount) as total FROM transactions WHERE user_id = $1 AND transaction_date >= $2 AND type != 'income' GROUP BY category_id`, [userId, ninetyDaysAgo])
    ]);

    const targets = {};
    for (const row of allocRows.rows) { targets[row.slug] = parseFloat(row.percentage); }

    const spendingByCategory = {};
    let totalSpend = 0;
    for (const row of txRows.rows) {
      spendingByCategory[row.category_id] = parseFloat(row.total);
      totalSpend += parseFloat(row.total);
    }

    if (totalSpend > 0) {
      const catMap = {};
      for (const c of catRows.rows) { catMap[c.id] = c.slug; }

      const actualPct = {};
      for (const [catId, amount] of Object.entries(spendingByCategory)) {
        const slug = catMap[catId];
        if (slug) actualPct[slug] = (amount / totalSpend) * 100;
      }

      let totalDeviation = 0;
      let categoryCount = 0;
      for (const [slug, targetPct] of Object.entries(targets)) {
        const actualP = actualPct[slug] || 0;
        totalDeviation += Math.abs(targetPct - actualP);
        categoryCount++;
        allocationData.target[slug] = parseFloat(targetPct.toFixed(1));
        allocationData.actual[slug] = parseFloat((actualP).toFixed(1));
      }

      const avgDeviation = categoryCount > 0 ? totalDeviation / categoryCount : 0;
      allocationScore = Math.max(0, Math.round(100 - avgDeviation * 2.5));
      allocationData.deviation = parseFloat(avgDeviation.toFixed(1));
      allocationData.total_tracked_90d = showDollarAmounts ? parseFloat(totalSpend.toFixed(2)) : null;
    } else {
      allocationData.note = 'No expense transactions in last 90 days';
    }
  } catch (e) { console.error('[Scorecard] allocationScore error:', e.message); }

  // ── 2. Savings Consistency ─────────────────────────────────────────────────
  // % of months in past 12 months where Save category has transactions
  let savingsScore = 0;
  let savingsData = { months_with_savings: 0, total_months: 12, trend: 'flat', monthly_data: [] };
  try {
    const saveCategory = (await pool.query("SELECT id FROM categories WHERE slug IN ('reserve','save') LIMIT 1")).rows[0];
    if (saveCategory) {
      const saveTxRows = await pool.query(`
        SELECT DATE_TRUNC('month', transaction_date) as month,
               COUNT(*) as tx_count,
               SUM(amount) as total
        FROM transactions
        WHERE user_id = $1
          AND category_id = $2
          AND transaction_date >= $3
          AND type != 'income'
        GROUP BY DATE_TRUNC('month', transaction_date)
        ORDER BY month ASC
      `, [userId, saveCategory.id, twelveMonthsAgo]);

      savingsData.months_with_savings = saveTxRows.rows.length;
      savingsScore = Math.round((saveTxRows.rows.length / 12) * 100);

      // Trend: compare last 3 months vs 3 months before
      const recent = saveTxRows.rows.filter(r => new Date(r.month) >= new Date(now - 90 * 24 * 60 * 60 * 1000));
      const older = saveTxRows.rows.filter(r => {
        const d = new Date(r.month);
        return d >= new Date(now - 180 * 24 * 60 * 60 * 1000) && d < new Date(now - 90 * 24 * 60 * 60 * 1000);
      });
      if (recent.length > older.length) savingsData.trend = 'improving';
      else if (recent.length < older.length) savingsData.trend = 'declining';

      savingsData.monthly_data = saveTxRows.rows.map(r => ({
        month: r.month,
        count: parseInt(r.tx_count),
        amount: showDollarAmounts ? parseFloat(parseFloat(r.total).toFixed(2)) : null,
        pct_of_income: null // will be set below
      }));
    }
  } catch (e) { console.error('[Scorecard] savingsScore error:', e.message); }

  // ── 3. Debt Reduction Progress ─────────────────────────────────────────────
  let debtScore = 100;
  let debtData = { has_debt: false, debt_count: 0, strategy: null, trajectory: 'none' };
  try {
    const debtRows = await pool.query('SELECT id, name, balance, minimum_payment, current_payment, interest_rate FROM debts WHERE user_id = $1', [userId]);
    if (debtRows.rows.length > 0) {
      debtData.has_debt = true;
      debtData.debt_count = debtRows.rows.length;
      const totalBalance = debtRows.rows.reduce((s, d) => s + parseFloat(d.balance || 0), 0);
      const totalMinPayment = debtRows.rows.reduce((s, d) => s + parseFloat(d.minimum_payment || 0), 0);
      const totalCurrentPayment = debtRows.rows.reduce((s, d) => s + parseFloat(d.current_payment || d.minimum_payment || 0), 0);

      // Score: are they paying more than minimum? How many debts?
      const paymentRatio = totalMinPayment > 0 ? totalCurrentPayment / totalMinPayment : 1;
      debtScore = Math.round(Math.min(90, paymentRatio * 50)); // max 90 when have debt

      if (totalBalance > 0 && totalCurrentPayment > totalMinPayment) {
        debtData.trajectory = 'accelerated_payoff';
        debtScore = Math.min(90, debtScore + 20);
      } else if (totalCurrentPayment >= totalMinPayment) {
        debtData.trajectory = 'on_track';
      } else {
        debtData.trajectory = 'behind';
        debtScore = Math.max(10, debtScore - 20);
      }

      debtData.total_balance = showDollarAmounts ? parseFloat(totalBalance.toFixed(2)) : null;
      debtData.total_monthly_payment = showDollarAmounts ? parseFloat(totalCurrentPayment.toFixed(2)) : null;

      // Determine strategy from payment sizes (highest interest first = avalanche)
      const sortedByRate = [...debtRows.rows].sort((a, b) => parseFloat(b.interest_rate) - parseFloat(a.interest_rate));
      const sortedByBalance = [...debtRows.rows].sort((a, b) => parseFloat(a.balance) - parseFloat(b.balance));
      if (sortedByBalance[0]?.current_payment > sortedByBalance[0]?.minimum_payment) {
        debtData.strategy = 'snowball';
      } else if (sortedByRate[0]?.current_payment > sortedByRate[0]?.minimum_payment) {
        debtData.strategy = 'avalanche';
      } else {
        debtData.strategy = 'minimum_payments';
      }
    }
  } catch (e) { console.error('[Scorecard] debtScore error:', e.message); }

  // ── 4. Income vs Expense Ratio ─────────────────────────────────────────────
  let incomeExpenseScore = 50;
  let incomeExpenseData = { months_living_within_means: 0, total_months_tracked: 0, avg_ratio: null };
  try {
    const monthlyFlow = await pool.query(`
      SELECT
        DATE_TRUNC('month', transaction_date) as month,
        SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END) as income,
        SUM(CASE WHEN type != 'income' THEN amount ELSE 0 END) as expenses
      FROM transactions
      WHERE user_id = $1 AND transaction_date >= $2
      GROUP BY DATE_TRUNC('month', transaction_date)
      ORDER BY month ASC
    `, [userId, twelveMonthsAgo]);

    if (monthlyFlow.rows.length > 0) {
      let monthsWithinMeans = 0;
      let totalRatio = 0;
      let validMonths = 0;

      for (const row of monthlyFlow.rows) {
        const income = parseFloat(row.income || 0);
        const expenses = parseFloat(row.expenses || 0);
        if (income > 0) {
          if (expenses <= income) monthsWithinMeans++;
          totalRatio += income > 0 ? (expenses / income) : 1;
          validMonths++;
        }
      }

      incomeExpenseData.months_living_within_means = monthsWithinMeans;
      incomeExpenseData.total_months_tracked = monthlyFlow.rows.length;
      if (validMonths > 0) {
        const avgRatio = totalRatio / validMonths;
        incomeExpenseData.avg_expense_to_income_pct = parseFloat((avgRatio * 100).toFixed(1));
        // Score: 100 if avg ratio < 0.8, scale down to 0 at ratio >= 1.3
        incomeExpenseScore = Math.max(0, Math.min(100, Math.round((1.3 - avgRatio) / 0.5 * 100)));
      }
    }
  } catch (e) { console.error('[Scorecard] incomeExpenseScore error:', e.message); }

  // ── 5. Financial Freedom Progress ─────────────────────────────────────────
  let ffScore = 0;
  let ffData = { has_ff_activity: false, trend: 'none', months_active: 0 };
  try {
    const ffCategory = (await pool.query("SELECT id FROM categories WHERE slug IN ('growth','ff','financial-freedom','financial_freedom') OR name ILIKE '%financial freedom%' LIMIT 1")).rows[0];
    if (ffCategory) {
      const ffRows = await pool.query(`
        SELECT DATE_TRUNC('month', transaction_date) as month,
               SUM(amount) as total
        FROM transactions
        WHERE user_id = $1 AND category_id = $2 AND transaction_date >= $3
        GROUP BY DATE_TRUNC('month', transaction_date)
        ORDER BY month ASC
      `, [userId, ffCategory.id, twelveMonthsAgo]);

      if (ffRows.rows.length > 0) {
        ffData.has_ff_activity = true;
        ffData.months_active = ffRows.rows.length;
        ffScore = Math.round((ffRows.rows.length / 12) * 80); // up to 80 for just activity

        // Trend check
        const recent3 = ffRows.rows.filter(r => new Date(r.month) >= new Date(now - 90 * 24 * 60 * 60 * 1000));
        if (recent3.length === 3) {
          ffScore = Math.min(100, ffScore + 20);
          ffData.trend = 'consistent';
        } else if (recent3.length > 0) {
          ffData.trend = 'active';
        }

        if (showDollarAmounts) {
          ffData.total_12m = parseFloat(ffRows.rows.reduce((s, r) => s + parseFloat(r.total || 0), 0).toFixed(2));
        }
      }
    }
  } catch (e) { console.error('[Scorecard] ffScore error:', e.message); }

  // ── 6. App Engagement Streak ───────────────────────────────────────────────
  let engagementScore = 0;
  let engagementData = { streak_days: 0, level: 1, xp: 0, total_transactions: 0 };
  try {
    const [tfrRows, txCountRows] = await Promise.all([
      pool.query('SELECT streak_days, level, xp, total_points FROM tfr_user_stats WHERE user_id = $1', [userId]),
      pool.query('SELECT COUNT(*) as total FROM transactions WHERE user_id = $1', [userId])
    ]);

    if (tfrRows.rows.length > 0) {
      const tfr = tfrRows.rows[0];
      engagementData.streak_days = parseInt(tfr.streak_days || 0);
      engagementData.level = parseInt(tfr.level || 1);
      engagementData.xp = parseInt(tfr.xp || 0);

      // Score: streak (0-50) + level bonus (0-30) + XP (0-20)
      const streakPoints = Math.min(50, engagementData.streak_days * 2);
      const levelPoints = Math.min(30, (engagementData.level - 1) * 5);
      const xpPoints = Math.min(20, Math.floor(engagementData.xp / 500));
      engagementScore = streakPoints + levelPoints + xpPoints;
    }

    engagementData.total_transactions = parseInt(txCountRows.rows[0]?.total || 0);
    // Bonus for lots of transactions
    if (engagementData.total_transactions > 100) engagementScore = Math.min(100, engagementScore + 10);
    if (engagementData.total_transactions > 500) engagementScore = Math.min(100, engagementScore + 10);
  } catch (e) { console.error('[Scorecard] engagementScore error:', e.message); }

  // ── 7. Composite Score ────────────────────────────────────────────────────
  const weights = {
    allocation: 0.25,
    savings: 0.20,
    debt: 0.20,
    incomeExpense: 0.15,
    ff: 0.10,
    engagement: 0.10
  };

  const rawCompositeScore = Math.round(
    allocationScore * weights.allocation +
    savingsScore * weights.savings +
    debtScore * weights.debt +
    incomeExpenseScore * weights.incomeExpense +
    ffScore * weights.ff +
    engagementScore * weights.engagement
  );

  // ── 8. Integrity Multiplier (Plaid verification status) ──────────────────
  // 1.0 = all Plaid-verified within 7 days
  // 0.85 = mixed (some verified, some manual)
  // 0.70 = all manual / stale (> 7 days or never synced)
  let integrityMultiplier = 0.70;
  let integrityLabel = 'Unverified';
  try {
    const bankResult = await pool.query(`
      SELECT
        COUNT(*) FILTER (WHERE is_verified = true AND last_sync_at >= NOW() - INTERVAL '7 days') AS fresh,
        COUNT(*) FILTER (WHERE is_verified = true AND (last_sync_at IS NULL OR last_sync_at < NOW() - INTERVAL '7 days')) AS stale,
        COUNT(*) FILTER (WHERE is_verified = false) AS unverified,
        COUNT(*) AS total
      FROM bank_accounts
      WHERE user_id = $1 AND is_archived = false
    `, [userId]);
    const s = bankResult.rows[0];
    const total = parseInt(s.total || 0, 10);
    const fresh = parseInt(s.fresh || 0, 10);
    const stale = parseInt(s.stale || 0, 10);
    if (total === 0) {
      integrityMultiplier = 0.70; integrityLabel = 'No data';
    } else if (fresh === total) {
      integrityMultiplier = 1.0; integrityLabel = 'Fully verified';
    } else if (fresh > 0) {
      integrityMultiplier = 0.85; integrityLabel = 'Partially verified';
    } else if (stale > 0) {
      integrityMultiplier = 0.70; integrityLabel = 'Stale data';
    } else {
      integrityMultiplier = 0.70; integrityLabel = 'Manual only';
    }
  } catch (e) { /* non-fatal — integrity check failed, use 0.70 */ }

  const compositeScore = Math.min(100, Math.round(rawCompositeScore * integrityMultiplier));

  function getTier(score) {
    if (score >= 81) return { tier: 'Legacy-Ready', color: '#7C3AED', emoji: '🏆', description: 'Exceptional financial discipline — a true model for generational wealth.' };
    if (score >= 61) return { tier: 'Exceptional', color: '#059669', emoji: '⭐', description: 'Strong financial habits consistently applied. In the top tier.' };
    if (score >= 41) return { tier: 'Strong', color: '#0891B2', emoji: '💪', description: 'Solid foundation with good financial discipline.' };
    if (score >= 21) return { tier: 'Building', color: '#D97706', emoji: '📈', description: 'Making progress. Keep consistent and results compound.' };
    return { tier: 'Emerging', color: '#DC2626', emoji: '🌱', description: 'Early stage. Every positive habit you build now matters.' };
  }

  const tier = getTier(compositeScore);

  return {
    composite_score: compositeScore,
    tier: tier.tier,
    tier_color: tier.color,
    tier_emoji: tier.emoji,
    tier_description: tier.description,
    metrics: {
      allocation_adherence: {
        score: allocationScore,
        label: 'Allocation Adherence',
        description: 'How consistently you stay within your set FACTS percentages',
        data: allocationData
      },
      savings_consistency: {
        score: savingsScore,
        label: 'Savings Consistency',
        description: 'Regular savings deposits over the past 12 months',
        data: savingsData
      },
      debt_reduction: {
        score: debtScore,
        label: 'Debt Reduction Progress',
        description: 'Debt payoff trajectory and strategy effectiveness',
        data: debtData
      },
      income_expense_ratio: {
        score: incomeExpenseScore,
        label: 'Income vs. Expense Ratio',
        description: 'How consistently you live within your means',
        data: incomeExpenseData
      },
      financial_freedom: {
        score: ffScore,
        label: 'Financial Freedom Progress',
        description: 'Consistent investment toward your Financial Freedom Number',
        data: ffData
      },
      app_engagement: {
        score: engagementScore,
        label: 'App Engagement Streak',
        description: 'Consecutive days of active financial tracking',
        data: engagementData
      }
    },
    show_dollar_amounts: showDollarAmounts,
    calculated_at: new Date().toISOString(),
    integrity: {
      multiplier: integrityMultiplier,
      label: integrityLabel,
      raw_score: rawCompositeScore
    }
  };
}

// ── GET /api/scorecard/me ─────────────────────────────────────────────────────
app.get('/api/scorecard/me', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const showDollars = req.query.show_dollars === 'true';
    const scorecard = await calculateScorecard(userId, showDollars);

    // Get user's share links
    const links = (await pool.query(
      'SELECT id, token, show_dollar_amounts, is_active, view_count, created_at, expires_at FROM scorecard_share_links WHERE user_id = $1 ORDER BY created_at DESC',
      [userId]
    )).rows;

    // Get incoming access requests
    const requests = (await pool.query(`
      SELECT sar.id, sar.status, sar.message, sar.created_at, sar.expires_type,
             u.name as requester_name, u.email as requester_email
      FROM scorecard_access_requests sar
      JOIN users u ON u.id = sar.requester_id
      WHERE sar.target_user_id = $1
      ORDER BY sar.created_at DESC
      LIMIT 50
    `, [userId])).rows;

    // Get who currently has approved access
    const sharedWith = (await pool.query(`
      SELECT sar.id, sar.expires_type, sar.expires_at, sar.updated_at,
             u.name as viewer_name, u.email as viewer_email
      FROM scorecard_access_requests sar
      JOIN users u ON u.id = sar.requester_id
      WHERE sar.target_user_id = $1 AND sar.status = 'approved'
        AND (sar.expires_at IS NULL OR sar.expires_at > NOW())
      ORDER BY sar.updated_at DESC
    `, [userId])).rows;

    res.json({ success: true, scorecard, share_links: links, access_requests: requests, shared_with: sharedWith });
  } catch (err) {
    console.error('[Scorecard] GET /api/scorecard/me error:', err);
    res.status(500).json({ error: 'Failed to load scorecard' });
  }
});

// ── POST /api/scorecard/share-links ───────────────────────────────────────────
app.post('/api/scorecard/share-links', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { show_dollar_amounts = false } = req.body;

    // Generate unique token
    const token = crypto.randomBytes(32).toString('hex');
    const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);

    const result = await pool.query(
      'INSERT INTO scorecard_share_links (user_id, token, show_dollar_amounts, expires_at) VALUES ($1, $2, $3, $4) RETURNING *',
      [userId, token, show_dollar_amounts, expiresAt]
    );

    res.json({ success: true, link: result.rows[0] });
  } catch (err) {
    console.error('[Scorecard] POST share-links error:', err);
    res.status(500).json({ error: 'Failed to generate share link' });
  }
});

// ── PATCH /api/scorecard/share-links/:id ──────────────────────────────────────
app.patch('/api/scorecard/share-links/:id', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { id } = req.params;
    const { is_active, show_dollar_amounts } = req.body;

    const updates = [];
    const values = [userId, id];
    if (is_active !== undefined) { updates.push(`is_active = $${values.length + 1}`); values.push(is_active); }
    if (show_dollar_amounts !== undefined) { updates.push(`show_dollar_amounts = $${values.length + 1}`); values.push(show_dollar_amounts); }

    if (updates.length === 0) return res.json({ success: true });

    await pool.query(
      `UPDATE scorecard_share_links SET ${updates.join(', ')} WHERE user_id = $1 AND id = $2`,
      values
    );

    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Failed to update link' });
  }
});

// ── DELETE /api/scorecard/share-links/:id ─────────────────────────────────────
app.delete('/api/scorecard/share-links/:id', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { id } = req.params;
    await pool.query('UPDATE scorecard_share_links SET is_active = false WHERE user_id = $1 AND id = $2', [userId, id]);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Failed to revoke link' });
  }
});

// ── GET /api/scorecard/view/:token ────────────────────────────────────────────
// Public endpoint — no auth required (link-based sharing)
app.get('/api/scorecard/view/:token', optionalAuth, async (req, res) => {
  try {
    const { token } = req.params;
    const link = (await pool.query(
      'SELECT * FROM scorecard_share_links WHERE token = $1 AND is_active = true AND expires_at > NOW()',
      [token]
    )).rows[0];

    if (!link) return res.status(404).json({ error: 'Link not found or expired' });

    // Update view count
    await pool.query(
      'UPDATE scorecard_share_links SET view_count = view_count + 1, last_viewed_at = NOW() WHERE id = $1',
      [link.id]
    );

    const scorecard = await calculateScorecard(link.user_id, link.show_dollar_amounts);

    // Get display name for the shared user
    const owner = (await pool.query('SELECT name, created_at FROM users WHERE id = $1', [link.user_id])).rows[0];

    res.json({
      success: true,
      scorecard,
      owner_name: owner?.name || 'FACTS Member',
      member_since: owner?.created_at,
      link_expires_at: link.expires_at
    });
  } catch (err) {
    console.error('[Scorecard] view by token error:', err);
    res.status(500).json({ error: 'Failed to load scorecard' });
  }
});

// ── POST /api/scorecard/request-access ───────────────────────────────────────
// Request access to another user's scorecard (by email)
app.post('/api/scorecard/request-access', requireAuth, async (req, res) => {
  try {
    const requesterId = req.userId;
    const { target_email, message, expires_type = '30days' } = req.body;

    if (!target_email) return res.status(400).json({ error: 'target_email is required' });

    const target = (await pool.query('SELECT id, name FROM users WHERE LOWER(email) = LOWER($1)', [target_email])).rows[0];
    if (!target) return res.status(404).json({ error: 'No FACTS member found with that email' });
    if (target.id === requesterId) return res.status(400).json({ error: 'You cannot request access to your own scorecard' });

    const validExpiry = ['30days', '90days', 'permanent'];
    const expiresType = validExpiry.includes(expires_type) ? expires_type : '30days';

    // Upsert — if already exists, update message and reset to pending
    const existing = (await pool.query(
      'SELECT id, status FROM scorecard_access_requests WHERE requester_id = $1 AND target_user_id = $2',
      [requesterId, target.id]
    )).rows[0];

    if (existing) {
      if (existing.status === 'approved') {
        return res.json({ success: true, already_approved: true, message: 'You already have access to this scorecard.' });
      }
      await pool.query(
        'UPDATE scorecard_access_requests SET status = $1, message = $2, expires_type = $3, updated_at = NOW() WHERE id = $4',
        ['pending', message || null, expiresType, existing.id]
      );
    } else {
      await pool.query(
        'INSERT INTO scorecard_access_requests (requester_id, target_user_id, status, message, expires_type) VALUES ($1, $2, $3, $4, $5)',
        [requesterId, target.id, 'pending', message || null, expiresType]
      );
    }

    res.json({ success: true, message: `Access request sent to ${target.name || target_email}` });
  } catch (err) {
    console.error('[Scorecard] request-access error:', err);
    res.status(500).json({ error: 'Failed to send access request' });
  }
});

// ── GET /api/scorecard/access-requests ───────────────────────────────────────
app.get('/api/scorecard/access-requests', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const [incoming, outgoing] = await Promise.all([
      pool.query(`
        SELECT sar.id, sar.status, sar.message, sar.expires_type, sar.created_at, sar.updated_at,
               u.name as requester_name, u.email as requester_email
        FROM scorecard_access_requests sar
        JOIN users u ON u.id = sar.requester_id
        WHERE sar.target_user_id = $1
        ORDER BY sar.created_at DESC
      `, [userId]),
      pool.query(`
        SELECT sar.id, sar.target_user_id, sar.status, sar.message, sar.expires_type, sar.created_at, sar.updated_at,
               u.name as target_name, u.email as target_email
        FROM scorecard_access_requests sar
        JOIN users u ON u.id = sar.target_user_id
        WHERE sar.requester_id = $1
        ORDER BY sar.created_at DESC
      `, [userId])
    ]);

    res.json({ success: true, incoming: incoming.rows, outgoing: outgoing.rows });
  } catch (err) {
    res.status(500).json({ error: 'Failed to load access requests' });
  }
});

// ── PUT /api/scorecard/access-requests/:id/approve ───────────────────────────
app.put('/api/scorecard/access-requests/:id/approve', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { id } = req.params;

    const request = (await pool.query(
      'SELECT * FROM scorecard_access_requests WHERE id = $1 AND target_user_id = $2',
      [id, userId]
    )).rows[0];
    if (!request) return res.status(404).json({ error: 'Request not found' });

    let expiresAt = null;
    if (request.expires_type === '30days') expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);
    else if (request.expires_type === '90days') expiresAt = new Date(Date.now() + 90 * 24 * 60 * 60 * 1000);

    await pool.query(
      'UPDATE scorecard_access_requests SET status = $1, expires_at = $2, updated_at = NOW() WHERE id = $3',
      ['approved', expiresAt, id]
    );

    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Failed to approve request' });
  }
});

// ── PUT /api/scorecard/access-requests/:id/deny ──────────────────────────────
app.put('/api/scorecard/access-requests/:id/deny', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { id } = req.params;
    await pool.query(
      'UPDATE scorecard_access_requests SET status = $1, updated_at = NOW() WHERE id = $2 AND target_user_id = $3',
      ['denied', id, userId]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Failed to deny request' });
  }
});

// ── DELETE /api/scorecard/access-requests/:id/revoke ─────────────────────────
// Target user revokes previously-approved access
app.delete('/api/scorecard/access-requests/:id/revoke', requireAuth, async (req, res) => {
  try {
    const userId = req.userId;
    const { id } = req.params;
    await pool.query(
      'UPDATE scorecard_access_requests SET status = $1, updated_at = NOW() WHERE id = $2 AND (target_user_id = $3 OR requester_id = $3)',
      ['revoked', id, userId]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Failed to revoke access' });
  }
});

// ── GET /api/scorecard/user/:targetUserId ─────────────────────────────────────
// View another user's scorecard (only if you have approved access)
app.get('/api/scorecard/user/:targetUserId', requireAuth, async (req, res) => {
  try {
    const requesterId = req.userId;
    const targetId = parseInt(req.params.targetUserId);

    // Check admin bypass
    const isAdmin = (await pool.query('SELECT is_creator FROM users WHERE id = $1', [requesterId])).rows[0]?.is_creator;

    if (!isAdmin) {
      const access = (await pool.query(`
        SELECT id FROM scorecard_access_requests
        WHERE requester_id = $1 AND target_user_id = $2
          AND status = 'approved'
          AND (expires_at IS NULL OR expires_at > NOW())
      `, [requesterId, targetId])).rows[0];

      if (!access) return res.status(403).json({ error: 'You do not have access to this scorecard' });
    }

    // Admin always sees dollar amounts; regular users see what was approved (default: no dollars)
    const showDollars = isAdmin ? true : false;
    const scorecard = await calculateScorecard(targetId, showDollars);
    const owner = (await pool.query('SELECT name, created_at FROM users WHERE id = $1', [targetId])).rows[0];

    res.json({
      success: true,
      scorecard,
      owner_name: owner?.name || 'FACTS Member',
      member_since: owner?.created_at
    });
  } catch (err) {
    console.error('[Scorecard] user view error:', err);
    res.status(500).json({ error: 'Failed to load scorecard' });
  }
});

