// ── GET /api/profile/heir-designation — Get current heir designation ─────────
app.get('/api/profile/heir-designation', requireAuth, async (req, res) => {
  try {
    const result = await pool.query(
      `SELECT hd.*,
              hu.email AS heir_email,
              hu.name  AS heir_name,
              u.pricing_tier AS heir_pricing_tier,
              u.plan         AS heir_plan
         FROM heir_designation hd
         JOIN users hu ON hu.id = hd.heir_user_id
         LEFT JOIN users u ON u.id = hd.heir_user_id
        WHERE hd.user_id = $1
          AND hd.activation_status IN ('pending', 'activated')
        ORDER BY hd.created_at DESC
        LIMIT 1`,
      [req.userId]
    );

    const log = await pool.query(
      `SELECT sal.*, au.email AS admin_email
         FROM succession_activation_log sal
         LEFT JOIN users au ON au.id = sal.admin_id
        WHERE sal.original_user_id = $1
        ORDER BY sal.created_at DESC
        LIMIT 10`,
      [req.userId]
    );

    res.json({
      success: true,
      designation: result.rows[0] || null,
      activity_log: log.rows
    });
  } catch (err) {
    console.error('[HeirDesignation] GET error:', err.message);
    res.status(500).json({ error: 'Failed to load heir designation' });
  }
});

// ── POST /api/profile/heir-designation — Save / update heir designation ──────
app.post('/api/profile/heir-designation', requireAuth, async (req, res) => {
  const { heir_email, relationship } = req.body;
  if (!heir_email) return res.status(400).json({ error: 'heir_email is required' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Look up the heir account
    const heirResult = await client.query(
      `SELECT id, email, name, pricing_tier, plan FROM users WHERE LOWER(email) = LOWER($1)`,
      [heir_email.trim()]
    );
    if (!heirResult.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'No TFR account found for that email. Your heir must have an active TFR account.' });
    }
    const heir = heirResult.rows[0];

    if (heir.id === req.userId) {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'You cannot designate yourself as heir.' });
    }

    // Revoke any existing active designation first
    await client.query(
      `UPDATE heir_designation
         SET activation_status = 'revoked', revoked_at = NOW(), revoked_reason = 'Replaced by new designation', updated_at = NOW()
       WHERE user_id = $1 AND activation_status IN ('pending', 'activated')`,
      [req.userId]
    );

    // Check heir subscription status
    const heirHasPro = heir.plan === 'paid' ||
      ['tfr_pro','individual_pro','business_core','business_bundle','tfr_elite','sovereign_executive'].includes(heir.pricing_tier);

    // Insert new designation
    const insert = await client.query(
      `INSERT INTO heir_designation
         (user_id, heir_user_id, relationship, designated_date, activation_status, heir_subscription_active, heir_subscription_last_checked)
       VALUES ($1, $2, $3, CURRENT_DATE, 'pending', $4, NOW())
       RETURNING *`,
      [req.userId, heir.id, relationship || null, heirHasPro]
    );

    const designation = insert.rows[0];

    // Log the action
    await client.query(
      `INSERT INTO succession_activation_log
         (designation_id, original_user_id, heir_user_id, action, notes, metadata)
       VALUES ($1, $2, $3, 'designated', $4, $5)`,
      [designation.id, req.userId, heir.id,
       `Heir designated: ${heir.email}${relationship ? ` (${relationship})` : ''}`,
       JSON.stringify({ heir_email: heir.email, heir_name: heir.name, heir_subscription_active: heirHasPro })]
    );

    await client.query('COMMIT');

    res.json({
      success: true,
      designation: { ...designation, heir_email: heir.email, heir_name: heir.name },
      message: `Heir designated: ${heir.name || heir.email}. They must maintain an active TFR Pro subscription to keep the commission engine live.`
    });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('[HeirDesignation] POST error:', err.message);
    res.status(500).json({ error: 'Failed to save heir designation' });
  } finally {
    client.release();
  }
});

// ── DELETE /api/profile/heir-designation — Revoke designation ─────────────────
app.delete('/api/profile/heir-designation', requireAuth, async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    const result = await client.query(
      `UPDATE heir_designation
         SET activation_status = 'revoked', revoked_at = NOW(), revoked_reason = 'Revoked by account holder', updated_at = NOW()
       WHERE user_id = $1 AND activation_status IN ('pending', 'activated')
       RETURNING *`,
      [req.userId]
    );

    if (!result.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'No active designation found' });
    }

    const d = result.rows[0];
    await client.query(
      `INSERT INTO succession_activation_log
         (designation_id, original_user_id, heir_user_id, action, notes)
       VALUES ($1, $2, $3, 'designation_revoked', 'Revoked by account holder')`,
      [d.id, req.userId, d.heir_user_id]
    );

    await client.query('COMMIT');
    res.json({ success: true, message: 'Heir designation revoked.' });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('[HeirDesignation] DELETE error:', err.message);
    res.status(500).json({ error: 'Failed to revoke designation' });
  } finally {
    client.release();
  }
});

// ── POST /api/admin/succession/activate-heir/:designationId — Admin activates ─
app.post('/api/admin/succession/activate-heir/:designationId', requireAuth, async (req, res) => {
  if (!(await requireCreator(req, res))) return;
  const designationId = parseInt(req.params.designationId);
  const { notes } = req.body;
  const adminId = req.userId;

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Load designation
    const dResult = await client.query(
      `SELECT hd.*, u.email AS owner_email, u.name AS owner_name,
              hu.email AS heir_email, hu.name AS heir_name,
              hu.plan AS heir_plan, hu.pricing_tier AS heir_pricing_tier
         FROM heir_designation hd
         JOIN users u  ON u.id  = hd.user_id
         JOIN users hu ON hu.id = hd.heir_user_id
        WHERE hd.id = $1 FOR UPDATE`,
      [designationId]
    );

    if (!dResult.rows.length) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Designation not found' });
    }

    const d = dResult.rows[0];
    if (d.activation_status === 'activated') {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'Succession already activated' });
    }
    if (d.activation_status === 'revoked') {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'Designation has been revoked and cannot be activated' });
    }

    // Check heir subscription
    const heirHasPro = d.heir_plan === 'paid' ||
      ['tfr_pro','individual_pro','business_core','business_bundle','tfr_elite','sovereign_executive'].includes(d.heir_pricing_tier);

    if (!heirHasPro) {
      // Log it but don't hard-block — admin can override
      console.warn(`[Succession] Heir ${d.heir_email} does not have active Pro. Admin activating anyway with note.`);
    }

    // Activate the designation
    await client.query(
      `UPDATE heir_designation
         SET activation_status = 'activated',
             activated_at = NOW(),
             activated_by = $2,
             heir_subscription_active = $3,
             heir_subscription_last_checked = NOW(),
             updated_at = NOW()
       WHERE id = $1`,
      [designationId, adminId, heirHasPro]
    );

    // Transfer affiliate node ownership (if applicable)
    // Look up the original holder's affiliate record
    const affResult = await client.query(
      `SELECT id, user_id, affiliate_level, referral_code, status
         FROM affiliates WHERE user_id = $1 AND status = 'active'`,
      [d.user_id]
    );

    let affiliateTransferred = false;
    if (affResult.rows.length) {
      const aff = affResult.rows[0];
      // Transfer the affiliate node to the heir
      await client.query(
        `UPDATE affiliates SET user_id = $2, updated_at = NOW() WHERE id = $1`,
        [aff.id, d.heir_user_id]
      );
      affiliateTransferred = true;
    }

    // Transfer sovereign flags to heir
    await client.query(
      `UPDATE users AS heir
         SET pricing_tier = orig.pricing_tier,
             p2p_lending_visible = orig.p2p_lending_visible,
             mastermind_access   = orig.mastermind_access,
             summit_invite       = orig.summit_invite
         FROM users orig
        WHERE orig.id = $1 AND heir.id = $2`,
      [d.user_id, d.heir_user_id]
    );

    // Log the activation
    await client.query(
      `INSERT INTO succession_activation_log
         (designation_id, original_user_id, heir_user_id, action, admin_id, notes, metadata)
       VALUES ($1, $2, $3, 'succession_activated', $4, $5, $6)`,
      [designationId, d.user_id, d.heir_user_id, adminId,
       notes || `Succession activated by admin. Heir: ${d.heir_email}`,
       JSON.stringify({
         original_email: d.owner_email,
         heir_email: d.heir_email,
         affiliate_transferred: affiliateTransferred,
         heir_had_pro: heirHasPro
       })]
    );

    // Pause commission if heir has no Pro
    if (!heirHasPro) {
      await client.query(
        `UPDATE heir_designation SET commission_paused = TRUE, commission_paused_at = NOW() WHERE id = $1`,
        [designationId]
      );
      await client.query(
        `INSERT INTO succession_activation_log
           (designation_id, original_user_id, heir_user_id, action, admin_id, notes)
         VALUES ($1, $2, $3, 'commission_paused', $4, 'Heir lacks active Pro subscription at activation time')`,
        [designationId, d.user_id, d.heir_user_id, adminId]
      );
    }

    await client.query('COMMIT');

    res.json({
      success: true,
      message: `Succession activated. ${affiliateTransferred ? 'Affiliate node transferred.' : 'No active affiliate node found.'} ${heirHasPro ? 'Commission engine active.' : '⚠️ Commission engine PAUSED — heir must activate Pro subscription.'}`,
      designation_id: designationId,
      affiliate_transferred: affiliateTransferred,
      commission_paused: !heirHasPro
    });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('[Succession] POST activate-heir error:', err.message);
    res.status(500).json({ error: 'Failed to activate succession' });
  } finally {
    client.release();
  }
});

// ── GET /api/admin/succession/heir-designations — Admin list ─────────────────
app.get('/api/admin/succession/heir-designations', requireAuth, async (req, res) => {
  if (!(await requireCreator(req, res))) return;
  try {
    const { status } = req.query;
    const cond = status ? `WHERE hd.activation_status = $1` : '';
    const params = status ? [status] : [];

    const result = await pool.query(
      `SELECT hd.*,
              u.email  AS owner_email,  u.name  AS owner_name,
              hu.email AS heir_email,   hu.name AS heir_name,
              hu.plan  AS heir_plan, hu.pricing_tier AS heir_pricing_tier,
              au.email AS activated_by_email
         FROM heir_designation hd
         JOIN users u  ON u.id  = hd.user_id
         JOIN users hu ON hu.id = hd.heir_user_id
         LEFT JOIN users au ON au.id = hd.activated_by
         ${cond}
        ORDER BY hd.created_at DESC`,
      params
    );

    res.json({ success: true, designations: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('[Succession] GET admin heir-designations error:', err.message);
    res.status(500).json({ error: 'Failed to load designations' });
  }
});

