// ── POST /api/vantage-point/shares — Create a new share link ─────────────────
app.post('/api/vantage-point/shares', requireAuth, async (req, res) => {
  const { viewer_email, label, permissions, expires_days } = req.body;
  if (!viewer_email) return res.status(400).json({ error: 'viewer_email is required' });

  try {
    const token = require('crypto').randomBytes(32).toString('hex');
    const expiresAt = expires_days
      ? new Date(Date.now() + parseInt(expires_days) * 24 * 60 * 60 * 1000)
      : null;

    const defaultPerms = {
      facts_ledger: true,
      debt_position: true,
      allocation_percentages: true,
      net_worth: true,
      affiliate_tree: true
    };

    const finalPerms = permissions ? { ...defaultPerms, ...permissions } : defaultPerms;

    // Look up viewer if they have a TFR account
    const viewerResult = await pool.query(
      `SELECT id FROM users WHERE LOWER(email) = LOWER($1)`,
      [viewer_email.trim()]
    );
    const viewerId = viewerResult.rows.length ? viewerResult.rows[0].id : null;

    const result = await pool.query(
      `INSERT INTO vantage_point_shares
         (owner_id, viewer_email, viewer_id, token, permissions, label, expires_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       RETURNING *`,
      [req.userId, viewer_email.trim(), viewerId, token,
       JSON.stringify(finalPerms), label || viewer_email.trim(), expiresAt]
    );

    const share = result.rows[0];
    const shareUrl = `${process.env.APP_URL || ''}/vantage-point.html?token=${token}`;

    res.json({
      success: true,
      share,
      share_url: shareUrl,
      message: `Vantage Point share created for ${viewer_email}. Share the link — it expires ${expiresAt ? expiresAt.toLocaleDateString() : 'never'}.`
    });
  } catch (err) {
    console.error('[VantagePoint] POST share error:', err.message);
    res.status(500).json({ error: 'Failed to create share' });
  }
});

// ── DELETE /api/vantage-point/shares/:id — Revoke a share ────────────────────
app.delete('/api/vantage-point/shares/:id', requireAuth, async (req, res) => {
  const shareId = parseInt(req.params.id);
  try {
    const result = await pool.query(
      `UPDATE vantage_point_shares
         SET revoked = TRUE, revoked_at = NOW(), updated_at = NOW()
       WHERE id = $1 AND owner_id = $2 AND revoked = FALSE
       RETURNING id`,
      [shareId, req.userId]
    );
    if (!result.rows.length) return res.status(404).json({ error: 'Share not found or already revoked' });
    res.json({ success: true, message: 'Vantage Point access revoked.' });
  } catch (err) {
    console.error('[VantagePoint] DELETE share error:', err.message);
    res.status(500).json({ error: 'Failed to revoke share' });
  }
});

// ── GET /api/vantage/:token — Public shared view (validates token) ────────────
app.get('/api/vantage/:token', async (req, res) => {
  const { token } = req.params;
  try {
    // Look up the share
    const shareResult = await pool.query(
      `SELECT vps.*, u.name AS owner_name
         FROM vantage_point_shares vps
         JOIN users u ON u.id = vps.owner_id
        WHERE vps.token = $1 AND vps.revoked = FALSE`,
      [token]
    );

    if (!shareResult.rows.length) {
      return res.status(404).json({ error: 'This Vantage Point link is invalid or has been revoked.' });
    }

    const share = shareResult.rows[0];

    // Check expiry
    if (share.expires_at && new Date(share.expires_at) < new Date()) {
      return res.status(410).json({ error: 'This Vantage Point link has expired.' });
    }

    const ownerId = share.owner_id;
    const perms = share.permissions || {};

    // Assemble the shared data
    const data = { owner_name: share.owner_name };

    // FACTS ledger summary
    if (perms.facts_ledger) {
      const ledger = await pool.query(
        `SELECT SUM(CASE WHEN type='income' THEN amount_cents ELSE 0 END) AS total_income_cents,
                SUM(CASE WHEN type='expense' THEN amount_cents ELSE 0 END) AS total_expense_cents,
                COUNT(*) AS transaction_count,
                MAX(date) AS last_transaction_date
           FROM transactions WHERE user_id = $1`,
        [ownerId]
      );
      data.facts_ledger = ledger.rows[0] || null;
    }

    // Debt position
    if (perms.debt_position) {
      const debts = await pool.query(
        `SELECT account_name, balance_cents, interest_rate, minimum_payment_cents, status
           FROM debts WHERE user_id = $1 AND status NOT IN ('paid_off')
          ORDER BY balance_cents DESC`,
        [ownerId]
      );
      data.debt_position = {
        debts: debts.rows,
        total_debt_cents: debts.rows.reduce((s, d) => s + (d.balance_cents || 0), 0)
      };
    }

    // Allocation percentages
    if (perms.allocation_percentages) {
      const alloc = await pool.query(
        `SELECT allocation_config FROM users WHERE id = $1`,
        [ownerId]
      );
      data.allocation_percentages = alloc.rows[0]?.allocation_config || null;
    }

    // Net worth snapshot
    if (perms.net_worth) {
      const nw = await pool.query(
        `SELECT total_assets_cents, total_liabilities_cents, net_worth_cents, snapshot_date
           FROM net_worth_entries WHERE user_id = $1
          ORDER BY snapshot_date DESC LIMIT 1`,
        [ownerId]
      );
      data.net_worth = nw.rows[0] || null;
    }

    // Affiliate tree (read-only structure)
    if (perms.affiliate_tree) {
      const aff = await pool.query(
        `SELECT a.referral_code, a.affiliate_level, a.status, a.total_earned_cents,
                a.total_personal_recruits, a.personal_recruits_count,
                u.name AS holder_name
           FROM affiliates a
           JOIN users u ON u.id = a.user_id
          WHERE a.user_id = $1`,
        [ownerId]
      );
      data.affiliate_tree = aff.rows[0] || null;
    }

    // Update access tracking
    await pool.query(
      `UPDATE vantage_point_shares
         SET last_accessed_at = NOW(), access_count = access_count + 1, updated_at = NOW()
       WHERE id = $1`,
      [share.id]
    );

    res.json({
      success: true,
      share_label: share.label,
      owner_name: share.owner_name,
      permissions: perms,
      expires_at: share.expires_at,
      data
    });
  } catch (err) {
    console.error('[VantagePoint] GET /api/vantage/:token error:', err.message);
    res.status(500).json({ error: 'Failed to load Vantage Point data' });
  }
});

