// ─── RECEIPT SCANNER (L7-9 Business Pro Part 3) ──────────────────────────────
// In-memory temp store for scanned receipt images (expires in 10 minutes)
const receiptScanCache = new Map();
setInterval(() => {
  const now = Date.now();
  for (const [key, val] of receiptScanCache) {
    if (now - val.createdAt > 10 * 60 * 1000) receiptScanCache.delete(key);
  }
}, 60_000);

const receiptScanUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 20 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    const mime = file.mimetype.toLowerCase();
    const allowed = ['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'];
    if (allowed.includes(mime)) {
      cb(null, true);
    } else {
      cb(new Error('Only JPG, PNG, or HEIC images are supported for receipt scanning'));
    }
  }
});

// FACTS category slug → 5-Bucket pillar mapping
// Updated to use current FACTS slugs (post-Give→Legacy merge + bucket renames)
const CATEGORY_PILLAR_MAP = {
  'necessities':  'operating_reserve',
  'legacy':       'tax_shield',      // Education merged with Give → Legacy
  'reserve':      'wealth_bridge',   // The Reserve
  'lifestyle':    'clearing',        // Lifestyle
  'growth':       'growth_innovation',
  'velocity':      'growth_innovation',
};
const PILLAR_LABELS = {
  clearing:           'Clearing',
  tax_shield:         'Tax Shield',
  operating_reserve:  'Operating Reserve',
  growth_innovation:  'Growth & Innovation',
  wealth_bridge:      'Wealth Bridge',
};
const VALID_PILLARS = Object.keys(PILLAR_LABELS);

// POST /api/receipts/scan — upload receipt image, OCR via AI vision, return extracted fields
app.post('/api/receipts/scan', requireAuth, receiptScanUpload.single('file'), async (req, res) => {
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ error: 'Paid plan required', upgrade_required: true });

    if (!req.file) return res.status(400).json({ error: 'No image uploaded' });

    // Load FACTS categories for category suggestion
    const catsResult = await pool.query('SELECT id, name, slug, color, icon FROM categories ORDER BY sort_order');
    const categories = catsResult.rows;
    const categoryList = categories.map(c => `${c.id}:${c.name}`).join(', ');

    // Determine if user is on Full Business Bundle (required for AI Receipt Scanning)
    const userTierRow = await pool.query('SELECT pricing_tier FROM users WHERE id = $1', [req.userId]);
    const pricing_tier = userTierRow.rows[0]?.pricing_tier || 'none';
    const isBusinessPro = pricing_tier === 'business_bundle';

    // Call AI vision to extract receipt data
    const aiClient = new OpenAI();
    const mimeType = ['image/heic', 'image/heif'].includes(req.file.mimetype) ? 'image/jpeg' : req.file.mimetype;
    const b64 = req.file.buffer.toString('base64');
    const today = new Date().toISOString().split('T')[0];

    let completion;
    try {
      completion = await aiClient.chat.completions.create({
        model: 'gpt-4o',
        task: 'receipt-ocr',
        max_tokens: 512,
        response_format: { type: 'json_object' },
        messages: [{
          role: 'user',
          content: [
            {
              type: 'image_url',
              image_url: { url: `data:${mimeType};base64,${b64}`, detail: 'low' }
            },
            {
              type: 'text',
              text: `You are a receipt OCR assistant. Extract data from this receipt image and return ONLY a JSON object with these exact fields:
{
  "vendor": "merchant or store name as a string",
  "amount": total amount as a number (e.g. 42.50),
  "date": "YYYY-MM-DD format, use ${today} if not visible",
  "description": "brief 3-6 word description of the purchase",
  "suggested_category_id": one of these category IDs as a number: ${categoryList}
}

Category selection rules:
- Necessities: rent, mortgage, groceries, gas, utilities, insurance, transportation
- Education: courses, books, workshops, certifications, tuition
- Give: donations, charity, tithing, gifts
- Save: savings account, emergency fund, retirement contributions
- Fun: restaurants, dining, entertainment, hobbies, travel, subscriptions
- Financial Freedom: business expenses, investments, debt payments

If the image is not a receipt or is unreadable, return: {"error": "Could not read receipt"}
Return ONLY the JSON object, no other text.`
            }
          ]
        }]
      });
    } catch (aiErr) {
      console.error('[ReceiptScanner] AI error:', aiErr.message);
      return res.status(503).json({ error: 'AI service unavailable. Please try again shortly.' });
    }

    let extracted;
    try {
      extracted = JSON.parse(completion.choices[0].message.content);
    } catch (e) {
      return res.status(422).json({ error: 'Could not parse receipt. Try a clearer photo.' });
    }
    if (extracted.error) {
      return res.status(422).json({ error: extracted.error });
    }

    // Suggest pillar based on matched category
    const matchedCat = categories.find(c => c.id === parseInt(extracted.suggested_category_id));
    const pillarKey = matchedCat ? (CATEGORY_PILLAR_MAP[matchedCat.slug] || 'clearing') : 'clearing';

    // Cache file buffer for the confirm step (10-minute TTL)
    const scanId = crypto.randomUUID();
    receiptScanCache.set(scanId, {
      buffer: req.file.buffer,
      originalName: req.file.originalname,
      mimeType: req.file.mimetype,
      userId: req.userId,
      createdAt: Date.now()
    });

    res.json({
      success: true,
      scan_id: scanId,
      extracted: {
        vendor:               extracted.vendor || '',
        amount:               parseFloat(extracted.amount) || 0,
        date:                 extracted.date || today,
        description:          extracted.description || '',
        suggested_category_id: parseInt(extracted.suggested_category_id) || null,
      },
      pillar_suggestion:       pillarKey,
      pillar_suggestion_label: PILLAR_LABELS[pillarKey],
      is_business_pro:         isBusinessPro,
      categories,
    });
  } catch (err) {
    console.error('[ReceiptScanner] scan error:', err.message);
    res.status(500).json({ error: 'Receipt scan failed. Please try again.' });
  }
});

// POST /api/receipts/save — confirm extracted data → save to vault + FACTS ledger atomically
app.post('/api/receipts/save', requireAuth, async (req, res) => {
  const client = await pool.connect();
  try {
    const hasPro = await hasProAccess(req.userId);
    if (!hasPro) return res.status(403).json({ error: 'Paid plan required', upgrade_required: true });

    const { scan_id, amount, description, category_id, transaction_date, pillar_tag } = req.body;

    if (!scan_id)                            return res.status(400).json({ error: 'scan_id required' });
    if (!amount || parseFloat(amount) <= 0)  return res.status(400).json({ error: 'amount must be positive' });
    if (!category_id)                        return res.status(400).json({ error: 'category_id required' });
    if (pillar_tag && !VALID_PILLARS.includes(pillar_tag)) {
      return res.status(400).json({ error: 'Invalid pillar_tag' });
    }

    // Retrieve cached file
    const cached = receiptScanCache.get(scan_id);
    if (!cached || cached.userId !== req.userId) {
      return res.status(400).json({ error: 'Scan session expired. Please scan the receipt again.' });
    }

    // For Full Business Bundle: validate pillar tag if provided (AI receipt scanning is bundle-only)
    const userTierRow = await pool.query('SELECT pricing_tier FROM users WHERE id = $1', [req.userId]);
    const pricing_tier = userTierRow.rows[0]?.pricing_tier || 'none';
    const isBusinessPro = pricing_tier === 'business_bundle';
    const finalPillarTag = isBusinessPro ? (pillar_tag || null) : null;

    await client.query('BEGIN');

    // 1. Save receipt image to Document Vault
    const txDate = transaction_date || new Date().toISOString().split('T')[0];
    const vendorSlug = (description || 'receipt').replace(/[^a-zA-Z0-9]/g, '_').substring(0, 40);
    const ext = cached.originalName.split('.').pop() || 'jpg';
    const fileName = `receipt_${txDate}_${vendorSlug}.${ext}`;

    const docResult = await client.query(
      `INSERT INTO user_documents (user_id, category, file_name, file_mime_type, file_size_bytes, file_data, notes)
       VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING id`,
      [req.userId, 'receipts', fileName, cached.mimeType, cached.buffer.length, cached.buffer,
       `Scanned receipt: ${description || 'Receipt'}`]
    );
    const documentId = docResult.rows[0].id;

    // 2. Create FACTS ledger entry (expense) with receipt link
    const txResult = await client.query(
      `INSERT INTO transactions
         (user_id, type, amount, description, category_id, transaction_date, receipt_document_id, pillar_tag, is_split)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, FALSE) RETURNING *`,
      [req.userId, 'expense', parseFloat(amount), description || null,
       parseInt(category_id), txDate, documentId, finalPillarTag]
    );
    const transaction = txResult.rows[0];

    await client.query('COMMIT');

    // Clean up cache entry
    receiptScanCache.delete(scan_id);

    // Fire-and-forget challenge updates
    setImmediate(async () => {
      try {
        await tryAutoCompleteChallenge(req.userId, 'log_transaction');
        await tryAutoCompleteChallenge(req.userId, 'log_3_transactions');
        await tryAutoCompleteChallenge(req.userId, 'log_bill');
        await tryAutoCompleteChallenge(req.userId, 'log_15_weekly');
        await tryAutoCompleteChallenge(req.userId, 'monthly_50_logs');
      } catch (e) { /* ignore */ }
    });

    res.json({
      success: true,
      transaction,
      document_id: documentId,
      pillar_tag:   finalPillarTag,
      pillar_label: finalPillarTag ? PILLAR_LABELS[finalPillarTag] : null,
    });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('[ReceiptScanner] save error:', err.message);
    res.status(500).json({ error: 'Failed to save receipt. Please try again.' });
  } finally {
    client.release();
  }
});

