// LEVEL 1 — GROUND ZERO INTELLIGENCE GATE
// ═══════════════════════════════════════════════════════════════════════════════

// Helper: ensure a level1_intake_status row exists for user
async function ensureLevel1Status(userId) {
  await pool.query(`
    INSERT INTO level1_intake_status (user_id)
    VALUES ($1)
    ON CONFLICT (user_id) DO NOTHING
  `, [userId]);
}

// Helper: recompute + persist daily interest leak and unlock Level 2 if ready
async function refreshLevel1Status(userId) {
  // Sum daily interest across credit intake creditors
  const creditRow = await pool.query(
    'SELECT creditors FROM level1_credit_intake WHERE user_id = $1',
    [userId]
  );
  const liabilityRows = await pool.query(
    'SELECT balance_cents, apr FROM level1_liability_items WHERE user_id = $1',
    [userId]
  );

  let dailyLeakCents = 0;

  // From credit intake creditors
  if (creditRow.rows.length > 0) {
    const creditors = creditRow.rows[0].creditors || [];
    for (const c of creditors) {
      const bal = parseFloat(c.balance_cents || 0);
      const apr = parseFloat(c.apr || 0);
      if (bal > 0 && apr > 0) {
        dailyLeakCents += (bal * (apr / 100)) / 365;
      }
    }
  }

  // From liability sync items
  for (const row of liabilityRows.rows) {
    const bal = parseFloat(row.balance_cents || 0);
    const apr = parseFloat(row.apr || 0);
    if (bal > 0 && apr > 0) {
      dailyLeakCents += (bal * (apr / 100)) / 365;
    }
  }

  const dailyLeakDollars = dailyLeakCents / 100;

  const statusRow = await pool.query(
    'SELECT credit_completed, cashflow_completed, liability_completed, asset_completed FROM level1_intake_status WHERE user_id = $1',
    [userId]
  );
  const s = statusRow.rows[0];
  const allDone = s && s.credit_completed && s.cashflow_completed && s.liability_completed && s.asset_completed;

  await pool.query(`
    UPDATE level1_intake_status
    SET daily_interest_leak = $2,
        level2_unlocked     = $3,
        completed_at        = CASE WHEN $3 AND completed_at IS NULL THEN NOW() ELSE completed_at END,
        updated_at          = NOW()
    WHERE user_id = $1
  `, [userId, dailyLeakDollars, allDone]);

  return { dailyLeakDollars, allDone };
}

