// POST /api/level1/credit-intake — save credit data
// Body: { credit_score, total_debt_cents, creditors: [{name, balance_cents, apr, account_type, min_payment_cents}], source_type, notes }
app.post('/api/level1/credit-intake', requireAuth, async (req, res) => {
  try {
    await ensureLevel1Status(req.userId);

    const { credit_score, total_debt_cents, creditors = [], source_type = 'manual', notes } = req.body;

    if (!Array.isArray(creditors) || creditors.length === 0) {
      return res.status(400).json({ success: false, message: 'At least one creditor is required.' });
    }

    // Upsert
    await pool.query(`
      INSERT INTO level1_credit_intake (user_id, credit_score, total_debt_cents, creditors, source_type, notes, updated_at)
      VALUES ($1, $2, $3, $4, $5, $6, NOW())
      ON CONFLICT (user_id) DO UPDATE SET
        credit_score     = EXCLUDED.credit_score,
        total_debt_cents = EXCLUDED.total_debt_cents,
        creditors        = EXCLUDED.creditors,
        source_type      = EXCLUDED.source_type,
        notes            = EXCLUDED.notes,
        updated_at       = NOW()
    `, [req.userId, credit_score || null, total_debt_cents || null, JSON.stringify(creditors), source_type, notes || null]);

    // Mark credit step complete
    await pool.query(`
      UPDATE level1_intake_status
      SET credit_completed = TRUE, updated_at = NOW()
      WHERE user_id = $1
    `, [req.userId]);

    const { dailyLeakDollars, allDone } = await refreshLevel1Status(req.userId);

    res.json({ success: true, message: 'Credit intake saved.', daily_interest_leak: dailyLeakDollars, all_complete: allDone });
  } catch (err) {
    console.error('[Level1] credit-intake error:', err.message);
    res.status(500).json({ success: false, message: 'Failed to save credit intake.' });
  }
});

