// POST /api/level1/liability-sync — save bill/liability items
// Body: { items: [{liability_type, creditor_name, balance_cents, apr, min_payment_cents, due_day}] }
app.post('/api/level1/liability-sync', requireAuth, async (req, res) => {
  try {
    await ensureLevel1Status(req.userId);

    const { items = [] } = req.body;

    if (!Array.isArray(items) || items.length === 0) {
      return res.status(400).json({ success: false, message: 'At least one liability is required.' });
    }

    const VALID_TYPES = ['credit_card','auto_loan','student_loan','personal_loan','medical','mortgage','other'];

    // Replace all existing items for this user
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      await client.query('DELETE FROM level1_liability_items WHERE user_id = $1', [req.userId]);
      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const lType = VALID_TYPES.includes(item.liability_type) ? item.liability_type : 'other';
        await client.query(`
          INSERT INTO level1_liability_items
            (user_id, liability_type, creditor_name, balance_cents, apr, min_payment_cents, due_day, sort_order)
          VALUES ($1,$2,$3,$4,$5,$6,$7,$8)
        `, [
          req.userId, lType,
          item.creditor_name || 'Unknown',
          Math.round(parseFloat(item.balance_cents || 0)),
          parseFloat(item.apr || 0),
          Math.round(parseFloat(item.min_payment_cents || 0)),
          item.due_day || null,
          i
        ]);
      }
      await client.query(`
        UPDATE level1_intake_status
        SET liability_completed = TRUE, updated_at = NOW()
        WHERE user_id = $1
      `, [req.userId]);
      await client.query('COMMIT');
    } catch (e) {
      await client.query('ROLLBACK');
      throw e;
    } finally {
      client.release();
    }

    const { dailyLeakDollars, allDone } = await refreshLevel1Status(req.userId);

    res.json({ success: true, message: 'Liability sync saved.', daily_interest_leak: dailyLeakDollars, all_complete: allDone });
  } catch (err) {
    console.error('[Level1] liability-sync error:', err.message);
    res.status(500).json({ success: false, message: 'Failed to save liabilities.' });
  }
});

