// ─── Feature Waitlist ───────────────────────────────────────────────────────
// POST /api/waitlist/feature — capture email interest for upcoming features
// Deduplicates by (feature_name, email) — returns success either way
app.post('/api/waitlist/feature', async (req, res) => {
  try {
    const { feature_name, email } = req.body;

    if (!feature_name || typeof feature_name !== 'string') {
      return res.status(400).json({ success: false, message: 'feature_name is required.' });
    }
    if (!email || typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) {
      return res.status(400).json({ success: false, message: 'A valid email is required.' });
    }

    const cleanEmail  = email.trim().toLowerCase();
    const cleanFeature = feature_name.trim().substring(0, 100);

    // Resolve user_id if authenticated
    let userId = null;
    try {
      const authHeader = req.headers.authorization;
      if (authHeader && authHeader.startsWith('Bearer ')) {
        const jwt = require('jsonwebtoken');
        const decoded = jwt.verify(authHeader.slice(7), process.env.JWT_SECRET);
        userId = decoded.userId || decoded.id || null;
      }
    } catch (_) { /* non-fatal — anonymous sign-up is fine */ }

    await pool.query(
      `INSERT INTO feature_waitlist (feature_name, email, user_id)
       VALUES ($1, $2, $3)
       ON CONFLICT (feature_name, LOWER(email)) DO NOTHING`,
      [cleanFeature, cleanEmail, userId]
    );

    console.log(`[Waitlist] ${cleanFeature} — ${cleanEmail}`);
    res.json({ success: true, message: "You're on the list!" });
  } catch (err) {
    console.error('[Waitlist] error:', err.message);
    res.status(500).json({ success: false, message: 'Could not save your request. Please try again.' });
  }
});

// GET /api/admin/waitlist
app.get('/api/admin/waitlist', async (req, res) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ success: false, message: 'Unauthorized' });
    }
    const jwt = require('jsonwebtoken');
    const decoded = jwt.verify(authHeader.slice(7), process.env.JWT_SECRET);
    if (!decoded.is_creator) {
      return res.status(403).json({ success: false, message: 'Forbidden' });
    }

    const { feature_name } = req.query;
    let sql = `
      SELECT fw.feature_name, fw.email, fw.user_id, fw.created_at,
             u.name as user_name
      FROM feature_waitlist fw
      LEFT JOIN users u ON fw.user_id = u.id
    `;
    const params = [];
    if (feature_name) {
      sql += ' WHERE fw.feature_name = $1';
      params.push(feature_name);
    }
    sql += ' ORDER BY fw.created_at DESC';

    const result = await pool.query(sql, params);
    res.json({ success: true, entries: result.rows });
  } catch (err) {
    console.error('[Admin Waitlist] error:', err.message);
    res.status(500).json({ success: false, message: 'Could not fetch waitlist.' });
  }
});

