// ─── COMPLIANCE DISCLAIMER & ONBOARDING TOUR ─────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════

// Current TOS version — bump this string to re-trigger acknowledgment for all users
const FACTS_TOS_VERSION = process.env.FACTS_TOS_VERSION || 'v1';
const EDUCATIONAL_DISCLAIMER_VERSION = process.env.EDUCATIONAL_DISCLAIMER_VERSION || 'edu-v1';

/**
 * GET /api/user/compliance-status
 * Returns whether the user needs to see the disclaimer and/or the onboarding tour.
 */
app.get('/api/user/compliance-status', requireAuth, async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT facts_tos_acknowledged_at, facts_tos_version, onboarding_tour_completed_at FROM users WHERE id = $1',
      [req.userId]
    );
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }
    const user = result.rows[0];

    // Needs disclaimer if never acknowledged, or acknowledged an older TOS version
    const needsDisclaimer = !user.facts_tos_acknowledged_at || user.facts_tos_version !== FACTS_TOS_VERSION;

    // Needs tour if never completed (even if skipped, we store a completion timestamp)
    const needsTour = !user.onboarding_tour_completed_at;

    res.json({
      needs_disclaimer: needsDisclaimer,
      needs_tour: needsTour,
      tos_version: FACTS_TOS_VERSION
    });
  } catch (err) {
    console.error('GET /api/user/compliance-status error:', err.message);
    res.status(500).json({ error: 'Could not fetch compliance status' });
  }
});

