// PATCH /api/profile/settings — update ZIP, dependents, business_switch
app.patch('/api/profile/settings', requireAuth, async (req, res) => {
  try {
    const { zip_code, num_dependents, business_switch } = req.body;
    const updates = [];
    const params = [];
    let idx = 1;

    if (zip_code !== undefined) { updates.push(`zip_code=$${idx++}`); params.push(zip_code?.slice(0,10) || null); }
    if (num_dependents !== undefined) { updates.push(`num_dependents=$${idx++}`); params.push(Math.max(0, parseInt(num_dependents) || 0)); }
    if (business_switch !== undefined) { updates.push(`business_switch=$${idx++}`); params.push(!!business_switch); }
    // Clear cached baseline when inputs change
    if (zip_code !== undefined || num_dependents !== undefined || business_switch !== undefined) {
      updates.push(`sovereignty_calculated_at=NULL`);
    }

    if (updates.length === 0) return res.status(400).json({ error: 'Nothing to update' });

    params.push(req.userId);
    const result = await pool.query(
      `UPDATE users SET ${updates.join(', ')}, updated_at=NOW() WHERE id=$${idx} RETURNING zip_code, num_dependents, business_switch`,
      params
    );
    res.json(result.rows[0]);
  } catch (err) {
    console.error('PATCH /api/profile/settings error:', err.message);
    res.status(500).json({ error: 'Failed to update profile settings' });
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// §7: Sovereignty Baseline — CPI-based monthly necessity floor
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Estimate regional cost-of-living multiplier from ZIP code prefix.
 * Based on BLS CPI-U metro area data and HUD Fair Market Rents (2026 est.).
 */
function getRegionalMultiplier(zipCode) {
  if (!zipCode) return 1.0;
  const prefix3 = parseInt(zipCode.toString().slice(0, 3), 10);

  // High cost metros (1.7–2.2×)
  if (prefix3 >= 100 && prefix3 <= 104) return 2.2; // NYC
  if ((prefix3 >= 900 && prefix3 <= 902) || (prefix3 >= 940 && prefix3 <= 949)) return 1.95; // LA/SF/Bay
  if (prefix3 >= 980 && prefix3 <= 984) return 1.8;  // Seattle
  if (prefix3 >= 200 && prefix3 <= 205) return 1.85; // DC
  if (prefix3 >= 21 && prefix3 <= 24) return 1.6;    // Boston
  if (prefix3 >= 941 && prefix3 <= 943) return 2.0;  // SF Bay Area
  // Medium-high cost (1.3–1.5×)
  if (prefix3 >= 606 && prefix3 <= 608) return 1.4;  // Chicago
  if (prefix3 >= 800 && prefix3 <= 802) return 1.45; // Denver
  if (prefix3 >= 331 && prefix3 <= 334) return 1.35; // Miami
  if (prefix3 >= 970 && prefix3 <= 972) return 1.55; // Portland
  if (prefix3 >= 960 && prefix3 <= 962) return 1.9;  // Honolulu
  if (prefix3 >= 995 && prefix3 <= 999) return 1.5;  // Alaska
  // Medium cost (1.05–1.2×)
  if (prefix3 >= 750 && prefix3 <= 752) return 1.1;  // Dallas
  if (prefix3 >= 303 && prefix3 <= 304) return 1.15; // Atlanta
  if (prefix3 >= 850 && prefix3 <= 852) return 1.1;  // Phoenix
  if (prefix3 >= 770 && prefix3 <= 772) return 1.1;  // Houston
  if (prefix3 >= 191 && prefix3 <= 195) return 1.3;  // Philadelphia
  if (prefix3 >= 481 && prefix3 <= 483) return 1.05; // Detroit
  if (prefix3 >= 430 && prefix3 <= 432) return 1.0;  // Columbus
  // Low cost rural/midwest/south (0.80–0.95×)
  if ((prefix3 >= 385 && prefix3 <= 399) || (prefix3 >= 700 && prefix3 <= 714)) return 0.82; // MS/LA
  if (prefix3 >= 570 && prefix3 <= 577) return 0.82; // SD/ND
  if (prefix3 >= 680 && prefix3 <= 692) return 0.85; // Nebraska
  if (prefix3 >= 650 && prefix3 <= 658) return 0.87; // Missouri rural
  if (prefix3 >= 730 && prefix3 <= 749) return 0.88; // Oklahoma
  return 1.0; // National average default
}

/**
 * Calculate Sovereignty Baseline for a user.
 * Returns { total, breakdown, regional_multiplier }
 */
function calculateSovereigntyBaseline(zipCode, numDependents, businessSwitch) {
  const multiplier = getRegionalMultiplier(zipCode);
  const dependentScale = 1 + (Math.max(0, numDependents) * 0.22); // 22% more per dependent

  // 2026 national median baseline costs per category (monthly)
  const base = {
    shelter:            1350,
    utilities:           380,
    sustenance:          480,
    health:              320,
    personal_defense:    160
  };

  // Business switch: exclude Structural Maintenance (business entity costs) from personal floor
  const structuralMaintenance = businessSwitch ? 0 : 85;

  const breakdown = {};
  for (const [key, amount] of Object.entries(base)) {
    breakdown[key] = Math.round(amount * multiplier * dependentScale);
  }
  breakdown.structural_maintenance = Math.round(structuralMaintenance * multiplier);

  const total = Object.values(breakdown).reduce((s, v) => s + v, 0);

  return {
    total,
    breakdown,
    regional_multiplier: Math.round(multiplier * 100) / 100,
    dependent_scale: Math.round(dependentScale * 100) / 100,
    zip_code: zipCode || null,
    num_dependents: numDependents,
    business_switch: businessSwitch,
    note: zipCode ? `Estimated for ZIP ${zipCode} metro area (2026 BLS/HUD data)` : 'National average (set your ZIP for local estimate)'
  };
}

// GET /api/sovereignty-baseline — fetch/recalculate baseline for authenticated user
app.get('/api/sovereignty-baseline', requireAuth, async (req, res) => {
  try {
    const userRow = await pool.query(
      `SELECT zip_code, num_dependents, business_switch, sovereignty_baseline,
              sovereignty_baseline_breakdown, sovereignty_calculated_at
       FROM users WHERE id=$1`,
      [req.userId]
    );
    const u = userRow.rows[0];
    if (!u) return res.status(404).json({ error: 'User not found' });

    // Use cached if fresh (< 90 days)
    const ninetyDaysAgo = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000);
    if (u.sovereignty_calculated_at && new Date(u.sovereignty_calculated_at) > ninetyDaysAgo && u.sovereignty_baseline) {
      return res.json({
        total: parseFloat(u.sovereignty_baseline),
        breakdown: u.sovereignty_baseline_breakdown,
        cached: true
      });
    }

    // Recalculate
    const result = calculateSovereigntyBaseline(u.zip_code, u.num_dependents || 0, u.business_switch || false);

    // Cache it
    await pool.query(
      `UPDATE users SET sovereignty_baseline=$1, sovereignty_baseline_breakdown=$2, sovereignty_calculated_at=NOW() WHERE id=$3`,
      [result.total, JSON.stringify(result.breakdown), req.userId]
    );

    res.json({ ...result, cached: false });
  } catch (err) {
    console.error('GET /api/sovereignty-baseline error:', err.message);
    res.status(500).json({ error: 'Failed to calculate Sovereignty Baseline' });
  }
});

