/** Middleware: verify module API key (Bearer token in Authorization header) */
async function requireModuleToken(req, res, next) {
  try {
    const authHeader = req.headers['authorization'] || '';
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : null;
    if (!token) return res.status(401).json({ error: 'Bearer token required' });

    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
    const keyRow = await pool.query(
      `SELECT * FROM module_api_keys WHERE token_hash=$1 AND revoked_at IS NULL`,
      [tokenHash]
    );
    if (keyRow.rows.length === 0) return res.status(401).json({ error: 'Invalid or revoked token' });

    const key = keyRow.rows[0];
    // Update last_used_at
    pool.query(`UPDATE module_api_keys SET last_used_at=NOW() WHERE id=$1`, [key.id]).catch(() => {});
    // Log access
    pool.query(
      `INSERT INTO module_audit_log (api_key_id, user_id, action, endpoint, ip_address) VALUES ($1,$2,$3,$4,$5)`,
      [key.id, key.user_id, 'api_access', req.path, req.ip]
    ).catch(() => {});

    req.moduleKey = key;
    req.userId = key.user_id;
    next();
  } catch (err) {
    console.error('[ModuleToken] Auth error:', err.message);
    res.status(500).json({ error: 'Token verification failed' });
  }
}

// POST /api/module-tokens — create a module API key (requires session auth)
app.post('/api/module-tokens', requireAuth, async (req, res) => {
  try {
    const { module_name, read_buckets, can_push_events } = req.body;
    if (!module_name) return res.status(400).json({ error: 'module_name required' });

    const rawToken = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

    const result = await pool.query(
      `INSERT INTO module_api_keys (user_id, module_name, token_hash, read_buckets, can_push_events)
       VALUES ($1, $2, $3, $4, $5) RETURNING id, module_name, read_buckets, can_push_events, created_at`,
      [req.userId, module_name, tokenHash, read_buckets || null, !!can_push_events]
    );
    res.json({ ...result.rows[0], token: rawToken, warning: 'Save this token — it will not be shown again' });
  } catch (err) {
    console.error('POST /api/module-tokens error:', err.message);
    res.status(500).json({ error: 'Failed to create module token' });
  }
});

