// GET /api/v1/state/buckets — current balances for all 6 buckets
app.get('/api/v1/state/buckets', requireModuleToken, async (req, res) => {
  try {
    const key = req.moduleKey;
    const buckets = await pool.query(
      `SELECT c.id, c.name, c.slug, c.color, c.icon,
              COALESCE(pa.percentage, ac.percentage) as allocation_pct,
              COALESCE(
                SUM(CASE WHEN t.type='income' THEN t.amount ELSE 0 END) -
                SUM(CASE WHEN t.type='expense' THEN t.amount ELSE 0 END), 0
              ) as balance
       FROM categories c
       JOIN allocation_config ac ON ac.category_id=c.id
       LEFT JOIN permanent_allocations pa ON pa.category_id=c.id AND pa.user_id=$1
       LEFT JOIN transactions t ON t.category_id=c.id AND t.user_id=$1
       WHERE c.is_active IS DISTINCT FROM FALSE
         AND ($2::text[] IS NULL OR c.slug = ANY($2::text[]))
       GROUP BY c.id, c.name, c.slug, c.color, c.icon, pa.percentage, ac.percentage
       ORDER BY c.sort_order`,
      [key.user_id, key.read_buckets || null]
    );
    res.json({ buckets: buckets.rows, module: key.module_name });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch bucket state' });
  }
});

