// ── §8: Diagnostic Upload — Spending vs. Sovereignty Baseline ─────────────────
// POST /api/diagnostic/analyze — compare uploaded spending against baseline
app.post('/api/diagnostic/analyze', requireAuth, async (req, res) => {
  try {
    const { spending } = req.body;
    // spending: array of { category_slug, subcategory, amount }

    if (!Array.isArray(spending)) {
      return res.status(400).json({ error: 'spending array required' });
    }

    // Get user sovereignty baseline
    const userRow = await pool.query(
      `SELECT zip_code, num_dependents, business_switch, sovereignty_baseline, sovereignty_baseline_breakdown
       FROM users WHERE id=$1`,
      [req.userId]
    );
    const u = userRow.rows[0];
    const baseline = u.sovereignty_baseline
      ? { total: parseFloat(u.sovereignty_baseline), breakdown: u.sovereignty_baseline_breakdown }
      : calculateSovereigntyBaseline(u.zip_code, u.num_dependents || 0, u.business_switch || false);

    // Aggregate spending by bucket
    const actualByBucket = {};
    let totalActual = 0;
    for (const item of spending) {
      const slug = item.category_slug || 'necessities';
      actualByBucket[slug] = (actualByBucket[slug] || 0) + parseFloat(item.amount || 0);
      totalActual += parseFloat(item.amount || 0);
    }

    // Build comparison for Necessities subcategories
    const baselineBreakdown = baseline.breakdown || {};
    const comparison = [];
    for (const [key, baselineAmt] of Object.entries(baselineBreakdown)) {
      const actualAmt = actualByBucket[key] || 0;
      const delta = actualAmt - baselineAmt;
      const deltaPercent = baselineAmt > 0 ? (delta / baselineAmt) * 100 : 0;
      let status = 'on_track';
      if (deltaPercent > 20) status = 'overspending';
      else if (deltaPercent > 10) status = 'warning';
      else if (delta < 0) status = 'under_baseline';

      comparison.push({
        subcategory: key,
        actual: Math.round(actualAmt),
        baseline: Math.round(baselineAmt),
        delta: Math.round(delta),
        delta_percent: Math.round(deltaPercent),
        status
      });
    }

    const leakage = comparison.filter(c => c.status === 'overspending')
      .sort((a, b) => b.delta - a.delta)
      .slice(0, 3);

    res.json({
      total_actual: Math.round(totalActual),
      total_baseline: Math.round(baseline.total),
      total_delta: Math.round(totalActual - baseline.total),
      comparison,
      leakage,
      summary: leakage.length > 0
        ? `You're spending $${Math.round(totalActual - baseline.total)} above your Sovereignty Baseline. Top ${leakage.length} leak${leakage.length > 1 ? 's' : ''}: ${leakage.map(l => `${l.subcategory} $${l.delta}`).join(', ')}`
        : `You're within your Sovereignty Baseline. Keep going.`
    });
  } catch (err) {
    console.error('POST /api/diagnostic/analyze error:', err.message);
    res.status(500).json({ error: 'Failed to analyze spending' });
  }
});

