async function initializeModuleArchitecture() {
  try {
    // Create core API contract
    const coreAPI = createCoreAPI(pool);

    // Initialize module loader
    const moduleLoader = new ModuleLoader(pool, coreAPI);
    await moduleLoader.discoverModules();

    console.log('[Modules] Discovery complete');

    // Mount modules onto Express app
    await moduleLoader.mountModules(app);

    // Mount preview environment (requires moduleLoader)
    if (typeof createPreviewRouter === 'function') {
      const previewRouter = createPreviewRouter(pool, moduleLoader);
      app.use('/preview', previewRouter);
      console.log('[Modules] Preview environment mounted at /preview');
    }

    // Global module error handler (catches all module errors)
    app.use(moduleErrorHandler);
    const requestErrorLogger = require('./middleware/requestErrorLogger');
    app.use(requestErrorLogger);

    // Make moduleLoader available to routes if needed
    app.locals.moduleLoader = moduleLoader;

    console.log('[Modules] Architecture ready');
    return true;
  } catch (err) {
    console.error('[Modules] Initialization failed:', err);
    return false;
  }
}

// ─── Plaid Nightly Sovereign Audit (Sovereignty tier only, 2:00 AM UTC) ────────
(function initPlaidNightlyAudit() {
  try {
    const schedule = '0 2 * * *'; // 2:00 AM UTC
    if (!cron.validate(schedule)) return;

    cron.schedule(schedule, async () => {
      console.log('[Plaid Nightly] Starting sovereignty audit');
      const clientId = process.env.PLAID_CLIENT_ID;
      const secret = process.env.PLAID_SECRET;
      if (!clientId || !secret) {
        console.log('[Plaid Nightly] Plaid not configured — skipping');
        return;
      }

      let plaidNightlyClient;
      try {
        const { Configuration, PlaidApi, PlaidEnvironments } = require('plaid');
        const plaidEnv = process.env.PLAID_ENV || 'sandbox';
        const config = new Configuration({
          basePath: PlaidEnvironments[plaidEnv] || PlaidEnvironments.sandbox,
          baseOptions: { headers: { 'PLAID-CLIENT-ID': clientId, 'PLAID-SECRET': secret } }
        });
        plaidNightlyClient = new PlaidApi(config);
      } catch (e) {
        console.error('[Plaid Nightly] Client init failed:', e.message);
        return;
      }

      // Encryption helpers (must match mod_plaid's logic)
      const nightlyCrypto = require('crypto');
      function nightlyDecrypt(payload) {
        const [ivHex, encHex, tagHex] = payload.split(':');
        const raw = process.env.SESSION_SECRET || process.env.PLAID_SECRET || 'fallback-key-change-me';
        const key = nightlyCrypto.createHash('sha256').update(raw).digest();
        const iv = Buffer.from(ivHex, 'hex');
        const enc = Buffer.from(encHex, 'hex');
        const tag = Buffer.from(tagHex, 'hex');
        const decipher = nightlyCrypto.createDecipheriv('aes-256-gcm', key, iv);
        decipher.setAuthTag(tag);
        return Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
      }

      // Get all active Sovereignty users with Plaid connections
      let sovereigntyUsers;
      try {
        sovereigntyUsers = await pool.query(`
          SELECT DISTINCT pc.user_id
          FROM plaid_connections pc
          JOIN users u ON u.id = pc.user_id
          WHERE pc.status = 'active'
            AND LOWER(COALESCE(u.subscription_tier, '')) = 'sovereignty'
        `);
      } catch (e) {
        console.error('[Plaid Nightly] User query failed:', e.message);
        return;
      }

      console.log(`[Plaid Nightly] Processing ${sovereigntyUsers.rows.length} Sovereignty users`);

      for (const row of sovereigntyUsers.rows) {
        const userId = row.user_id;
        try {
          const connections = await pool.query(
            `SELECT * FROM plaid_connections WHERE user_id = $1 AND status = 'active'`,
            [userId]
          );

          let discrepancyDetected = false;
          const discrepancyDetails = {};

          for (const conn of connections.rows) {
            let accessToken;
            try { accessToken = nightlyDecrypt(conn.access_token); } catch (e) { continue; }

            // Pull balances
            const balResp = await plaidNightlyClient.accountsBalanceGet({ access_token: accessToken });
            const accounts = balResp.data.accounts;

            // Update bank_accounts
            await pool.query(
              `UPDATE bank_accounts SET is_verified = true, last_sync_at = NOW(), updated_at = NOW()
               WHERE user_id = $1 AND is_archived = false`,
              [userId]
            );

            // Cross-reference Necessities bucket
            const factsResult = await pool.query(
              `SELECT COALESCE(SUM(current_balance), 0) AS total_balance
               FROM bank_accounts WHERE user_id = $1 AND is_archived = false`,
              [userId]
            );
            const factsTotalBal = parseFloat(factsResult.rows[0]?.total_balance || 0);

            let plaidTotalBal = 0;
            for (const acct of accounts) {
              if (acct.type === 'depository') plaidTotalBal += parseFloat(acct.balances.current || 0);
            }

            if (factsTotalBal > 0 && plaidTotalBal > 0) {
              const discPct = Math.abs(factsTotalBal - plaidTotalBal) / plaidTotalBal;
              if (discPct > 0.05) {
                discrepancyDetected = true;
                discrepancyDetails[conn.institution_name || conn.id] = {
                  facts_total: factsTotalBal,
                  plaid_total: plaidTotalBal,
                  discrepancy_pct: Math.round(discPct * 1000) / 10
                };
              }
            }

            // Log sync
            await pool.query(`
              INSERT INTO plaid_sync_logs
                (user_id, plaid_connection_id, sync_type, accounts_synced,
                 balances_updated, discrepancy_detected, discrepancy_details, created_at)
              VALUES ($1, $2, 'nightly', $3, true, $4, $5, NOW())
            `, [
              userId, conn.id, accounts.length,
              discrepancyDetected,
              discrepancyDetected ? JSON.stringify(discrepancyDetails) : null
            ]);
          }

          // Integrity Alert if discrepancy detected
          if (discrepancyDetected) {
            const firstKey = Object.keys(discrepancyDetails)[0];
            const detail = discrepancyDetails[firstKey];
            const msg = `⚠️ Integrity Alert — Necessities bucket shows ${detail.discrepancy_pct}% discrepancy between FACTS allocation ($${detail.facts_total.toFixed(0)}) and Plaid balance ($${detail.plaid_total.toFixed(0)}). Verify your entries.`;
            // Store in notifications if available
            await pool.query(`
              INSERT INTO notifications (user_id, type, message, is_read, created_at)
              VALUES ($1, 'integrity_alert', $2, false, NOW())
              ON CONFLICT DO NOTHING
            `, [userId, msg]).catch(() => {}); // Non-fatal — notifications table may not exist
          }

        } catch (e) {
          console.error(`[Plaid Nightly] Failed for user ${userId}:`, e.message);
        }
      }

      console.log('[Plaid Nightly] Sovereignty audit complete');
    }, { scheduled: true, timezone: 'UTC' });

    console.log('[Plaid Nightly] Sovereignty audit scheduled at 2:00 AM UTC');
  } catch (e) {
    console.error('[Plaid Nightly] Failed to initialize scheduler:', e.message);
  }
})();

