const supportUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 }, // 5 MB screenshots
  fileFilter: (req, file, cb) => {
    const allowed = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
    if (allowed.includes(file.mimetype)) {
      cb(null, true);
    } else {
      cb(new Error('Only image files are accepted for screenshots'));
    }
  }
});

// POST /api/support/tickets — submit a support ticket (authenticated or anonymous)
// optionalAuth: anonymous users can report issues from public routes (e.g. /credit-analysis); user_id nullable in DB
app.post('/api/support/tickets', optionalAuth, supportUpload.single('screenshot'), async (req, res) => {
  try {
    const { subject, description, page_url } = req.body;
    if (!subject || !description) {
      return res.status(400).json({ error: 'Subject and description are required' });
    }
    if (subject.length > 255) return res.status(400).json({ error: 'Subject too long (max 255 chars)' });
    if (description.length > 10000) return res.status(400).json({ error: 'Description too long (max 10,000 chars)' });

    let screenshot_url = null;

    // Upload screenshot to R2 if provided
    if (req.file) {
      try {
        const POLSIA_API_KEY = process.env.POLSIA_API_KEY;
        if (POLSIA_API_KEY) {
          const filename = `support-${Date.now()}-${req.file.originalname}`;
          const formData = new FormData();
          formData.append('file', req.file.buffer, {
            filename,
            contentType: req.file.mimetype,
          });

          const r2Res = await nodeFetch('https://polsia.com/api/proxy/r2/upload', {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${POLSIA_API_KEY}`,
              ...formData.getHeaders(), // CRITICAL: includes Content-Type with boundary
            },
            body: formData,
          });
          const r2Data = await r2Res.json().catch(() => ({}));
          if (r2Data.success && r2Data.file && r2Data.file.url) {
            screenshot_url = r2Data.file.url;
          }
        }
      } catch (uploadErr) {
        console.error('[SupportTickets] screenshot upload failed:', uploadErr.message);
        // Non-fatal — proceed without screenshot
      }
    }

    const result = await pool.query(
      `INSERT INTO support_tickets (user_id, subject, description, screenshot_url, page_url, status, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, 'open', NOW(), NOW())
       RETURNING id, subject, status, created_at`,
      [req.userId, subject.trim(), description.trim(), screenshot_url, page_url || null]
    );

    res.json({ success: true, ticket: result.rows[0] });
  } catch (err) {
    console.error('[SupportTickets] submit error:', err.message);
    res.status(500).json({ error: 'Failed to submit support ticket' });
  }
});

// GET /api/admin/support-tickets — admin view of all tickets
app.get('/api/admin/support-tickets', requireAuth, async (req, res) => {
  try {
    if (!(await requireAdminAllowlist(req, res))) return;

    const { status, limit = 50, offset = 0 } = req.query;
    let query = `
      SELECT
        st.id, st.subject, st.description, st.screenshot_url, st.page_url,
        st.status, st.admin_notes, st.created_at, st.resolved_at,
        u.email AS user_email, u.name AS user_name
      FROM support_tickets st
      LEFT JOIN users u ON u.id = st.user_id
    `;
    const params = [];
    if (status && ['open', 'resolved'].includes(status)) {
      query += ` WHERE st.status = $1`;
      params.push(status);
    }
    query += ` ORDER BY st.created_at DESC LIMIT $${params.length + 1} OFFSET $${params.length + 2}`;
    params.push(parseInt(limit) || 50, parseInt(offset) || 0);

    const [tickets, countRes] = await Promise.all([
      pool.query(query, params),
      pool.query(`SELECT COUNT(*) FROM support_tickets${status && ['open', 'resolved'].includes(status) ? ` WHERE status = '${status}'` : ''}`)
    ]);

    res.json({
      success: true,
      tickets: tickets.rows,
      total: parseInt(countRes.rows[0].count)
    });
  } catch (err) {
    console.error('[SupportTickets] admin list error:', err.message);
    res.status(500).json({ error: 'Failed to load support tickets' });
  }
});

// PATCH /api/admin/support-tickets/:id — update ticket status/notes
app.patch('/api/admin/support-tickets/:id', requireAuth, async (req, res) => {
  try {
    if (!(await requireAdminAllowlist(req, res))) return;

    const ticketId = parseInt(req.params.id);
    const { status, admin_notes } = req.body;
    if (!status || !['open', 'resolved'].includes(status)) {
      return res.status(400).json({ error: 'Status must be open or resolved' });
    }

    const result = await pool.query(
      `UPDATE support_tickets
       SET status = $1, admin_notes = $2, resolved_at = $3, updated_at = NOW()
       WHERE id = $4
       RETURNING id, status, admin_notes, resolved_at`,
      [status, admin_notes || null, status === 'resolved' ? new Date() : null, ticketId]
    );
    if (!result.rows.length) return res.status(404).json({ error: 'Ticket not found' });

    res.json({ success: true, ticket: result.rows[0] });
  } catch (err) {
    console.error('[SupportTickets] update error:', err.message);
    res.status(500).json({ error: 'Failed to update ticket' });
  }
});

// ─── ADVISORY SWITCH (Schema deployed; API stubs) ────────────────────────────
//
// PRIVACY RULES:
// 1. No user can see another user's data without explicit invite
// 2. CO-PRESENCE REQUIRED: both parties must be online simultaneously
// 3. When either disconnects (2 missed heartbeats = 60s), session auto-expires
// 4. Pro feature gate: Individual Pro and above

async function requireAdvisoryAccess(userId) {
  const user = await pool.query(
    `SELECT plan, paid_until, is_creator, promo_code_used, promo_grace_expired, trial_expires_at
     FROM users WHERE id = $1`,
    [userId]
  );
  if (!user.rows.length) return false;
  return hasProAccess(user.rows[0]);
}

// POST /api/advisory/invite — owner generates a session invite
app.post('/api/advisory/invite', requireAuth, async (req, res) => {
  try {
    const hasPro = await requireAdvisoryAccess(req.userId);
    if (!hasPro) {
      return res.status(403).json({ error: 'Advisory Switch requires a paid subscription', upgrade_required: true });
    }

    // Revoke any existing pending/active sessions for this owner
    await pool.query(
      `UPDATE advisory_sessions SET status = 'revoked', expired_at = NOW()
       WHERE owner_user_id = $1 AND status IN ('pending', 'active')`,
      [req.userId]
    );

    const token = crypto.randomBytes(32).toString('hex');
    const result = await pool.query(
      `INSERT INTO advisory_sessions (owner_user_id, session_token, status, created_at, last_heartbeat_owner)
       VALUES ($1, $2, 'pending', NOW(), NOW())
       RETURNING id, session_token, status, created_at`,
      [req.userId, token]
    );

    const session = result.rows[0];
    const shareLink = `${process.env.APP_URL || 'https://financial-revolution.polsia.app'}/advisory-join?token=${token}`;

    res.json({
      success: true,
      session_id: session.id,
      session_token: session.session_token,
      share_link: shareLink,
      expires_in: '10 minutes — both parties must be online for session to activate'
    });
  } catch (err) {
    console.error('[Advisory] invite error:', err.message);
    res.status(500).json({ error: 'Failed to create advisory session' });
  }
});

// POST /api/advisory/join/:token — viewer joins with token
app.post('/api/advisory/join/:token', requireAuth, async (req, res) => {
  try {
    const { token } = req.params;

    const sessionRes = await pool.query(
      `SELECT id, owner_user_id, viewer_user_id, status, created_at
       FROM advisory_sessions WHERE session_token = $1`,
      [token]
    );

    if (!sessionRes.rows.length) {
      return res.status(404).json({ error: 'Session not found or has expired' });
    }

    const advisorySession = sessionRes.rows[0];

    // Privacy check: cannot join your own session
    if (advisorySession.owner_user_id === req.userId) {
      return res.status(400).json({ error: 'You cannot join your own advisory session' });
    }

    if (advisorySession.status !== 'pending') {
      return res.status(400).json({ error: `Session is ${advisorySession.status}` });
    }

    // Check session hasn't expired (10 min invite window)
    const ageMs = Date.now() - new Date(advisorySession.created_at).getTime();
    if (ageMs > 10 * 60 * 1000) {
      await pool.query(
        `UPDATE advisory_sessions SET status = 'expired', expired_at = NOW() WHERE id = $1`,
        [advisorySession.id]
      );
      return res.status(410).json({ error: 'Session invite has expired. Ask the owner to generate a new one.' });
    }

    // Activate the session
    const updated = await pool.query(
      `UPDATE advisory_sessions
       SET viewer_user_id = $1, status = 'active', activated_at = NOW(), last_heartbeat_viewer = NOW()
       WHERE id = $2 AND status = 'pending'
       RETURNING id, status, activated_at`,
      [req.userId, advisorySession.id]
    );

    if (!updated.rows.length) {
      return res.status(409).json({ error: 'Session no longer available' });
    }

    res.json({
      success: true,
      session_id: advisorySession.id,
      status: 'active',
      message: 'Advisory session active. Both parties must remain connected. Session ends if either party disconnects for 60+ seconds.'
    });
  } catch (err) {
    console.error('[Advisory] join error:', err.message);
    res.status(500).json({ error: 'Failed to join advisory session' });
  }
});

// POST /api/advisory/heartbeat — both parties ping every 30s
// If either misses 2 consecutive heartbeats (60s), session auto-expires
app.post('/api/advisory/heartbeat', requireAuth, async (req, res) => {
  try {
    // Find active session for this user (as owner or viewer)
    const sessionRes = await pool.query(
      `SELECT id, owner_user_id, viewer_user_id, status,
              last_heartbeat_owner, last_heartbeat_viewer
       FROM advisory_sessions
       WHERE (owner_user_id = $1 OR viewer_user_id = $1) AND status = 'active'
       ORDER BY activated_at DESC LIMIT 1`,
      [req.userId]
    );

    if (!sessionRes.rows.length) {
      return res.status(404).json({ error: 'No active advisory session found' });
    }

    const advisorySession = sessionRes.rows[0];
    const isOwner = advisorySession.owner_user_id === req.userId;
    const now = new Date();

    // Update the correct heartbeat field
    const updateField = isOwner ? 'last_heartbeat_owner' : 'last_heartbeat_viewer';
    await pool.query(
      `UPDATE advisory_sessions SET ${updateField} = $1 WHERE id = $2`,
      [now, advisorySession.id]
    );

    // Check if the OTHER party has gone stale (>60s without heartbeat)
    const otherHeartbeat = isOwner
      ? advisorySession.last_heartbeat_viewer
      : advisorySession.last_heartbeat_owner;

    let otherPartyStatus = 'connected';
    if (otherHeartbeat) {
      const staleSecs = (now - new Date(otherHeartbeat)) / 1000;
      if (staleSecs > 60) {
        // Other party disconnected — expire the session
        await pool.query(
          `UPDATE advisory_sessions SET status = 'expired', expired_at = NOW() WHERE id = $1`,
          [advisorySession.id]
        );
        return res.json({
          success: true,
          session_id: advisorySession.id,
          status: 'expired',
          reason: 'Other party disconnected (no heartbeat for 60+ seconds). Session ended.'
        });
      } else if (staleSecs > 30) {
        otherPartyStatus = 'delayed';
      }
    } else {
      otherPartyStatus = 'waiting'; // viewer hasn't sent first heartbeat yet
    }

    res.json({
      success: true,
      session_id: advisorySession.id,
      status: 'active',
      role: isOwner ? 'owner' : 'viewer',
      other_party: otherPartyStatus
    });
  } catch (err) {
    console.error('[Advisory] heartbeat error:', err.message);
    res.status(500).json({ error: 'Heartbeat failed' });
  }
});

// POST /api/advisory/revoke/:sessionId — owner manually ends session
app.post('/api/advisory/revoke/:sessionId', requireAuth, async (req, res) => {
  try {
    const sessionId = parseInt(req.params.sessionId);

    const result = await pool.query(
      `UPDATE advisory_sessions
       SET status = 'revoked', expired_at = NOW()
       WHERE id = $1 AND owner_user_id = $2 AND status IN ('pending', 'active')
       RETURNING id, status`,
      [sessionId, req.userId]
    );

    if (!result.rows.length) {
      return res.status(404).json({ error: 'Session not found or you are not the owner' });
    }

    res.json({ success: true, message: 'Advisory session revoked' });
  } catch (err) {
    console.error('[Advisory] revoke error:', err.message);
    res.status(500).json({ error: 'Failed to revoke session' });
  }
});

// GET /api/advisory/active — check if user has an active advisory session
app.get('/api/advisory/active', requireAuth, async (req, res) => {
  try {
    const result = await pool.query(
      `SELECT id, owner_user_id, viewer_user_id, status, activated_at,
              last_heartbeat_owner, last_heartbeat_viewer
       FROM advisory_sessions
       WHERE (owner_user_id = $1 OR viewer_user_id = $1) AND status IN ('pending', 'active')
       ORDER BY created_at DESC LIMIT 1`,
      [req.userId]
    );

    if (!result.rows.length) {
      return res.json({ success: true, has_active: false });
    }

    const advisorySession = result.rows[0];
    res.json({
      success: true,
      has_active: true,
      session: {
        id: advisorySession.id,
        status: advisorySession.status,
        role: advisorySession.owner_user_id === req.userId ? 'owner' : 'viewer',
        activated_at: advisorySession.activated_at
      }
    });
  } catch (err) {
    console.error('[Advisory] active check error:', err.message);
    res.status(500).json({ error: 'Failed to check advisory status' });
  }
});

// ─── Cron: expire stale advisory sessions every 5 minutes ───────────────────
(function initAdvisoryCron() {
  // Guard: only start in-process schedulers when Blaxel shadow is not active
  if (process.env.POLSIA_IN_PROCESS_CRONS_ENABLED !== 'true') {
    console.log('[Advisory] Cleanup cron skipped: POLSIA_IN_PROCESS_CRONS_ENABLED != true');
    return;
  }
  try {
    const cron = require('node-cron');
    cron.schedule('*/5 * * * *', async () => {
      try {
        const p = getPool();
        if (!p) {
          console.error('[Advisory] stale cleanup skipped: pool unavailable');
          return;
        }
        const cutoff = new Date(Date.now() - 60 * 1000); // 60s heartbeat window
        await p.query(
          `UPDATE advisory_sessions
           SET status = 'expired', expired_at = NOW()
           WHERE status = 'active'
             AND (last_heartbeat_owner < $1 OR last_heartbeat_viewer < $1
                  OR last_heartbeat_owner IS NULL OR last_heartbeat_viewer IS NULL)`,
          [cutoff]
        );
        // Also expire pending invites older than 10 minutes
        const inviteCutoff = new Date(Date.now() - 10 * 60 * 1000);
        await p.query(
          `UPDATE advisory_sessions SET status = 'expired', expired_at = NOW()
           WHERE status = 'pending' AND created_at < $1`,
          [inviteCutoff]
        );
      } catch (err) {
        console.error('[Advisory] stale cleanup error:', err.message);
      }
    }, { scheduled: true, timezone: 'UTC' });
    console.log('[Advisory] Heartbeat cleanup cron scheduled (*/5 * * * *)');
  } catch (e) {
    console.error('[Advisory] Failed to schedule cleanup cron:', e.message);
  }
}());

